INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-1-01', 'colloc-1', 'Cụm học thuật · Nhóm 1', 'Academic Collocation List (Pearson/PTE) — nhóm 1 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 1, 'abstract concept', 'khái niệm trừu tượng', 'adj + n', '[{"en":"Students often struggle to grasp an abstract concept without concrete examples.","vi":"Sinh viên thường khó nắm bắt một khái niệm trừu tượng nếu thiếu ví dụ cụ thể."},{"en":"The lecturer explained the abstract concept using a simple diagram.","vi":"Giảng viên giải thích khái niệm trừu tượng bằng một sơ đồ đơn giản."},{"en":"Philosophy deals with abstract concepts such as justice and freedom.","vi":"Triết học bàn về những khái niệm trừu tượng như công lý và tự do."}]', '[]', NULL, '/ˈæbstrækt ˈkɑːnsept/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 2, 'academic achievement', 'thành tích học tập', 'adj + n', '[{"en":"Her academic achievement earned her a full scholarship abroad.","vi":"Thành tích học tập của cô ấy giúp giành được học bổng toàn phần ở nước ngoài."},{"en":"The school celebrates academic achievement at an annual ceremony.","vi":"Nhà trường vinh danh thành tích học tập trong lễ trao thưởng thường niên."},{"en":"Parental support strongly influences a child''s academic achievement.","vi":"Sự hỗ trợ của cha mẹ ảnh hưởng mạnh đến thành tích học tập của trẻ."}]', '[]', NULL, '/ˌækəˈdemɪk əˈtʃiːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 3, 'academic career', 'sự nghiệp học thuật', 'adj + n', '[{"en":"He devoted his entire academic career to medieval history.","vi":"Ông dành trọn sự nghiệp học thuật cho lịch sử trung cổ."},{"en":"Publishing papers is essential for a successful academic career.","vi":"Công bố bài báo là điều thiết yếu cho một sự nghiệp học thuật thành công."},{"en":"She began her academic career as a junior lecturer.","vi":"Cô bắt đầu sự nghiệp học thuật với vị trí giảng viên tập sự."}]', '[]', NULL, '/ˌækəˈdemɪk kəˈrɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 4, 'academic circles', 'giới học thuật', 'adj + n', '[{"en":"His theory is widely respected in academic circles.","vi":"Lý thuyết của ông được giới học thuật rất kính trọng."},{"en":"The discovery sparked heated debate in academic circles.","vi":"Phát hiện này làm dấy lên tranh luận sôi nổi trong giới học thuật."},{"en":"Such ideas rarely reach beyond academic circles.","vi":"Những ý tưởng như vậy hiếm khi vượt ra ngoài giới học thuật."}]', '[]', NULL, '/ˌækəˈdemɪk ˈsɜːrkəlz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 5, 'academic community', 'cộng đồng học thuật', 'adj + n', '[{"en":"The academic community welcomed the new research findings.","vi":"Cộng đồng học thuật hoan nghênh các phát hiện nghiên cứu mới."},{"en":"Online journals connect the global academic community.","vi":"Các tạp chí trực tuyến kết nối cộng đồng học thuật toàn cầu."},{"en":"Plagiarism damages trust within the academic community.","vi":"Đạo văn làm tổn hại lòng tin trong cộng đồng học thuật."}]', '[]', NULL, '/ˌækəˈdemɪk kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 6, 'academic debate', 'tranh luận học thuật', 'adj + n', '[{"en":"The topic remains the subject of intense academic debate.","vi":"Chủ đề này vẫn là tâm điểm của những tranh luận học thuật gay gắt."},{"en":"Her paper contributed fresh ideas to the academic debate.","vi":"Bài viết của cô đóng góp những ý tưởng mới cho cuộc tranh luận học thuật."},{"en":"Academic debate helps refine competing theories.","vi":"Tranh luận học thuật giúp hoàn thiện các lý thuyết đối lập."}]', '[]', NULL, '/ˌækəˈdemɪk dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 7, 'academic discipline', 'ngành học, bộ môn học thuật', 'adj + n', '[{"en":"Economics is a well-established academic discipline.","vi":"Kinh tế học là một ngành học đã được khẳng định."},{"en":"Each academic discipline has its own research methods.","vi":"Mỗi ngành học có phương pháp nghiên cứu riêng."},{"en":"The course draws on several academic disciplines.","vi":"Khóa học vận dụng kiến thức từ nhiều ngành học khác nhau."}]', '[]', NULL, '/ˌækəˈdemɪk ˈdɪsəplɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 8, 'academic discourse', 'diễn ngôn học thuật', 'adj + n', '[{"en":"Academic discourse requires precise and formal language.","vi":"Diễn ngôn học thuật đòi hỏi ngôn ngữ chính xác và trang trọng."},{"en":"Students must learn the conventions of academic discourse.","vi":"Sinh viên phải nắm các quy ước của diễn ngôn học thuật."},{"en":"Citations are a key feature of academic discourse.","vi":"Trích dẫn là một đặc trưng quan trọng của diễn ngôn học thuật."}]', '[]', NULL, '/ˌækəˈdemɪk ˈdɪskɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 9, 'academic institution', 'cơ sở, tổ chức học thuật', 'adj + n', '[{"en":"The university is a leading academic institution in the region.","vi":"Trường đại học này là một cơ sở học thuật hàng đầu trong khu vực."},{"en":"Academic institutions rely on funding for research.","vi":"Các cơ sở học thuật dựa vào nguồn tài trợ để nghiên cứu."},{"en":"She works at a prestigious academic institution.","vi":"Cô làm việc tại một tổ chức học thuật danh tiếng."}]', '[]', NULL, '/ˌækəˈdemɪk ˌɪnstɪˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 10, 'academic journal', 'tạp chí học thuật', 'adj + n', '[{"en":"Her study appeared in a respected academic journal.","vi":"Nghiên cứu của cô được đăng trên một tạp chí học thuật uy tín."},{"en":"Peer review ensures the quality of academic journals.","vi":"Bình duyệt đảm bảo chất lượng của các tạp chí học thuật."},{"en":"Access to academic journals is often expensive.","vi":"Việc truy cập các tạp chí học thuật thường tốn kém."}]', '[]', NULL, '/ˌækəˈdemɪk ˈdʒɜːrnəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 11, 'academic life', 'đời sống học thuật', 'adj + n', '[{"en":"Academic life involves both teaching and research.","vi":"Đời sống học thuật bao gồm cả giảng dạy lẫn nghiên cứu."},{"en":"He enjoys the intellectual freedom of academic life.","vi":"Ông tận hưởng sự tự do trí tuệ của đời sống học thuật."},{"en":"Balancing academic life and family can be difficult.","vi":"Cân bằng giữa đời sống học thuật và gia đình có thể rất khó."}]', '[]', NULL, '/ˌækəˈdemɪk laɪf/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 12, 'academic performance', 'kết quả, thành tích học tập', 'adj + n', '[{"en":"Lack of sleep can harm a student''s academic performance.","vi":"Thiếu ngủ có thể ảnh hưởng xấu đến kết quả học tập của sinh viên."},{"en":"The program aims to improve academic performance.","vi":"Chương trình nhằm cải thiện thành tích học tập."},{"en":"Teachers monitor academic performance throughout the year.","vi":"Giáo viên theo dõi kết quả học tập suốt cả năm."}]', '[]', NULL, '/ˌækəˈdemɪk pərˈfɔːrməns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 13, 'academic research', 'nghiên cứu học thuật', 'adj + n', '[{"en":"Academic research often takes years to complete.","vi":"Nghiên cứu học thuật thường mất nhiều năm để hoàn thành."},{"en":"The grant will fund academic research on climate change.","vi":"Khoản tài trợ sẽ cấp kinh phí cho nghiên cứu học thuật về biến đổi khí hậu."},{"en":"Academic research must follow strict ethical guidelines.","vi":"Nghiên cứu học thuật phải tuân theo các nguyên tắc đạo đức nghiêm ngặt."}]', '[]', NULL, '/ˌækəˈdemɪk ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 14, 'academic skills', 'kỹ năng học thuật', 'adj + n', '[{"en":"The workshop helps students develop essential academic skills.","vi":"Buổi tập huấn giúp sinh viên phát triển các kỹ năng học thuật thiết yếu."},{"en":"Note-taking is an important academic skill.","vi":"Ghi chép là một kỹ năng học thuật quan trọng."},{"en":"Strong academic skills improve exam results.","vi":"Kỹ năng học thuật vững vàng giúp cải thiện kết quả thi."}]', '[]', NULL, '/ˌækəˈdemɪk skɪlz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 15, 'academic study', 'việc học, nghiên cứu học thuật', 'adj + n', '[{"en":"Years of academic study prepared her for the role.","vi":"Nhiều năm học tập học thuật đã chuẩn bị cho cô đảm nhận vị trí này."},{"en":"The library is a quiet place for academic study.","vi":"Thư viện là nơi yên tĩnh để học tập."},{"en":"Academic study requires discipline and patience.","vi":"Việc học học thuật đòi hỏi tính kỷ luật và kiên nhẫn."}]', '[]', NULL, '/ˌækəˈdemɪk ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 16, 'academic success', 'thành công trong học tập', 'adj + n', '[{"en":"Motivation is a key factor in academic success.","vi":"Động lực là yếu tố then chốt cho thành công trong học tập."},{"en":"The school credits its methods for students'' academic success.","vi":"Nhà trường cho rằng phương pháp của mình tạo nên thành công học tập của học sinh."},{"en":"Academic success often opens career opportunities.","vi":"Thành công trong học tập thường mở ra cơ hội nghề nghiệp."}]', '[]', NULL, '/ˌækəˈdemɪk səkˈses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 17, 'academic work', 'công việc, bài vở học thuật', 'adj + n', '[{"en":"She submitted her academic work before the deadline.","vi":"Cô nộp bài vở học thuật trước hạn chót."},{"en":"His academic work has been cited many times.","vi":"Công trình học thuật của ông được trích dẫn nhiều lần."},{"en":"Good time management improves academic work.","vi":"Quản lý thời gian tốt giúp nâng cao chất lượng bài vở học thuật."}]', '[]', NULL, '/ˌækəˈdemɪk wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 18, 'academic world', 'thế giới, giới học thuật', 'adj + n', '[{"en":"The academic world can be highly competitive.","vi":"Giới học thuật có thể rất cạnh tranh."},{"en":"Her ideas made an impact on the academic world.","vi":"Những ý tưởng của cô tạo dấu ấn trong giới học thuật."},{"en":"He felt at home in the academic world.","vi":"Ông cảm thấy thoải mái trong thế giới học thuật."}]', '[]', NULL, '/ˌækəˈdemɪk wɜːrld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 19, 'academic writing', 'viết học thuật', 'adj + n', '[{"en":"Academic writing should be clear and well-structured.","vi":"Văn viết học thuật cần rõ ràng và có cấu trúc chặt chẽ."},{"en":"Students take a course in academic writing.","vi":"Sinh viên tham gia một khóa học về viết học thuật."},{"en":"Academic writing avoids slang and contractions.","vi":"Văn viết học thuật tránh tiếng lóng và dạng viết tắt."}]', '[]', NULL, '/ˌækəˈdemɪk ˈraɪtɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 20, 'academic year', 'năm học', 'adj + n', '[{"en":"The academic year begins in early September.","vi":"Năm học bắt đầu vào đầu tháng Chín."},{"en":"Exams are held at the end of the academic year.","vi":"Các kỳ thi diễn ra vào cuối năm học."},{"en":"She studied abroad for one academic year.","vi":"Cô đi du học trong một năm học."}]', '[]', NULL, '/ˌækəˈdemɪk jɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 21, 'accept responsibility', 'nhận trách nhiệm', 'v + n', '[{"en":"The manager agreed to accept responsibility for the error.","vi":"Người quản lý đồng ý nhận trách nhiệm về sai sót này."},{"en":"Leaders must accept responsibility for their decisions.","vi":"Người lãnh đạo phải nhận trách nhiệm cho các quyết định của mình."},{"en":"She refused to accept responsibility for the delay.","vi":"Cô từ chối nhận trách nhiệm về sự chậm trễ."}]', '[]', NULL, '/əkˈsept rɪˌspɑːnsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 22, 'acceptable behavior', 'hành vi chấp nhận được', 'adj + n', '[{"en":"The school sets clear rules for acceptable behavior.","vi":"Nhà trường đặt ra quy định rõ ràng về hành vi chấp nhận được."},{"en":"Honesty is considered acceptable behavior in any workplace.","vi":"Trung thực được xem là hành vi chấp nhận được ở mọi nơi làm việc."},{"en":"What counts as acceptable behavior varies between cultures.","vi":"Hành vi được coi là chấp nhận được khác nhau giữa các nền văn hóa."}]', '[]', NULL, '/əkˈseptəbəl bɪˈheɪvjər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 23, 'accurate assessment', 'đánh giá chính xác', 'adj + n', '[{"en":"Teachers need data for an accurate assessment of progress.","vi":"Giáo viên cần dữ liệu để đánh giá chính xác sự tiến bộ."},{"en":"An accurate assessment of risk is vital for planning.","vi":"Đánh giá rủi ro chính xác là rất quan trọng cho việc lập kế hoạch."},{"en":"The report gives an accurate assessment of the situation.","vi":"Báo cáo đưa ra một đánh giá chính xác về tình hình."}]', '[]', NULL, '/ˈækjərət əˈsesmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 24, 'accurate description', 'mô tả chính xác', 'adj + n', '[{"en":"The witness gave an accurate description of the event.","vi":"Nhân chứng đưa ra một mô tả chính xác về sự việc."},{"en":"An accurate description helps readers picture the scene.","vi":"Mô tả chính xác giúp người đọc hình dung khung cảnh."},{"en":"Scientists aim for an accurate description of nature.","vi":"Các nhà khoa học hướng tới việc mô tả chính xác tự nhiên."}]', '[]', NULL, '/ˈækjərət dɪˈskrɪpʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 25, 'accurate information', 'thông tin chính xác', 'adj + n', '[{"en":"Decisions should be based on accurate information.","vi":"Các quyết định nên dựa trên thông tin chính xác."},{"en":"The website provides accurate information about the course.","vi":"Trang web cung cấp thông tin chính xác về khóa học."},{"en":"Spreading accurate information reduces public confusion.","vi":"Lan truyền thông tin chính xác giúp giảm bối rối trong công chúng."}]', '[]', NULL, '/ˈækjərət ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 26, 'accurate measurement', 'phép đo chính xác', 'adj + n', '[{"en":"Accurate measurement is essential in scientific experiments.","vi":"Phép đo chính xác là thiết yếu trong các thí nghiệm khoa học."},{"en":"The tool allows accurate measurement of temperature.","vi":"Thiết bị cho phép đo nhiệt độ một cách chính xác."},{"en":"Small errors prevent accurate measurement of distance.","vi":"Những sai số nhỏ khiến việc đo khoảng cách thiếu chính xác."}]', '[]', NULL, '/ˈækjərət ˈmeʒərmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 27, 'accurate picture', 'bức tranh, hình dung chính xác', 'adj + n', '[{"en":"The survey gives an accurate picture of public opinion.","vi":"Cuộc khảo sát cho thấy một bức tranh chính xác về dư luận."},{"en":"These figures paint an accurate picture of the economy.","vi":"Những số liệu này phác họa một bức tranh chính xác về nền kinh tế."},{"en":"We need more data for an accurate picture.","vi":"Chúng ta cần thêm dữ liệu để có hình dung chính xác."}]', '[]', NULL, '/ˈækjərət ˈpɪktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 28, 'accurate record', 'hồ sơ, bản ghi chính xác', 'adj + n', '[{"en":"The clinic keeps an accurate record of every patient.","vi":"Phòng khám lưu giữ hồ sơ chính xác của từng bệnh nhân."},{"en":"Accurate records help track spending over time.","vi":"Hồ sơ chính xác giúp theo dõi chi tiêu theo thời gian."},{"en":"Historians rely on accurate records of past events.","vi":"Các nhà sử học dựa vào những bản ghi chính xác về sự kiện quá khứ."}]', '[]', NULL, '/ˈækjərət ˈrekərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 29, 'achieve a goal', 'đạt được mục tiêu', 'v + n', '[{"en":"Hard work helped her achieve her goal of graduating early.","vi":"Sự chăm chỉ giúp cô đạt được mục tiêu tốt nghiệp sớm."},{"en":"The team worked together to achieve a common goal.","vi":"Cả nhóm cùng nhau làm việc để đạt được một mục tiêu chung."},{"en":"Setting small steps makes it easier to achieve a goal.","vi":"Chia thành các bước nhỏ giúp đạt được mục tiêu dễ hơn."}]', '[]', NULL, '/əˈtʃiːv ə ɡoʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 30, 'achieve an objective', 'đạt được mục tiêu (cụ thể)', 'v + n', '[{"en":"The project must achieve its objective within budget.","vi":"Dự án phải đạt được mục tiêu trong khuôn khổ ngân sách."},{"en":"Clear planning helps a company achieve its objective.","vi":"Lập kế hoạch rõ ràng giúp công ty đạt được mục tiêu."},{"en":"They failed to achieve the objective on time.","vi":"Họ không đạt được mục tiêu đúng hạn."}]', '[]', NULL, '/əˈtʃiːv ən əbˈdʒektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 31, 'achieve an outcome', 'đạt được kết quả', 'v + n', '[{"en":"The new method helped achieve a better outcome.","vi":"Phương pháp mới giúp đạt được kết quả tốt hơn."},{"en":"Careful treatment can achieve a positive outcome.","vi":"Điều trị cẩn thận có thể đạt được kết quả tích cực."},{"en":"Both sides worked to achieve a fair outcome.","vi":"Cả hai bên nỗ lực để đạt được một kết quả công bằng."}]', '[]', NULL, '/əˈtʃiːv ən ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 32, 'acquire knowledge', 'thu nhận, tích lũy kiến thức', 'v + n', '[{"en":"Students acquire knowledge through reading and practice.","vi":"Sinh viên thu nhận kiến thức qua việc đọc và thực hành."},{"en":"Travel helps people acquire knowledge of other cultures.","vi":"Du lịch giúp con người thu nhận kiến thức về các nền văn hóa khác."},{"en":"We acquire knowledge gradually over many years.","vi":"Chúng ta tích lũy kiến thức dần dần qua nhiều năm."}]', '[]', NULL, '/əˈkwaɪər ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 33, 'active involvement', 'sự tham gia tích cực', 'adj + n', '[{"en":"Her active involvement in the project improved its outcome.","vi":"Sự tham gia tích cực của cô vào dự án đã cải thiện kết quả."},{"en":"The course rewards active involvement in class discussions.","vi":"Khóa học khuyến khích sự tham gia tích cực vào các buổi thảo luận trên lớp."},{"en":"Active involvement from parents supports student learning.","vi":"Sự tham gia tích cực của phụ huynh hỗ trợ việc học của học sinh."}]', '[]', NULL, '/ˈæktɪv ɪnˈvɑːlvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 34, 'active participant', 'người tham gia tích cực', 'adj + n', '[{"en":"She was an active participant in the debate.","vi":"Cô là một người tham gia tích cực trong cuộc tranh luận."},{"en":"Every active participant received a certificate.","vi":"Mỗi người tham gia tích cực đều nhận được giấy chứng nhận."},{"en":"He became an active participant in community projects.","vi":"Anh trở thành người tham gia tích cực trong các dự án cộng đồng."}]', '[]', NULL, '/ˈæktɪv pɑːrˈtɪsəpənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 35, 'active participation', 'sự tham gia tích cực', 'adj + n', '[{"en":"The class encourages active participation from everyone.","vi":"Lớp học khuyến khích sự tham gia tích cực từ mọi người."},{"en":"Active participation improves language learning.","vi":"Sự tham gia tích cực giúp cải thiện việc học ngôn ngữ."},{"en":"Grades partly depend on active participation.","vi":"Điểm số một phần phụ thuộc vào sự tham gia tích cực."}]', '[]', NULL, '/ˈæktɪv pɑːrˌtɪsəˈpeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 36, 'active role', 'vai trò tích cực, chủ động', 'adj + n', '[{"en":"Teachers play an active role in students'' development.","vi":"Giáo viên giữ vai trò tích cực trong sự phát triển của học sinh."},{"en":"She took an active role in organizing the event.","vi":"Cô đảm nhận vai trò chủ động trong việc tổ chức sự kiện."},{"en":"Citizens can play an active role in local politics.","vi":"Người dân có thể đóng vai trò tích cực trong chính trị địa phương."}]', '[]', NULL, '/ˈæktɪv roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 37, 'actively involved', 'tham gia tích cực, chủ động', 'adv + vpp', '[{"en":"Parents who are actively involved help their children succeed.","vi":"Phụ huynh tham gia tích cực sẽ giúp con cái thành công."},{"en":"She is actively involved in several research projects.","vi":"Cô tham gia tích cực vào nhiều dự án nghiên cứu."},{"en":"Students should be actively involved in their own learning.","vi":"Học sinh nên chủ động tham gia vào việc học của chính mình."}]', '[]', NULL, '/ˈæktɪvli ɪnˈvɑːlvd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 38, 'acutely aware', 'ý thức rõ rệt, sâu sắc', 'adv + adj', '[{"en":"She is acutely aware of the risks involved.","vi":"Cô ý thức rõ rệt về những rủi ro liên quan."},{"en":"The company is acutely aware of customer needs.","vi":"Công ty nhận thức sâu sắc về nhu cầu của khách hàng."},{"en":"He became acutely aware of his own mistakes.","vi":"Anh trở nên ý thức sâu sắc về những lỗi của bản thân."}]', '[]', NULL, '/əˈkjuːtli əˈwer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 39, 'add information', 'bổ sung thông tin', 'v + n', '[{"en":"Please add information about your previous experience.","vi":"Vui lòng bổ sung thông tin về kinh nghiệm trước đây của bạn."},{"en":"The editor asked her to add information to the report.","vi":"Biên tập viên yêu cầu cô bổ sung thông tin vào báo cáo."},{"en":"You can add information to the form at any time.","vi":"Bạn có thể bổ sung thông tin vào biểu mẫu bất cứ lúc nào."}]', '[]', NULL, '/æd ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 40, 'additional cost', 'chi phí phát sinh, chi phí thêm', 'adj + n', '[{"en":"Shipping may involve an additional cost.","vi":"Việc vận chuyển có thể phát sinh thêm chi phí."},{"en":"There is no additional cost for this service.","vi":"Dịch vụ này không có chi phí phát sinh."},{"en":"The repair came at a significant additional cost.","vi":"Việc sửa chữa tốn một khoản chi phí phát sinh đáng kể."}]', '[]', NULL, '/əˈdɪʃənəl kɔːst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 41, 'additional information', 'thông tin bổ sung', 'adj + n', '[{"en":"Please contact us for additional information.","vi":"Vui lòng liên hệ với chúng tôi để biết thêm thông tin."},{"en":"The appendix provides additional information on the method.","vi":"Phần phụ lục cung cấp thông tin bổ sung về phương pháp."},{"en":"She requested additional information before deciding.","vi":"Cô yêu cầu thông tin bổ sung trước khi quyết định."}]', '[]', NULL, '/əˈdɪʃənəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 42, 'additional problem', 'vấn đề phát sinh thêm', 'adj + n', '[{"en":"The delay created an additional problem for the team.","vi":"Sự chậm trễ tạo ra một vấn đề phát sinh thêm cho nhóm."},{"en":"Bad weather added an additional problem to the trip.","vi":"Thời tiết xấu làm phát sinh thêm một vấn đề cho chuyến đi."},{"en":"We solved one issue but faced an additional problem.","vi":"Chúng tôi giải quyết được một việc nhưng lại gặp thêm một vấn đề."}]', '[]', NULL, '/əˈdɪʃənəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 43, 'additional resources', 'nguồn lực bổ sung, tài nguyên thêm', 'adj + n', '[{"en":"The school requested additional resources for the lab.","vi":"Nhà trường đề nghị cấp thêm nguồn lực cho phòng thí nghiệm."},{"en":"Additional resources are needed to finish the project.","vi":"Cần thêm nguồn lực để hoàn thành dự án."},{"en":"Teachers shared additional resources with the students.","vi":"Giáo viên chia sẻ thêm tài nguyên cho học sinh."}]', '[]', NULL, '/əˈdɪʃənəl ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 44, 'additional support', 'hỗ trợ thêm', 'adj + n', '[{"en":"Struggling students receive additional support after class.","vi":"Học sinh gặp khó khăn được hỗ trợ thêm sau giờ học."},{"en":"The government promised additional support for farmers.","vi":"Chính phủ cam kết hỗ trợ thêm cho nông dân."},{"en":"She needed additional support to meet the deadline.","vi":"Cô cần được hỗ trợ thêm để kịp hạn chót."}]', '[]', NULL, '/əˈdɪʃənəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 45, 'address an issue', 'giải quyết vấn đề', 'v + n', '[{"en":"The meeting was held to address the issue of safety.","vi":"Cuộc họp được tổ chức để giải quyết vấn đề an toàn."},{"en":"We must address this issue before it gets worse.","vi":"Chúng ta phải giải quyết vấn đề này trước khi nó tệ hơn."},{"en":"The policy fails to address the real issue.","vi":"Chính sách này không giải quyết được vấn đề cốt lõi."}]', '[]', NULL, '/əˈdres ən ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 46, 'administrative practices', 'thông lệ, quy trình hành chính', 'adj + n', '[{"en":"The company reviewed its administrative practices.","vi":"Công ty rà soát lại các quy trình hành chính của mình."},{"en":"Poor administrative practices slowed the whole process.","vi":"Quy trình hành chính kém làm chậm toàn bộ tiến trình."},{"en":"New software improved their administrative practices.","vi":"Phần mềm mới cải thiện các thông lệ hành chính của họ."}]', '[]', NULL, '/ədˈmɪnəstreɪtɪv ˈpræktɪsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 47, 'adopt a procedure', 'áp dụng quy trình', 'v + n', '[{"en":"The hospital decided to adopt a new procedure.","vi":"Bệnh viện quyết định áp dụng một quy trình mới."},{"en":"Staff were trained to adopt the safety procedure.","vi":"Nhân viên được đào tạo để áp dụng quy trình an toàn."},{"en":"Many firms adopt the same procedure for hiring.","vi":"Nhiều công ty áp dụng cùng một quy trình tuyển dụng."}]', '[]', NULL, '/əˈdɑːpt ə prəˈsiːdʒər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 48, 'adopt an approach', 'áp dụng cách tiếp cận', 'v + n', '[{"en":"Researchers decided to adopt a different approach.","vi":"Các nhà nghiên cứu quyết định áp dụng một cách tiếp cận khác."},{"en":"The teacher adopts a flexible approach to learning.","vi":"Giáo viên áp dụng một cách tiếp cận linh hoạt cho việc học."},{"en":"We should adopt a more practical approach.","vi":"Chúng ta nên áp dụng một cách tiếp cận thực tế hơn."}]', '[]', NULL, '/əˈdɑːpt ən əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 49, 'advanced economy', 'nền kinh tế phát triển', 'adj + n', '[{"en":"Japan is often cited as an advanced economy.","vi":"Nhật Bản thường được xem là một nền kinh tế phát triển."},{"en":"An advanced economy depends on skilled workers.","vi":"Một nền kinh tế phát triển phụ thuộc vào lao động lành nghề."},{"en":"Advanced economies invest heavily in technology.","vi":"Các nền kinh tế phát triển đầu tư mạnh vào công nghệ."}]', '[]', NULL, '/ədˈvænst ɪˈkɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 50, 'advanced technology', 'công nghệ tiên tiến', 'adj + n', '[{"en":"The factory uses advanced technology to cut waste.","vi":"Nhà máy sử dụng công nghệ tiên tiến để giảm lãng phí."},{"en":"Advanced technology has transformed modern medicine.","vi":"Công nghệ tiên tiến đã thay đổi nền y học hiện đại."},{"en":"The country exports advanced technology worldwide.","vi":"Quốc gia này xuất khẩu công nghệ tiên tiến ra toàn thế giới."}]', '[]', NULL, '/ədˈvænst tekˈnɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 51, 'adverse effect', 'tác động bất lợi', 'adj + n', '[{"en":"The drug may have an adverse effect on the liver.","vi":"Loại thuốc này có thể gây tác động bất lợi lên gan."},{"en":"Pollution has an adverse effect on public health.","vi":"Ô nhiễm gây tác động bất lợi đến sức khỏe cộng đồng."},{"en":"Stress can have an adverse effect on sleep.","vi":"Căng thẳng có thể gây tác động bất lợi đến giấc ngủ."}]', '[]', NULL, '/ædˈvɜːrs ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 52, 'adverse reaction', 'phản ứng bất lợi', 'adj + n', '[{"en":"Some patients had an adverse reaction to the vaccine.","vi":"Một số bệnh nhân có phản ứng bất lợi với vắc-xin."},{"en":"Report any adverse reaction to your doctor immediately.","vi":"Hãy báo ngay cho bác sĩ về bất kỳ phản ứng bất lợi nào."},{"en":"The new policy provoked an adverse reaction from staff.","vi":"Chính sách mới gây ra phản ứng bất lợi từ nhân viên."}]', '[]', NULL, '/ædˈvɜːrs riˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 53, 'adversely affect', 'ảnh hưởng xấu, ảnh hưởng bất lợi', 'adv + v', '[{"en":"Noise can adversely affect concentration.","vi":"Tiếng ồn có thể ảnh hưởng xấu đến sự tập trung."},{"en":"The drought adversely affected this year''s harvest.","vi":"Hạn hán ảnh hưởng bất lợi đến vụ mùa năm nay."},{"en":"High fees may adversely affect enrollment.","vi":"Học phí cao có thể ảnh hưởng xấu đến số lượng nhập học."}]', '[]', NULL, '/ædˈvɜːrsli əˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 54, 'affect the outcome', 'ảnh hưởng đến kết quả', 'v + n', '[{"en":"Many factors can affect the outcome of the experiment.","vi":"Nhiều yếu tố có thể ảnh hưởng đến kết quả của thí nghiệm."},{"en":"Weather may affect the outcome of the match.","vi":"Thời tiết có thể ảnh hưởng đến kết quả trận đấu."},{"en":"Bias can seriously affect the outcome of a study.","vi":"Sự thiên lệch có thể ảnh hưởng nghiêm trọng đến kết quả nghiên cứu."}]', '[]', NULL, '/əˈfekt ði ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 55, 'affect the development of', 'ảnh hưởng đến sự phát triển', 'v + n', '[{"en":"Early nutrition can affect a child''s development.","vi":"Dinh dưỡng sớm có thể ảnh hưởng đến sự phát triển của trẻ."},{"en":"Government policy may affect economic development.","vi":"Chính sách của chính phủ có thể ảnh hưởng đến sự phát triển kinh tế."},{"en":"Stress can affect the development of the brain.","vi":"Căng thẳng có thể ảnh hưởng đến sự phát triển của não bộ."}]', '[]', NULL, '/əˈfekt ðə dɪˈveləpmənt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 56, 'allocate resources', 'phân bổ nguồn lực', 'v + n', '[{"en":"Managers must allocate resources wisely.","vi":"Người quản lý phải phân bổ nguồn lực một cách khôn ngoan."},{"en":"The government allocates resources to public health.","vi":"Chính phủ phân bổ nguồn lực cho y tế công cộng."},{"en":"We need to allocate resources to the most urgent tasks.","vi":"Chúng ta cần phân bổ nguồn lực cho những nhiệm vụ cấp bách nhất."}]', '[]', NULL, '/ˈæləkeɪt ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 57, 'allow access to', 'cho phép truy cập, cho phép tiếp cận', 'v + n', '[{"en":"The pass will allow access to all areas.","vi":"Thẻ này sẽ cho phép truy cập vào mọi khu vực."},{"en":"The library allows access to rare manuscripts.","vi":"Thư viện cho phép tiếp cận các bản thảo quý hiếm."},{"en":"The system does not allow access without a password.","vi":"Hệ thống không cho phép truy cập nếu không có mật khẩu."}]', '[]', NULL, '/əˈlaʊ ˈækses tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 58, 'almost identical', 'gần như giống hệt', 'adv + adj', '[{"en":"The two samples were almost identical.","vi":"Hai mẫu vật gần như giống hệt nhau."},{"en":"Their results were almost identical to ours.","vi":"Kết quả của họ gần như giống hệt của chúng tôi."},{"en":"The twins look almost identical.","vi":"Cặp song sinh trông gần như giống hệt nhau."}]', '[]', NULL, '/ˈɔːlmoʊst aɪˈdentɪkəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 59, 'alternative approach', 'cách tiếp cận khác', 'adj + n', '[{"en":"When one method fails, try an alternative approach.","vi":"Khi một phương pháp thất bại, hãy thử một cách tiếp cận khác."},{"en":"The team proposed an alternative approach to the problem.","vi":"Nhóm đề xuất một cách tiếp cận khác cho vấn đề."},{"en":"An alternative approach might save both time and money.","vi":"Một cách tiếp cận khác có thể tiết kiệm cả thời gian lẫn tiền bạc."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 60, 'alternative explanation', 'lời giải thích khác', 'adj + n', '[{"en":"Scientists offered an alternative explanation for the data.","vi":"Các nhà khoa học đưa ra một lời giải thích khác cho dữ liệu."},{"en":"There may be an alternative explanation for his behavior.","vi":"Có thể có một lời giải thích khác cho hành vi của anh ta."},{"en":"She rejected the alternative explanation as unlikely.","vi":"Cô bác bỏ lời giải thích khác vì cho rằng khó xảy ra."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv ˌekspləˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 61, 'alternative form', 'hình thức khác, dạng thay thế', 'adj + n', '[{"en":"Solar power is an alternative form of energy.","vi":"Năng lượng mặt trời là một dạng năng lượng thay thế."},{"en":"The essay can be submitted in an alternative form.","vi":"Bài luận có thể được nộp dưới một hình thức khác."},{"en":"Sign language is an alternative form of communication.","vi":"Ngôn ngữ ký hiệu là một hình thức giao tiếp khác."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv fɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 62, 'alternative interpretation', 'cách diễn giải khác', 'adj + n', '[{"en":"The poem allows for an alternative interpretation.","vi":"Bài thơ cho phép một cách diễn giải khác."},{"en":"He proposed an alternative interpretation of the results.","vi":"Ông đề xuất một cách diễn giải khác về kết quả."},{"en":"An alternative interpretation challenges the old theory.","vi":"Một cách diễn giải khác thách thức lý thuyết cũ."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv ɪnˌtɜːrprəˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 63, 'alternative means', 'phương tiện khác, cách thức khác', 'adj + n', '[{"en":"Cycling is an alternative means of transport.","vi":"Đạp xe là một phương tiện di chuyển khác."},{"en":"They sought alternative means of funding the project.","vi":"Họ tìm những cách thức khác để tài trợ cho dự án."},{"en":"Email offers an alternative means of contact.","vi":"Email cung cấp một phương tiện liên lạc khác."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv miːnz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 64, 'alternative method', 'phương pháp khác', 'adj + n', '[{"en":"Researchers tested an alternative method of analysis.","vi":"Các nhà nghiên cứu thử một phương pháp phân tích khác."},{"en":"An alternative method produced faster results.","vi":"Một phương pháp khác cho kết quả nhanh hơn."},{"en":"She prefers the alternative method of teaching.","vi":"Cô thích phương pháp giảng dạy khác hơn."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 65, 'alternative model', 'mô hình khác', 'adj + n', '[{"en":"Economists proposed an alternative model of growth.","vi":"Các nhà kinh tế đề xuất một mô hình tăng trưởng khác."},{"en":"The study tests an alternative model of behavior.","vi":"Nghiên cứu kiểm tra một mô hình hành vi khác."},{"en":"An alternative model better explains the findings.","vi":"Một mô hình khác giải thích các phát hiện tốt hơn."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv ˈmɑːdəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 66, 'alternative solution', 'giải pháp khác', 'adj + n', '[{"en":"If this fails, we need an alternative solution.","vi":"Nếu cách này thất bại, ta cần một giải pháp khác."},{"en":"Engineers searched for an alternative solution.","vi":"Các kỹ sư tìm kiếm một giải pháp khác."},{"en":"The committee rejected the alternative solution.","vi":"Ủy ban bác bỏ giải pháp khác."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv səˈluːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 67, 'alternative source', 'nguồn khác, nguồn thay thế', 'adj + n', '[{"en":"Wind is an alternative source of energy.","vi":"Gió là một nguồn năng lượng khác."},{"en":"Journalists confirmed it with an alternative source.","vi":"Các nhà báo xác nhận điều đó qua một nguồn khác."},{"en":"We must find an alternative source of funding.","vi":"Chúng ta phải tìm một nguồn tài trợ khác."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 68, 'alternative strategy', 'chiến lược khác', 'adj + n', '[{"en":"The company adopted an alternative strategy to grow.","vi":"Công ty áp dụng một chiến lược khác để phát triển."},{"en":"An alternative strategy reduced their losses.","vi":"Một chiến lược khác giúp giảm thiệt hại của họ."},{"en":"Coaches prepared an alternative strategy for the final.","vi":"Các huấn luyện viên chuẩn bị một chiến lược khác cho trận chung kết."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv ˈstrætədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 69, 'alternative view', 'quan điểm khác', 'adj + n', '[{"en":"She presented an alternative view of the issue.","vi":"Cô trình bày một quan điểm khác về vấn đề."},{"en":"The article offers an alternative view of history.","vi":"Bài báo đưa ra một quan điểm khác về lịch sử."},{"en":"It is healthy to consider an alternative view.","vi":"Việc xem xét một quan điểm khác là điều lành mạnh."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv vjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 70, 'alternative way', 'cách khác', 'adj + n', '[{"en":"There must be an alternative way to solve this.","vi":"Hẳn phải có một cách khác để giải quyết việc này."},{"en":"She found an alternative way to reach the office.","vi":"Cô tìm được một cách khác để đến văn phòng."},{"en":"Technology offers an alternative way of learning.","vi":"Công nghệ mang đến một cách học khác."}]', '[]', NULL, '/ɔːlˈtɜːrnətɪv weɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 71, 'ample evidence', 'bằng chứng dồi dào, đầy đủ', 'adj + n', '[{"en":"There is ample evidence to support the theory.","vi":"Có bằng chứng dồi dào để ủng hộ lý thuyết này."},{"en":"The study provides ample evidence of the trend.","vi":"Nghiên cứu cung cấp bằng chứng đầy đủ về xu hướng này."},{"en":"Ample evidence shows that exercise improves health.","vi":"Bằng chứng dồi dào cho thấy tập thể dục cải thiện sức khỏe."}]', '[]', NULL, '/ˈæmpəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 72, 'analytical approach', 'cách tiếp cận phân tích', 'adj + n', '[{"en":"An analytical approach helps break down complex problems.","vi":"Cách tiếp cận phân tích giúp chia nhỏ các vấn đề phức tạp."},{"en":"She takes an analytical approach to research.","vi":"Cô áp dụng cách tiếp cận phân tích trong nghiên cứu."},{"en":"The job requires a careful, analytical approach.","vi":"Công việc đòi hỏi một cách tiếp cận phân tích cẩn thận."}]', '[]', NULL, '/ˌænəˈlɪtɪkəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 73, 'analytical tool', 'công cụ phân tích', 'adj + n', '[{"en":"Statistics is a powerful analytical tool.","vi":"Thống kê là một công cụ phân tích mạnh mẽ."},{"en":"The software is a useful analytical tool for data.","vi":"Phần mềm là một công cụ phân tích dữ liệu hữu ích."},{"en":"Researchers developed a new analytical tool.","vi":"Các nhà nghiên cứu phát triển một công cụ phân tích mới."}]', '[]', NULL, '/ˌænəˈlɪtɪkəl tuːl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 74, 'anecdotal evidence', 'bằng chứng giai thoại, truyền miệng', 'adj + n', '[{"en":"Anecdotal evidence is not enough to prove the claim.","vi":"Bằng chứng giai thoại không đủ để chứng minh khẳng định này."},{"en":"He relied on anecdotal evidence rather than data.","vi":"Anh ta dựa vào bằng chứng truyền miệng thay vì dữ liệu."},{"en":"Anecdotal evidence suggests the method works.","vi":"Bằng chứng giai thoại cho thấy phương pháp này có hiệu quả."}]', '[]', NULL, '/ˌænɪkˈdoʊtəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 75, 'annual conference', 'hội nghị thường niên', 'adj + n', '[{"en":"The annual conference attracts experts from many countries.","vi":"Hội nghị thường niên thu hút chuyên gia từ nhiều quốc gia."},{"en":"She presented her findings at the annual conference.","vi":"Cô trình bày các phát hiện tại hội nghị thường niên."},{"en":"The annual conference will be held online this year.","vi":"Hội nghị thường niên năm nay sẽ được tổ chức trực tuyến."}]', '[]', NULL, '/ˈænjuəl ˈkɑːnfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 76, 'annual meeting', 'cuộc họp thường niên', 'adj + n', '[{"en":"Shareholders gather for the annual meeting.","vi":"Các cổ đông tụ họp trong cuộc họp thường niên."},{"en":"The annual meeting reviews the year''s progress.","vi":"Cuộc họp thường niên đánh giá tiến độ của cả năm."},{"en":"Decisions are made at the annual meeting.","vi":"Các quyết định được đưa ra tại cuộc họp thường niên."}]', '[]', NULL, '/ˈænjuəl ˈmiːtɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 77, 'annual rate', 'tỷ lệ hằng năm, lãi suất hằng năm', 'adj + n', '[{"en":"The loan has an annual rate of five percent.","vi":"Khoản vay có lãi suất hằng năm là năm phần trăm."},{"en":"Inflation reached an annual rate of three percent.","vi":"Lạm phát đạt tỷ lệ hằng năm là ba phần trăm."},{"en":"The annual rate of growth slowed last year.","vi":"Tỷ lệ tăng trưởng hằng năm chậm lại vào năm ngoái."}]', '[]', NULL, '/ˈænjuəl reɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 78, 'annual report', 'báo cáo thường niên', 'adj + n', '[{"en":"The company published its annual report online.","vi":"Công ty công bố báo cáo thường niên trực tuyến."},{"en":"The annual report shows a rise in profits.","vi":"Báo cáo thường niên cho thấy lợi nhuận tăng."},{"en":"Investors study the annual report carefully.","vi":"Các nhà đầu tư nghiên cứu kỹ báo cáo thường niên."}]', '[]', NULL, '/ˈænjuəl rɪˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 79, 'annual review', 'đánh giá thường niên', 'adj + n', '[{"en":"Employees receive feedback during the annual review.","vi":"Nhân viên nhận phản hồi trong kỳ đánh giá thường niên."},{"en":"The annual review highlighted several achievements.","vi":"Bản đánh giá thường niên nêu bật nhiều thành tựu."},{"en":"Her salary increased after the annual review.","vi":"Lương của cô tăng sau kỳ đánh giá thường niên."}]', '[]', NULL, '/ˈænjuəl rɪˈvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 80, 'apply equally', 'áp dụng như nhau, áp dụng bình đẳng', 'v + adv', '[{"en":"The rules apply equally to all students.","vi":"Các quy định áp dụng như nhau cho mọi học sinh."},{"en":"This principle applies equally in both cases.","vi":"Nguyên tắc này áp dụng như nhau trong cả hai trường hợp."},{"en":"The law should apply equally to everyone.","vi":"Luật pháp nên áp dụng bình đẳng cho tất cả mọi người."}]', '[]', NULL, '/əˈplaɪ ˈiːkwəli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 81, 'apply a method', 'áp dụng phương pháp', 'v + n', '[{"en":"Researchers apply a scientific method to the study.","vi":"Các nhà nghiên cứu áp dụng phương pháp khoa học cho nghiên cứu."},{"en":"You can apply this method to similar problems.","vi":"Bạn có thể áp dụng phương pháp này cho các vấn đề tương tự."},{"en":"She applied a new method to analyze the results.","vi":"Cô áp dụng một phương pháp mới để phân tích kết quả."}]', '[]', NULL, '/əˈplaɪ ə ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 82, 'apply the theory', 'áp dụng lý thuyết', 'v + n', '[{"en":"Students learn to apply theory to real situations.","vi":"Sinh viên học cách áp dụng lý thuyết vào tình huống thực tế."},{"en":"It is hard to apply theory without practice.","vi":"Khó áp dụng lý thuyết nếu thiếu thực hành."},{"en":"Engineers apply theory to design safer bridges.","vi":"Các kỹ sư áp dụng lý thuyết để thiết kế những cây cầu an toàn hơn."}]', '[]', NULL, '/əˈplaɪ ðə ˈθɪri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 83, 'appropriate action', 'hành động phù hợp', 'adj + n', '[{"en":"The committee took appropriate action to resolve the dispute quickly.","vi":"Ủy ban đã có hành động phù hợp để giải quyết tranh chấp nhanh chóng."},{"en":"Managers must decide on appropriate action when problems arise.","vi":"Người quản lý phải quyết định hành động phù hợp khi vấn đề phát sinh."},{"en":"Failing to take appropriate action can worsen the situation.","vi":"Không có hành động phù hợp có thể khiến tình hình tồi tệ hơn."}]', '[]', NULL, '/əˈproʊpriət ˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 84, 'appropriate behavior', 'hành vi phù hợp', 'adj + n', '[{"en":"Teachers model appropriate behavior for young children in class.","vi":"Giáo viên làm gương về hành vi phù hợp cho trẻ nhỏ trong lớp."},{"en":"The handbook defines appropriate behavior in the workplace clearly.","vi":"Cẩm nang quy định rõ hành vi phù hợp tại nơi làm việc."},{"en":"Students learn appropriate behavior through consistent rules and feedback.","vi":"Học sinh học hành vi phù hợp qua các quy tắc và phản hồi nhất quán."}]', '[]', NULL, '/əˈproʊpriət bɪˈheɪvjər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 85, 'appropriate conditions', 'điều kiện phù hợp', 'adj + n', '[{"en":"Plants grow well only under appropriate conditions of light.","vi":"Cây chỉ phát triển tốt trong điều kiện ánh sáng phù hợp."},{"en":"Researchers created appropriate conditions for the experiment to succeed.","vi":"Các nhà nghiên cứu tạo điều kiện phù hợp để thí nghiệm thành công."},{"en":"Appropriate conditions are essential for storing sensitive chemical samples.","vi":"Điều kiện phù hợp rất cần thiết để bảo quản mẫu hóa chất nhạy cảm."}]', '[]', NULL, '/əˈproʊpriət kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 86, 'appropriate data', 'dữ liệu phù hợp', 'adj + n', '[{"en":"Selecting appropriate data is the first step in any analysis.","vi":"Chọn dữ liệu phù hợp là bước đầu tiên trong mọi phân tích."},{"en":"Without appropriate data, the conclusions remain weak and unreliable.","vi":"Nếu thiếu dữ liệu phù hợp, kết luận sẽ yếu và không đáng tin."},{"en":"The team gathered appropriate data from several reliable sources.","vi":"Nhóm đã thu thập dữ liệu phù hợp từ nhiều nguồn đáng tin cậy."}]', '[]', NULL, '/əˈproʊpriət ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 87, 'appropriate form', 'hình thức phù hợp', 'adj + n', '[{"en":"Choose the appropriate form to present your research findings clearly.","vi":"Hãy chọn hình thức phù hợp để trình bày rõ kết quả nghiên cứu."},{"en":"Data should be stored in an appropriate form for analysis.","vi":"Dữ liệu nên được lưu ở hình thức phù hợp để phân tích."},{"en":"The instructor explained the appropriate form for citing sources.","vi":"Giảng viên giải thích hình thức phù hợp để trích dẫn nguồn."}]', '[]', NULL, '/əˈproʊpriət fɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 88, 'appropriate language', 'ngôn ngữ phù hợp', 'adj + n', '[{"en":"Academic essays require appropriate language and a formal tone.","vi":"Bài luận học thuật đòi hỏi ngôn ngữ phù hợp và giọng văn trang trọng."},{"en":"Using appropriate language helps readers understand complex ideas easily.","vi":"Dùng ngôn ngữ phù hợp giúp người đọc hiểu ý phức tạp dễ dàng."},{"en":"The teacher praised her appropriate language during the formal presentation.","vi":"Giáo viên khen ngôn ngữ phù hợp của cô trong bài thuyết trình trang trọng."}]', '[]', NULL, '/əˈproʊpriət ˈlæŋɡwɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 89, 'appropriate level', 'mức độ phù hợp', 'adj + n', '[{"en":"The course is taught at an appropriate level for beginners.","vi":"Khóa học được dạy ở mức độ phù hợp cho người mới bắt đầu."},{"en":"Maintaining an appropriate level of difficulty keeps students motivated.","vi":"Giữ mức độ khó phù hợp giúp học sinh duy trì động lực."},{"en":"Managers set tasks at an appropriate level for each employee.","vi":"Quản lý giao việc ở mức độ phù hợp với từng nhân viên."}]', '[]', NULL, '/əˈproʊpriət ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 90, 'appropriate point', 'thời điểm phù hợp', 'adj + n', '[{"en":"Raise your questions at an appropriate point during the lecture.","vi":"Hãy nêu câu hỏi vào thời điểm phù hợp trong buổi giảng."},{"en":"The author introduces the theory at an appropriate point.","vi":"Tác giả giới thiệu lý thuyết vào thời điểm phù hợp."},{"en":"Stopping the discussion at an appropriate point avoids confusion.","vi":"Dừng thảo luận vào thời điểm phù hợp giúp tránh nhầm lẫn."}]', '[]', NULL, '/əˈproʊpriət pɔɪnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 91, 'appropriate response', 'phản ứng phù hợp', 'adj + n', '[{"en":"An appropriate response to criticism is to listen calmly.","vi":"Một phản ứng phù hợp với lời chỉ trích là lắng nghe bình tĩnh."},{"en":"The government''s appropriate response reduced public panic during the crisis.","vi":"Phản ứng phù hợp của chính phủ đã giảm hoảng loạn trong khủng hoảng."},{"en":"Choosing an appropriate response requires understanding the whole situation.","vi":"Chọn phản ứng phù hợp đòi hỏi hiểu rõ toàn bộ tình huống."}]', '[]', NULL, '/əˈproʊpriət rɪˈspɑːns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 92, 'appropriate skills', 'kỹ năng phù hợp', 'adj + n', '[{"en":"Employers look for candidates with the appropriate skills and experience.","vi":"Nhà tuyển dụng tìm ứng viên có kỹ năng phù hợp và kinh nghiệm."},{"en":"The program develops appropriate skills for the modern workplace.","vi":"Chương trình phát triển kỹ năng phù hợp cho nơi làm việc hiện đại."},{"en":"Without appropriate skills, completing the task becomes very difficult.","vi":"Nếu thiếu kỹ năng phù hợp, việc hoàn thành nhiệm vụ trở nên rất khó."}]', '[]', NULL, '/əˈproʊpriət skɪlz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 93, 'appropriate treatment', 'phương pháp điều trị phù hợp', 'adj + n', '[{"en":"Doctors recommend appropriate treatment based on each patient''s condition.","vi":"Bác sĩ đề xuất điều trị phù hợp dựa trên tình trạng từng bệnh nhân."},{"en":"Early diagnosis allows for more appropriate treatment of the disease.","vi":"Chẩn đoán sớm cho phép điều trị bệnh phù hợp hơn."},{"en":"The study compared appropriate treatment options for chronic pain.","vi":"Nghiên cứu so sánh các phương pháp điều trị phù hợp cho cơn đau mãn tính."}]', '[]', NULL, '/əˈproʊpriət ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 94, 'appropriate way', 'cách thức phù hợp', 'adj + n', '[{"en":"There is an appropriate way to address senior colleagues formally.","vi":"Có một cách thức phù hợp để xưng hô trang trọng với đồng nghiệp lớn tuổi."},{"en":"The manual describes the appropriate way to handle equipment.","vi":"Sổ tay mô tả cách thức phù hợp để vận hành thiết bị."},{"en":"Finding the appropriate way to explain results helps readers.","vi":"Tìm cách thức phù hợp để giải thích kết quả giúp ích cho người đọc."}]', '[]', NULL, '/əˈproʊpriət weɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 95, 'armed conflict', 'xung đột vũ trang', 'adj + n', '[{"en":"Millions of people were displaced by the long armed conflict.","vi":"Hàng triệu người phải di tản vì xung đột vũ trang kéo dài."},{"en":"The treaty aimed to end decades of armed conflict.","vi":"Hiệp ước nhằm chấm dứt hàng chục năm xung đột vũ trang."},{"en":"Researchers study how armed conflict affects civilian populations and economies.","vi":"Các nhà nghiên cứu tìm hiểu xung đột vũ trang ảnh hưởng dân thường và kinh tế thế nào."}]', '[]', NULL, '/ɑːrmd ˈkɑːnflɪkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 96, 'artificial intelligence', 'trí tuệ nhân tạo', 'adj + n', '[{"en":"Artificial intelligence is transforming how businesses analyze large datasets.","vi":"Trí tuệ nhân tạo đang thay đổi cách doanh nghiệp phân tích dữ liệu lớn."},{"en":"The university offers a new course on artificial intelligence.","vi":"Trường đại học mở một khóa học mới về trí tuệ nhân tạo."},{"en":"Many jobs may change as artificial intelligence becomes more advanced.","vi":"Nhiều công việc có thể thay đổi khi trí tuệ nhân tạo tiến bộ hơn."}]', '[]', NULL, '/ˌɑːrtɪˈfɪʃəl ɪnˈtelɪdʒəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 97, 'assess the impact of', 'đánh giá tác động của', 'v + n', '[{"en":"Scientists assess the impact of climate change on coastal cities.","vi":"Các nhà khoa học đánh giá tác động của biến đổi khí hậu lên thành phố ven biển."},{"en":"The report tries to assess the impact of new policies.","vi":"Báo cáo cố gắng đánh giá tác động của các chính sách mới."},{"en":"We must assess the impact of advertising on consumer choices.","vi":"Chúng ta phải đánh giá tác động của quảng cáo lên lựa chọn người tiêu dùng."}]', '[]', NULL, '/əˈses ði ˈɪmpækt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 98, 'assessment process', 'quá trình đánh giá', 'n + n', '[{"en":"The assessment process includes written tests and practical exercises.","vi":"Quá trình đánh giá gồm bài kiểm tra viết và bài thực hành."},{"en":"A fair assessment process ensures all students are treated equally.","vi":"Quá trình đánh giá công bằng đảm bảo mọi học sinh được đối xử như nhau."},{"en":"Teachers explained each stage of the assessment process clearly.","vi":"Giáo viên giải thích rõ từng giai đoạn của quá trình đánh giá."}]', '[]', NULL, '/əˈsesmənt ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 99, 'associated factors', 'các yếu tố liên quan', 'adj + n', '[{"en":"The study identified several associated factors that influence student performance.","vi":"Nghiên cứu xác định một số yếu tố liên quan ảnh hưởng đến thành tích học sinh."},{"en":"Researchers examined associated factors linked to high blood pressure.","vi":"Các nhà nghiên cứu khảo sát yếu tố liên quan đến huyết áp cao."},{"en":"Understanding associated factors helps doctors prevent the disease early.","vi":"Hiểu các yếu tố liên quan giúp bác sĩ phòng bệnh sớm."}]', '[]', NULL, '/əˈsoʊsieɪtɪd ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 100, 'assume responsibility', 'đảm nhận trách nhiệm', 'v + n', '[{"en":"New managers must assume responsibility for their team''s results.","vi":"Quản lý mới phải đảm nhận trách nhiệm về kết quả của nhóm mình."},{"en":"She agreed to assume responsibility for the entire research project.","vi":"Cô đồng ý đảm nhận trách nhiệm cho toàn bộ dự án nghiên cứu."},{"en":"Citizens should assume responsibility for protecting their local environment.","vi":"Người dân nên đảm nhận trách nhiệm bảo vệ môi trường địa phương."}]', '[]', NULL, '/əˈsuːm rɪˌspɑːnsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 101, 'assume the role of', 'đảm nhận vai trò', 'v + n', '[{"en":"She will assume the role of department head next month.","vi":"Cô sẽ đảm nhận vai trò trưởng phòng vào tháng tới."},{"en":"In the experiment, students assume the role of observers.","vi":"Trong thí nghiệm, học sinh đảm nhận vai trò người quan sát."},{"en":"Older siblings often assume the role of caregivers at home.","vi":"Anh chị lớn thường đảm nhận vai trò người chăm sóc ở nhà."}]', '[]', NULL, '/əˈsuːm ðə roʊl əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 102, 'atomic energy', 'năng lượng nguyên tử', 'adj + n', '[{"en":"Atomic energy can generate large amounts of electricity efficiently.","vi":"Năng lượng nguyên tử có thể tạo ra lượng điện lớn một cách hiệu quả."},{"en":"The agency monitors the peaceful use of atomic energy worldwide.","vi":"Cơ quan này giám sát việc sử dụng hòa bình năng lượng nguyên tử toàn cầu."},{"en":"Debates about atomic energy focus on safety and waste.","vi":"Các tranh luận về năng lượng nguyên tử tập trung vào an toàn và chất thải."}]', '[]', NULL, '/əˈtɑːmɪk ˈenərdʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 103, 'attend a conference', 'tham dự một hội nghị', 'v + n', '[{"en":"She will attend a conference on renewable energy next week.","vi":"Cô sẽ tham dự một hội nghị về năng lượng tái tạo vào tuần tới."},{"en":"Many researchers travel abroad to attend a conference each year.","vi":"Nhiều nhà nghiên cứu ra nước ngoài để tham dự một hội nghị mỗi năm."},{"en":"Students were encouraged to attend a conference and present posters.","vi":"Sinh viên được khuyến khích tham dự một hội nghị và trình bày áp phích."}]', '[]', NULL, '/əˈtend ə ˈkɑːnfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 104, 'available data', 'dữ liệu sẵn có', 'adj + n', '[{"en":"The conclusion is based on all the available data so far.","vi":"Kết luận dựa trên toàn bộ dữ liệu sẵn có cho đến nay."},{"en":"Limited available data made the analysis quite challenging for researchers.","vi":"Dữ liệu sẵn có hạn chế khiến việc phân tích khá khó với các nhà nghiên cứu."},{"en":"They reviewed available data before designing the new survey.","vi":"Họ xem lại dữ liệu sẵn có trước khi thiết kế khảo sát mới."}]', '[]', NULL, '/əˈveɪləbəl ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 105, 'available evidence', 'bằng chứng sẵn có', 'adj + n', '[{"en":"The available evidence strongly supports the researcher''s main hypothesis.","vi":"Bằng chứng sẵn có ủng hộ mạnh mẽ giả thuyết chính của nhà nghiên cứu."},{"en":"Based on available evidence, the court reached a fair decision.","vi":"Dựa trên bằng chứng sẵn có, tòa án đã đưa ra phán quyết công bằng."},{"en":"Scientists must weigh all available evidence before drawing conclusions.","vi":"Các nhà khoa học phải cân nhắc mọi bằng chứng sẵn có trước khi kết luận."}]', '[]', NULL, '/əˈveɪləbəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 106, 'available information', 'thông tin sẵn có', 'adj + n', '[{"en":"Make your decision using all the available information you have.","vi":"Hãy đưa ra quyết định bằng mọi thông tin sẵn có mà bạn có."},{"en":"The website gathers available information about local public transport services.","vi":"Trang web tập hợp thông tin sẵn có về dịch vụ giao thông công cộng địa phương."},{"en":"With little available information, predicting the outcome proved difficult.","vi":"Với ít thông tin sẵn có, việc dự đoán kết quả trở nên khó khăn."}]', '[]', NULL, '/əˈveɪləbəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 107, 'available resources', 'nguồn lực sẵn có', 'adj + n', '[{"en":"The team completed the project using only available resources efficiently.","vi":"Nhóm hoàn thành dự án chỉ bằng nguồn lực sẵn có một cách hiệu quả."},{"en":"Schools must make the best use of available resources.","vi":"Trường học phải tận dụng tốt nhất nguồn lực sẵn có."},{"en":"Limited available resources forced the charity to set priorities.","vi":"Nguồn lực sẵn có hạn chế buộc tổ chức từ thiện phải đặt ưu tiên."}]', '[]', NULL, '/əˈveɪləbəl ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 108, 'average score', 'điểm trung bình', 'adj + n', '[{"en":"The class achieved an average score above the national level.","vi":"Lớp đạt điểm trung bình cao hơn mức của cả nước."},{"en":"Her average score improved steadily throughout the entire semester.","vi":"Điểm trung bình của cô cải thiện đều đặn suốt cả học kỳ."},{"en":"The report compares the average score of different age groups.","vi":"Báo cáo so sánh điểm trung bình của các nhóm tuổi khác nhau."}]', '[]', NULL, '/ˈævərɪdʒ skɔːr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 109, 'background knowledge', 'kiến thức nền', 'n + n', '[{"en":"Strong background knowledge helps students understand difficult academic texts.","vi":"Kiến thức nền vững giúp học sinh hiểu các văn bản học thuật khó."},{"en":"The lecture assumes some background knowledge of basic economics.","vi":"Bài giảng giả định người học có kiến thức nền về kinh tế cơ bản."},{"en":"Readers with little background knowledge may find the article confusing.","vi":"Người đọc thiếu kiến thức nền có thể thấy bài viết khó hiểu."}]', '[]', NULL, '/ˈbækɡraʊnd ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 110, 'basic assumption', 'giả định cơ bản', 'adj + n', '[{"en":"The model rests on a basic assumption about human behavior.","vi":"Mô hình dựa trên một giả định cơ bản về hành vi con người."},{"en":"If the basic assumption is wrong, the whole theory fails.","vi":"Nếu giả định cơ bản sai, toàn bộ lý thuyết sẽ thất bại."},{"en":"Economists often question the basic assumption that people act rationally.","vi":"Các nhà kinh tế thường nghi ngờ giả định cơ bản rằng con người hành động hợp lý."}]', '[]', NULL, '/ˈbeɪsɪk əˈsʌmpʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 111, 'basic component', 'thành phần cơ bản', 'adj + n', '[{"en":"Water is a basic component of every living cell.","vi":"Nước là một thành phần cơ bản của mọi tế bào sống."},{"en":"Trust is a basic component of any healthy relationship.","vi":"Sự tin tưởng là một thành phần cơ bản của mọi mối quan hệ lành mạnh."},{"en":"The course covers each basic component of computer hardware.","vi":"Khóa học giới thiệu từng thành phần cơ bản của phần cứng máy tính."}]', '[]', NULL, '/ˈbeɪsɪk kəmˈpoʊnənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 112, 'basic concept', 'khái niệm cơ bản', 'adj + n', '[{"en":"Students must grasp the basic concept before moving to applications.","vi":"Học sinh phải nắm khái niệm cơ bản trước khi học các ứng dụng."},{"en":"The first chapter introduces the basic concept of supply.","vi":"Chương đầu giới thiệu khái niệm cơ bản về cung."},{"en":"A clear example explains the basic concept very effectively.","vi":"Một ví dụ rõ ràng giải thích khái niệm cơ bản rất hiệu quả."}]', '[]', NULL, '/ˈbeɪsɪk ˈkɑːnsept/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 113, 'basic element', 'yếu tố cơ bản', 'adj + n', '[{"en":"Color is a basic element of effective visual design.","vi":"Màu sắc là một yếu tố cơ bản của thiết kế hình ảnh hiệu quả."},{"en":"Communication is a basic element of successful teamwork everywhere.","vi":"Giao tiếp là một yếu tố cơ bản của làm việc nhóm thành công khắp nơi."},{"en":"The teacher explained each basic element of the writing process.","vi":"Giáo viên giải thích từng yếu tố cơ bản của quá trình viết."}]', '[]', NULL, '/ˈbeɪsɪk ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 114, 'basic function', 'chức năng cơ bản', 'adj + n', '[{"en":"The basic function of the heart is to pump blood.","vi":"Chức năng cơ bản của tim là bơm máu."},{"en":"Every government has the basic function of protecting its citizens.","vi":"Mọi chính phủ đều có chức năng cơ bản là bảo vệ công dân."},{"en":"The manual describes the basic function of each button.","vi":"Sổ tay mô tả chức năng cơ bản của từng nút."}]', '[]', NULL, '/ˈbeɪsɪk ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 115, 'basic information', 'thông tin cơ bản', 'adj + n', '[{"en":"Please provide some basic information about your previous work experience.","vi":"Vui lòng cung cấp một số thông tin cơ bản về kinh nghiệm làm việc trước đây."},{"en":"The form collects basic information such as name and address.","vi":"Mẫu đơn thu thập thông tin cơ bản như tên và địa chỉ."},{"en":"The leaflet gives basic information about the new health service.","vi":"Tờ rơi cung cấp thông tin cơ bản về dịch vụ y tế mới."}]', '[]', NULL, '/ˈbeɪsɪk ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 116, 'basic premise', 'tiền đề cơ bản', 'adj + n', '[{"en":"The basic premise of the argument is that education matters.","vi":"Tiền đề cơ bản của lập luận là giáo dục có vai trò quan trọng."},{"en":"Critics challenged the basic premise behind the entire study.","vi":"Các nhà phê bình thách thức tiền đề cơ bản đằng sau toàn bộ nghiên cứu."},{"en":"Her essay clearly states its basic premise in the introduction.","vi":"Bài luận của cô nêu rõ tiền đề cơ bản ngay ở phần mở đầu."}]', '[]', NULL, '/ˈbeɪsɪk ˈpremɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 117, 'basic principle', 'nguyên tắc cơ bản', 'adj + n', '[{"en":"Fairness is a basic principle of any good legal system.","vi":"Công bằng là một nguyên tắc cơ bản của mọi hệ thống pháp luật tốt."},{"en":"The lecture explains the basic principle of supply and demand.","vi":"Bài giảng giải thích nguyên tắc cơ bản về cung và cầu."},{"en":"Engineers apply this basic principle when designing safe bridges.","vi":"Kỹ sư áp dụng nguyên tắc cơ bản này khi thiết kế cầu an toàn."}]', '[]', NULL, '/ˈbeɪsɪk ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 118, 'basic research', 'nghiên cứu cơ bản', 'adj + n', '[{"en":"Basic research often leads to unexpected and valuable practical applications.","vi":"Nghiên cứu cơ bản thường dẫn đến những ứng dụng thực tế bất ngờ và giá trị."},{"en":"The government increased funding for basic research in biology.","vi":"Chính phủ tăng kinh phí cho nghiên cứu cơ bản trong sinh học."},{"en":"Without basic research, technological progress would slow down considerably.","vi":"Nếu thiếu nghiên cứu cơ bản, tiến bộ công nghệ sẽ chậm lại đáng kể."}]', '[]', NULL, '/ˈbeɪsɪk ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 119, 'basic structure', 'cấu trúc cơ bản', 'adj + n', '[{"en":"The basic structure of an essay includes introduction and conclusion.","vi":"Cấu trúc cơ bản của một bài luận gồm mở bài và kết bài."},{"en":"Scientists studied the basic structure of the protein molecule.","vi":"Các nhà khoa học nghiên cứu cấu trúc cơ bản của phân tử protein."},{"en":"Understanding the basic structure helps readers follow the argument.","vi":"Hiểu cấu trúc cơ bản giúp người đọc theo dõi lập luận."}]', '[]', NULL, '/ˈbeɪsɪk ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 120, 'basic technique', 'kỹ thuật cơ bản', 'adj + n', '[{"en":"Students learn the basic technique before attempting advanced experiments.","vi":"Học sinh học kỹ thuật cơ bản trước khi thử các thí nghiệm nâng cao."},{"en":"This basic technique is used widely in modern photography.","vi":"Kỹ thuật cơ bản này được dùng rộng rãi trong nhiếp ảnh hiện đại."},{"en":"The coach demonstrated the basic technique to the new players.","vi":"Huấn luyện viên minh họa kỹ thuật cơ bản cho các cầu thủ mới."}]', '[]', NULL, '/ˈbeɪsɪk tekˈniːk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 121, 'bear resemblance to', 'có nét giống với', 'v + n', '[{"en":"The new design bears resemblance to an older famous model.","vi":"Thiết kế mới có nét giống với một mẫu nổi tiếng cũ hơn."},{"en":"Her painting bears resemblance to the works of impressionist masters.","vi":"Bức tranh của cô có nét giống với tác phẩm của các bậc thầy trường phái ấn tượng."},{"en":"These two languages bear resemblance to each other in grammar.","vi":"Hai ngôn ngữ này có nét giống nhau về ngữ pháp."}]', '[]', NULL, '/ber rɪˈzembləns tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 122, 'become apparent', 'trở nên rõ ràng', 'v + adj', '[{"en":"The problems with the plan soon became apparent to everyone.","vi":"Những vấn đề của kế hoạch nhanh chóng trở nên rõ ràng với mọi người."},{"en":"It became apparent that the data had been recorded incorrectly.","vi":"Rõ ràng là dữ liệu đã được ghi chép sai."},{"en":"The benefits of exercise become apparent after a few weeks.","vi":"Lợi ích của tập thể dục trở nên rõ ràng sau vài tuần."}]', '[]', NULL, '/bɪˈkʌm əˈpærənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 123, 'become available', 'trở nên sẵn có', 'v + adj', '[{"en":"New scholarships will become available to students next academic year.","vi":"Học bổng mới sẽ trở nên sẵn có cho sinh viên vào năm học tới."},{"en":"As more data become available, the model grows more accurate.","vi":"Khi có thêm dữ liệu sẵn có, mô hình trở nên chính xác hơn."},{"en":"The medicine became available after years of careful testing.","vi":"Loại thuốc trở nên sẵn có sau nhiều năm thử nghiệm kỹ lưỡng."}]', '[]', NULL, '/bɪˈkʌm əˈveɪləbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 124, 'become aware', 'trở nên ý thức được', 'v + adj', '[{"en":"People are becoming aware of the dangers of plastic waste.","vi":"Mọi người đang trở nên ý thức được mối nguy của rác thải nhựa."},{"en":"Students gradually become aware of their own learning habits.","vi":"Học sinh dần trở nên ý thức được thói quen học tập của mình."},{"en":"She became aware that the experiment had a serious flaw.","vi":"Cô nhận ra rằng thí nghiệm có một lỗi nghiêm trọng."}]', '[]', NULL, '/bɪˈkʌm əˈwer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 125, 'become blurred', 'trở nên mờ nhạt', 'v + adj', '[{"en":"The line between work and home has become blurred recently.","vi":"Ranh giới giữa công việc và gia đình gần đây đã trở nên mờ nhạt."},{"en":"Distinctions between the two categories often become blurred over time.","vi":"Sự phân biệt giữa hai loại thường trở nên mờ nhạt theo thời gian."},{"en":"Old memories become blurred as the years go by.","vi":"Những ký ức cũ trở nên mờ nhạt khi năm tháng trôi qua."}]', '[]', NULL, '/bɪˈkʌm blɜːrd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 126, 'become established', 'trở nên vững chắc', 'v + adj', '[{"en":"The new theory took years to become established in science.","vi":"Lý thuyết mới mất nhiều năm để trở nên vững chắc trong khoa học."},{"en":"Once habits become established, they are hard to change.","vi":"Một khi thói quen trở nên vững chắc, chúng rất khó thay đổi."},{"en":"The company became established as a leader in renewable energy.","vi":"Công ty đã trở nên vững chắc với vị thế dẫn đầu về năng lượng tái tạo."}]', '[]', NULL, '/bɪˈkʌm ɪˈstæblɪʃt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 127, 'become evident', 'trở nên rõ rệt', 'v + adj', '[{"en":"It became evident that further research would be necessary soon.","vi":"Rõ rệt là cần phải có thêm nghiên cứu trong thời gian tới."},{"en":"The effects of the policy became evident within a year.","vi":"Tác động của chính sách trở nên rõ rệt chỉ trong một năm."},{"en":"Her talent became evident during the first few rehearsals.","vi":"Tài năng của cô trở nên rõ rệt trong vài buổi tập đầu tiên."}]', '[]', NULL, '/bɪˈkʌm ˈevɪdənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 128, 'become independent', 'trở nên độc lập', 'v + adj', '[{"en":"Many countries became independent during the twentieth century.","vi":"Nhiều quốc gia đã trở nên độc lập trong thế kỷ hai mươi."},{"en":"University helps young people become independent and self-reliant adults.","vi":"Đại học giúp người trẻ trở nên độc lập và tự lập."},{"en":"Children gradually become independent as they grow older.","vi":"Trẻ em dần trở nên độc lập khi lớn lên."}]', '[]', NULL, '/bɪˈkʌm ˌɪndɪˈpendənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 129, 'become involved with', 'trở nên gắn bó với', 'v + adj', '[{"en":"She became involved with several community projects during college.","vi":"Cô trở nên gắn bó với nhiều dự án cộng đồng trong thời đại học."},{"en":"Students are encouraged to become involved with campus organizations.","vi":"Sinh viên được khuyến khích tham gia gắn bó với các tổ chức trong trường."},{"en":"He became involved with the research team after graduation.","vi":"Anh trở nên gắn bó với nhóm nghiên cứu sau khi tốt nghiệp."}]', '[]', NULL, '/bɪˈkʌm ɪnˈvɑːlvd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 130, 'become obvious', 'trở nên hiển nhiên', 'v + adj', '[{"en":"The mistake became obvious as soon as we checked again.","vi":"Lỗi sai trở nên hiển nhiên ngay khi chúng tôi kiểm tra lại."},{"en":"It became obvious that the original plan would not work.","vi":"Rõ ràng là kế hoạch ban đầu sẽ không hiệu quả."},{"en":"The reasons for the failure became obvious after the analysis.","vi":"Lý do thất bại trở nên hiển nhiên sau khi phân tích."}]', '[]', NULL, '/bɪˈkʌm ˈɑːbviəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 131, 'become visible', 'trở nên rõ thấy', 'v + adj', '[{"en":"Tiny cracks become visible only under a powerful microscope.","vi":"Những vết nứt nhỏ chỉ trở nên rõ thấy dưới kính hiển vi mạnh."},{"en":"The stars become visible once the city lights fade.","vi":"Các ngôi sao trở nên rõ thấy khi ánh đèn thành phố mờ đi."},{"en":"Social problems become visible during times of economic crisis.","vi":"Các vấn đề xã hội trở nên rõ thấy trong thời kỳ khủng hoảng kinh tế."}]', '[]', NULL, '/bɪˈkʌm ˈvɪzəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 132, 'become widespread', 'trở nên phổ biến rộng rãi', 'v + adj', '[{"en":"Mobile phones became widespread within a single decade worldwide.","vi":"Điện thoại di động trở nên phổ biến rộng rãi chỉ trong một thập kỷ."},{"en":"The practice became widespread after the new law passed.","vi":"Thực hành này trở nên phổ biến rộng rãi sau khi luật mới được thông qua."},{"en":"Once the idea became widespread, attitudes slowly began changing.","vi":"Khi ý tưởng trở nên phổ biến rộng rãi, thái độ dần bắt đầu thay đổi."}]', '[]', NULL, '/bɪˈkʌm ˈwaɪdˈspred/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 133, 'become a source of', 'trở thành nguồn gốc của', 'v + n', '[{"en":"The river became a source of fresh water for the village.","vi":"Con sông trở thành nguồn nước ngọt cho ngôi làng."},{"en":"Social media can become a source of stress for teenagers.","vi":"Mạng xã hội có thể trở thành nguồn gây căng thẳng cho thanh thiếu niên."},{"en":"Tourism has become a source of income for the region.","vi":"Du lịch đã trở thành nguồn thu nhập cho cả vùng."}]', '[]', NULL, '/bɪˈkʌm ə sɔːrs əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 134, 'become the focus of', 'trở thành trọng tâm của', 'v + n', '[{"en":"Climate change has become the focus of recent global discussions.","vi":"Biến đổi khí hậu đã trở thành trọng tâm của các thảo luận toàn cầu gần đây."},{"en":"The young scientist became the focus of considerable media attention.","vi":"Nhà khoa học trẻ trở thành trọng tâm của nhiều sự chú ý từ truyền thông."},{"en":"Education became the focus of the government''s new reform program.","vi":"Giáo dục trở thành trọng tâm của chương trình cải cách mới của chính phủ."}]', '[]', NULL, '/bɪˈkʌm ðə ˈfoʊkəs əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 135, 'begin a process', 'bắt đầu một quá trình', 'v + n', '[{"en":"The company will begin a process of major internal reform.","vi":"Công ty sẽ bắt đầu một quá trình cải tổ nội bộ lớn."},{"en":"Researchers begin a process of testing before publishing any results.","vi":"Các nhà nghiên cứu bắt đầu một quá trình thử nghiệm trước khi công bố kết quả."},{"en":"The two nations agreed to begin a process of negotiation.","vi":"Hai quốc gia đồng ý bắt đầu một quá trình đàm phán."}]', '[]', NULL, '/bɪˈɡɪn ə ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 136, 'behave differently', 'hành xử khác nhau', 'v + adv', '[{"en":"Children often behave differently when their parents are watching.","vi":"Trẻ em thường hành xử khác đi khi có bố mẹ quan sát."},{"en":"These materials behave differently under high temperature and pressure.","vi":"Các vật liệu này phản ứng khác nhau dưới nhiệt độ và áp suất cao."},{"en":"People may behave differently in unfamiliar social situations.","vi":"Mọi người có thể hành xử khác nhau trong tình huống xã hội lạ lẫm."}]', '[]', NULL, '/bɪˈheɪv ˈdɪfrəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 137, 'beneficial effect', 'tác động có lợi', 'adj + n', '[{"en":"Regular exercise has a beneficial effect on mental health.","vi":"Tập thể dục đều đặn có tác động có lợi đối với sức khỏe tinh thần."},{"en":"The new policy had a beneficial effect on small businesses.","vi":"Chính sách mới có tác động có lợi đối với các doanh nghiệp nhỏ."},{"en":"Sleep has a beneficial effect on memory and concentration.","vi":"Giấc ngủ có tác động có lợi đối với trí nhớ và sự tập trung."}]', '[]', NULL, '/ˌbenɪˈfɪʃəl ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 138, 'best described as', 'được mô tả chính xác nhất là', 'adv + vpp', '[{"en":"The novel is best described as a thoughtful social commentary.","vi":"Cuốn tiểu thuyết được mô tả chính xác nhất là một bình luận xã hội sâu sắc."},{"en":"His leadership style is best described as calm and inclusive.","vi":"Phong cách lãnh đạo của anh được mô tả chính xác nhất là điềm tĩnh và bao dung."},{"en":"The region''s climate is best described as warm and humid.","vi":"Khí hậu của vùng này được mô tả chính xác nhất là ấm và ẩm."}]', '[]', NULL, '/best dɪˈskraɪbd æz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 139, 'binary opposition', 'đối lập nhị phân', 'adj + n', '[{"en":"The essay explores the binary opposition between nature and culture.","vi":"Bài luận khám phá sự đối lập nhị phân giữa tự nhiên và văn hóa."},{"en":"Many myths are structured around a clear binary opposition.","vi":"Nhiều thần thoại được cấu trúc quanh một đối lập nhị phân rõ ràng."},{"en":"Critics question whether this binary opposition truly reflects reality.","vi":"Các nhà phê bình nghi ngờ liệu đối lập nhị phân này có phản ánh đúng thực tế."}]', '[]', NULL, '/ˈbaɪnəri ˌɑːpəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 140, 'binary system', 'hệ nhị phân', 'adj + n', '[{"en":"Computers store information using a simple binary system of digits.","vi":"Máy tính lưu thông tin bằng một hệ nhị phân đơn giản gồm các chữ số."},{"en":"The binary system uses only the digits zero and one.","vi":"Hệ nhị phân chỉ dùng hai chữ số là không và một."},{"en":"Students learn to convert numbers into the binary system.","vi":"Học sinh học cách chuyển đổi số sang hệ nhị phân."}]', '[]', NULL, '/ˈbaɪnəri ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 141, 'biological evolution', 'tiến hóa sinh học', 'adj + n', '[{"en":"Biological evolution explains how species change over many generations.","vi":"Tiến hóa sinh học giải thích cách các loài thay đổi qua nhiều thế hệ."},{"en":"The lecture covered the basic mechanisms of biological evolution.","vi":"Bài giảng trình bày các cơ chế cơ bản của tiến hóa sinh học."},{"en":"Fossils provide strong evidence for biological evolution over time.","vi":"Hóa thạch cung cấp bằng chứng mạnh mẽ cho tiến hóa sinh học theo thời gian."}]', '[]', NULL, '/ˌbaɪəˈlɑːdʒɪkəl ˌevəˈluːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 142, 'biological science', 'khoa học sinh học', 'adj + n', '[{"en":"Biological science has made remarkable progress in recent decades.","vi":"Khoa học sinh học đã đạt nhiều tiến bộ đáng kể trong những thập kỷ gần đây."},{"en":"She decided to major in biological science at university.","vi":"Cô quyết định học chuyên ngành khoa học sinh học ở đại học."},{"en":"Advances in biological science improve medicine and agriculture worldwide.","vi":"Tiến bộ trong khoa học sinh học cải thiện y học và nông nghiệp toàn cầu."}]', '[]', NULL, '/ˌbaɪəˈlɑːdʒɪkəl ˈsaɪəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 143, 'biological sex', 'giới tính sinh học', 'adj + n', '[{"en":"The study examined health differences related to biological sex.","vi":"Nghiên cứu khảo sát khác biệt về sức khỏe liên quan đến giới tính sinh học."},{"en":"Researchers distinguish biological sex from socially constructed gender roles.","vi":"Các nhà nghiên cứu phân biệt giới tính sinh học với vai trò giới do xã hội tạo nên."},{"en":"Some medical conditions are linked closely to biological sex.","vi":"Một số bệnh lý liên quan chặt chẽ đến giới tính sinh học."}]', '[]', NULL, '/ˌbaɪəˈlɑːdʒɪkəl seks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 144, 'brief account', 'bản tường thuật ngắn gọn', 'adj + n', '[{"en":"The article gives a brief account of the region''s history.","vi":"Bài viết đưa ra một bản tường thuật ngắn gọn về lịch sử của vùng."},{"en":"She wrote a brief account of the meeting for colleagues.","vi":"Cô viết một bản tường thuật ngắn gọn về cuộc họp cho đồng nghiệp."},{"en":"Please provide a brief account of what happened yesterday.","vi":"Vui lòng cung cấp một bản tường thuật ngắn gọn về việc xảy ra hôm qua."}]', '[]', NULL, '/briːf əˈkaʊnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 145, 'brief description', 'mô tả ngắn gọn', 'adj + n', '[{"en":"Each chapter begins with a brief description of its goals.","vi":"Mỗi chương bắt đầu với một mô tả ngắn gọn về mục tiêu của nó."},{"en":"The catalog includes a brief description of every product available.","vi":"Bản danh mục có một mô tả ngắn gọn về mọi sản phẩm hiện có."},{"en":"Write a brief description of yourself for the application form.","vi":"Hãy viết một mô tả ngắn gọn về bản thân cho mẫu đơn xin việc."}]', '[]', NULL, '/briːf dɪˈskrɪpʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 146, 'brief discussion', 'cuộc thảo luận ngắn gọn', 'adj + n', '[{"en":"After a brief discussion, the committee reached a final decision.","vi":"Sau một cuộc thảo luận ngắn gọn, ủy ban đã đi đến quyết định cuối cùng."},{"en":"The section ends with a brief discussion of future research.","vi":"Phần này kết thúc bằng một cuộc thảo luận ngắn gọn về nghiên cứu tương lai."},{"en":"We had a brief discussion about the changes before lunch.","vi":"Chúng tôi có một cuộc thảo luận ngắn gọn về các thay đổi trước bữa trưa."}]', '[]', NULL, '/briːf dɪˈskʌʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 147, 'brief history', 'lịch sử tóm lược', 'adj + n', '[{"en":"The book offers a brief history of modern computing technology.","vi":"Cuốn sách đưa ra một lịch sử tóm lược về công nghệ máy tính hiện đại."},{"en":"The lecture opened with a brief history of the company.","vi":"Bài giảng mở đầu bằng một lịch sử tóm lược về công ty."},{"en":"She gave a brief history of the town''s growth.","vi":"Cô trình bày một lịch sử tóm lược về sự phát triển của thị trấn."}]', '[]', NULL, '/briːf ˈhɪstəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 148, 'brief introduction', 'phần giới thiệu ngắn gọn', 'adj + n', '[{"en":"The speaker gave a brief introduction before starting the lecture.","vi":"Diễn giả có phần giới thiệu ngắn gọn trước khi bắt đầu bài giảng."},{"en":"This chapter provides a brief introduction to economic theory.","vi":"Chương này cung cấp một phần giới thiệu ngắn gọn về lý thuyết kinh tế."},{"en":"After a brief introduction, the workshop moved to practical tasks.","vi":"Sau phần giới thiệu ngắn gọn, buổi học chuyển sang các bài tập thực hành."}]', '[]', NULL, '/briːf ˌɪntrəˈdʌkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 149, 'brief overview', 'cái nhìn tổng quan ngắn gọn', 'adj + n', '[{"en":"The report begins with a brief overview of the findings.","vi":"Báo cáo mở đầu bằng một cái nhìn tổng quan ngắn gọn về các phát hiện."},{"en":"Let me give you a brief overview of today''s agenda.","vi":"Hãy để tôi đưa ra một cái nhìn tổng quan ngắn gọn về chương trình hôm nay."},{"en":"A brief overview helps new readers grasp the main ideas.","vi":"Một cái nhìn tổng quan ngắn gọn giúp người đọc mới nắm các ý chính."}]', '[]', NULL, '/briːf ˈoʊvərˌvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-1-01', 150, 'brief period', 'khoảng thời gian ngắn', 'adj + n', '[{"en":"For a brief period, the factory stopped production entirely.","vi":"Trong một khoảng thời gian ngắn, nhà máy ngừng sản xuất hoàn toàn."},{"en":"She lived abroad for a brief period after graduation.","vi":"Cô sống ở nước ngoài trong một khoảng thời gian ngắn sau khi tốt nghiệp."},{"en":"Prices rose sharply during a brief period of shortage.","vi":"Giá tăng mạnh trong một khoảng thời gian ngắn khan hiếm."}]', '[]', NULL, '/briːf ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-2-01', 'colloc-2', 'Cụm học thuật · Nhóm 2', 'Academic Collocation List (Pearson/PTE) — nhóm 2 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 1, 'brief review', 'bản tổng quan ngắn gọn', 'adj + n', '[{"en":"The paper opens with a brief review of earlier studies.","vi":"Bài báo mở đầu bằng một bản tổng quan ngắn gọn về các nghiên cứu trước."},{"en":"She wrote a brief review of the new economics textbook.","vi":"Cô viết một bản tổng quan ngắn gọn về cuốn giáo trình kinh tế mới."},{"en":"A brief review of the literature reveals several research gaps.","vi":"Một bản tổng quan ngắn gọn về tài liệu cho thấy vài khoảng trống nghiên cứu."}]', '[]', NULL, '/briːf rɪˈvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 2, 'brief summary', 'bản tóm tắt ngắn gọn', 'adj + n', '[{"en":"Please write a brief summary of the article''s main points.","vi":"Vui lòng viết một bản tóm tắt ngắn gọn về các ý chính của bài."},{"en":"The conclusion provides a brief summary of all the results.","vi":"Phần kết luận đưa ra một bản tóm tắt ngắn gọn về toàn bộ kết quả."},{"en":"He gave a brief summary before the meeting ended.","vi":"Anh đưa ra một bản tóm tắt ngắn gọn trước khi cuộc họp kết thúc."}]', '[]', NULL, '/briːf ˈsʌməri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 3, 'brief time', 'thời gian ngắn ngủi', 'adj + n', '[{"en":"In a brief time, the small startup grew enormously.","vi":"Trong một thời gian ngắn ngủi, công ty khởi nghiệp nhỏ đã lớn mạnh đáng kể."},{"en":"They achieved remarkable results in a surprisingly brief time.","vi":"Họ đạt được kết quả đáng kể trong một thời gian ngắn ngủi đáng ngạc nhiên."},{"en":"For a brief time, the two teams worked together closely.","vi":"Trong một thời gian ngắn ngủi, hai nhóm đã hợp tác chặt chẽ."}]', '[]', NULL, '/briːf taɪm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 4, 'briefly describe', 'mô tả ngắn gọn', 'adv + v', '[{"en":"Please briefly describe your previous experience in the field.","vi":"Vui lòng mô tả ngắn gọn kinh nghiệm trước đây của bạn trong lĩnh vực này."},{"en":"The author briefly describes the method used in the experiment.","vi":"Tác giả mô tả ngắn gọn phương pháp được dùng trong thí nghiệm."},{"en":"Can you briefly describe how the new system works?","vi":"Bạn có thể mô tả ngắn gọn cách hệ thống mới hoạt động không?"}]', '[]', NULL, '/ˈbriːfli dɪˈskraɪb/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 5, 'briefly discuss', 'thảo luận ngắn gọn', 'adv + v', '[{"en":"The essay will briefly discuss the causes of urban poverty.","vi":"Bài luận sẽ thảo luận ngắn gọn về nguyên nhân của nghèo đô thị."},{"en":"Let us briefly discuss the limitations of this approach.","vi":"Hãy thảo luận ngắn gọn về những hạn chế của cách tiếp cận này."},{"en":"The teacher asked students to briefly discuss the reading.","vi":"Giáo viên yêu cầu học sinh thảo luận ngắn gọn về bài đọc."}]', '[]', NULL, '/ˈbriːfli dɪˈskʌs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 6, 'broad agreement', 'sự đồng thuận rộng rãi', 'adj + n', '[{"en":"There is broad agreement that pollution harms public health.","vi":"Có sự đồng thuận rộng rãi rằng ô nhiễm gây hại cho sức khỏe cộng đồng."},{"en":"The delegates reached broad agreement on the main proposals.","vi":"Các đại biểu đạt được sự đồng thuận rộng rãi về các đề xuất chính."},{"en":"Despite some debate, broad agreement emerged among the experts.","vi":"Dù còn tranh luận, sự đồng thuận rộng rãi đã hình thành giữa các chuyên gia."}]', '[]', NULL, '/brɔːd əˈɡriːmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 7, 'broad category', 'phạm trù rộng', 'adj + n', '[{"en":"The survey divides respondents into a few broad categories.","vi":"Khảo sát chia người trả lời thành một vài phạm trù rộng."},{"en":"These problems fall within a broad category of social issues.","vi":"Những vấn đề này thuộc một phạm trù rộng về các vấn đề xã hội."},{"en":"Each broad category includes several more specific subgroups.","vi":"Mỗi phạm trù rộng bao gồm vài nhóm nhỏ cụ thể hơn."}]', '[]', NULL, '/brɔːd ˈkætəɡɔːri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 8, 'broad definition', 'định nghĩa rộng', 'adj + n', '[{"en":"The author uses a broad definition of the term culture.","vi":"Tác giả dùng một định nghĩa rộng cho thuật ngữ văn hóa."},{"en":"A broad definition allows the concept to cover many cases.","vi":"Một định nghĩa rộng cho phép khái niệm bao quát nhiều trường hợp."},{"en":"Critics argue that the broad definition is too vague.","vi":"Các nhà phê bình cho rằng định nghĩa rộng này quá mơ hồ."}]', '[]', NULL, '/brɔːd ˌdefɪˈnɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 9, 'broad range of', 'phạm vi rộng', 'adj + n', '[{"en":"The university offers a broad range of courses for students.","vi":"Trường đại học cung cấp một phạm vi rộng các khóa học cho sinh viên."},{"en":"The study covers a broad range of social and economic topics.","vi":"Nghiên cứu bao quát một phạm vi rộng các chủ đề xã hội và kinh tế."},{"en":"Her work appeals to a broad range of readers.","vi":"Tác phẩm của cô thu hút một phạm vi rộng độc giả."}]', '[]', NULL, '/brɔːd reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 10, 'broad spectrum', 'phổ rộng', 'adj + n', '[{"en":"The conference attracted a broad spectrum of industry professionals.","vi":"Hội nghị thu hút một phổ rộng các chuyên gia trong ngành."},{"en":"This medicine treats a broad spectrum of bacterial infections.","vi":"Loại thuốc này điều trị một phổ rộng các bệnh nhiễm khuẩn."},{"en":"Their policies appeal to a broad spectrum of voters.","vi":"Các chính sách của họ thu hút một phổ rộng cử tri."}]', '[]', NULL, '/brɔːd ˈspektrəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 11, 'broader context', 'bối cảnh rộng hơn', 'adj + n', '[{"en":"We must understand the event within its broader context.","vi":"Chúng ta phải hiểu sự kiện trong bối cảnh rộng hơn của nó."},{"en":"The author places the issue in a broader historical context.","vi":"Tác giả đặt vấn đề trong một bối cảnh lịch sử rộng hơn."},{"en":"Viewing data in a broader context reveals important patterns.","vi":"Nhìn dữ liệu trong bối cảnh rộng hơn làm lộ ra các quy luật quan trọng."}]', '[]', NULL, '/ˈbrɔːdər ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 12, 'broadly defined', 'được định nghĩa một cách rộng rãi', 'adv + vpp', '[{"en":"Health, broadly defined, includes physical, mental, and social wellbeing.","vi":"Sức khỏe, được định nghĩa rộng rãi, gồm thể chất, tinh thần và xã hội."},{"en":"The term, broadly defined, covers many different research areas.","vi":"Thuật ngữ này, được định nghĩa rộng rãi, bao quát nhiều lĩnh vực nghiên cứu."},{"en":"Culture is broadly defined as shared values and practices.","vi":"Văn hóa được định nghĩa rộng rãi là các giá trị và thực hành chung."}]', '[]', NULL, '/ˈbrɔːdli dɪˈfaɪnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 13, 'broadly similar', 'tương tự về cơ bản', 'adv + adj', '[{"en":"The two regions have broadly similar climates and economies.","vi":"Hai vùng có khí hậu và nền kinh tế tương tự về cơ bản."},{"en":"Results from both experiments were broadly similar overall.","vi":"Kết quả từ cả hai thí nghiệm về cơ bản là tương tự nhau."},{"en":"Although different in detail, the plans are broadly similar.","vi":"Dù khác nhau ở chi tiết, các kế hoạch về cơ bản là tương tự."}]', '[]', NULL, '/ˈbrɔːdli ˈsɪmələr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 14, 'business sector', 'khu vực doanh nghiệp', 'n + n', '[{"en":"The business sector plays a major role in the economy.","vi":"Khu vực doanh nghiệp đóng vai trò quan trọng trong nền kinh tế."},{"en":"Government policies strongly affect the entire business sector nationwide.","vi":"Các chính sách của chính phủ ảnh hưởng mạnh đến toàn bộ khu vực doanh nghiệp."},{"en":"New technology is reshaping the global business sector rapidly.","vi":"Công nghệ mới đang định hình lại khu vực doanh nghiệp toàn cầu nhanh chóng."}]', '[]', NULL, '/ˈbɪznəs ˈsektər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 15, 'business transaction', 'giao dịch kinh doanh', 'n + n', '[{"en":"Every business transaction should be recorded carefully for accounting.","vi":"Mỗi giao dịch kinh doanh nên được ghi chép cẩn thận cho kế toán."},{"en":"Online platforms make each business transaction faster and easier.","vi":"Các nền tảng trực tuyến giúp mỗi giao dịch kinh doanh nhanh và dễ hơn."},{"en":"Trust is essential in any successful business transaction between partners.","vi":"Niềm tin là điều thiết yếu trong mọi giao dịch kinh doanh thành công giữa các đối tác."}]', '[]', NULL, '/ˈbɪznəs trænˈzækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 16, 'capitalist country', 'nước tư bản chủ nghĩa', 'adj + n', '[{"en":"In a capitalist country, private businesses drive most economic growth.","vi":"Ở một nước tư bản, các doanh nghiệp tư nhân thúc đẩy phần lớn tăng trưởng kinh tế."},{"en":"The author compares living standards across several capitalist countries.","vi":"Tác giả so sánh mức sống giữa nhiều nước tư bản khác nhau."},{"en":"Many capitalist countries rely heavily on free-market competition.","vi":"Nhiều nước tư bản phụ thuộc nhiều vào cạnh tranh thị trường tự do."}]', '[]', NULL, '/ˈkæpɪtəlɪst ˈkʌntri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 17, 'capitalist economy', 'nền kinh tế tư bản', 'adj + n', '[{"en":"A capitalist economy lets supply and demand set most prices.","vi":"Một nền kinh tế tư bản để cung và cầu quyết định phần lớn giá cả."},{"en":"The lecture explained how a capitalist economy distributes resources.","vi":"Bài giảng giải thích cách nền kinh tế tư bản phân bổ nguồn lực."},{"en":"Inequality often grows quickly within an unregulated capitalist economy.","vi":"Bất bình đẳng thường tăng nhanh trong nền kinh tế tư bản thiếu kiểm soát."}]', '[]', NULL, '/ˈkæpɪtəlɪst ɪˈkɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 18, 'capitalist society', 'xã hội tư bản', 'adj + n', '[{"en":"In a capitalist society, success is often measured by wealth.","vi":"Trong xã hội tư bản, thành công thường được đo bằng của cải."},{"en":"The essay critiques class divisions found in capitalist society.","vi":"Bài luận phê phán sự phân chia giai cấp trong xã hội tư bản."},{"en":"Capitalist society rewards individual ambition more than collective effort.","vi":"Xã hội tư bản tưởng thưởng tham vọng cá nhân hơn nỗ lực tập thể."}]', '[]', NULL, '/ˈkæpɪtəlɪst səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 19, 'capitalist system', 'hệ thống tư bản', 'adj + n', '[{"en":"The capitalist system depends on private ownership and open markets.","vi":"Hệ thống tư bản dựa trên sở hữu tư nhân và thị trường mở."},{"en":"Critics argue the capitalist system concentrates power among the wealthy.","vi":"Người phê phán cho rằng hệ thống tư bản tập trung quyền lực vào người giàu."},{"en":"Reforms aim to soften the harsher effects of the capitalist system.","vi":"Các cải cách nhằm làm dịu những tác động khắc nghiệt của hệ thống tư bản."}]', '[]', NULL, '/ˈkæpɪtəlɪst ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 20, 'capitalist world', 'thế giới tư bản', 'adj + n', '[{"en":"Global trade ties most nations into one capitalist world.","vi":"Thương mại toàn cầu gắn hầu hết các quốc gia vào một thế giới tư bản."},{"en":"In the capitalist world, competition shapes nearly every industry.","vi":"Trong thế giới tư bản, cạnh tranh định hình gần như mọi ngành công nghiệp."},{"en":"The book traces how the capitalist world expanded after colonialism.","vi":"Cuốn sách lần theo cách thế giới tư bản mở rộng sau thời thuộc địa."}]', '[]', NULL, '/ˈkæpɪtəlɪst wɜːrld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 21, 'career development', 'sự phát triển nghề nghiệp', 'n + n', '[{"en":"The company invests in the career development of every employee.","vi":"Công ty đầu tư vào sự phát triển nghề nghiệp của từng nhân viên."},{"en":"Mentoring plays a key role in long-term career development.","vi":"Việc cố vấn đóng vai trò quan trọng trong phát triển nghề nghiệp lâu dài."},{"en":"Students attended a workshop focused on career development skills.","vi":"Sinh viên tham gia hội thảo tập trung vào kỹ năng phát triển nghề nghiệp."}]', '[]', NULL, '/kəˈrɪr dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 22, 'career opportunity', 'cơ hội nghề nghiệp', 'n + n', '[{"en":"Graduating abroad opened up a major career opportunity for her.","vi":"Tốt nghiệp ở nước ngoài đã mở ra một cơ hội nghề nghiệp lớn cho cô."},{"en":"The fair connected students with new career opportunities each year.","vi":"Hội chợ kết nối sinh viên với những cơ hội nghề nghiệp mới mỗi năm."},{"en":"He turned down a promising career opportunity to study further.","vi":"Anh từ chối một cơ hội nghề nghiệp hứa hẹn để học cao hơn."}]', '[]', NULL, '/kəˈrɪr ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 23, 'careful analysis', 'sự phân tích cẩn thận', 'adj + n', '[{"en":"Careful analysis of the data revealed an unexpected trend.","vi":"Sự phân tích cẩn thận dữ liệu đã cho thấy một xu hướng bất ngờ."},{"en":"The report draws its conclusions from careful analysis of records.","vi":"Báo cáo rút ra kết luận từ sự phân tích cẩn thận các hồ sơ."},{"en":"Only careful analysis can separate correlation from genuine causation.","vi":"Chỉ phân tích cẩn thận mới tách được tương quan khỏi nhân quả thực sự."}]', '[]', NULL, '/ˈkerfəl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 24, 'careful attention', 'sự chú ý cẩn thận', 'adj + n', '[{"en":"The experiment requires careful attention to every measurement.","vi":"Thí nghiệm đòi hỏi sự chú ý cẩn thận đến từng phép đo."},{"en":"She paid careful attention to the instructions before starting.","vi":"Cô chú ý cẩn thận đến hướng dẫn trước khi bắt đầu."},{"en":"Editing demands careful attention to grammar and tone.","vi":"Việc biên tập đòi hỏi sự chú ý cẩn thận đến ngữ pháp và giọng văn."}]', '[]', NULL, '/ˈkerfəl əˈtenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 25, 'careful consideration', 'sự cân nhắc kỹ lưỡng', 'adj + n', '[{"en":"The proposal deserves careful consideration before any decision is made.","vi":"Đề xuất xứng đáng được cân nhắc kỹ lưỡng trước khi đưa ra quyết định nào."},{"en":"After careful consideration, the committee approved the new policy.","vi":"Sau khi cân nhắc kỹ lưỡng, ủy ban đã phê duyệt chính sách mới."},{"en":"These risks warrant careful consideration by the whole research team.","vi":"Những rủi ro này đáng được cả nhóm nghiên cứu cân nhắc kỹ lưỡng."}]', '[]', NULL, '/ˈkerfəl kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 26, 'careful thought', 'sự suy nghĩ thấu đáo', 'adj + n', '[{"en":"The design clearly reflects careful thought about user needs.","vi":"Thiết kế rõ ràng phản ánh sự suy nghĩ thấu đáo về nhu cầu người dùng."},{"en":"Such a complex question demands careful thought, not quick answers.","vi":"Một câu hỏi phức tạp như vậy đòi hỏi suy nghĩ thấu đáo, không phải trả lời vội."},{"en":"After careful thought, she changed the structure of her essay.","vi":"Sau khi suy nghĩ thấu đáo, cô đã thay đổi cấu trúc bài luận."}]', '[]', NULL, '/ˈkerfəl θɔːt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 27, 'carefully controlled', 'được kiểm soát cẩn thận', 'adv + vpp', '[{"en":"The temperature was carefully controlled throughout the entire experiment.","vi":"Nhiệt độ được kiểm soát cẩn thận trong suốt toàn bộ thí nghiệm."},{"en":"Results are reliable because conditions were carefully controlled.","vi":"Kết quả đáng tin cậy vì các điều kiện được kiểm soát cẩn thận."},{"en":"In a carefully controlled trial, each variable is monitored closely.","vi":"Trong một thử nghiệm được kiểm soát cẩn thận, mỗi biến số được theo dõi sát."}]', '[]', NULL, '/ˈkerfəli kənˈtroʊld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 28, 'carefully selected', 'được chọn lựa kỹ càng', 'adv + vpp', '[{"en":"The participants were carefully selected to match the study criteria.","vi":"Những người tham gia được chọn lựa kỹ càng để phù hợp tiêu chí nghiên cứu."},{"en":"Each quotation in the book was carefully selected for relevance.","vi":"Mỗi trích dẫn trong sách đều được chọn lựa kỹ càng cho phù hợp."},{"en":"A carefully selected sample helps reduce bias in the findings.","vi":"Một mẫu được chọn lựa kỹ càng giúp giảm thiên lệch trong kết quả."}]', '[]', NULL, '/ˈkerfəli sɪˈlektɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 29, 'carry information', 'truyền tải thông tin', 'v + n', '[{"en":"Nerve cells carry information from the body to the brain.","vi":"Các tế bào thần kinh truyền tải thông tin từ cơ thể đến não."},{"en":"Fiber-optic cables carry information across continents in milliseconds.","vi":"Cáp quang truyền tải thông tin qua các châu lục chỉ trong vài mili giây."},{"en":"Genes carry information that determines an organism''s traits.","vi":"Gen mang thông tin quyết định các đặc điểm của một sinh vật."}]', '[]', NULL, '/ˈkæri ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 30, 'carry out research of', 'tiến hành nghiên cứu về', 'v + n', '[{"en":"The team will carry out research of marine ecosystems next summer.","vi":"Nhóm sẽ tiến hành nghiên cứu về hệ sinh thái biển vào mùa hè tới."},{"en":"Scientists carry out research of new materials in this lab.","vi":"Các nhà khoa học tiến hành nghiên cứu về vật liệu mới trong phòng thí nghiệm này."},{"en":"She received a grant to carry out research of rural education.","vi":"Cô nhận được tài trợ để tiến hành nghiên cứu về giáo dục nông thôn."}]', '[]', NULL, '/ˈkæri aʊt ˈriːsɜːrtʃ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 31, 'carry out the task', 'thực hiện nhiệm vụ', 'v + n', '[{"en":"The students worked together to carry out the task efficiently.","vi":"Các sinh viên cùng nhau thực hiện nhiệm vụ một cách hiệu quả."},{"en":"He needed clear instructions before he could carry out the task.","vi":"Anh cần hướng dẫn rõ ràng trước khi có thể thực hiện nhiệm vụ."},{"en":"The robot was programmed to carry out the task automatically.","vi":"Robot được lập trình để thực hiện nhiệm vụ một cách tự động."}]', '[]', NULL, '/ˈkæri aʊt ðə tæsk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 32, 'cast doubt on', 'gây nghi ngờ về', 'v + n', '[{"en":"New evidence cast doubt on the original conclusions of the study.","vi":"Bằng chứng mới đã gây nghi ngờ về các kết luận ban đầu của nghiên cứu."},{"en":"Critics cast doubt on the reliability of the survey results.","vi":"Người phê phán gây nghi ngờ về độ tin cậy của kết quả khảo sát."},{"en":"The contradiction casts doubt on his entire argument.","vi":"Sự mâu thuẫn này gây nghi ngờ về toàn bộ lập luận của anh."}]', '[]', NULL, '/kæst daʊt ɑːn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 33, 'causal link', 'mối liên hệ nhân quả', 'adj + n', '[{"en":"Researchers found a causal link between smoking and lung disease.","vi":"Các nhà nghiên cứu tìm thấy mối liên hệ nhân quả giữa hút thuốc và bệnh phổi."},{"en":"Correlation alone does not prove a true causal link.","vi":"Chỉ riêng tương quan không chứng minh được mối liên hệ nhân quả thực sự."},{"en":"The study failed to establish any clear causal link.","vi":"Nghiên cứu không thiết lập được mối liên hệ nhân quả rõ ràng nào."}]', '[]', NULL, '/ˈkɔːzəl lɪŋk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 34, 'causal relation', 'quan hệ nhân quả', 'adj + n', '[{"en":"Philosophers have long debated the nature of causal relation.","vi":"Các nhà triết học từ lâu đã tranh luận về bản chất của quan hệ nhân quả."},{"en":"The data suggest a causal relation between income and health.","vi":"Dữ liệu gợi ý một quan hệ nhân quả giữa thu nhập và sức khỏe."},{"en":"Establishing a causal relation requires controlled experiments.","vi":"Thiết lập một quan hệ nhân quả đòi hỏi các thí nghiệm có kiểm soát."}]', '[]', NULL, '/ˈkɔːzəl rɪˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 35, 'causal relationship', 'mối quan hệ nhân quả', 'adj + n', '[{"en":"The experiment confirmed a causal relationship between diet and weight.","vi":"Thí nghiệm xác nhận một mối quan hệ nhân quả giữa chế độ ăn và cân nặng."},{"en":"It is hard to prove a causal relationship in social science.","vi":"Rất khó chứng minh một mối quan hệ nhân quả trong khoa học xã hội."},{"en":"They tested whether a causal relationship existed between the two factors.","vi":"Họ kiểm tra xem có mối quan hệ nhân quả giữa hai yếu tố hay không."}]', '[]', NULL, '/ˈkɔːzəl rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 36, 'cause consequences', 'gây ra hậu quả', 'v + n', '[{"en":"Careless decisions can cause consequences that last for years.","vi":"Những quyết định cẩu thả có thể gây ra hậu quả kéo dài nhiều năm."},{"en":"Pollution causes consequences far beyond the local area.","vi":"Ô nhiễm gây ra hậu quả vượt xa khu vực địa phương."},{"en":"Ignoring the warnings may cause serious consequences later.","vi":"Bỏ qua những cảnh báo có thể gây ra hậu quả nghiêm trọng về sau."}]', '[]', NULL, '/kɔːz ˈkɑːnsɪkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 37, 'cause stress', 'gây căng thẳng', 'v + n', '[{"en":"Tight deadlines often cause stress for many students.","vi":"Những hạn chót gấp gáp thường gây căng thẳng cho nhiều sinh viên."},{"en":"Financial pressure can cause stress that affects physical health.","vi":"Áp lực tài chính có thể gây căng thẳng ảnh hưởng đến sức khỏe thể chất."},{"en":"Loud, crowded environments tend to cause stress over time.","vi":"Môi trường ồn ào, đông đúc có xu hướng gây căng thẳng theo thời gian."}]', '[]', NULL, '/kɔːz stres/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 38, 'central authority', 'cơ quan trung ương', 'adj + n', '[{"en":"A strong central authority coordinated the country''s emergency response.","vi":"Một cơ quan trung ương mạnh đã điều phối ứng phó khẩn cấp của cả nước."},{"en":"Without a central authority, the regions made conflicting decisions.","vi":"Không có cơ quan trung ương, các vùng đưa ra những quyết định mâu thuẫn."},{"en":"The central authority sets standards that local offices must follow.","vi":"Cơ quan trung ương đặt ra các tiêu chuẩn mà văn phòng địa phương phải tuân theo."}]', '[]', NULL, '/ˈsentrəl əˈθɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 39, 'central concept', 'khái niệm trung tâm', 'adj + n', '[{"en":"Supply and demand is a central concept in economics.","vi":"Cung và cầu là một khái niệm trung tâm trong kinh tế học."},{"en":"The lecture introduced the central concept of natural selection.","vi":"Bài giảng giới thiệu khái niệm trung tâm về chọn lọc tự nhiên."},{"en":"Understanding this central concept makes the rest of the theory clearer.","vi":"Hiểu khái niệm trung tâm này khiến phần còn lại của lý thuyết rõ ràng hơn."}]', '[]', NULL, '/ˈsentrəl ˈkɑːnsept/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 40, 'central concern', 'mối quan tâm chính', 'adj + n', '[{"en":"Student safety is a central concern for the whole university.","vi":"An toàn của sinh viên là mối quan tâm chính của toàn trường đại học."},{"en":"Fairness remained the central concern throughout the policy debate.","vi":"Sự công bằng vẫn là mối quan tâm chính trong suốt cuộc tranh luận chính sách."},{"en":"Data privacy has become a central concern in modern research.","vi":"Quyền riêng tư dữ liệu đã trở thành mối quan tâm chính trong nghiên cứu hiện đại."}]', '[]', NULL, '/ˈsentrəl kənˈsɜːrn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 41, 'central control', 'sự kiểm soát tập trung', 'adj + n', '[{"en":"The system relies on central control to keep operations consistent.","vi":"Hệ thống dựa vào sự kiểm soát tập trung để giữ hoạt động nhất quán."},{"en":"Too much central control can slow down local decision-making.","vi":"Sự kiểm soát tập trung quá mức có thể làm chậm việc ra quyết định địa phương."},{"en":"The reform reduced central control and gave regions more freedom.","vi":"Cuộc cải cách giảm sự kiểm soát tập trung và cho các vùng nhiều tự do hơn."}]', '[]', NULL, '/ˈsentrəl kənˈtroʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 42, 'central core', 'lõi trung tâm', 'adj + n', '[{"en":"Honesty forms the central core of his entire argument.","vi":"Sự trung thực tạo thành lõi trung tâm của toàn bộ lập luận của anh."},{"en":"The central core of the planet remains extremely hot.","vi":"Lõi trung tâm của hành tinh vẫn còn cực kỳ nóng."},{"en":"These principles make up the central core of the curriculum.","vi":"Những nguyên tắc này tạo nên lõi trung tâm của chương trình học."}]', '[]', NULL, '/ˈsentrəl kɔːr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 43, 'central feature', 'đặc điểm trung tâm', 'adj + n', '[{"en":"Repetition is a central feature of the author''s writing style.","vi":"Sự lặp lại là một đặc điểm trung tâm trong phong cách viết của tác giả."},{"en":"Collaboration became the central feature of the new program.","vi":"Sự hợp tác trở thành đặc điểm trung tâm của chương trình mới."},{"en":"Open courtyards are a central feature of traditional architecture.","vi":"Sân trong rộng mở là một đặc điểm trung tâm của kiến trúc truyền thống."}]', '[]', NULL, '/ˈsentrəl ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 44, 'central focus', 'trọng tâm chính', 'adj + n', '[{"en":"Climate change is the central focus of this year''s conference.","vi":"Biến đổi khí hậu là trọng tâm chính của hội nghị năm nay."},{"en":"The central focus of her thesis is childhood language development.","vi":"Trọng tâm chính của luận văn cô là sự phát triển ngôn ngữ ở trẻ em."},{"en":"Student wellbeing should be the central focus of any school.","vi":"Sự khỏe mạnh của học sinh nên là trọng tâm chính của mọi trường học."}]', '[]', NULL, '/ˈsentrəl ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 45, 'central government', 'chính quyền trung ương', 'adj + n', '[{"en":"The central government allocated extra funding to rural schools.","vi":"Chính quyền trung ương phân bổ thêm ngân sách cho các trường nông thôn."},{"en":"Local councils often clash with the central government over budgets.","vi":"Hội đồng địa phương thường xung đột với chính quyền trung ương về ngân sách."},{"en":"The central government sets national policies on education and health.","vi":"Chính quyền trung ương đặt ra chính sách quốc gia về giáo dục và y tế."}]', '[]', NULL, '/ˈsentrəl ˈɡʌvərnmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 46, 'central importance', 'tầm quan trọng cốt lõi', 'adj + n', '[{"en":"Clean water is of central importance to public health.","vi":"Nước sạch có tầm quan trọng cốt lõi đối với sức khỏe cộng đồng."},{"en":"The author stresses the central importance of historical context.","vi":"Tác giả nhấn mạnh tầm quan trọng cốt lõi của bối cảnh lịch sử."},{"en":"Trust is of central importance in any working relationship.","vi":"Sự tin tưởng có tầm quan trọng cốt lõi trong bất kỳ mối quan hệ làm việc nào."}]', '[]', NULL, '/ˈsentrəl ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 47, 'central issue', 'vấn đề trung tâm', 'adj + n', '[{"en":"The central issue of the debate was access to healthcare.","vi":"Vấn đề trung tâm của cuộc tranh luận là khả năng tiếp cận y tế."},{"en":"Funding remains the central issue facing the research department.","vi":"Ngân sách vẫn là vấn đề trung tâm mà khoa nghiên cứu đối mặt."},{"en":"We must address the central issue before discussing minor details.","vi":"Chúng ta phải giải quyết vấn đề trung tâm trước khi bàn các chi tiết nhỏ."}]', '[]', NULL, '/ˈsentrəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 48, 'central part', 'phần trung tâm', 'adj + n', '[{"en":"Fieldwork forms the central part of this geography course.","vi":"Thực địa tạo thành phần trung tâm của khóa học địa lý này."},{"en":"The market sits in the central part of the old city.","vi":"Khu chợ nằm ở phần trung tâm của thành phố cổ."},{"en":"Reflection is a central part of effective learning.","vi":"Sự suy ngẫm là một phần trung tâm của việc học hiệu quả."}]', '[]', NULL, '/ˈsentrəl pɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 49, 'central point', 'luận điểm trung tâm', 'adj + n', '[{"en":"The central point of her argument is often overlooked.","vi":"Luận điểm trung tâm trong lập luận của cô thường bị bỏ qua."},{"en":"Let me restate the central point so it stays clear.","vi":"Để mình nhắc lại luận điểm trung tâm để nó luôn rõ ràng."},{"en":"Every paragraph should support the essay''s central point.","vi":"Mỗi đoạn văn nên hỗ trợ cho luận điểm trung tâm của bài luận."}]', '[]', NULL, '/ˈsentrəl pɔɪnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 50, 'central position', 'vị trí trung tâm', 'adj + n', '[{"en":"The theory holds a central position in modern psychology.","vi":"Lý thuyết này giữ một vị trí trung tâm trong tâm lý học hiện đại."},{"en":"Her central position in the team gave her real influence.","vi":"Vị trí trung tâm của cô trong nhóm mang lại cho cô ảnh hưởng thực sự."},{"en":"The city''s central position made it a key trading hub.","vi":"Vị trí trung tâm của thành phố khiến nó thành một trung tâm thương mại quan trọng."}]', '[]', NULL, '/ˈsentrəl pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 51, 'central problem', 'vấn đề cốt lõi', 'adj + n', '[{"en":"The central problem is a lack of reliable, recent data.","vi":"Vấn đề cốt lõi là thiếu dữ liệu đáng tin cậy và mới."},{"en":"Her paper identifies the central problem facing urban planners.","vi":"Bài viết của cô xác định vấn đề cốt lõi mà các nhà quy hoạch đô thị gặp phải."},{"en":"Solving the central problem will resolve many smaller difficulties.","vi":"Giải quyết vấn đề cốt lõi sẽ tháo gỡ nhiều khó khăn nhỏ hơn."}]', '[]', NULL, '/ˈsentrəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 52, 'central question', 'câu hỏi trung tâm', 'adj + n', '[{"en":"The central question of the study concerns memory and aging.","vi":"Câu hỏi trung tâm của nghiên cứu liên quan đến trí nhớ và lão hóa."},{"en":"A clear central question keeps the research focused.","vi":"Một câu hỏi trung tâm rõ ràng giữ cho nghiên cứu tập trung."},{"en":"The seminar revolved around one central question about justice.","vi":"Buổi hội thảo xoay quanh một câu hỏi trung tâm về công lý."}]', '[]', NULL, '/ˈsentrəl ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 53, 'central role', 'vai trò trung tâm', 'adj + n', '[{"en":"Technology plays a central role in modern education.","vi":"Công nghệ đóng một vai trò trung tâm trong giáo dục hiện đại."},{"en":"She played a central role in organizing the conference.","vi":"Cô đóng vai trò trung tâm trong việc tổ chức hội nghị."},{"en":"Trust plays a central role in successful teamwork.","vi":"Sự tin tưởng đóng vai trò trung tâm trong làm việc nhóm thành công."}]', '[]', NULL, '/ˈsentrəl roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 54, 'central tenet', 'nguyên lý cốt lõi', 'adj + n', '[{"en":"Equality is a central tenet of democratic society.","vi":"Bình đẳng là một nguyên lý cốt lõi của xã hội dân chủ."},{"en":"The central tenet of his philosophy is personal responsibility.","vi":"Nguyên lý cốt lõi trong triết lý của ông là trách nhiệm cá nhân."},{"en":"Respect for evidence is a central tenet of science.","vi":"Tôn trọng bằng chứng là một nguyên lý cốt lõi của khoa học."}]', '[]', NULL, '/ˈsentrəl ˈtenət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 55, 'central theme', 'chủ đề trung tâm', 'adj + n', '[{"en":"Identity is the central theme of the entire novel.","vi":"Bản sắc là chủ đề trung tâm của toàn bộ cuốn tiểu thuyết."},{"en":"The central theme of the lecture was sustainable development.","vi":"Chủ đề trung tâm của bài giảng là phát triển bền vững."},{"en":"Loss runs as a central theme through her poetry.","vi":"Mất mát là chủ đề trung tâm xuyên suốt thơ của cô."}]', '[]', NULL, '/ˈsentrəl θiːm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 56, 'central aspect', 'khía cạnh trung tâm', 'adj + n', '[{"en":"Communication is a central aspect of effective leadership.","vi":"Giao tiếp là một khía cạnh trung tâm của khả năng lãnh đạo hiệu quả."},{"en":"The central aspect of the design is its flexibility.","vi":"Khía cạnh trung tâm của thiết kế là tính linh hoạt của nó."},{"en":"Motivation remains a central aspect of student success.","vi":"Động lực vẫn là một khía cạnh trung tâm của thành công học tập."}]', '[]', NULL, '/ˈsentrəl ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 57, 'central assumptions', 'giả định cốt lõi', 'adj + n', '[{"en":"The model rests on several central assumptions about human behavior.","vi":"Mô hình dựa trên một số giả định cốt lõi về hành vi con người."},{"en":"Critics questioned the central assumptions behind the forecast.","vi":"Người phê phán nghi ngờ những giả định cốt lõi đằng sau dự báo."},{"en":"If the central assumptions are wrong, the conclusions collapse.","vi":"Nếu các giả định cốt lõi sai, các kết luận sẽ sụp đổ."}]', '[]', NULL, '/ˈsentrəl əˈsʌmpʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 58, 'central characteristics', 'đặc trưng cốt lõi', 'adj + n', '[{"en":"The report lists the central characteristics of a healthy ecosystem.","vi":"Báo cáo liệt kê các đặc trưng cốt lõi của một hệ sinh thái khỏe mạnh."},{"en":"Flexibility and curiosity are central characteristics of good researchers.","vi":"Linh hoạt và tò mò là những đặc trưng cốt lõi của nhà nghiên cứu giỏi."},{"en":"These central characteristics distinguish one species from another.","vi":"Những đặc trưng cốt lõi này phân biệt loài này với loài khác."}]', '[]', NULL, '/ˈsentrəl ˌkærəktəˈrɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 59, 'central circumstances', 'hoàn cảnh cốt lõi', 'adj + n', '[{"en":"The court examined the central circumstances surrounding the dispute.","vi":"Tòa án xem xét các hoàn cảnh cốt lõi xoay quanh vụ tranh chấp."},{"en":"Understanding the central circumstances helps explain the decision.","vi":"Hiểu các hoàn cảnh cốt lõi giúp giải thích quyết định đó."},{"en":"Her analysis focuses on the central circumstances of the conflict.","vi":"Phân tích của cô tập trung vào các hoàn cảnh cốt lõi của cuộc xung đột."}]', '[]', NULL, '/ˈsentrəl ˈsɜːrkəmstænsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 60, 'change constantly', 'thay đổi liên tục', 'v + adv', '[{"en":"Market prices change constantly in response to global events.","vi":"Giá thị trường thay đổi liên tục để phản ứng với các sự kiện toàn cầu."},{"en":"Languages change constantly as new words enter everyday use.","vi":"Ngôn ngữ thay đổi liên tục khi những từ mới đi vào sử dụng hàng ngày."},{"en":"Weather patterns change constantly, making forecasts difficult.","vi":"Các kiểu thời tiết thay đổi liên tục, khiến việc dự báo trở nên khó khăn."}]', '[]', NULL, '/tʃeɪndʒ ˈkɑːnstəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 61, 'change dramatically', 'thay đổi mạnh mẽ', 'v + adv', '[{"en":"Attitudes toward technology have changed dramatically over a decade.","vi":"Thái độ đối với công nghệ đã thay đổi mạnh mẽ trong một thập kỷ."},{"en":"The landscape can change dramatically after a single flood.","vi":"Cảnh quan có thể thay đổi mạnh mẽ chỉ sau một trận lũ."},{"en":"Her writing style changed dramatically between the two novels.","vi":"Phong cách viết của cô thay đổi mạnh mẽ giữa hai cuốn tiểu thuyết."}]', '[]', NULL, '/tʃeɪndʒ drəˈmætɪkli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 62, 'change rapidly', 'thay đổi nhanh chóng', 'v + adv', '[{"en":"Digital technology continues to change rapidly every year.","vi":"Công nghệ số tiếp tục thay đổi nhanh chóng mỗi năm."},{"en":"Consumer habits can change rapidly during an economic crisis.","vi":"Thói quen tiêu dùng có thể thay đổi nhanh chóng trong khủng hoảng kinh tế."},{"en":"Cities change rapidly when populations grow without planning.","vi":"Các thành phố thay đổi nhanh chóng khi dân số tăng mà thiếu quy hoạch."}]', '[]', NULL, '/tʃeɪndʒ ˈræpɪdli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 63, 'change an attitude', 'thay đổi thái độ', 'v + n', '[{"en":"A single experience can change an attitude that lasted for years.","vi":"Một trải nghiệm duy nhất có thể thay đổi thái độ đã tồn tại nhiều năm."},{"en":"Good teachers know how to change an attitude through encouragement.","vi":"Giáo viên giỏi biết cách thay đổi thái độ thông qua sự khích lệ."},{"en":"Campaigns try to change an attitude toward recycling.","vi":"Các chiến dịch cố gắng thay đổi thái độ đối với việc tái chế."}]', '[]', NULL, '/tʃeɪndʒ ən ˈætɪtuːd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 64, 'changing attitudes', 'những thái độ đang thay đổi', 'adj + n', '[{"en":"The survey tracks changing attitudes toward remote work.","vi":"Cuộc khảo sát theo dõi những thái độ đang thay đổi về làm việc từ xa."},{"en":"Changing attitudes about diet have reshaped the food industry.","vi":"Những thái độ đang thay đổi về ăn uống đã định hình lại ngành thực phẩm."},{"en":"Advertisers must respond to changing attitudes among young consumers.","vi":"Nhà quảng cáo phải đáp ứng những thái độ đang thay đổi của người tiêu dùng trẻ."}]', '[]', NULL, '/ˈtʃeɪndʒɪŋ ˈætɪtuːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 65, 'changing circumstances', 'hoàn cảnh thay đổi', 'adj + n', '[{"en":"Successful businesses adapt quickly to changing circumstances.","vi":"Doanh nghiệp thành công thích nghi nhanh với hoàn cảnh thay đổi."},{"en":"The plan was flexible enough to handle changing circumstances.","vi":"Kế hoạch đủ linh hoạt để ứng phó với hoàn cảnh thay đổi."},{"en":"Leaders must make decisions under constantly changing circumstances.","vi":"Người lãnh đạo phải ra quyết định trong hoàn cảnh thay đổi liên tục."}]', '[]', NULL, '/ˈtʃeɪndʒɪŋ ˈsɜːrkəmstænsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 66, 'changing nature', 'bản chất thay đổi', 'adj + n', '[{"en":"The book explores the changing nature of modern families.","vi":"Cuốn sách khám phá bản chất thay đổi của gia đình hiện đại."},{"en":"Researchers study the changing nature of work in a digital age.","vi":"Các nhà nghiên cứu nghiên cứu bản chất thay đổi của công việc trong thời đại số."},{"en":"We must understand the changing nature of global trade.","vi":"Chúng ta phải hiểu bản chất thay đổi của thương mại toàn cầu."}]', '[]', NULL, '/ˈtʃeɪndʒɪŋ ˈneɪtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 67, 'changing needs', 'nhu cầu thay đổi', 'adj + n', '[{"en":"The curriculum is updated to meet students'' changing needs.","vi":"Chương trình học được cập nhật để đáp ứng nhu cầu thay đổi của sinh viên."},{"en":"Hospitals must adapt services to the changing needs of patients.","vi":"Bệnh viện phải điều chỉnh dịch vụ theo nhu cầu thay đổi của bệnh nhân."},{"en":"Good design anticipates the changing needs of its users.","vi":"Thiết kế tốt dự đoán được nhu cầu thay đổi của người dùng."}]', '[]', NULL, '/ˈtʃeɪndʒɪŋ niːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 68, 'changing pattern', 'khuôn mẫu thay đổi', 'adj + n', '[{"en":"The data show a changing pattern of migration across the region.","vi":"Dữ liệu cho thấy một khuôn mẫu di cư đang thay đổi trong khu vực."},{"en":"Scientists noticed a changing pattern in seasonal rainfall.","vi":"Các nhà khoa học nhận thấy một khuôn mẫu thay đổi trong lượng mưa theo mùa."},{"en":"The changing pattern of consumption reflects new lifestyles.","vi":"Khuôn mẫu tiêu dùng đang thay đổi phản ánh những lối sống mới."}]', '[]', NULL, '/ˈtʃeɪndʒɪŋ ˈpætərn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 69, 'changing world', 'thế giới đang thay đổi', 'adj + n', '[{"en":"Education must prepare young people for a changing world.","vi":"Giáo dục phải chuẩn bị cho người trẻ bước vào một thế giới đang thay đổi."},{"en":"Businesses that ignore a changing world rarely survive long.","vi":"Doanh nghiệp bỏ qua một thế giới đang thay đổi hiếm khi tồn tại lâu."},{"en":"In a rapidly changing world, lifelong learning is essential.","vi":"Trong một thế giới thay đổi nhanh, học tập suốt đời là điều thiết yếu."}]', '[]', NULL, '/ˈtʃeɪndʒɪŋ wɜːrld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 70, 'characteristic feature', 'đặc điểm đặc trưng', 'adj + n', '[{"en":"Steep roofs are a characteristic feature of alpine houses.","vi":"Mái dốc là một đặc điểm đặc trưng của những ngôi nhà vùng núi cao."},{"en":"Irony is a characteristic feature of the writer''s later work.","vi":"Sự châm biếm là một đặc điểm đặc trưng trong tác phẩm sau này của nhà văn."},{"en":"A characteristic feature of the disease is sudden fatigue.","vi":"Một đặc điểm đặc trưng của căn bệnh là sự mệt mỏi đột ngột."}]', '[]', NULL, '/ˌkærəktəˈrɪstɪk ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 71, 'chemical reaction', 'phản ứng hóa học', 'adj + n', '[{"en":"Mixing the two liquids triggered a violent chemical reaction.","vi":"Trộn hai chất lỏng đã kích hoạt một phản ứng hóa học dữ dội."},{"en":"Heat often speeds up the rate of a chemical reaction.","vi":"Nhiệt thường làm tăng tốc độ của một phản ứng hóa học."},{"en":"Photosynthesis is a chemical reaction that produces oxygen.","vi":"Quang hợp là một phản ứng hóa học tạo ra oxy."}]', '[]', NULL, '/ˈkemɪkəl riˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 72, 'civil case', 'vụ án dân sự', 'adj + n', '[{"en":"A civil case usually involves disputes over money or property.","vi":"Một vụ án dân sự thường liên quan đến tranh chấp về tiền hoặc tài sản."},{"en":"Unlike criminal trials, a civil case rarely leads to prison.","vi":"Khác với án hình sự, một vụ án dân sự hiếm khi dẫn đến tù giam."},{"en":"The lawyer specialized in complex civil cases for businesses.","vi":"Luật sư chuyên về các vụ án dân sự phức tạp cho doanh nghiệp."}]', '[]', NULL, '/ˈsɪvəl keɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 73, 'civil society', 'xã hội dân sự', 'adj + n', '[{"en":"A strong civil society helps hold governments accountable.","vi":"Một xã hội dân sự mạnh giúp buộc chính phủ phải có trách nhiệm."},{"en":"Charities and unions are important parts of civil society.","vi":"Các tổ chức từ thiện và công đoàn là phần quan trọng của xã hội dân sự."},{"en":"The essay examines the role of civil society in reform.","vi":"Bài luận xem xét vai trò của xã hội dân sự trong cải cách."}]', '[]', NULL, '/ˈsɪvəl səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 74, 'class consciousness', 'ý thức giai cấp', 'n + n', '[{"en":"Marx argued that class consciousness drives social change.","vi":"Marx lập luận rằng ý thức giai cấp thúc đẩy thay đổi xã hội."},{"en":"The strike reflected a growing sense of class consciousness.","vi":"Cuộc đình công phản ánh một ý thức giai cấp ngày càng tăng."},{"en":"The novel explores class consciousness among factory workers.","vi":"Cuốn tiểu thuyết khám phá ý thức giai cấp trong giới công nhân nhà máy."}]', '[]', NULL, '/klæs ˈkɑːnʃəsnəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 75, 'classic example', 'ví dụ điển hình', 'adj + n', '[{"en":"This experiment is a classic example of scientific method.","vi":"Thí nghiệm này là một ví dụ điển hình về phương pháp khoa học."},{"en":"Her speech offers a classic example of persuasive writing.","vi":"Bài phát biểu của cô là một ví dụ điển hình về văn thuyết phục."},{"en":"The case is a classic example of how markets fail.","vi":"Vụ việc là một ví dụ điển hình về cách thị trường thất bại."}]', '[]', NULL, '/ˈklæsɪk ɪɡˈzæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 76, 'classic study', 'nghiên cứu kinh điển', 'adj + n', '[{"en":"The lecture referred to a classic study on human memory.","vi":"Bài giảng nhắc đến một nghiên cứu kinh điển về trí nhớ con người."},{"en":"This classic study still shapes how psychologists view obedience.","vi":"Nghiên cứu kinh điển này vẫn định hình cách nhà tâm lý nhìn nhận sự phục tùng."},{"en":"Many textbooks cite this classic study as foundational.","vi":"Nhiều sách giáo khoa trích dẫn nghiên cứu kinh điển này như nền tảng."}]', '[]', NULL, '/ˈklæsɪk ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 77, 'classic text', 'văn bản kinh điển', 'adj + n', '[{"en":"Students are required to read this classic text on ethics.","vi":"Sinh viên được yêu cầu đọc văn bản kinh điển này về đạo đức học."},{"en":"The classic text remains relevant to debates today.","vi":"Văn bản kinh điển này vẫn còn phù hợp với các tranh luận ngày nay."},{"en":"Every law student encounters this classic text early on.","vi":"Mọi sinh viên luật đều tiếp xúc văn bản kinh điển này từ sớm."}]', '[]', NULL, '/ˈklæsɪk tekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 78, 'classic work', 'tác phẩm kinh điển', 'adj + n', '[{"en":"This classic work influenced generations of economists.","vi":"Tác phẩm kinh điển này đã ảnh hưởng đến nhiều thế hệ nhà kinh tế."},{"en":"The professor recommended a classic work on political theory.","vi":"Giáo sư giới thiệu một tác phẩm kinh điển về lý thuyết chính trị."},{"en":"Few classic works are read as widely as this one.","vi":"Ít tác phẩm kinh điển nào được đọc rộng rãi như cuốn này."}]', '[]', NULL, '/ˈklæsɪk wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 79, 'classical theory', 'lý thuyết cổ điển', 'adj + n', '[{"en":"Classical theory assumes that markets always reach equilibrium.","vi":"Lý thuyết cổ điển giả định rằng thị trường luôn đạt đến cân bằng."},{"en":"Modern research often challenges aspects of classical theory.","vi":"Nghiên cứu hiện đại thường thách thức nhiều khía cạnh của lý thuyết cổ điển."},{"en":"The course compares classical theory with newer approaches.","vi":"Khóa học so sánh lý thuyết cổ điển với các cách tiếp cận mới hơn."}]', '[]', NULL, '/ˈklæsɪkəl ˈθɪri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 80, 'clear boundary', 'ranh giới rõ ràng', 'adj + n', '[{"en":"There is no clear boundary between the two disciplines.","vi":"Không có ranh giới rõ ràng giữa hai ngành học này."},{"en":"The fence marks a clear boundary between the properties.","vi":"Hàng rào đánh dấu một ranh giới rõ ràng giữa các khu đất."},{"en":"Good managers set a clear boundary between work and rest.","vi":"Người quản lý giỏi đặt ranh giới rõ ràng giữa công việc và nghỉ ngơi."}]', '[]', NULL, '/klɪr ˈbaʊndri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 81, 'clear distinction', 'sự phân biệt rõ ràng', 'adj + n', '[{"en":"The author draws a clear distinction between fact and opinion.","vi":"Tác giả phân biệt rõ ràng giữa sự thật và ý kiến."},{"en":"There is a clear distinction between weather and climate.","vi":"Có một sự phân biệt rõ ràng giữa thời tiết và khí hậu."},{"en":"We must make a clear distinction between cause and effect.","vi":"Chúng ta phải phân biệt rõ ràng giữa nguyên nhân và kết quả."}]', '[]', NULL, '/klɪr dɪˈstɪŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 82, 'clear evidence', 'bằng chứng rõ ràng', 'adj + n', '[{"en":"The study provides clear evidence of rising sea levels.","vi":"Nghiên cứu cung cấp bằng chứng rõ ràng về mực nước biển dâng."},{"en":"There is clear evidence that exercise improves mental health.","vi":"Có bằng chứng rõ ràng rằng tập thể dục cải thiện sức khỏe tinh thần."},{"en":"Without clear evidence, the claim remains unconvincing.","vi":"Không có bằng chứng rõ ràng, lời tuyên bố vẫn thiếu thuyết phục."}]', '[]', NULL, '/klɪr ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 83, 'clear focus', 'trọng tâm rõ ràng', 'adj + n', '[{"en":"A good essay needs a clear focus from the start.","vi":"Một bài luận hay cần có trọng tâm rõ ràng ngay từ đầu."},{"en":"The project succeeded because the team kept a clear focus.","vi":"Dự án thành công vì cả nhóm giữ được một trọng tâm rõ ràng."},{"en":"Without a clear focus, the research became scattered.","vi":"Không có trọng tâm rõ ràng, nghiên cứu trở nên rời rạc."}]', '[]', NULL, '/klɪr ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 84, 'clear indication', 'dấu hiệu rõ ràng', 'adj + n', '[{"en":"Rising temperatures are a clear indication of climate change.","vi":"Nhiệt độ tăng là một dấu hiệu rõ ràng của biến đổi khí hậu."},{"en":"Her quick reply was a clear indication of her interest.","vi":"Câu trả lời nhanh của cô là một dấu hiệu rõ ràng về sự quan tâm."},{"en":"The data give a clear indication of improving performance.","vi":"Dữ liệu đưa ra một dấu hiệu rõ ràng về hiệu suất đang cải thiện."}]', '[]', NULL, '/klɪr ˌɪndɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 85, 'clear relationship', 'mối liên hệ rõ ràng', 'adj + n', '[{"en":"There is a clear relationship between sleep and learning.","vi":"Có một mối liên hệ rõ ràng giữa giấc ngủ và việc học."},{"en":"The graph shows a clear relationship between price and demand.","vi":"Biểu đồ cho thấy mối liên hệ rõ ràng giữa giá cả và nhu cầu."},{"en":"Researchers found a clear relationship between diet and energy.","vi":"Các nhà nghiên cứu tìm thấy mối liên hệ rõ ràng giữa chế độ ăn và năng lượng."}]', '[]', NULL, '/klɪr rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 86, 'clear statement', 'tuyên bố rõ ràng', 'adj + n', '[{"en":"The report opens with a clear statement of its aims.","vi":"Báo cáo mở đầu bằng một tuyên bố rõ ràng về mục tiêu của nó."},{"en":"A clear statement of the problem helps the reader follow.","vi":"Một tuyên bố rõ ràng về vấn đề giúp người đọc dễ theo dõi."},{"en":"The policy needs a clear statement about who is responsible.","vi":"Chính sách cần một tuyên bố rõ ràng về việc ai chịu trách nhiệm."}]', '[]', NULL, '/klɪr ˈsteɪtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 87, 'clear structure', 'cấu trúc rõ ràng', 'adj + n', '[{"en":"A clear structure makes any argument easier to follow.","vi":"Một cấu trúc rõ ràng khiến mọi lập luận dễ theo dõi hơn."},{"en":"The essay lacked a clear structure, so ideas felt disconnected.","vi":"Bài luận thiếu cấu trúc rõ ràng, nên các ý tưởng có vẻ rời rạc."},{"en":"Good presentations rely on a clear structure and strong examples.","vi":"Bài thuyết trình tốt dựa vào cấu trúc rõ ràng và ví dụ mạnh."}]', '[]', NULL, '/klɪr ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 88, 'clearly defined', 'được xác định rõ ràng', 'adv + vpp', '[{"en":"Each team member had a clearly defined role in the project.","vi":"Mỗi thành viên trong nhóm có một vai trò được xác định rõ ràng."},{"en":"The goals must be clearly defined before work begins.","vi":"Các mục tiêu phải được xác định rõ ràng trước khi bắt đầu làm việc."},{"en":"A clearly defined hypothesis guides the entire experiment.","vi":"Một giả thuyết được xác định rõ ràng dẫn dắt toàn bộ thí nghiệm."}]', '[]', NULL, '/ˈklɪrli dɪˈfaɪnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 89, 'clearly demonstrated', 'được chứng minh rõ ràng', 'adv + vpp', '[{"en":"The benefits of the method were clearly demonstrated in trials.","vi":"Lợi ích của phương pháp đã được chứng minh rõ ràng trong các thử nghiệm."},{"en":"She clearly demonstrated the link between the two variables.","vi":"Cô đã chứng minh rõ ràng mối liên hệ giữa hai biến số."},{"en":"The results clearly demonstrated the value of early intervention.","vi":"Kết quả đã chứng minh rõ ràng giá trị của việc can thiệp sớm."}]', '[]', NULL, '/ˈklɪrli ˈdemənstreɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 90, 'clearly established', 'được thiết lập rõ ràng', 'adv + vpp', '[{"en":"The link between smoking and cancer is clearly established.","vi":"Mối liên hệ giữa hút thuốc và ung thư đã được thiết lập rõ ràng."},{"en":"Once the rules are clearly established, disputes become rare.","vi":"Một khi các quy tắc được thiết lập rõ ràng, tranh chấp trở nên hiếm."},{"en":"The procedure follows a clearly established set of guidelines.","vi":"Quy trình tuân theo một bộ hướng dẫn được thiết lập rõ ràng."}]', '[]', NULL, '/ˈklɪrli ɪˈstæblɪʃt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 91, 'clearly evident', 'rõ ràng hiển nhiên', 'adv + adj', '[{"en":"Her talent was clearly evident from her very first essay.","vi":"Tài năng của cô rõ ràng hiển nhiên ngay từ bài luận đầu tiên."},{"en":"The effects of the drought were clearly evident across the fields.","vi":"Tác động của hạn hán rõ ràng hiển nhiên trên khắp các cánh đồng."},{"en":"It is clearly evident that more research is needed here.","vi":"Rõ ràng hiển nhiên rằng cần thêm nghiên cứu ở lĩnh vực này."}]', '[]', NULL, '/ˈklɪrli ˈevɪdənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 92, 'clearly identified', 'được xác định rõ ràng', 'adv + vpp', '[{"en":"Each risk must be clearly identified before the project starts.","vi":"Mỗi rủi ro phải được xác định rõ ràng trước khi dự án bắt đầu."},{"en":"The main causes of failure were clearly identified in the report.","vi":"Những nguyên nhân chính của thất bại được xác định rõ ràng trong báo cáo."},{"en":"Sources should be clearly identified to avoid plagiarism.","vi":"Nguồn tài liệu nên được xác định rõ ràng để tránh đạo văn."}]', '[]', NULL, '/ˈklɪrli aɪˈdentɪfaɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 93, 'clearly important', 'rõ ràng quan trọng', 'adv + adj', '[{"en":"Sleep is clearly important for memory and concentration.","vi":"Giấc ngủ rõ ràng quan trọng đối với trí nhớ và sự tập trung."},{"en":"It is clearly important to verify sources before citing them.","vi":"Rõ ràng quan trọng là phải kiểm chứng nguồn trước khi trích dẫn."},{"en":"Funding is clearly important, but leadership matters too.","vi":"Ngân sách rõ ràng quan trọng, nhưng sự lãnh đạo cũng quan trọng."}]', '[]', NULL, '/ˈklɪrli ɪmˈpɔːrtənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 94, 'clearly related to', 'rõ ràng liên quan đến', 'adv + vpp', '[{"en":"These symptoms are clearly related to a lack of sleep.","vi":"Những triệu chứng này rõ ràng liên quan đến việc thiếu ngủ."},{"en":"Her thesis is clearly related to earlier work in the field.","vi":"Luận văn của cô rõ ràng liên quan đến các công trình trước trong lĩnh vực."},{"en":"The rise in cases is clearly related to crowded conditions.","vi":"Sự gia tăng số ca rõ ràng liên quan đến điều kiện đông đúc."}]', '[]', NULL, '/ˈklɪrli rɪˈleɪtɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 95, 'clearly understand', 'hiểu rõ ràng', 'adv + v', '[{"en":"Students must clearly understand the rules before the exam.","vi":"Sinh viên phải hiểu rõ ràng các quy tắc trước kỳ thi."},{"en":"I want to clearly understand your argument before responding.","vi":"Mình muốn hiểu rõ ràng lập luận của bạn trước khi phản hồi."},{"en":"Few people clearly understand how the algorithm actually works.","vi":"Ít người hiểu rõ ràng thuật toán thực sự hoạt động như thế nào."}]', '[]', NULL, '/ˈklɪrli ˌʌndərˈstænd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 96, 'clearly visible', 'rõ ràng có thể thấy', 'adv + adj', '[{"en":"The mountains were clearly visible on that bright morning.","vi":"Những ngọn núi rõ ràng có thể thấy trong buổi sáng quang đãng đó."},{"en":"The trend is clearly visible in the latest set of graphs.","vi":"Xu hướng rõ ràng có thể thấy trong bộ biểu đồ mới nhất."},{"en":"Safety signs should be clearly visible at every entrance.","vi":"Biển báo an toàn nên rõ ràng có thể thấy ở mọi lối vào."}]', '[]', NULL, '/ˈklɪrli ˈvɪzəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 97, 'climate change', 'biến đổi khí hậu', 'n + n', '[{"en":"Climate change is one of the greatest challenges of our time.","vi":"Biến đổi khí hậu là một trong những thách thức lớn nhất thời đại."},{"en":"Scientists warn that climate change is accelerating worldwide.","vi":"Các nhà khoa học cảnh báo biến đổi khí hậu đang tăng tốc trên toàn cầu."},{"en":"Reducing emissions is essential to slowing climate change.","vi":"Giảm phát thải là điều thiết yếu để làm chậm biến đổi khí hậu."}]', '[]', NULL, '/ˈklaɪmət tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 98, 'climatic conditions', 'điều kiện khí hậu', 'adj + n', '[{"en":"Crops vary depending on local climatic conditions.","vi":"Cây trồng thay đổi tùy theo điều kiện khí hậu địa phương."},{"en":"Harsh climatic conditions limit which species can survive.","vi":"Điều kiện khí hậu khắc nghiệt hạn chế những loài có thể sống sót."},{"en":"The study compares plant growth under different climatic conditions.","vi":"Nghiên cứu so sánh sự phát triển của cây trong các điều kiện khí hậu khác nhau."}]', '[]', NULL, '/klaɪˈmætɪk kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 99, 'close contact', 'sự tiếp xúc gần', 'adj + n', '[{"en":"The disease spreads through close contact between infected people.","vi":"Bệnh lây lan qua sự tiếp xúc gần giữa những người bị nhiễm."},{"en":"She kept in close contact with her former colleagues.","vi":"Cô ấy giữ liên lạc thường xuyên với các đồng nghiệp cũ."},{"en":"Researchers maintain close contact with the communities they study.","vi":"Các nhà nghiên cứu duy trì sự tiếp xúc gần với cộng đồng họ nghiên cứu."}]', '[]', NULL, '/kloʊs ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 100, 'close proximity', 'khoảng cách rất gần', 'adj + n', '[{"en":"The two buildings stand in close proximity to each other.","vi":"Hai tòa nhà nằm rất gần nhau."},{"en":"Living in close proximity to factories can affect health.","vi":"Sống gần các nhà máy có thể ảnh hưởng đến sức khỏe."},{"en":"The study examined animals living in close proximity to humans.","vi":"Nghiên cứu xem xét các loài vật sống rất gần con người."}]', '[]', NULL, '/kloʊs prɑːkˈsɪməti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 101, 'close relationship', 'mối quan hệ thân thiết', 'adj + n', '[{"en":"There is a close relationship between diet and overall health.","vi":"Có một mối quan hệ chặt chẽ giữa chế độ ăn và sức khỏe."},{"en":"She built a close relationship with her academic supervisor.","vi":"Cô ấy xây dựng mối quan hệ thân thiết với người hướng dẫn."},{"en":"The data show a close relationship between income and education.","vi":"Dữ liệu cho thấy mối quan hệ chặt chẽ giữa thu nhập và học vấn."}]', '[]', NULL, '/kloʊs rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 102, 'close scrutiny', 'sự xem xét kỹ lưỡng', 'adj + n', '[{"en":"The proposal came under close scrutiny from the committee.","vi":"Đề xuất bị ủy ban xem xét kỹ lưỡng."},{"en":"These results deserve close scrutiny before any conclusions are drawn.","vi":"Những kết quả này cần được xem xét kỹ trước khi kết luận."},{"en":"Public spending is subject to close scrutiny by auditors.","vi":"Chi tiêu công chịu sự xem xét kỹ lưỡng từ các kiểm toán viên."}]', '[]', NULL, '/kloʊs ˈskruːtəni/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 103, 'closely allied to', 'gắn bó chặt chẽ với', 'adv + vpp', '[{"en":"Linguistics is closely allied to psychology in many respects.","vi":"Ngôn ngữ học gắn bó chặt chẽ với tâm lý học ở nhiều khía cạnh."},{"en":"This theory is closely allied to earlier philosophical ideas.","vi":"Lý thuyết này gắn bó chặt chẽ với các tư tưởng triết học trước đó."},{"en":"The firm is closely allied to several major research institutions.","vi":"Công ty gắn bó chặt chẽ với nhiều viện nghiên cứu lớn."}]', '[]', NULL, '/ˈkloʊsli əˈlaɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 104, 'closely associated with', 'gắn liền chặt chẽ với', 'adv + vpp', '[{"en":"Smoking is closely associated with several serious diseases.","vi":"Hút thuốc gắn liền chặt chẽ với nhiều căn bệnh nghiêm trọng."},{"en":"His name is closely associated with the civil rights movement.","vi":"Tên ông gắn liền chặt chẽ với phong trào dân quyền."},{"en":"Poverty is closely associated with poor educational outcomes.","vi":"Nghèo đói gắn liền chặt chẽ với kết quả học tập kém."}]', '[]', NULL, '/ˈkloʊsli əˈsoʊsieɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 105, 'closely connected to', 'liên kết chặt chẽ với', 'adv + vpp', '[{"en":"Economic growth is closely connected to political stability.","vi":"Tăng trưởng kinh tế liên kết chặt chẽ với ổn định chính trị."},{"en":"These two problems are closely connected to one another.","vi":"Hai vấn đề này liên kết chặt chẽ với nhau."},{"en":"Her research is closely connected to current environmental debates.","vi":"Nghiên cứu của cô liên kết chặt chẽ với các tranh luận môi trường hiện nay."}]', '[]', NULL, '/ˈkloʊsli kəˈnektɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 106, 'closely linked to', 'liên hệ mật thiết với', 'adv + vpp', '[{"en":"Mental health is closely linked to physical wellbeing.","vi":"Sức khỏe tinh thần liên hệ mật thiết với sức khỏe thể chất."},{"en":"Unemployment is closely linked to rising crime rates.","vi":"Thất nghiệp liên hệ mật thiết với tỉ lệ tội phạm tăng."},{"en":"The decline is closely linked to changes in consumer behaviour.","vi":"Sự suy giảm liên hệ mật thiết với thay đổi trong hành vi tiêu dùng."}]', '[]', NULL, '/ˈkloʊsli lɪŋkt tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 107, 'closely related to', 'có liên quan mật thiết với', 'adv + vpp', '[{"en":"This species is closely related to the domestic cat.","vi":"Loài này có liên quan mật thiết với mèo nhà."},{"en":"The two questions are closely related to each other.","vi":"Hai câu hỏi có liên quan mật thiết với nhau."},{"en":"Job satisfaction is closely related to employee productivity.","vi":"Sự hài lòng trong công việc liên quan mật thiết với năng suất."}]', '[]', NULL, '/ˈkloʊsli rɪˈleɪtɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 108, 'closely resemble', 'rất giống với', 'adv + v', '[{"en":"The fake documents closely resemble the genuine originals.","vi":"Các tài liệu giả rất giống bản gốc thật."},{"en":"Her early paintings closely resemble those of her teacher.","vi":"Các bức tranh ban đầu của cô rất giống tranh của thầy."},{"en":"The model''s predictions closely resemble the observed data.","vi":"Dự đoán của mô hình rất giống với dữ liệu quan sát được."}]', '[]', NULL, '/ˈkloʊsli rɪˈzembəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 109, 'closely tied', 'gắn kết chặt chẽ', 'adv + vpp', '[{"en":"Their success is closely tied to government funding.","vi":"Thành công của họ gắn kết chặt chẽ với nguồn tài trợ chính phủ."},{"en":"National identity is closely tied to shared language and history.","vi":"Bản sắc dân tộc gắn kết chặt chẽ với ngôn ngữ và lịch sử chung."},{"en":"Wages are closely tied to overall company performance.","vi":"Tiền lương gắn kết chặt chẽ với hiệu quả chung của công ty."}]', '[]', NULL, '/ˈkloʊsli taɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 110, 'closer examination', 'sự xem xét kỹ hơn', 'adj + n', '[{"en":"Closer examination of the data revealed several errors.","vi":"Việc xem xét kỹ hơn dữ liệu đã phát hiện nhiều sai sót."},{"en":"The argument falls apart under closer examination.","vi":"Lập luận sụp đổ khi được xem xét kỹ hơn."},{"en":"Closer examination shows the two cases differ significantly.","vi":"Xem xét kỹ hơn cho thấy hai trường hợp khác nhau đáng kể."}]', '[]', NULL, '/ˈkloʊsər ɪɡˌzæmɪˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 111, 'closer inspection', 'sự kiểm tra kỹ hơn', 'adj + n', '[{"en":"On closer inspection, the painting turned out to be a copy.","vi":"Khi kiểm tra kỹ hơn, bức tranh hóa ra là bản sao."},{"en":"Closer inspection of the results raised new questions.","vi":"Việc kiểm tra kỹ hơn các kết quả làm nảy sinh câu hỏi mới."},{"en":"The flaw became obvious only on closer inspection.","vi":"Lỗi chỉ trở nên rõ ràng khi kiểm tra kỹ hơn."}]', '[]', NULL, '/ˈkloʊsər ɪnˈspekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 112, 'closer look', 'cái nhìn cận cảnh hơn', 'adj + n', '[{"en":"Let us take a closer look at the underlying causes.","vi":"Chúng ta hãy nhìn kỹ hơn vào các nguyên nhân sâu xa."},{"en":"A closer look reveals important differences between the groups.","vi":"Một cái nhìn kỹ hơn cho thấy những khác biệt quan trọng giữa các nhóm."},{"en":"This chapter takes a closer look at urban migration.","vi":"Chương này xem xét kỹ hơn hiện tượng di cư đô thị."}]', '[]', NULL, '/ˈkloʊsər lʊk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 113, 'cognitive ability', 'khả năng nhận thức', 'adj + n', '[{"en":"Sleep deprivation can reduce a person''s cognitive ability.","vi":"Thiếu ngủ có thể làm giảm khả năng nhận thức của một người."},{"en":"The tests measure several aspects of cognitive ability.","vi":"Các bài kiểm tra đo lường nhiều khía cạnh của khả năng nhận thức."},{"en":"Cognitive ability tends to decline gradually with age.","vi":"Khả năng nhận thức có xu hướng giảm dần theo tuổi tác."}]', '[]', NULL, '/ˈkɑːɡnətɪv əˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 114, 'cognitive development', 'sự phát triển nhận thức', 'adj + n', '[{"en":"Early childhood is crucial for cognitive development.","vi":"Tuổi thơ ấu rất quan trọng đối với sự phát triển nhận thức."},{"en":"Play supports cognitive development in young children.","vi":"Vui chơi hỗ trợ sự phát triển nhận thức ở trẻ nhỏ."},{"en":"The study tracked cognitive development over several years.","vi":"Nghiên cứu theo dõi sự phát triển nhận thức trong nhiều năm."}]', '[]', NULL, '/ˈkɑːɡnətɪv dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 115, 'cognitive skills', 'kỹ năng nhận thức', 'adj + n', '[{"en":"Reading regularly helps children develop cognitive skills.","vi":"Đọc sách thường xuyên giúp trẻ phát triển kỹ năng nhận thức."},{"en":"The program aims to strengthen students'' cognitive skills.","vi":"Chương trình nhằm tăng cường kỹ năng nhận thức của học sinh."},{"en":"Problem solving relies on a range of cognitive skills.","vi":"Giải quyết vấn đề dựa vào nhiều kỹ năng nhận thức khác nhau."}]', '[]', NULL, '/ˈkɑːɡnətɪv skɪlz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 116, 'collaborative learning', 'học tập hợp tác', 'adj + n', '[{"en":"Collaborative learning encourages students to share ideas freely.","vi":"Học tập hợp tác khuyến khích học sinh chia sẻ ý tưởng tự do."},{"en":"The teacher organized the class around collaborative learning tasks.","vi":"Giáo viên tổ chức lớp học quanh các nhiệm vụ học tập hợp tác."},{"en":"Research suggests collaborative learning improves long-term retention.","vi":"Nghiên cứu cho thấy học tập hợp tác cải thiện khả năng ghi nhớ lâu dài."}]', '[]', NULL, '/kəˈlæbərətɪv ˈlɜːrnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 117, 'collect data', 'thu thập dữ liệu', 'v + n', '[{"en":"Researchers collect data through surveys and interviews.","vi":"Các nhà nghiên cứu thu thập dữ liệu qua khảo sát và phỏng vấn."},{"en":"We need to collect data before drawing any conclusions.","vi":"Chúng ta cần thu thập dữ liệu trước khi đưa ra kết luận."},{"en":"The sensors collect data on temperature every hour.","vi":"Các cảm biến thu thập dữ liệu về nhiệt độ mỗi giờ."}]', '[]', NULL, '/kəˈlekt ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 118, 'collect information', 'thu thập thông tin', 'v + n', '[{"en":"The team collects information from a wide range of sources.","vi":"Nhóm thu thập thông tin từ nhiều nguồn khác nhau."},{"en":"Companies collect information about their customers'' preferences.","vi":"Các công ty thu thập thông tin về sở thích của khách hàng."},{"en":"We collect information carefully to ensure accurate results.","vi":"Chúng tôi thu thập thông tin cẩn thận để đảm bảo kết quả chính xác."}]', '[]', NULL, '/kəˈlekt ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 119, 'collective action', 'hành động tập thể', 'adj + n', '[{"en":"Collective action is often needed to tackle climate change.","vi":"Hành động tập thể thường cần thiết để giải quyết biến đổi khí hậu."},{"en":"The workers organized collective action to demand fair pay.","vi":"Công nhân tổ chức hành động tập thể để đòi mức lương công bằng."},{"en":"Collective action can achieve what individuals cannot alone.","vi":"Hành động tập thể có thể đạt được điều mà cá nhân không thể."}]', '[]', NULL, '/kəˈlektɪv ˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 120, 'collective identity', 'bản sắc tập thể', 'adj + n', '[{"en":"Shared traditions help build a strong collective identity.","vi":"Truyền thống chung giúp xây dựng bản sắc tập thể mạnh mẽ."},{"en":"The festival reinforces the community''s collective identity.","vi":"Lễ hội củng cố bản sắc tập thể của cộng đồng."},{"en":"Migration can challenge a nation''s sense of collective identity.","vi":"Di cư có thể thách thức cảm thức về bản sắc tập thể của một quốc gia."}]', '[]', NULL, '/kəˈlektɪv aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 121, 'collective memory', 'ký ức tập thể', 'adj + n', '[{"en":"The war remains part of the nation''s collective memory.","vi":"Cuộc chiến vẫn là một phần ký ức tập thể của dân tộc."},{"en":"Monuments help preserve a society''s collective memory.","vi":"Các đài tưởng niệm giúp lưu giữ ký ức tập thể của xã hội."},{"en":"Stories passed down shape our collective memory of the past.","vi":"Những câu chuyện truyền lại định hình ký ức tập thể về quá khứ."}]', '[]', NULL, '/kəˈlektɪv ˈmeməri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 122, 'combined effect', 'tác động tổng hợp', 'adj + n', '[{"en":"The combined effect of heat and drought damaged the crops.","vi":"Tác động tổng hợp của nắng nóng và hạn hán đã làm hỏng mùa màng."},{"en":"Researchers studied the combined effect of diet and exercise.","vi":"Các nhà nghiên cứu nghiên cứu tác động tổng hợp của ăn uống và tập luyện."},{"en":"The combined effect of these factors is difficult to predict.","vi":"Tác động tổng hợp của các yếu tố này rất khó dự đoán."}]', '[]', NULL, '/kəmˈbaɪnd ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 123, 'come into conflict with', 'xảy ra xung đột với', 'v + n', '[{"en":"New regulations often come into conflict with existing laws.","vi":"Các quy định mới thường xung đột với luật hiện hành."},{"en":"His personal beliefs came into conflict with company policy.","vi":"Niềm tin cá nhân của anh xung đột với chính sách công ty."},{"en":"Economic goals can come into conflict with environmental ones.","vi":"Các mục tiêu kinh tế có thể xung đột với mục tiêu môi trường."}]', '[]', NULL, '/kʌm ˈɪntə ˈkɑːnflɪkt wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 124, 'come into contact with', 'tiếp xúc với', 'v + n', '[{"en":"Workers may come into contact with hazardous chemicals.","vi":"Công nhân có thể tiếp xúc với hóa chất nguy hiểm."},{"en":"Children come into contact with many germs at school.","vi":"Trẻ em tiếp xúc với nhiều vi khuẩn ở trường."},{"en":"The two cultures first came into contact through trade.","vi":"Hai nền văn hóa lần đầu tiếp xúc thông qua thương mại."}]', '[]', NULL, '/kʌm ˈɪntə ˈkɑːntækt wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 125, 'commercial activity', 'hoạt động thương mại', 'adj + n', '[{"en":"The new port boosted commercial activity in the region.","vi":"Cảng mới thúc đẩy hoạt động thương mại trong khu vực."},{"en":"Commercial activity slowed during the economic downturn.","vi":"Hoạt động thương mại chậm lại trong thời kỳ suy thoái kinh tế."},{"en":"Strict rules govern commercial activity near the reserve.","vi":"Các quy định nghiêm ngặt điều chỉnh hoạt động thương mại gần khu bảo tồn."}]', '[]', NULL, '/kəˈmɜːrʃəl ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 126, 'commercial transaction', 'giao dịch thương mại', 'adj + n', '[{"en":"Every commercial transaction is recorded for accounting purposes.","vi":"Mọi giao dịch thương mại đều được ghi lại để phục vụ kế toán."},{"en":"Online platforms now handle millions of commercial transactions daily.","vi":"Các nền tảng trực tuyến nay xử lý hàng triệu giao dịch thương mại mỗi ngày."},{"en":"The contract governs the terms of each commercial transaction.","vi":"Hợp đồng quy định các điều khoản của mỗi giao dịch thương mại."}]', '[]', NULL, '/kəˈmɜːrʃəl trænˈzækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 127, 'commit a crime', 'phạm tội', 'v + n', '[{"en":"Anyone who commits a crime should face legal consequences.","vi":"Bất kỳ ai phạm tội đều phải đối mặt với hậu quả pháp lý."},{"en":"Poverty does not force people to commit a crime.","vi":"Nghèo đói không buộc người ta phải phạm tội."},{"en":"He was accused of committing a serious crime abroad.","vi":"Anh ta bị cáo buộc phạm một tội nghiêm trọng ở nước ngoài."}]', '[]', NULL, '/kəˈmɪt ə kraɪm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 128, 'commit an offence', 'vi phạm pháp luật', 'v + n', '[{"en":"Drivers who commit an offence may lose their licence.","vi":"Tài xế vi phạm có thể bị tước bằng lái."},{"en":"The law clearly states what it means to commit an offence.","vi":"Luật nêu rõ thế nào là vi phạm pháp luật."},{"en":"Companies that commit an offence can be heavily fined.","vi":"Các công ty vi phạm có thể bị phạt nặng."}]', '[]', NULL, '/kəˈmɪt ən əˈfens/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 129, 'common ancestor', 'tổ tiên chung', 'adj + n', '[{"en":"Humans and apes share a distant common ancestor.","vi":"Con người và vượn có chung một tổ tiên xa xưa."},{"en":"These languages descend from a single common ancestor.","vi":"Các ngôn ngữ này đều bắt nguồn từ một tổ tiên chung."},{"en":"Fossils help scientists trace the common ancestor of mammals.","vi":"Hóa thạch giúp các nhà khoa học truy tìm tổ tiên chung của loài có vú."}]', '[]', NULL, '/ˈkɑːmən ˈænsestər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 130, 'common approach', 'cách tiếp cận phổ biến', 'adj + n', '[{"en":"A common approach is to divide the task into stages.","vi":"Một cách tiếp cận phổ biến là chia nhiệm vụ thành các giai đoạn."},{"en":"The teams agreed on a common approach to the problem.","vi":"Các nhóm đồng ý về một cách tiếp cận chung cho vấn đề."},{"en":"This common approach has both strengths and clear limitations.","vi":"Cách tiếp cận phổ biến này có cả điểm mạnh lẫn hạn chế rõ ràng."}]', '[]', NULL, '/ˈkɑːmən əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 131, 'common assumption', 'giả định phổ biến', 'adj + n', '[{"en":"A common assumption is that money guarantees happiness.","vi":"Một giả định phổ biến là tiền bạc đảm bảo hạnh phúc."},{"en":"The study challenges a common assumption about ageing.","vi":"Nghiên cứu thách thức một giả định phổ biến về sự lão hóa."},{"en":"This common assumption is not supported by the evidence.","vi":"Giả định phổ biến này không được bằng chứng ủng hộ."}]', '[]', NULL, '/ˈkɑːmən əˈsʌmpʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 132, 'common characteristic', 'đặc điểm chung', 'adj + n', '[{"en":"Patience is a common characteristic among successful researchers.","vi":"Sự kiên nhẫn là đặc điểm chung của các nhà nghiên cứu thành công."},{"en":"The groups share several common characteristics worth examining.","vi":"Các nhóm có chung nhiều đặc điểm đáng để xem xét."},{"en":"A common characteristic of these regions is high rainfall.","vi":"Một đặc điểm chung của các vùng này là lượng mưa cao."}]', '[]', NULL, '/ˈkɑːmən ˌkerəktəˈrɪstɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 133, 'common culture', 'nền văn hóa chung', 'adj + n', '[{"en":"A common culture helps bind diverse communities together.","vi":"Một nền văn hóa chung giúp gắn kết các cộng đồng đa dạng."},{"en":"Language is central to maintaining a common culture.","vi":"Ngôn ngữ là yếu tố cốt lõi để duy trì một nền văn hóa chung."},{"en":"Globalization is creating a more common culture worldwide.","vi":"Toàn cầu hóa đang tạo ra một nền văn hóa chung hơn trên thế giới."}]', '[]', NULL, '/ˈkɑːmən ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 134, 'common error', 'lỗi phổ biến', 'adj + n', '[{"en":"Confusing the two terms is a common error among beginners.","vi":"Nhầm lẫn hai thuật ngữ là lỗi phổ biến ở người mới học."},{"en":"The guide lists common errors and how to avoid them.","vi":"Cẩm nang liệt kê các lỗi phổ biến và cách tránh chúng."},{"en":"Skipping the review step is a surprisingly common error.","vi":"Bỏ qua bước rà soát là một lỗi phổ biến đáng ngạc nhiên."}]', '[]', NULL, '/ˈkɑːmən ˈerər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 135, 'common feature', 'đặc trưng chung', 'adj + n', '[{"en":"Open spaces are a common feature of modern offices.","vi":"Không gian mở là đặc trưng chung của các văn phòng hiện đại."},{"en":"Repetition is a common feature of traditional folk songs.","vi":"Sự lặp lại là đặc trưng chung của các bài dân ca truyền thống."},{"en":"Strict deadlines are a common feature of this industry.","vi":"Hạn chót nghiêm ngặt là đặc trưng chung của ngành này."}]', '[]', NULL, '/ˈkɑːmən ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 136, 'common goal', 'mục tiêu chung', 'adj + n', '[{"en":"The team worked together toward a common goal.","vi":"Cả nhóm cùng làm việc hướng tới một mục tiêu chung."},{"en":"Reducing emissions is a common goal of many nations.","vi":"Giảm phát thải là mục tiêu chung của nhiều quốc gia."},{"en":"A common goal helps members stay motivated and focused.","vi":"Một mục tiêu chung giúp các thành viên duy trì động lực và tập trung."}]', '[]', NULL, '/ˈkɑːmən ɡoʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 137, 'common method', 'phương pháp phổ biến', 'adj + n', '[{"en":"Interviewing is a common method of gathering qualitative data.","vi":"Phỏng vấn là phương pháp phổ biến để thu thập dữ liệu định tính."},{"en":"A common method for storing food is freezing.","vi":"Một phương pháp phổ biến để bảo quản thực phẩm là đông lạnh."},{"en":"The authors compare several common methods of analysis.","vi":"Các tác giả so sánh một số phương pháp phân tích phổ biến."}]', '[]', NULL, '/ˈkɑːmən ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 138, 'common source', 'nguồn chung', 'adj + n', '[{"en":"Contaminated water is a common source of illness.","vi":"Nước bị ô nhiễm là một nguồn gây bệnh phổ biến."},{"en":"Misunderstanding is a common source of workplace conflict.","vi":"Hiểu lầm là nguồn gốc phổ biến của xung đột nơi làm việc."},{"en":"The two texts appear to share a common source.","vi":"Hai văn bản dường như có chung một nguồn gốc."}]', '[]', NULL, '/ˈkɑːmən sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 139, 'common theme', 'chủ đề chung', 'adj + n', '[{"en":"Loss is a common theme throughout the author''s novels.","vi":"Mất mát là chủ đề chung xuyên suốt các tiểu thuyết của tác giả."},{"en":"A common theme emerged from the interview responses.","vi":"Một chủ đề chung đã xuất hiện từ các câu trả lời phỏng vấn."},{"en":"Identity is a common theme in postcolonial literature.","vi":"Bản sắc là chủ đề chung trong văn học hậu thuộc địa."}]', '[]', NULL, '/ˈkɑːmən θiːm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 140, 'common usage', 'cách dùng thông dụng', 'adj + n', '[{"en":"The word has shifted in meaning through common usage.","vi":"Từ này đã thay đổi nghĩa qua cách dùng thông dụng."},{"en":"Dictionaries record changes in common usage over time.","vi":"Từ điển ghi lại những thay đổi trong cách dùng thông dụng theo thời gian."},{"en":"This phrase has entered common usage among young people.","vi":"Cụm từ này đã trở nên thông dụng trong giới trẻ."}]', '[]', NULL, '/ˈkɑːmən ˈjuːsɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 141, 'commonly accepted', 'được chấp nhận rộng rãi', 'adv + vpp', '[{"en":"It is commonly accepted that exercise benefits mental health.","vi":"Người ta thường chấp nhận rằng tập thể dục tốt cho sức khỏe tinh thần."},{"en":"The theory is now commonly accepted within the field.","vi":"Lý thuyết này hiện được chấp nhận rộng rãi trong lĩnh vực."},{"en":"These standards are commonly accepted across the industry.","vi":"Các tiêu chuẩn này được chấp nhận rộng rãi trong toàn ngành."}]', '[]', NULL, '/ˈkɑːmənli əkˈseptɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 142, 'commonly associated with', 'thường gắn liền với', 'adv + vpp', '[{"en":"Stress is commonly associated with high blood pressure.","vi":"Căng thẳng thường gắn liền với huyết áp cao."},{"en":"This style is commonly associated with the Renaissance period.","vi":"Phong cách này thường gắn liền với thời kỳ Phục hưng."},{"en":"Such symptoms are commonly associated with vitamin deficiency.","vi":"Những triệu chứng như vậy thường gắn liền với thiếu vitamin."}]', '[]', NULL, '/ˈkɑːmənli əˈsoʊsieɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 143, 'commonly called', 'thường được gọi là', 'adv + vpp', '[{"en":"The condition is commonly called the common cold.","vi":"Tình trạng này thường được gọi là cảm lạnh thông thường."},{"en":"This region is commonly called the breadbasket of the country.","vi":"Vùng này thường được gọi là vựa lúa của đất nước."},{"en":"The device is commonly called a smartphone today.","vi":"Thiết bị này ngày nay thường được gọi là điện thoại thông minh."}]', '[]', NULL, '/ˈkɑːmənli kɔːld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 144, 'commonly encountered', 'thường gặp', 'adv + vpp', '[{"en":"These problems are commonly encountered by new students.","vi":"Những vấn đề này thường gặp ở sinh viên mới."},{"en":"This species is commonly encountered in coastal areas.","vi":"Loài này thường gặp ở các vùng ven biển."},{"en":"The error is commonly encountered when running old software.","vi":"Lỗi này thường gặp khi chạy phần mềm cũ."}]', '[]', NULL, '/ˈkɑːmənli ɪnˈkaʊntərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 145, 'commonly found in', 'thường thấy trong', 'adv + vpp', '[{"en":"This mineral is commonly found in volcanic rocks.","vi":"Khoáng chất này thường thấy trong đá núi lửa."},{"en":"Such errors are commonly found in early drafts.","vi":"Những lỗi như vậy thường thấy trong các bản nháp đầu tiên."},{"en":"Iron is commonly found in green leafy vegetables.","vi":"Sắt thường thấy trong các loại rau lá xanh."}]', '[]', NULL, '/ˈkɑːmənli faʊnd ɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 146, 'commonly known as', 'thường được biết đến là', 'adv + vpp', '[{"en":"The disease is commonly known as whooping cough.","vi":"Căn bệnh này thường được biết đến là ho gà."},{"en":"The plant is commonly known as the snake plant.","vi":"Loại cây này thường được biết đến là cây lưỡi hổ."},{"en":"The era is commonly known as the Industrial Revolution.","vi":"Thời kỳ này thường được biết đến là Cách mạng Công nghiệp."}]', '[]', NULL, '/ˈkɑːmənli noʊn æz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 147, 'commonly referred to as', 'thường được gọi là', 'adv + vpp', '[{"en":"The phenomenon is commonly referred to as global warming.","vi":"Hiện tượng này thường được gọi là sự nóng lên toàn cầu."},{"en":"These cells are commonly referred to as stem cells.","vi":"Những tế bào này thường được gọi là tế bào gốc."},{"en":"The model is commonly referred to as a feedback loop.","vi":"Mô hình này thường được gọi là vòng phản hồi."}]', '[]', NULL, '/ˈkɑːmənli rɪˈfɜːrd tə æz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 148, 'commonly used', 'được sử dụng phổ biến', 'adv + vpp', '[{"en":"This method is commonly used in social science research.","vi":"Phương pháp này được sử dụng phổ biến trong nghiên cứu khoa học xã hội."},{"en":"The term is commonly used in everyday conversation.","vi":"Thuật ngữ này được sử dụng phổ biến trong giao tiếp hằng ngày."},{"en":"These tools are commonly used by professional designers.","vi":"Những công cụ này được các nhà thiết kế chuyên nghiệp sử dụng phổ biến."}]', '[]', NULL, '/ˈkɑːmənli juːzd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 149, 'communicate effectively', 'giao tiếp hiệu quả', 'v + adv', '[{"en":"Good leaders must communicate effectively with their teams.","vi":"Những nhà lãnh đạo giỏi phải giao tiếp hiệu quả với nhóm của mình."},{"en":"The course teaches students to communicate effectively in writing.","vi":"Khóa học dạy sinh viên giao tiếp hiệu quả qua văn bản."},{"en":"Doctors need to communicate effectively with anxious patients.","vi":"Bác sĩ cần giao tiếp hiệu quả với những bệnh nhân lo lắng."}]', '[]', NULL, '/kəˈmjuːnɪkeɪt ɪˈfektɪvli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-2-01', 150, 'comparative analysis', 'phân tích so sánh', 'adj + n', '[{"en":"The report offers a comparative analysis of three economies.","vi":"Báo cáo đưa ra một phân tích so sánh giữa ba nền kinh tế."},{"en":"A comparative analysis reveals key differences in policy.","vi":"Phân tích so sánh cho thấy những khác biệt then chốt về chính sách."},{"en":"She conducted a comparative analysis of two teaching methods.","vi":"Cô tiến hành phân tích so sánh hai phương pháp giảng dạy."}]', '[]', NULL, '/kəmˈpærətɪv əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-3-01', 'colloc-3', 'Cụm học thuật · Nhóm 3', 'Academic Collocation List (Pearson/PTE) — nhóm 3 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 1, 'comparative research', 'nghiên cứu so sánh', 'adj + n', '[{"en":"Comparative research helps identify patterns across different cultures.","vi":"Nghiên cứu so sánh giúp nhận ra các khuôn mẫu giữa các nền văn hóa."},{"en":"Her comparative research focused on education systems in Asia.","vi":"Nghiên cứu so sánh của cô tập trung vào các hệ thống giáo dục ở châu Á."},{"en":"Comparative research requires careful selection of comparable cases.","vi":"Nghiên cứu so sánh đòi hỏi lựa chọn cẩn thận các trường hợp tương đương."}]', '[]', NULL, '/kəmˈpærətɪv ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 2, 'comparative study', 'công trình so sánh', 'adj + n', '[{"en":"The team published a comparative study of urban transport.","vi":"Nhóm đã công bố một công trình so sánh về giao thông đô thị."},{"en":"This comparative study examines healthcare in five countries.","vi":"Công trình so sánh này xem xét hệ thống y tế ở năm quốc gia."},{"en":"A comparative study can highlight strengths of each approach.","vi":"Một công trình so sánh có thể làm nổi bật điểm mạnh của từng cách tiếp cận."}]', '[]', NULL, '/kəmˈpærətɪv ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 3, 'compelling argument', 'lập luận thuyết phục', 'adj + n', '[{"en":"She made a compelling argument for reforming the system.","vi":"Cô đưa ra một lập luận thuyết phục để cải cách hệ thống."},{"en":"The essay presents a compelling argument supported by data.","vi":"Bài luận trình bày một lập luận thuyết phục được dữ liệu hỗ trợ."},{"en":"His compelling argument changed many people''s minds.","vi":"Lập luận thuyết phục của ông đã thay đổi suy nghĩ của nhiều người."}]', '[]', NULL, '/kəmˈpelɪŋ ˈɑːrɡjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 4, 'compelling evidence', 'bằng chứng thuyết phục', 'adj + n', '[{"en":"The study provides compelling evidence of climate change.","vi":"Nghiên cứu cung cấp bằng chứng thuyết phục về biến đổi khí hậu."},{"en":"There is compelling evidence linking smoking to cancer.","vi":"Có bằng chứng thuyết phục liên hệ hút thuốc với ung thư."},{"en":"Without compelling evidence, the claim cannot be accepted.","vi":"Không có bằng chứng thuyết phục, tuyên bố không thể được chấp nhận."}]', '[]', NULL, '/kəmˈpelɪŋ ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 5, 'compelling reason', 'lý do thuyết phục', 'adj + n', '[{"en":"There is a compelling reason to revise the current policy.","vi":"Có một lý do thuyết phục để sửa đổi chính sách hiện tại."},{"en":"She gave no compelling reason for missing the deadline.","vi":"Cô không đưa ra lý do thuyết phục nào cho việc trễ hạn."},{"en":"Investors need a compelling reason to fund the project.","vi":"Các nhà đầu tư cần một lý do thuyết phục để tài trợ dự án."}]', '[]', NULL, '/kəmˈpelɪŋ ˈriːzən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 6, 'competitive market', 'thị trường cạnh tranh', 'adj + n', '[{"en":"In a competitive market, prices tend to stay low.","vi":"Trong một thị trường cạnh tranh, giá cả có xu hướng thấp."},{"en":"Small firms struggle to survive in a competitive market.","vi":"Các công ty nhỏ khó tồn tại trong thị trường cạnh tranh."},{"en":"Innovation is essential to thrive in a competitive market.","vi":"Đổi mới là thiết yếu để phát triển trong thị trường cạnh tranh."}]', '[]', NULL, '/kəmˈpetətɪv ˈmɑːrkɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 7, 'competitive pressure', 'áp lực cạnh tranh', 'adj + n', '[{"en":"Competitive pressure forced the company to lower its prices.","vi":"Áp lực cạnh tranh buộc công ty phải hạ giá."},{"en":"Firms face growing competitive pressure from overseas rivals.","vi":"Các công ty đối mặt với áp lực cạnh tranh ngày càng tăng từ đối thủ nước ngoài."},{"en":"Competitive pressure often drives rapid technological change.","vi":"Áp lực cạnh tranh thường thúc đẩy thay đổi công nghệ nhanh chóng."}]', '[]', NULL, '/kəmˈpetətɪv ˈpreʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 8, 'complete a task', 'hoàn thành nhiệm vụ', 'v + n', '[{"en":"Students must complete a task before moving to the next.","vi":"Học sinh phải hoàn thành nhiệm vụ trước khi chuyển sang phần tiếp."},{"en":"It took the team two weeks to complete the task.","vi":"Nhóm mất hai tuần để hoàn thành nhiệm vụ."},{"en":"Clear instructions help workers complete a task efficiently.","vi":"Hướng dẫn rõ ràng giúp công nhân hoàn thành nhiệm vụ hiệu quả."}]', '[]', NULL, '/kəmˈpliːt ə tæsk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 9, 'complex area', 'lĩnh vực phức tạp', 'adj + n', '[{"en":"Tax law is a complex area that requires expert advice.","vi":"Luật thuế là một lĩnh vực phức tạp đòi hỏi tư vấn chuyên môn."},{"en":"This complex area of research is still poorly understood.","vi":"Lĩnh vực nghiên cứu phức tạp này vẫn chưa được hiểu rõ."},{"en":"Ethics in medicine remains a deeply complex area.","vi":"Đạo đức trong y học vẫn là một lĩnh vực hết sức phức tạp."}]', '[]', NULL, '/ˈkɑːmpleks ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 10, 'complex interaction', 'tương tác phức tạp', 'adj + n', '[{"en":"Behaviour results from a complex interaction of many factors.","vi":"Hành vi nảy sinh từ sự tương tác phức tạp của nhiều yếu tố."},{"en":"The model captures the complex interaction between species.","vi":"Mô hình nắm bắt sự tương tác phức tạp giữa các loài."},{"en":"Climate involves a complex interaction of ocean and atmosphere.","vi":"Khí hậu liên quan đến tương tác phức tạp giữa đại dương và khí quyển."}]', '[]', NULL, '/ˈkɑːmpleks ˌɪntərˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 11, 'complex issue', 'vấn đề phức tạp', 'adj + n', '[{"en":"Immigration is a complex issue with no simple solution.","vi":"Nhập cư là một vấn đề phức tạp không có lời giải đơn giản."},{"en":"The report addresses the complex issue of inequality.","vi":"Báo cáo đề cập đến vấn đề phức tạp về bất bình đẳng."},{"en":"Resolving this complex issue requires cooperation from everyone.","vi":"Giải quyết vấn đề phức tạp này cần sự hợp tác từ mọi người."}]', '[]', NULL, '/ˈkɑːmpleks ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 12, 'complex pattern', 'mô hình phức tạp', 'adj + n', '[{"en":"The data reveal a complex pattern of seasonal change.","vi":"Dữ liệu cho thấy một mô hình thay đổi theo mùa phức tạp."},{"en":"Migration follows a complex pattern shaped by many forces.","vi":"Di cư diễn ra theo mô hình phức tạp do nhiều yếu tố tạo nên."},{"en":"Researchers uncovered a complex pattern in the genetic data.","vi":"Các nhà nghiên cứu phát hiện một mô hình phức tạp trong dữ liệu di truyền."}]', '[]', NULL, '/ˈkɑːmpleks ˈpætərn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 13, 'complex problem', 'bài toán phức tạp', 'adj + n', '[{"en":"Climate change is a complex problem facing every nation.","vi":"Biến đổi khí hậu là một bài toán phức tạp với mọi quốc gia."},{"en":"Breaking a complex problem into steps makes it manageable.","vi":"Chia một bài toán phức tạp thành các bước giúp dễ xử lý hơn."},{"en":"The engineers solved a complex problem with a simple design.","vi":"Các kỹ sư giải một bài toán phức tạp bằng một thiết kế đơn giản."}]', '[]', NULL, '/ˈkɑːmpleks ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 14, 'complex process', 'quá trình phức tạp', 'adj + n', '[{"en":"Learning a language is a long and complex process.","vi":"Học một ngôn ngữ là một quá trình lâu dài và phức tạp."},{"en":"Digestion is a complex process involving several organs.","vi":"Tiêu hóa là một quá trình phức tạp liên quan đến nhiều cơ quan."},{"en":"The complex process of approval can take many months.","vi":"Quá trình phê duyệt phức tạp có thể mất nhiều tháng."}]', '[]', NULL, '/ˈkɑːmpleks ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 15, 'complex question', 'câu hỏi phức tạp', 'adj + n', '[{"en":"This is a complex question that deserves careful thought.","vi":"Đây là một câu hỏi phức tạp xứng đáng được suy nghĩ kỹ."},{"en":"The essay tackles the complex question of free will.","vi":"Bài luận giải quyết câu hỏi phức tạp về ý chí tự do."},{"en":"There is no easy answer to such a complex question.","vi":"Không có câu trả lời dễ dàng cho một câu hỏi phức tạp như vậy."}]', '[]', NULL, '/ˈkɑːmpleks ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 16, 'complex relationship', 'mối quan hệ phức tạp', 'adj + n', '[{"en":"There is a complex relationship between stress and illness.","vi":"Có một mối quan hệ phức tạp giữa căng thẳng và bệnh tật."},{"en":"The novel explores the complex relationship between the brothers.","vi":"Cuốn tiểu thuyết khám phá mối quan hệ phức tạp giữa hai anh em."},{"en":"Economics studies the complex relationship between supply and demand.","vi":"Kinh tế học nghiên cứu mối quan hệ phức tạp giữa cung và cầu."}]', '[]', NULL, '/ˈkɑːmpleks rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 17, 'complex set', 'tập hợp phức tạp', 'adj + n', '[{"en":"The rules form a complex set of legal obligations.","vi":"Các quy tắc tạo thành một tập hợp phức tạp các nghĩa vụ pháp lý."},{"en":"A complex set of factors shapes consumer behaviour.","vi":"Một tập hợp phức tạp các yếu tố định hình hành vi tiêu dùng."},{"en":"Pilots must follow a complex set of safety procedures.","vi":"Phi công phải tuân theo một tập hợp phức tạp các quy trình an toàn."}]', '[]', NULL, '/ˈkɑːmpleks set/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 18, 'complex situation', 'tình huống phức tạp', 'adj + n', '[{"en":"Managers must stay calm in a complex situation.","vi":"Các nhà quản lý phải bình tĩnh trong một tình huống phức tạp."},{"en":"The diplomat handled the complex situation with great skill.","vi":"Nhà ngoại giao xử lý tình huống phức tạp với kỹ năng tuyệt vời."},{"en":"This complex situation has no obvious right answer.","vi":"Tình huống phức tạp này không có câu trả lời đúng rõ ràng."}]', '[]', NULL, '/ˈkɑːmpleks ˌsɪtʃuˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 19, 'complex structure', 'cấu trúc phức tạp', 'adj + n', '[{"en":"The brain has an extremely complex structure.","vi":"Não bộ có một cấu trúc cực kỳ phức tạp."},{"en":"The molecule''s complex structure makes it hard to synthesize.","vi":"Cấu trúc phức tạp của phân tử khiến nó khó tổng hợp."},{"en":"The poem has a complex structure with shifting rhythms.","vi":"Bài thơ có một cấu trúc phức tạp với nhịp điệu biến đổi."}]', '[]', NULL, '/ˈkɑːmpleks ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 20, 'complex system', 'hệ thống phức tạp', 'adj + n', '[{"en":"The economy is a complex system with many moving parts.","vi":"Nền kinh tế là một hệ thống phức tạp với nhiều bộ phận vận động."},{"en":"Ecosystems are complex systems that respond to small changes.","vi":"Hệ sinh thái là những hệ thống phức tạp phản ứng với thay đổi nhỏ."},{"en":"Managing a complex system requires constant monitoring.","vi":"Quản lý một hệ thống phức tạp đòi hỏi giám sát liên tục."}]', '[]', NULL, '/ˈkɑːmpleks ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 21, 'comprehensive account', 'bản tường thuật toàn diện', 'adj + n', '[{"en":"The book offers a comprehensive account of the revolution.","vi":"Cuốn sách đưa ra một bản tường thuật toàn diện về cuộc cách mạng."},{"en":"She gave a comprehensive account of the experiment''s results.","vi":"Cô trình bày một bản tường thuật toàn diện về kết quả thí nghiệm."},{"en":"No single source provides a comprehensive account of events.","vi":"Không nguồn nào đưa ra bản tường thuật toàn diện về các sự kiện."}]', '[]', NULL, '/ˌkɑːmprɪˈhensɪv əˈkaʊnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 22, 'comprehensive approach', 'cách tiếp cận toàn diện', 'adj + n', '[{"en":"Tackling poverty requires a comprehensive approach.","vi":"Giải quyết nghèo đói đòi hỏi một cách tiếp cận toàn diện."},{"en":"The school adopted a comprehensive approach to student welfare.","vi":"Trường áp dụng cách tiếp cận toàn diện đối với phúc lợi học sinh."},{"en":"A comprehensive approach considers economic and social factors together.","vi":"Cách tiếp cận toàn diện xem xét cả yếu tố kinh tế và xã hội."}]', '[]', NULL, '/ˌkɑːmprɪˈhensɪv əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 23, 'comprehensive overview', 'cái nhìn tổng quan toàn diện', 'adj + n', '[{"en":"The first chapter gives a comprehensive overview of the field.","vi":"Chương đầu đưa ra cái nhìn tổng quan toàn diện về lĩnh vực này."},{"en":"Her lecture provided a comprehensive overview of recent research.","vi":"Bài giảng của cô cung cấp cái nhìn toàn diện về nghiên cứu gần đây."},{"en":"This guide offers a comprehensive overview for new employees.","vi":"Cẩm nang này cung cấp cái nhìn tổng quan toàn diện cho nhân viên mới."}]', '[]', NULL, '/ˌkɑːmprɪˈhensɪv ˈoʊvərvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 24, 'comprehensive review', 'đánh giá toàn diện', 'adj + n', '[{"en":"The committee conducted a comprehensive review of the policy.","vi":"Ủy ban tiến hành một cuộc đánh giá toàn diện về chính sách."},{"en":"The article provides a comprehensive review of the literature.","vi":"Bài viết cung cấp một đánh giá toàn diện về tài liệu nghiên cứu."},{"en":"A comprehensive review revealed several gaps in the system.","vi":"Một cuộc đánh giá toàn diện đã phát hiện nhiều lỗ hổng trong hệ thống."}]', '[]', NULL, '/ˌkɑːmprɪˈhensɪv rɪˈvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 25, 'comprehensive system', 'hệ thống toàn diện', 'adj + n', '[{"en":"The country built a comprehensive system of public healthcare.","vi":"Quốc gia này xây dựng một hệ thống y tế công toàn diện."},{"en":"A comprehensive system of checks prevents most errors.","vi":"Một hệ thống kiểm tra toàn diện ngăn chặn hầu hết sai sót."},{"en":"They developed a comprehensive system for tracking shipments.","vi":"Họ phát triển một hệ thống toàn diện để theo dõi các lô hàng."}]', '[]', NULL, '/ˌkɑːmprɪˈhensɪv ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 26, 'conceptual framework', 'khung khái niệm', 'adj + n', '[{"en":"The study is built on a clear conceptual framework.","vi":"Nghiên cứu được xây dựng trên một khung khái niệm rõ ràng."},{"en":"A solid conceptual framework guides the entire investigation.","vi":"Một khung khái niệm vững chắc định hướng toàn bộ cuộc điều tra."},{"en":"The authors propose a new conceptual framework for analysis.","vi":"Các tác giả đề xuất một khung khái niệm mới để phân tích."}]', '[]', NULL, '/kənˈseptʃuəl ˈfreɪmwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 27, 'concerted effort', 'nỗ lực phối hợp', 'adj + n', '[{"en":"A concerted effort is needed to reduce plastic waste.","vi":"Cần một nỗ lực phối hợp để giảm rác thải nhựa."},{"en":"Through a concerted effort, the team met the deadline.","vi":"Bằng một nỗ lực phối hợp, nhóm đã kịp hạn chót."},{"en":"Governments made a concerted effort to control the disease.","vi":"Các chính phủ đã nỗ lực phối hợp để kiểm soát dịch bệnh."}]', '[]', NULL, '/kənˈsɜːrtɪd ˈefərt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 28, 'concluding remarks', 'lời nhận xét kết luận', 'adj + n', '[{"en":"In her concluding remarks, she summarized the main findings.","vi":"Trong lời nhận xét kết luận, cô tóm tắt các phát hiện chính."},{"en":"The author''s concluding remarks point toward future research.","vi":"Lời nhận xét kết luận của tác giả hướng tới nghiên cứu tương lai."},{"en":"His concluding remarks were brief but memorable.","vi":"Lời nhận xét kết luận của ông ngắn gọn nhưng đáng nhớ."}]', '[]', NULL, '/kənˈkluːdɪŋ rɪˈmɑːrks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 29, 'concluding section', 'phần kết luận', 'adj + n', '[{"en":"The concluding section restates the paper''s central argument.","vi":"Phần kết luận nêu lại lập luận trung tâm của bài viết."},{"en":"In the concluding section, the author suggests further study.","vi":"Trong phần kết luận, tác giả gợi ý nghiên cứu thêm."},{"en":"The concluding section ties together the earlier chapters.","vi":"Phần kết luận liên kết các chương trước đó với nhau."}]', '[]', NULL, '/kənˈkluːdɪŋ ˈsekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 30, 'concluding probability', 'xác suất kết luận', 'adj + n', '[{"en":"The analysis yields a concluding probability for each outcome.","vi":"Phân tích đưa ra một xác suất kết luận cho mỗi kết quả."},{"en":"Researchers reported the concluding probability of the event.","vi":"Các nhà nghiên cứu báo cáo xác suất kết luận của sự kiện."},{"en":"A high concluding probability strengthens confidence in the model.","vi":"Xác suất kết luận cao làm tăng độ tin cậy vào mô hình."}]', '[]', NULL, '/kənˈkluːdɪŋ ˌprɑːbəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 31, 'conduct research', 'tiến hành nghiên cứu', 'v + n', '[{"en":"The university encourages students to conduct original research.","vi":"Trường đại học khuyến khích sinh viên tiến hành nghiên cứu độc lập."},{"en":"They conduct research on renewable energy sources.","vi":"Họ tiến hành nghiên cứu về các nguồn năng lượng tái tạo."},{"en":"Scientists conduct research to test their hypotheses carefully.","vi":"Các nhà khoa học tiến hành nghiên cứu để kiểm tra giả thuyết cẩn thận."}]', '[]', NULL, '/kənˈdʌkt ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 32, 'conduct a study', 'tiến hành một nghiên cứu', 'v + n', '[{"en":"Researchers will conduct a study on sleep and memory next year.","vi":"Các nhà nghiên cứu sẽ tiến hành một nghiên cứu về giấc ngủ và trí nhớ vào năm tới."},{"en":"We decided to conduct a study comparing two teaching methods.","vi":"Chúng tôi quyết định tiến hành một nghiên cứu so sánh hai phương pháp giảng dạy."},{"en":"The team conducted a study to measure customer satisfaction levels.","vi":"Nhóm đã tiến hành một nghiên cứu để đo mức độ hài lòng của khách hàng."}]', '[]', NULL, '/kənˈdʌkt ə ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 33, 'conduct a survey', 'thực hiện một cuộc khảo sát', 'v + n', '[{"en":"The university conducted a survey to learn about student needs.","vi":"Trường đại học đã thực hiện một cuộc khảo sát để tìm hiểu nhu cầu của sinh viên."},{"en":"We plan to conduct a survey among local small business owners.","vi":"Chúng tôi dự định thực hiện một cuộc khảo sát với các chủ doanh nghiệp nhỏ trong vùng."},{"en":"Before launching, the company conducted a survey of potential users.","vi":"Trước khi ra mắt, công ty đã thực hiện một cuộc khảo sát người dùng tiềm năng."}]', '[]', NULL, '/kənˈdʌkt ə ˈsɜːrveɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 34, 'conduct an analysis', 'thực hiện một phân tích', 'v + n', '[{"en":"The analysts conducted an analysis of last quarter''s sales data.","vi":"Các chuyên viên đã thực hiện một phân tích về dữ liệu bán hàng quý trước."},{"en":"We need to conduct an analysis before making any final decision.","vi":"Chúng ta cần thực hiện một phân tích trước khi đưa ra quyết định cuối cùng."},{"en":"She conducted an analysis to identify the main causes of failure.","vi":"Cô đã thực hiện một phân tích để xác định các nguyên nhân chính gây thất bại."}]', '[]', NULL, '/kənˈdʌkt ən əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 35, 'conduct an interview', 'tiến hành một cuộc phỏng vấn', 'v + n', '[{"en":"The journalist conducted an interview with the city''s new mayor.","vi":"Nhà báo đã tiến hành một cuộc phỏng vấn với thị trưởng mới của thành phố."},{"en":"Researchers conducted an interview with each participant separately.","vi":"Các nhà nghiên cứu đã tiến hành một cuộc phỏng vấn riêng với từng người tham gia."},{"en":"We will conduct an interview to understand their daily routines.","vi":"Chúng tôi sẽ tiến hành một cuộc phỏng vấn để hiểu thói quen hằng ngày của họ."}]', '[]', NULL, '/kənˈdʌkt ən ˈɪntərvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 36, 'conflict resolution', 'giải quyết xung đột', 'n + n', '[{"en":"Good managers need strong conflict resolution skills at work.","vi":"Người quản lý giỏi cần có kỹ năng giải quyết xung đột tốt trong công việc."},{"en":"The course teaches conflict resolution through real-life case studies.","vi":"Khóa học dạy giải quyết xung đột qua các tình huống thực tế."},{"en":"Conflict resolution often requires patience and careful listening.","vi":"Giải quyết xung đột thường đòi hỏi sự kiên nhẫn và lắng nghe cẩn thận."}]', '[]', NULL, '/ˈkɑːnflɪkt ˌrezəˈluːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 37, 'conflicting interests', 'những lợi ích xung đột nhau', 'adj + n', '[{"en":"The two departments have conflicting interests over the new budget.","vi":"Hai phòng ban có những lợi ích xung đột nhau về ngân sách mới."},{"en":"Negotiators must balance conflicting interests to reach an agreement.","vi":"Các nhà đàm phán phải cân bằng những lợi ích xung đột để đạt thỏa thuận."},{"en":"Conflicting interests among shareholders delayed the final decision.","vi":"Những lợi ích xung đột giữa các cổ đông đã trì hoãn quyết định cuối cùng."}]', '[]', NULL, '/kənˈflɪktɪŋ ˈɪntrəsts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 38, 'consider appropriate', 'cho là phù hợp', 'v + adj', '[{"en":"Teachers may use whatever methods they consider appropriate for the class.","vi":"Giáo viên có thể dùng bất kỳ phương pháp nào họ cho là phù hợp với lớp."},{"en":"The committee will take any action it considers appropriate.","vi":"Ủy ban sẽ thực hiện bất kỳ hành động nào họ cho là phù hợp."},{"en":"Please dress in a way you consider appropriate for the interview.","vi":"Hãy ăn mặc theo cách mà bạn cho là phù hợp cho buổi phỏng vấn."}]', '[]', NULL, '/kənˈsɪdər əˈproʊpriət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 39, 'consider relevant', 'cho là có liên quan', 'v + adj', '[{"en":"Include only the details you consider relevant to your argument.","vi":"Chỉ đưa vào những chi tiết mà bạn cho là có liên quan đến luận điểm."},{"en":"The judge will examine any evidence she considers relevant to the case.","vi":"Thẩm phán sẽ xem xét bất kỳ bằng chứng nào bà cho là có liên quan đến vụ án."},{"en":"Readers may skip sections they do not consider relevant.","vi":"Người đọc có thể bỏ qua các phần họ không cho là có liên quan."}]', '[]', NULL, '/kənˈsɪdər ˈreləvənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 40, 'consider a possibility', 'xem xét một khả năng', 'v + n', '[{"en":"We should consider a possibility that no one has examined yet.","vi":"Chúng ta nên xem xét một khả năng mà chưa ai khảo sát đến."},{"en":"The board agreed to consider a possibility of merging the two teams.","vi":"Hội đồng đồng ý xem xét một khả năng sáp nhập hai nhóm."},{"en":"Scientists must consider a possibility before rejecting any theory.","vi":"Các nhà khoa học phải xem xét một khả năng trước khi bác bỏ lý thuyết nào."}]', '[]', NULL, '/kənˈsɪdər ə ˌpɑːsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 41, 'consider an aspect', 'xem xét một khía cạnh', 'v + n', '[{"en":"The essay fails to consider an aspect central to the debate.","vi":"Bài luận không xem xét một khía cạnh trung tâm của cuộc tranh luận."},{"en":"Let us consider an aspect of the problem we often overlook.","vi":"Hãy xem xét một khía cạnh của vấn đề mà chúng ta thường bỏ qua."},{"en":"Good planners consider an aspect of cost at every stage.","vi":"Người lập kế hoạch giỏi xem xét một khía cạnh chi phí ở mọi giai đoạn."}]', '[]', NULL, '/kənˈsɪdər ən ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 42, 'consider an issue', 'xem xét một vấn đề', 'v + n', '[{"en":"The council will consider an issue raised by local residents.","vi":"Hội đồng sẽ xem xét một vấn đề do người dân địa phương nêu ra."},{"en":"We must consider an issue from several different points of view.","vi":"Chúng ta phải xem xét một vấn đề từ nhiều góc nhìn khác nhau."},{"en":"The chapter helps readers consider an issue more deeply.","vi":"Chương này giúp người đọc xem xét một vấn đề sâu sắc hơn."}]', '[]', NULL, '/kənˈsɪdər ən ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 43, 'consider the impact of', 'cân nhắc tác động của', 'v + n', '[{"en":"Planners must consider the impact of the new road on traffic.","vi":"Người quy hoạch phải cân nhắc tác động của con đường mới đến giao thông."},{"en":"The report asks us to consider the impact of climate change.","vi":"Báo cáo yêu cầu chúng ta cân nhắc tác động của biến đổi khí hậu."},{"en":"We should consider the impact of these cuts on poorer families.","vi":"Chúng ta nên cân nhắc tác động của những khoản cắt giảm này lên các gia đình nghèo."}]', '[]', NULL, '/kənˈsɪdər ði ˈɪmpækt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 44, 'consider the implications', 'cân nhắc những hệ quả', 'v + n', '[{"en":"Before voting, members should consider the implications of the proposal.","vi":"Trước khi bỏ phiếu, các thành viên nên cân nhắc những hệ quả của đề xuất."},{"en":"The author asks readers to consider the implications for future policy.","vi":"Tác giả yêu cầu người đọc cân nhắc những hệ quả đối với chính sách tương lai."},{"en":"We failed to consider the implications of releasing the data early.","vi":"Chúng tôi đã không cân nhắc những hệ quả của việc công bố dữ liệu sớm."}]', '[]', NULL, '/kənˈsɪdər ði ˌɪmplɪˈkeɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 45, 'consider the role of', 'xem xét vai trò của', 'v + n', '[{"en":"The lecture asks us to consider the role of luck in success.","vi":"Bài giảng yêu cầu chúng ta xem xét vai trò của may mắn trong thành công."},{"en":"We must consider the role of teachers in shaping young minds.","vi":"Chúng ta phải xem xét vai trò của giáo viên trong việc định hình tư duy trẻ."},{"en":"Historians consider the role of trade in building early cities.","vi":"Các nhà sử học xem xét vai trò của thương mại trong việc xây dựng các thành phố cổ."}]', '[]', NULL, '/kənˈsɪdər ðə roʊl əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 46, 'considerable amount of', 'một lượng đáng kể', 'adj + n', '[{"en":"The project required a considerable amount of time and money.","vi":"Dự án đòi hỏi một lượng đáng kể thời gian và tiền bạc."},{"en":"She spent a considerable amount of effort on the final report.","vi":"Cô đã bỏ ra một lượng đáng kể công sức cho bản báo cáo cuối cùng."},{"en":"A considerable amount of data was lost during the system failure.","vi":"Một lượng đáng kể dữ liệu đã bị mất trong sự cố hệ thống."}]', '[]', NULL, '/kənˈsɪdərəbəl əˈmaʊnt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 47, 'considerable attention', 'sự chú ý đáng kể', 'adj + n', '[{"en":"The new theory has attracted considerable attention from scientists.","vi":"Lý thuyết mới đã thu hút sự chú ý đáng kể từ các nhà khoa học."},{"en":"This issue deserves considerable attention in future research.","vi":"Vấn đề này xứng đáng nhận được sự chú ý đáng kể trong nghiên cứu sau này."},{"en":"The film received considerable attention after the awards ceremony.","vi":"Bộ phim nhận được sự chú ý đáng kể sau lễ trao giải."}]', '[]', NULL, '/kənˈsɪdərəbəl əˈtenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 48, 'considerable debate', 'cuộc tranh luận đáng kể', 'adj + n', '[{"en":"There is considerable debate about the causes of the decline.","vi":"Có một cuộc tranh luận đáng kể về nguyên nhân của sự suy giảm."},{"en":"The proposal sparked considerable debate among local officials.","vi":"Đề xuất đã làm dấy lên cuộc tranh luận đáng kể giữa các quan chức địa phương."},{"en":"Considerable debate surrounds the best way to teach reading.","vi":"Cuộc tranh luận đáng kể xoay quanh cách tốt nhất để dạy đọc."}]', '[]', NULL, '/kənˈsɪdərəbəl dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 49, 'considerable degree of', 'một mức độ đáng kể của', 'adj + n', '[{"en":"The task demands a considerable degree of skill and patience.","vi":"Nhiệm vụ đòi hỏi một mức độ đáng kể về kỹ năng và sự kiên nhẫn."},{"en":"Workers enjoy a considerable degree of freedom in this company.","vi":"Nhân viên được hưởng một mức độ tự do đáng kể trong công ty này."},{"en":"The results show a considerable degree of variation between groups.","vi":"Kết quả cho thấy một mức độ khác biệt đáng kể giữa các nhóm."}]', '[]', NULL, '/kənˈsɪdərəbəl dɪˈɡriː əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 50, 'considerable detail', 'sự chi tiết đáng kể', 'adj + n', '[{"en":"The author describes each method in considerable detail.","vi":"Tác giả mô tả từng phương pháp với sự chi tiết đáng kể."},{"en":"The report covers the budget in considerable detail.","vi":"Báo cáo trình bày ngân sách với sự chi tiết đáng kể."},{"en":"She explained the procedure in considerable detail for beginners.","vi":"Cô đã giải thích quy trình rất chi tiết cho người mới bắt đầu."}]', '[]', NULL, '/kənˈsɪdərəbəl ˈdiːteɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 51, 'considerable effort', 'công sức đáng kể', 'adj + n', '[{"en":"It took considerable effort to finish the thesis on time.","vi":"Phải mất công sức đáng kể mới hoàn thành luận văn đúng hạn."},{"en":"The team put considerable effort into improving the website.","vi":"Nhóm đã bỏ công sức đáng kể để cải thiện trang web."},{"en":"Considerable effort is needed to change such old habits.","vi":"Cần công sức đáng kể để thay đổi những thói quen cũ như vậy."}]', '[]', NULL, '/kənˈsɪdərəbəl ˈefərt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 52, 'considerable evidence', 'bằng chứng đáng kể', 'adj + n', '[{"en":"There is considerable evidence linking exercise to better health.","vi":"Có bằng chứng đáng kể liên hệ tập thể dục với sức khỏe tốt hơn."},{"en":"Considerable evidence suggests the policy reduced crime rates.","vi":"Bằng chứng đáng kể cho thấy chính sách đã làm giảm tỷ lệ tội phạm."},{"en":"The study collected considerable evidence over five long years.","vi":"Nghiên cứu đã thu thập bằng chứng đáng kể trong suốt năm năm dài."}]', '[]', NULL, '/kənˈsɪdərəbəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 53, 'considerable extent', 'mức độ đáng kể', 'adj + n', '[{"en":"To a considerable extent, the project''s success depended on funding.","vi":"Ở một mức độ đáng kể, thành công của dự án phụ thuộc vào nguồn vốn."},{"en":"Her work shaped the field to a considerable extent.","vi":"Công trình của bà đã định hình lĩnh vực ở một mức độ đáng kể."},{"en":"The outcome reflects the local culture to a considerable extent.","vi":"Kết quả phản ánh văn hóa địa phương ở một mức độ đáng kể."}]', '[]', NULL, '/kənˈsɪdərəbəl ɪkˈstent/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 54, 'considerable importance', 'tầm quan trọng đáng kể', 'adj + n', '[{"en":"These findings are of considerable importance to medical research.","vi":"Những phát hiện này có tầm quan trọng đáng kể đối với nghiên cứu y học."},{"en":"The treaty held considerable importance for both countries.","vi":"Hiệp ước có tầm quan trọng đáng kể đối với cả hai quốc gia."},{"en":"Early education is of considerable importance for later success.","vi":"Giáo dục sớm có tầm quan trọng đáng kể đối với thành công về sau."}]', '[]', NULL, '/kənˈsɪdərəbəl ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 55, 'considerable influence', 'ảnh hưởng đáng kể', 'adj + n', '[{"en":"The teacher had a considerable influence on my career choices.","vi":"Người thầy đã có ảnh hưởng đáng kể đến lựa chọn nghề nghiệp của tôi."},{"en":"Media exerts considerable influence over public opinion today.","vi":"Truyền thông tạo ảnh hưởng đáng kể lên dư luận ngày nay."},{"en":"Her writing exerted considerable influence on later philosophers.","vi":"Trước tác của bà có ảnh hưởng đáng kể đến các triết gia về sau."}]', '[]', NULL, '/kənˈsɪdərəbəl ˈɪnfluəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 56, 'considerable interest', 'sự quan tâm đáng kể', 'adj + n', '[{"en":"The discovery generated considerable interest among biologists.","vi":"Phát hiện đã tạo ra sự quan tâm đáng kể trong giới sinh học."},{"en":"There is considerable interest in renewable energy these days.","vi":"Hiện nay có sự quan tâm đáng kể đến năng lượng tái tạo."},{"en":"The lecture attracted considerable interest from local students.","vi":"Buổi giảng đã thu hút sự quan tâm đáng kể từ sinh viên địa phương."}]', '[]', NULL, '/kənˈsɪdərəbəl ˈɪntrəst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 57, 'considerable research', 'nghiên cứu đáng kể', 'adj + n', '[{"en":"Considerable research has examined how children learn languages.","vi":"Đã có nghiên cứu đáng kể khảo sát cách trẻ em học ngôn ngữ."},{"en":"The claim is supported by considerable research over decades.","vi":"Khẳng định này được hỗ trợ bởi nghiên cứu đáng kể qua nhiều thập kỷ."},{"en":"Considerable research is still needed to confirm these results.","vi":"Vẫn cần nghiên cứu đáng kể để xác nhận những kết quả này."}]', '[]', NULL, '/kənˈsɪdərəbəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 58, 'considerable support', 'sự ủng hộ đáng kể', 'adj + n', '[{"en":"The plan received considerable support from local community groups.","vi":"Kế hoạch nhận được sự ủng hộ đáng kể từ các nhóm cộng đồng địa phương."},{"en":"There is considerable support for reforming the exam system.","vi":"Có sự ủng hộ đáng kể cho việc cải cách hệ thống thi cử."},{"en":"Considerable support exists for protecting the old forest.","vi":"Tồn tại sự ủng hộ đáng kể cho việc bảo vệ khu rừng cổ."}]', '[]', NULL, '/kənˈsɪdərəbəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 59, 'considerable variation', 'sự khác biệt đáng kể', 'adj + n', '[{"en":"There is considerable variation in rainfall across the region.","vi":"Có sự khác biệt đáng kể về lượng mưa trên khắp khu vực."},{"en":"The data showed considerable variation between the two samples.","vi":"Dữ liệu cho thấy sự khác biệt đáng kể giữa hai mẫu."},{"en":"Prices reveal considerable variation from one city to another.","vi":"Giá cả cho thấy sự khác biệt đáng kể giữa thành phố này với thành phố khác."}]', '[]', NULL, '/kənˈsɪdərəbəl ˌveriˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 60, 'consistent pattern', 'khuôn mẫu nhất quán', 'adj + n', '[{"en":"The survey revealed a consistent pattern of late payments.","vi":"Cuộc khảo sát cho thấy một khuôn mẫu nhất quán về việc trả tiền muộn."},{"en":"Researchers found a consistent pattern across all five studies.","vi":"Các nhà nghiên cứu tìm thấy một khuôn mẫu nhất quán qua cả năm nghiên cứu."},{"en":"A consistent pattern of growth appeared over the last decade.","vi":"Một khuôn mẫu tăng trưởng nhất quán xuất hiện trong thập kỷ qua."}]', '[]', NULL, '/kənˈsɪstənt ˈpætərn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 61, 'consistent results', 'kết quả nhất quán', 'adj + n', '[{"en":"The experiment produced consistent results across many trials.","vi":"Thí nghiệm đã cho ra kết quả nhất quán qua nhiều lần thử."},{"en":"Consistent results give us confidence in the new method.","vi":"Kết quả nhất quán giúp chúng ta tự tin vào phương pháp mới."},{"en":"Both teams reported consistent results despite different conditions.","vi":"Cả hai nhóm đều báo cáo kết quả nhất quán dù điều kiện khác nhau."}]', '[]', NULL, '/kənˈsɪstənt rɪˈzʌlts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 62, 'constant rate', 'tốc độ không đổi', 'adj + n', '[{"en":"The chemical reaction proceeded at a constant rate throughout.","vi":"Phản ứng hóa học diễn ra với tốc độ không đổi suốt quá trình."},{"en":"The population grew at a constant rate for several years.","vi":"Dân số tăng với tốc độ không đổi trong vài năm."},{"en":"Water flowed from the tank at a constant rate.","vi":"Nước chảy ra khỏi bể với tốc độ không đổi."}]', '[]', NULL, '/ˈkɑːnstənt reɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 63, 'constituent elements', 'các thành phần cấu thành', 'adj + n', '[{"en":"Scientists studied the constituent elements of the unknown rock.","vi":"Các nhà khoa học đã nghiên cứu các thành phần cấu thành của loại đá lạ."},{"en":"The essay breaks the argument into its constituent elements.","vi":"Bài luận chia luận điểm thành các thành phần cấu thành của nó."},{"en":"Understanding the constituent elements helps explain the whole system.","vi":"Hiểu các thành phần cấu thành giúp giải thích toàn bộ hệ thống."}]', '[]', NULL, '/kənˈstɪtʃuənt ˈeləmənts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 64, 'constituent parts', 'các bộ phận cấu thành', 'adj + n', '[{"en":"Engineers examined the machine''s constituent parts one by one.","vi":"Các kỹ sư đã kiểm tra các bộ phận cấu thành của máy từng cái một."},{"en":"We can analyze the theory by separating its constituent parts.","vi":"Ta có thể phân tích lý thuyết bằng cách tách các bộ phận cấu thành của nó."},{"en":"The model shows how the constituent parts fit together.","vi":"Mô hình cho thấy các bộ phận cấu thành ghép với nhau như thế nào."}]', '[]', NULL, '/kənˈstɪtʃuənt pɑːrts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 65, 'contain information', 'chứa thông tin', 'v + n', '[{"en":"The report contains information about every department''s spending.","vi":"Báo cáo chứa thông tin về chi tiêu của từng phòng ban."},{"en":"This file contains information that should remain confidential.","vi":"Tệp này chứa thông tin cần được giữ bí mật."},{"en":"The website contains information for both students and parents.","vi":"Trang web chứa thông tin cho cả sinh viên lẫn phụ huynh."}]', '[]', NULL, '/kənˈteɪn ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 66, 'contain an element', 'chứa một yếu tố', 'v + n', '[{"en":"Most successful stories contain an element of surprise.","vi":"Hầu hết câu chuyện thành công đều chứa một yếu tố bất ngờ."},{"en":"The plan contains an element of risk we cannot ignore.","vi":"Kế hoạch chứa một yếu tố rủi ro mà ta không thể bỏ qua."},{"en":"Her argument contains an element of truth worth considering.","vi":"Lập luận của cô chứa một yếu tố sự thật đáng để cân nhắc."}]', '[]', NULL, '/kənˈteɪn ən ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 67, 'contemporary debate', 'cuộc tranh luận đương đại', 'adj + n', '[{"en":"The book engages with contemporary debate on free speech.","vi":"Cuốn sách tham gia vào cuộc tranh luận đương đại về tự do ngôn luận."},{"en":"Privacy is a major theme in contemporary debate about technology.","vi":"Quyền riêng tư là chủ đề lớn trong cuộc tranh luận đương đại về công nghệ."},{"en":"Her research contributes to contemporary debate on inequality.","vi":"Nghiên cứu của bà đóng góp vào cuộc tranh luận đương đại về bất bình đẳng."}]', '[]', NULL, '/kənˈtempəreri dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 68, 'contemporary issue', 'vấn đề đương đại', 'adj + n', '[{"en":"The class discusses one contemporary issue every week.","vi":"Lớp học thảo luận về một vấn đề đương đại mỗi tuần."},{"en":"Climate change is the defining contemporary issue of our age.","vi":"Biến đổi khí hậu là vấn đề đương đại tiêu biểu của thời đại chúng ta."},{"en":"Students chose a contemporary issue for their final project.","vi":"Sinh viên đã chọn một vấn đề đương đại cho dự án cuối khóa."}]', '[]', NULL, '/kənˈtempəreri ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 69, 'contemporary life', 'đời sống đương đại', 'adj + n', '[{"en":"Technology has transformed almost every part of contemporary life.","vi":"Công nghệ đã thay đổi gần như mọi mặt của đời sống đương đại."},{"en":"The novel paints a vivid picture of contemporary life.","vi":"Cuốn tiểu thuyết vẽ nên bức tranh sống động về đời sống đương đại."},{"en":"Stress is often described as a feature of contemporary life.","vi":"Căng thẳng thường được mô tả là một đặc điểm của đời sống đương đại."}]', '[]', NULL, '/kənˈtempəreri laɪf/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 70, 'contemporary society', 'xã hội đương đại', 'adj + n', '[{"en":"Social media plays a central role in contemporary society.","vi":"Mạng xã hội đóng vai trò trung tâm trong xã hội đương đại."},{"en":"The essay examines inequality within contemporary society.","vi":"Bài luận khảo sát sự bất bình đẳng trong xã hội đương đại."},{"en":"Contemporary society faces many challenges around privacy.","vi":"Xã hội đương đại đối mặt với nhiều thách thức về quyền riêng tư."}]', '[]', NULL, '/kənˈtempəreri səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 71, 'contemporary world', 'thế giới đương đại', 'adj + n', '[{"en":"Global trade connects every corner of the contemporary world.","vi":"Thương mại toàn cầu kết nối mọi ngóc ngách của thế giới đương đại."},{"en":"The contemporary world depends heavily on digital communication.","vi":"Thế giới đương đại phụ thuộc nhiều vào giao tiếp số."},{"en":"Migration is a defining feature of the contemporary world.","vi":"Di cư là một đặc điểm tiêu biểu của thế giới đương đại."}]', '[]', NULL, '/kənˈtempəreri wɜːrld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 72, 'contextual factors', 'các yếu tố bối cảnh', 'adj + n', '[{"en":"Contextual factors such as culture shape how people respond.","vi":"Các yếu tố bối cảnh như văn hóa định hình cách con người phản ứng."},{"en":"Researchers must account for contextual factors in their analysis.","vi":"Các nhà nghiên cứu phải tính đến các yếu tố bối cảnh trong phân tích."},{"en":"The outcome depends on several contextual factors at the school.","vi":"Kết quả phụ thuộc vào nhiều yếu tố bối cảnh tại trường học."}]', '[]', NULL, '/kənˈtekstʃuəl ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 73, 'continued existence', 'sự tồn tại tiếp diễn', 'adj + n', '[{"en":"Pollution threatens the continued existence of many species.","vi":"Ô nhiễm đe dọa sự tồn tại tiếp diễn của nhiều loài."},{"en":"Funding is essential for the continued existence of the museum.","vi":"Nguồn vốn rất cần thiết cho sự tồn tại tiếp diễn của bảo tàng."},{"en":"The treaty ensures the continued existence of the small nation.","vi":"Hiệp ước bảo đảm sự tồn tại tiếp diễn của quốc gia nhỏ."}]', '[]', NULL, '/kənˈtɪnjuːd ɪɡˈzɪstəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 74, 'continued growth', 'sự tăng trưởng liên tục', 'adj + n', '[{"en":"The company expects continued growth in overseas markets.","vi":"Công ty kỳ vọng sự tăng trưởng liên tục ở thị trường nước ngoài."},{"en":"Continued growth depends on investment in new technology.","vi":"Sự tăng trưởng liên tục phụ thuộc vào đầu tư cho công nghệ mới."},{"en":"The city has seen continued growth in its population.","vi":"Thành phố đã chứng kiến sự tăng trưởng liên tục về dân số."}]', '[]', NULL, '/kənˈtɪnjuːd ɡroʊθ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 75, 'continued use', 'việc tiếp tục sử dụng', 'adj + n', '[{"en":"The continued use of plastic harms the marine environment.","vi":"Việc tiếp tục sử dụng nhựa gây hại cho môi trường biển."},{"en":"Doctors warned against the continued use of the old drug.","vi":"Bác sĩ cảnh báo việc tiếp tục sử dụng loại thuốc cũ."},{"en":"Continued use of the software requires a yearly license.","vi":"Việc tiếp tục sử dụng phần mềm cần có giấy phép hằng năm."}]', '[]', NULL, '/kənˈtɪnjuːd juːs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 76, 'continuous process', 'quá trình liên tục', 'adj + n', '[{"en":"Learning a language is a continuous process, not a single event.","vi":"Học một ngôn ngữ là quá trình liên tục, không phải một sự kiện đơn lẻ."},{"en":"Quality control is a continuous process throughout production.","vi":"Kiểm soát chất lượng là quá trình liên tục trong suốt sản xuất."},{"en":"Improvement at the factory is treated as a continuous process.","vi":"Việc cải tiến tại nhà máy được xem là một quá trình liên tục."}]', '[]', NULL, '/kənˈtɪnjuəs ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 77, 'contribute significantly', 'đóng góp đáng kể', 'v + adv', '[{"en":"Volunteers contribute significantly to the success of the festival.","vi":"Các tình nguyện viên đóng góp đáng kể vào thành công của lễ hội."},{"en":"Small businesses contribute significantly to the local economy.","vi":"Các doanh nghiệp nhỏ đóng góp đáng kể vào nền kinh tế địa phương."},{"en":"Her research contributed significantly to our understanding of memory.","vi":"Nghiên cứu của bà đóng góp đáng kể vào hiểu biết của ta về trí nhớ."}]', '[]', NULL, '/kənˈtrɪbjuːt sɪɡˈnɪfɪkəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 78, 'contribute to the development of', 'góp phần vào sự phát triển của', 'v + n', '[{"en":"Reading widely contributes to the development of strong writing.","vi":"Đọc nhiều góp phần vào sự phát triển của kỹ năng viết tốt."},{"en":"Trade contributed to the development of early coastal towns.","vi":"Thương mại đã góp phần vào sự phát triển của các thị trấn ven biển sơ khai."},{"en":"Good teachers contribute to the development of a child''s confidence.","vi":"Giáo viên giỏi góp phần vào sự phát triển sự tự tin của trẻ."}]', '[]', NULL, '/kənˈtrɪbjuːt tə ðə dɪˈveləpmənt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 79, 'controversial issue', 'vấn đề gây tranh cãi', 'adj + n', '[{"en":"Immigration remains a controversial issue in many countries.","vi":"Nhập cư vẫn là một vấn đề gây tranh cãi ở nhiều quốc gia."},{"en":"The debate focused on a controversial issue in education policy.","vi":"Cuộc tranh luận tập trung vào một vấn đề gây tranh cãi trong chính sách giáo dục."},{"en":"Writing about a controversial issue requires careful, balanced evidence.","vi":"Viết về vấn đề gây tranh cãi đòi hỏi bằng chứng cẩn thận, cân bằng."}]', '[]', NULL, '/ˌkɑːntrəˈvɜːrʃəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 80, 'conventional view', 'quan điểm thông thường', 'adj + n', '[{"en":"The study challenges the conventional view of how memory works.","vi":"Nghiên cứu thách thức quan điểm thông thường về cách trí nhớ hoạt động."},{"en":"The conventional view assumes that growth always benefits everyone.","vi":"Quan điểm thông thường cho rằng tăng trưởng luôn có lợi cho mọi người."},{"en":"Her findings cast doubt on the conventional view of leadership.","vi":"Phát hiện của bà gieo nghi ngờ về quan điểm thông thường về lãnh đạo."}]', '[]', NULL, '/kənˈvenʃənəl vjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 81, 'conventional wisdom', 'lối nghĩ thông thường', 'adj + n', '[{"en":"Conventional wisdom says that practice always leads to perfection.","vi":"Lối nghĩ thông thường cho rằng luyện tập luôn dẫn đến hoàn hảo."},{"en":"The author questions conventional wisdom about healthy eating.","vi":"Tác giả đặt câu hỏi về lối nghĩ thông thường liên quan đến ăn uống lành mạnh."},{"en":"New data overturned the conventional wisdom on the subject.","vi":"Dữ liệu mới đã lật đổ lối nghĩ thông thường về chủ đề này."}]', '[]', NULL, '/kənˈvenʃənəl ˈwɪzdəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 82, 'convey information', 'truyền tải thông tin', 'v + n', '[{"en":"Clear graphs convey information faster than long paragraphs.","vi":"Biểu đồ rõ ràng truyền tải thông tin nhanh hơn những đoạn văn dài."},{"en":"The signs convey information to drivers who do not stop.","vi":"Các biển báo truyền tải thông tin cho tài xế không dừng lại."},{"en":"A good summary should convey information accurately and briefly.","vi":"Một bản tóm tắt tốt cần truyền tải thông tin chính xác và ngắn gọn."}]', '[]', NULL, '/kənˈveɪ ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 83, 'convey meaning', 'truyền đạt ý nghĩa', 'v + n', '[{"en":"Gestures can convey meaning even when words are not used.","vi":"Cử chỉ có thể truyền đạt ý nghĩa ngay cả khi không dùng từ ngữ."},{"en":"A skilled translator must convey meaning, not just words.","vi":"Một dịch giả giỏi phải truyền đạt ý nghĩa, không chỉ chuyển từ ngữ."},{"en":"Colors in the painting convey meaning about the artist''s mood.","vi":"Màu sắc trong bức tranh truyền đạt ý nghĩa về tâm trạng của họa sĩ."}]', '[]', NULL, '/kənˈveɪ ˈmiːnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 84, 'convey a message', 'truyền tải một thông điệp', 'v + n', '[{"en":"The advertisement tries to convey a message about saving water.","vi":"Mẩu quảng cáo cố truyền tải một thông điệp về tiết kiệm nước."},{"en":"Speakers must convey a message clearly to a large audience.","vi":"Người nói phải truyền tải một thông điệp rõ ràng đến đông khán giả."},{"en":"The film conveys a message about kindness and forgiveness.","vi":"Bộ phim truyền tải một thông điệp về lòng tốt và sự tha thứ."}]', '[]', NULL, '/kənˈveɪ ə ˈmesɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 85, 'convincing evidence', 'bằng chứng thuyết phục', 'adj + n', '[{"en":"The lawyer presented convincing evidence to support her claim.","vi":"Luật sư đã đưa ra bằng chứng thuyết phục để củng cố lập luận của mình."},{"en":"There is convincing evidence that exercise improves mental health.","vi":"Có bằng chứng thuyết phục rằng tập thể dục cải thiện sức khỏe tinh thần."},{"en":"Without convincing evidence, the theory will not be accepted.","vi":"Không có bằng chứng thuyết phục, lý thuyết sẽ không được chấp nhận."}]', '[]', NULL, '/kənˈvɪnsɪŋ ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 86, 'coping strategy', 'chiến lược ứng phó', 'adj + n', '[{"en":"Deep breathing is a simple coping strategy for stress.","vi":"Hít thở sâu là một chiến lược ứng phó đơn giản với căng thẳng."},{"en":"The counselor taught students a useful coping strategy for exams.","vi":"Chuyên viên tư vấn đã dạy sinh viên một chiến lược ứng phó hữu ích cho kỳ thi."},{"en":"Everyone needs a healthy coping strategy during difficult times.","vi":"Ai cũng cần một chiến lược ứng phó lành mạnh trong những lúc khó khăn."}]', '[]', NULL, '/ˈkoʊpɪŋ ˈstrætədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 87, 'core area', 'lĩnh vực cốt lõi', 'adj + n', '[{"en":"Mathematics is a core area of study in this program.","vi":"Toán học là một lĩnh vực cốt lõi trong chương trình này."},{"en":"The company decided to focus on its core area of expertise.","vi":"Công ty quyết định tập trung vào lĩnh vực chuyên môn cốt lõi của mình."},{"en":"Customer service remains a core area for the whole team.","vi":"Dịch vụ khách hàng vẫn là lĩnh vực cốt lõi của cả nhóm."}]', '[]', NULL, '/kɔːr ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 88, 'core element', 'yếu tố cốt lõi', 'adj + n', '[{"en":"Trust is a core element of any lasting friendship.","vi":"Niềm tin là yếu tố cốt lõi của bất kỳ tình bạn lâu bền nào."},{"en":"Feedback is a core element of the new training program.","vi":"Phản hồi là một yếu tố cốt lõi của chương trình đào tạo mới."},{"en":"Safety is treated as a core element of the design.","vi":"An toàn được xem là một yếu tố cốt lõi của thiết kế."}]', '[]', NULL, '/kɔːr ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 89, 'core issue', 'vấn đề cốt lõi', 'adj + n', '[{"en":"The core issue is whether the plan can be funded.","vi":"Vấn đề cốt lõi là liệu kế hoạch có thể được cấp vốn hay không."},{"en":"Let us return to the core issue of the discussion.","vi":"Hãy quay lại vấn đề cốt lõi của cuộc thảo luận."},{"en":"Fairness is the core issue behind the workers'' complaints.","vi":"Công bằng là vấn đề cốt lõi đằng sau những lời phàn nàn của công nhân."}]', '[]', NULL, '/kɔːr ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 90, 'core skills', 'kỹ năng cốt lõi', 'adj + n', '[{"en":"Reading and writing are core skills for academic success.","vi":"Đọc và viết là những kỹ năng cốt lõi cho thành công học thuật."},{"en":"The course aims to build core skills in problem solving.","vi":"Khóa học nhằm xây dựng kỹ năng cốt lõi trong giải quyết vấn đề."},{"en":"Employers expect graduates to have strong core skills.","vi":"Nhà tuyển dụng kỳ vọng sinh viên tốt nghiệp có kỹ năng cốt lõi vững."}]', '[]', NULL, '/kɔːr skɪlz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 91, 'core value', 'giá trị cốt lõi', 'adj + n', '[{"en":"Honesty is a core value the company expects from everyone.","vi":"Trung thực là một giá trị cốt lõi mà công ty kỳ vọng ở mọi người."},{"en":"Respect for others remains a core value at this school.","vi":"Tôn trọng người khác vẫn là một giá trị cốt lõi tại trường này."},{"en":"The charity built its work around one clear core value.","vi":"Tổ chức từ thiện xây dựng công việc quanh một giá trị cốt lõi rõ ràng."}]', '[]', NULL, '/kɔːr ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 92, 'correct interpretation', 'cách diễn giải đúng', 'adj + n', '[{"en":"Finding the correct interpretation of the data took several weeks.","vi":"Tìm ra cách diễn giải đúng của dữ liệu mất vài tuần."},{"en":"Scholars still argue about the correct interpretation of the text.","vi":"Các học giả vẫn tranh luận về cách diễn giải đúng của văn bản."},{"en":"A correct interpretation depends on understanding the full context.","vi":"Cách diễn giải đúng phụ thuộc vào việc hiểu toàn bộ bối cảnh."}]', '[]', NULL, '/kəˈrekt ɪnˌtɜːrprɪˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 93, 'correct an error', 'sửa một lỗi', 'v + n', '[{"en":"The editor took an hour to correct an error in the report.","vi":"Biên tập viên mất một giờ để sửa một lỗi trong báo cáo."},{"en":"Always read your work again to correct an error early.","vi":"Hãy luôn đọc lại bài để sửa một lỗi từ sớm."},{"en":"The team rushed to correct an error before the deadline.","vi":"Nhóm đã vội vã sửa một lỗi trước hạn chót."}]', '[]', NULL, '/kəˈrekt ən ˈerər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 94, 'counter argument', 'lập luận phản bác', 'adj + n', '[{"en":"A strong essay should address the main counter argument honestly.","vi":"Một bài luận mạnh nên giải quyết lập luận phản bác chính một cách trung thực."},{"en":"She offered a clear counter argument during the class debate.","vi":"Cô đã đưa ra một lập luận phản bác rõ ràng trong buổi tranh luận trên lớp."},{"en":"The counter argument focuses on the cost of the new policy.","vi":"Lập luận phản bác tập trung vào chi phí của chính sách mới."}]', '[]', NULL, '/ˈkaʊntər ˈɑːrɡjumənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 95, 'cover a range of', 'bao quát một loạt', 'v + n', '[{"en":"The textbook covers a range of topics in modern history.","vi":"Sách giáo khoa bao quát một loạt chủ đề trong lịch sử hiện đại."},{"en":"The survey covers a range of questions about daily habits.","vi":"Cuộc khảo sát bao quát một loạt câu hỏi về thói quen hằng ngày."},{"en":"Our service covers a range of needs for small businesses.","vi":"Dịch vụ của chúng tôi bao quát một loạt nhu cầu cho doanh nghiệp nhỏ."}]', '[]', NULL, '/ˈkʌvər ə reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 96, 'cover a topic', 'đề cập một chủ đề', 'v + n', '[{"en":"Each lecture will cover a topic in greater depth.","vi":"Mỗi bài giảng sẽ đề cập một chủ đề một cách sâu hơn."},{"en":"The article covers a topic that few writers have explored.","vi":"Bài báo đề cập một chủ đề mà ít cây bút đã khám phá."},{"en":"We did not have time to cover a topic on grammar.","vi":"Chúng tôi không có thời gian để đề cập một chủ đề về ngữ pháp."}]', '[]', NULL, '/ˈkʌvər ə ˈtɑːpɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 97, 'cover an area', 'bao phủ một khu vực', 'v + n', '[{"en":"The new network will cover an area of fifty square miles.","vi":"Mạng lưới mới sẽ bao phủ một khu vực rộng năm mươi dặm vuông."},{"en":"The flood covered an area larger than the whole city.","vi":"Trận lụt đã bao phủ một khu vực lớn hơn cả thành phố."},{"en":"Patrols cover an area along the entire northern border.","vi":"Các đội tuần tra bao phủ một khu vực dọc toàn bộ biên giới phía bắc."}]', '[]', NULL, '/ˈkʌvər ən ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 98, 'create conditions', 'tạo điều kiện', 'v + n', '[{"en":"Good policies create conditions that help businesses grow.","vi":"Chính sách tốt tạo điều kiện giúp doanh nghiệp phát triển."},{"en":"Teachers try to create conditions where students feel safe.","vi":"Giáo viên cố tạo điều kiện để học sinh cảm thấy an toàn."},{"en":"Heavy rain created conditions ideal for the spreading disease.","vi":"Mưa lớn đã tạo điều kiện lý tưởng cho dịch bệnh lan rộng."}]', '[]', NULL, '/kriˈeɪt kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 99, 'create opportunities', 'tạo cơ hội', 'v + n', '[{"en":"New technology can create opportunities for young entrepreneurs.","vi":"Công nghệ mới có thể tạo cơ hội cho các doanh nhân trẻ."},{"en":"The program aims to create opportunities for rural students.","vi":"Chương trình nhằm tạo cơ hội cho sinh viên vùng nông thôn."},{"en":"Travel often creates opportunities to learn new languages.","vi":"Du lịch thường tạo cơ hội để học các ngôn ngữ mới."}]', '[]', NULL, '/kriˈeɪt ˌɑːpərˈtuːnətiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 100, 'create problems', 'gây ra vấn đề', 'v + n', '[{"en":"Rushing the project may create problems we cannot fix later.","vi":"Vội vàng làm dự án có thể gây ra vấn đề ta không sửa được về sau."},{"en":"Poor planning often creates problems for the whole team.","vi":"Lập kế hoạch kém thường gây ra vấn đề cho cả nhóm."},{"en":"Too much traffic creates problems for people living downtown.","vi":"Quá nhiều xe cộ gây ra vấn đề cho người sống ở trung tâm."}]', '[]', NULL, '/kriˈeɪt ˈprɑːbləmz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 101, 'create an environment', 'tạo ra một môi trường', 'v + n', '[{"en":"Good leaders create an environment where everyone can contribute.","vi":"Người lãnh đạo giỏi tạo ra một môi trường để mọi người đều đóng góp được."},{"en":"The school tries to create an environment of mutual respect.","vi":"Trường học cố tạo ra một môi trường tôn trọng lẫn nhau."},{"en":"Soft lighting helps create an environment that feels calm.","vi":"Ánh sáng dịu giúp tạo ra một môi trường mang lại cảm giác yên bình."}]', '[]', NULL, '/kriˈeɪt ən ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 102, 'create an impression', 'tạo ấn tượng', 'v + n', '[{"en":"A neat resume helps create an impression of professionalism.","vi":"Một bản lý lịch gọn gàng giúp tạo ấn tượng về sự chuyên nghiệp."},{"en":"The opening scene creates an impression of quiet tension.","vi":"Cảnh mở đầu tạo ấn tượng về sự căng thẳng lặng lẽ."},{"en":"Try to create an impression of confidence during the interview.","vi":"Hãy cố tạo ấn tượng về sự tự tin trong buổi phỏng vấn."}]', '[]', NULL, '/kriˈeɪt ən ɪmˈpreʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 103, 'create an opportunity', 'tạo ra một cơ hội', 'v + n', '[{"en":"The merger could create an opportunity to enter new markets.","vi":"Việc sáp nhập có thể tạo ra một cơ hội để thâm nhập thị trường mới."},{"en":"Volunteering created an opportunity for her to meet experts.","vi":"Làm tình nguyện đã tạo ra một cơ hội để cô gặp gỡ các chuyên gia."},{"en":"A short delay created an opportunity to review the plan.","vi":"Một chút chậm trễ đã tạo ra một cơ hội để xem lại kế hoạch."}]', '[]', NULL, '/kriˈeɪt ən ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 104, 'creative process', 'quá trình sáng tạo', 'adj + n', '[{"en":"Writing a novel is a long and demanding creative process.","vi":"Viết một cuốn tiểu thuyết là một quá trình sáng tạo dài và đòi hỏi nhiều."},{"en":"The artist described her creative process in great detail.","vi":"Người nghệ sĩ đã mô tả quá trình sáng tạo của mình rất chi tiết."},{"en":"Mistakes are a natural part of any creative process.","vi":"Sai lầm là một phần tự nhiên của bất kỳ quá trình sáng tạo nào."}]', '[]', NULL, '/kriˈeɪtɪv ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 105, 'creative thinking', 'tư duy sáng tạo', 'adj + n', '[{"en":"The workshop encourages creative thinking through group activities.","vi":"Buổi hội thảo khuyến khích tư duy sáng tạo qua các hoạt động nhóm."},{"en":"Creative thinking helps students solve problems in new ways.","vi":"Tư duy sáng tạo giúp học sinh giải quyết vấn đề theo cách mới."},{"en":"Employers increasingly value creative thinking over rote memory.","vi":"Nhà tuyển dụng ngày càng coi trọng tư duy sáng tạo hơn học thuộc lòng."}]', '[]', NULL, '/kriˈeɪtɪv ˈθɪŋkɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 106, 'creative work', 'tác phẩm sáng tạo', 'adj + n', '[{"en":"The exhibition displays creative work by local young artists.","vi":"Triển lãm trưng bày tác phẩm sáng tạo của các nghệ sĩ trẻ địa phương."},{"en":"Copyright law protects creative work from being copied freely.","vi":"Luật bản quyền bảo vệ tác phẩm sáng tạo khỏi bị sao chép tùy ý."},{"en":"She devotes her evenings to creative work after office hours.","vi":"Cô dành các buổi tối cho công việc sáng tạo sau giờ làm việc."}]', '[]', NULL, '/kriˈeɪtɪv wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 107, 'criminal offence', 'hành vi phạm tội', 'adj + n', '[{"en":"Driving without a license is a serious criminal offence.","vi":"Lái xe không có bằng là một hành vi phạm tội nghiêm trọng."},{"en":"The new law makes online fraud a criminal offence.","vi":"Luật mới biến gian lận trực tuyến thành một hành vi phạm tội."},{"en":"He was charged with a criminal offence last month.","vi":"Anh ta bị buộc tội với một hành vi phạm tội vào tháng trước."}]', '[]', NULL, '/ˈkrɪmɪnəl əˈfens/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 108, 'critical analysis', 'phân tích phản biện', 'adj + n', '[{"en":"The essay offers a critical analysis of the author''s main claims.","vi":"Bài luận đưa ra một phân tích phản biện về các luận điểm chính của tác giả."},{"en":"Students must provide critical analysis, not just a summary.","vi":"Sinh viên phải đưa ra phân tích phản biện, chứ không chỉ tóm tắt."},{"en":"Her critical analysis revealed serious flaws in the study.","vi":"Phân tích phản biện của cô đã làm lộ những lỗ hổng nghiêm trọng trong nghiên cứu."}]', '[]', NULL, '/ˈkrɪtɪkəl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 109, 'critical approach', 'cách tiếp cận phản biện', 'adj + n', '[{"en":"The course teaches a critical approach to reading the news.","vi":"Khóa học dạy một cách tiếp cận phản biện khi đọc tin tức."},{"en":"A critical approach asks who benefits from each decision.","vi":"Cách tiếp cận phản biện đặt câu hỏi ai được lợi từ mỗi quyết định."},{"en":"She brought a critical approach to every source she used.","vi":"Cô áp dụng cách tiếp cận phản biện với mọi nguồn cô dùng."}]', '[]', NULL, '/ˈkrɪtɪkəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 110, 'critical attention', 'sự chú ý phê bình', 'adj + n', '[{"en":"The novel received critical attention soon after its release.","vi":"Cuốn tiểu thuyết nhận được sự chú ý phê bình ngay sau khi ra mắt."},{"en":"Her early films drew little critical attention at the time.","vi":"Những bộ phim đầu của bà ít được giới phê bình chú ý vào lúc đó."},{"en":"This topic deserves more critical attention from scholars.","vi":"Chủ đề này xứng đáng được giới học giả chú ý phê bình nhiều hơn."}]', '[]', NULL, '/ˈkrɪtɪkəl əˈtenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 111, 'critical essay', 'bài luận phản biện', 'adj + n', '[{"en":"Students wrote a critical essay on the poem''s central theme.","vi":"Sinh viên viết một bài luận phản biện về chủ đề trung tâm của bài thơ."},{"en":"A good critical essay supports every claim with clear evidence.","vi":"Một bài luận phản biện tốt hỗ trợ mọi luận điểm bằng bằng chứng rõ ràng."},{"en":"The professor praised her critical essay for its balanced argument.","vi":"Giáo sư khen bài luận phản biện của cô vì lập luận cân bằng."}]', '[]', NULL, '/ˈkrɪtɪkəl ˈeseɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 112, 'critical evaluation', 'đánh giá phản biện', 'adj + n', '[{"en":"The report includes a critical evaluation of the proposed plan.","vi":"Báo cáo bao gồm một đánh giá phản biện về kế hoạch được đề xuất."},{"en":"Critical evaluation of sources is a key research skill.","vi":"Đánh giá phản biện các nguồn là một kỹ năng nghiên cứu quan trọng."},{"en":"Her critical evaluation showed where the method could improve.","vi":"Đánh giá phản biện của cô chỉ ra nơi phương pháp có thể cải thiện."}]', '[]', NULL, '/ˈkrɪtɪkəl ɪˌvæljuˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 113, 'critical examination', 'sự xem xét phản biện', 'adj + n', '[{"en":"The book offers a critical examination of modern economic theory.","vi":"Cuốn sách đưa ra sự xem xét phản biện về lý thuyết kinh tế hiện đại."},{"en":"A critical examination of the data raised several new questions.","vi":"Sự xem xét phản biện đối với dữ liệu đã đặt ra nhiều câu hỏi mới."},{"en":"The chapter calls for a critical examination of old assumptions.","vi":"Chương này kêu gọi sự xem xét phản biện đối với các giả định cũ."}]', '[]', NULL, '/ˈkrɪtɪkəl ɪɡˌzæmɪˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 114, 'critical factor', 'yếu tố then chốt', 'adj + n', '[{"en":"Timing was a critical factor in the company''s early success.","vi":"Thời điểm là một yếu tố then chốt trong thành công sớm của công ty."},{"en":"Cost is often the critical factor when choosing a supplier.","vi":"Chi phí thường là yếu tố then chốt khi chọn nhà cung cấp."},{"en":"Motivation is a critical factor in long-term language learning.","vi":"Động lực là một yếu tố then chốt trong việc học ngôn ngữ lâu dài."}]', '[]', NULL, '/ˈkrɪtɪkəl ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 115, 'critical importance', 'tầm quan trọng then chốt', 'adj + n', '[{"en":"The study highlights the critical importance of early intervention.","vi":"Nghiên cứu nhấn mạnh tầm quan trọng then chốt của can thiệp sớm."},{"en":"Clean water is of critical importance to public health.","vi":"Nước sạch có tầm quan trọng then chốt đối với sức khỏe cộng đồng."},{"en":"Teachers stress the critical importance of regular practice.","vi":"Giáo viên nhấn mạnh tầm quan trọng then chốt của việc luyện tập đều đặn."}]', '[]', NULL, '/ˈkrɪtɪkəl ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 116, 'critical inquiry', 'sự tìm hiểu phản biện', 'adj + n', '[{"en":"The seminar encourages critical inquiry into historical sources.","vi":"Buổi hội thảo khuyến khích sự tìm hiểu phản biện về các nguồn lịch sử."},{"en":"Critical inquiry helps students question accepted assumptions.","vi":"Sự tìm hiểu phản biện giúp sinh viên chất vấn những giả định đã được chấp nhận."},{"en":"Her essay demonstrates careful critical inquiry and clear reasoning.","vi":"Bài luận của cô thể hiện sự tìm hiểu phản biện cẩn thận và lập luận rõ ràng."}]', '[]', NULL, '/ˈkrɪtɪkəl ɪnˈkwaɪri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 117, 'critical introduction', 'phần dẫn nhập phân tích', 'adj + n', '[{"en":"The book opens with a critical introduction to the topic.","vi":"Cuốn sách mở đầu bằng phần dẫn nhập phân tích về chủ đề."},{"en":"She wrote a critical introduction explaining the author''s main ideas.","vi":"Cô viết một phần dẫn nhập phân tích giải thích các ý chính của tác giả."},{"en":"A good critical introduction sets the context for later chapters.","vi":"Một phần dẫn nhập phân tích tốt định khung bối cảnh cho các chương sau."}]', '[]', NULL, '/ˈkrɪtɪkəl ˌɪntrəˈdʌkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 118, 'critical issue', 'vấn đề trọng yếu', 'adj + n', '[{"en":"Climate change remains a critical issue for future generations.","vi":"Biến đổi khí hậu vẫn là một vấn đề trọng yếu cho các thế hệ tương lai."},{"en":"The committee discussed several critical issues facing the school.","vi":"Ủy ban đã thảo luận nhiều vấn đề trọng yếu mà trường đang đối mặt."},{"en":"Data privacy has become a critical issue in modern society.","vi":"Quyền riêng tư dữ liệu đã trở thành một vấn đề trọng yếu trong xã hội hiện đại."}]', '[]', NULL, '/ˈkrɪtɪkəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 119, 'critical perspective', 'góc nhìn phản biện', 'adj + n', '[{"en":"The author adopts a critical perspective on modern technology.","vi":"Tác giả áp dụng một góc nhìn phản biện về công nghệ hiện đại."},{"en":"Reading widely gives students a richer critical perspective.","vi":"Đọc rộng mang lại cho sinh viên một góc nhìn phản biện phong phú hơn."},{"en":"A critical perspective helps us evaluate competing arguments.","vi":"Một góc nhìn phản biện giúp ta đánh giá các lập luận đối lập."}]', '[]', NULL, '/ˈkrɪtɪkəl pərˈspektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 120, 'critical point', 'điểm mấu chốt', 'adj + n', '[{"en":"The negotiations reached a critical point late at night.","vi":"Các cuộc đàm phán đã đến điểm mấu chốt vào đêm khuya."},{"en":"She made a critical point about the study''s limitations.","vi":"Cô đã nêu một điểm mấu chốt về những hạn chế của nghiên cứu."},{"en":"At this critical point, every decision carries serious consequences.","vi":"Tại điểm mấu chốt này, mọi quyết định đều mang hậu quả nghiêm trọng."}]', '[]', NULL, '/ˈkrɪtɪkəl pɔɪnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 121, 'critical reflection', 'sự suy ngẫm phản biện', 'adj + n', '[{"en":"The course requires critical reflection on your own learning.","vi":"Khóa học yêu cầu sự suy ngẫm phản biện về việc học của chính bạn."},{"en":"Critical reflection allows teachers to improve their practice.","vi":"Sự suy ngẫm phản biện cho phép giáo viên cải thiện phương pháp của mình."},{"en":"He kept a journal for daily critical reflection on events.","vi":"Anh giữ một cuốn nhật ký để suy ngẫm phản biện hằng ngày về các sự kiện."}]', '[]', NULL, '/ˈkrɪtɪkəl rɪˈflekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 122, 'critical review', 'bài đánh giá phản biện', 'adj + n', '[{"en":"She published a critical review of the new theory.","vi":"Cô đã công bố một bài đánh giá phản biện về lý thuyết mới."},{"en":"The assignment asks for a critical review of two articles.","vi":"Bài tập yêu cầu một bài đánh giá phản biện về hai bài báo."},{"en":"A critical review weighs both the strengths and weaknesses.","vi":"Một bài đánh giá phản biện cân nhắc cả điểm mạnh lẫn điểm yếu."}]', '[]', NULL, '/ˈkrɪtɪkəl rɪˈvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 123, 'critical role', 'vai trò then chốt', 'adj + n', '[{"en":"Sleep plays a critical role in memory consolidation.","vi":"Giấc ngủ đóng vai trò then chốt trong việc củng cố trí nhớ."},{"en":"Teachers play a critical role in shaping young minds.","vi":"Giáo viên đóng vai trò then chốt trong việc định hình tâm trí trẻ."},{"en":"Technology now plays a critical role in modern education.","vi":"Công nghệ giờ đây đóng vai trò then chốt trong giáo dục hiện đại."}]', '[]', NULL, '/ˈkrɪtɪkəl roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 124, 'critical scrutiny', 'sự xem xét kỹ lưỡng', 'adj + n', '[{"en":"The proposal came under critical scrutiny from the board.","vi":"Đề xuất chịu sự xem xét kỹ lưỡng từ hội đồng."},{"en":"His claims did not survive close critical scrutiny.","vi":"Các tuyên bố của anh không trụ vững trước sự xem xét kỹ lưỡng."},{"en":"Every source deserves critical scrutiny before being cited.","vi":"Mọi nguồn đều đáng được xem xét kỹ lưỡng trước khi trích dẫn."}]', '[]', NULL, '/ˈkrɪtɪkəl ˈskruːtəni/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 125, 'critical theory', 'lý thuyết phản biện', 'adj + n', '[{"en":"The lecture introduced students to critical theory and its origins.","vi":"Bài giảng giới thiệu cho sinh viên về lý thuyết phản biện và nguồn gốc của nó."},{"en":"Critical theory examines power relations within society.","vi":"Lý thuyết phản biện xem xét các quan hệ quyền lực trong xã hội."},{"en":"She applied critical theory to analyze the famous novel.","vi":"Cô áp dụng lý thuyết phản biện để phân tích cuốn tiểu thuyết nổi tiếng."}]', '[]', NULL, '/ˈkrɪtɪkəl ˈθɪri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 126, 'critical thinking', 'tư duy phản biện', 'adj + n', '[{"en":"The program aims to develop students'' critical thinking skills.","vi":"Chương trình nhằm phát triển kỹ năng tư duy phản biện của sinh viên."},{"en":"Critical thinking helps you spot weak arguments quickly.","vi":"Tư duy phản biện giúp bạn nhận ra các lập luận yếu một cách nhanh chóng."},{"en":"Employers value critical thinking as much as technical knowledge.","vi":"Nhà tuyển dụng coi trọng tư duy phản biện ngang với kiến thức chuyên môn."}]', '[]', NULL, '/ˈkrɪtɪkəl ˈθɪŋkɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 127, 'critical writing', 'lối viết phân tích', 'adj + n', '[{"en":"Academic essays require critical writing rather than mere description.","vi":"Bài luận học thuật đòi hỏi lối viết phân tích chứ không chỉ mô tả."},{"en":"The workshop teaches the basics of critical writing.","vi":"Buổi hội thảo dạy những điều cơ bản của lối viết phân tích."},{"en":"Good critical writing supports each claim with clear evidence.","vi":"Lối viết phân tích tốt chứng minh mỗi luận điểm bằng bằng chứng rõ ràng."}]', '[]', NULL, '/ˈkrɪtɪkəl ˈraɪtɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 128, 'critically evaluate', 'đánh giá một cách phản biện', 'adv + v', '[{"en":"Students must critically evaluate the evidence before drawing conclusions.","vi":"Sinh viên phải đánh giá bằng chứng một cách phản biện trước khi kết luận."},{"en":"The essay asks you to critically evaluate two opposing theories.","vi":"Bài luận yêu cầu bạn đánh giá một cách phản biện hai lý thuyết đối lập."},{"en":"Readers should critically evaluate claims found on social media.","vi":"Người đọc nên đánh giá một cách phản biện những tuyên bố trên mạng xã hội."}]', '[]', NULL, '/ˈkrɪtɪkli ɪˈvæljueɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 129, 'crucial difference', 'khác biệt mấu chốt', 'adj + n', '[{"en":"There is a crucial difference between knowing and understanding.","vi":"Có một khác biệt mấu chốt giữa biết và hiểu."},{"en":"Timing made a crucial difference to the final outcome.","vi":"Thời điểm tạo nên khác biệt mấu chốt cho kết quả cuối cùng."},{"en":"The study reveals a crucial difference between the two groups.","vi":"Nghiên cứu cho thấy một khác biệt mấu chốt giữa hai nhóm."}]', '[]', NULL, '/ˈkruːʃəl ˈdɪfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 130, 'crucial factor', 'yếu tố then chốt', 'adj + n', '[{"en":"Motivation is a crucial factor in academic success.","vi":"Động lực là yếu tố then chốt trong thành công học tập."},{"en":"Cost was the crucial factor in their final decision.","vi":"Chi phí là yếu tố then chốt trong quyết định cuối cùng của họ."},{"en":"Weather is a crucial factor affecting crop yields.","vi":"Thời tiết là yếu tố then chốt ảnh hưởng đến năng suất cây trồng."}]', '[]', NULL, '/ˈkruːʃəl ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 131, 'crucial importance', 'tầm quan trọng thiết yếu', 'adj + n', '[{"en":"Trust is of crucial importance in any working relationship.","vi":"Niềm tin có tầm quan trọng thiết yếu trong bất kỳ mối quan hệ làm việc nào."},{"en":"The report stresses the crucial importance of accurate data.","vi":"Báo cáo nhấn mạnh tầm quan trọng thiết yếu của dữ liệu chính xác."},{"en":"Early diagnosis is of crucial importance for treatment.","vi":"Chẩn đoán sớm có tầm quan trọng thiết yếu cho việc điều trị."}]', '[]', NULL, '/ˈkruːʃəl ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 132, 'crucial part', 'phần thiết yếu', 'adj + n', '[{"en":"Revision is a crucial part of preparing for exams.","vi":"Ôn tập là phần thiết yếu trong việc chuẩn bị cho kỳ thi."},{"en":"Feedback forms a crucial part of the learning process.","vi":"Phản hồi tạo nên phần thiết yếu của quá trình học tập."},{"en":"Trade has always been a crucial part of the economy.","vi":"Thương mại luôn là phần thiết yếu của nền kinh tế."}]', '[]', NULL, '/ˈkruːʃəl pɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 133, 'crucial point', 'điểm thiết yếu', 'adj + n', '[{"en":"She raised a crucial point that nobody had considered.","vi":"Cô nêu một điểm thiết yếu mà chưa ai cân nhắc."},{"en":"The lecture reached a crucial point about ethical limits.","vi":"Bài giảng đến một điểm thiết yếu về các giới hạn đạo đức."},{"en":"Understanding this crucial point clarifies the whole argument.","vi":"Hiểu điểm thiết yếu này làm sáng tỏ toàn bộ lập luận."}]', '[]', NULL, '/ˈkruːʃəl pɔɪnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 134, 'crucial question', 'câu hỏi mấu chốt', 'adj + n', '[{"en":"The crucial question is whether the method actually works.","vi":"Câu hỏi mấu chốt là liệu phương pháp có thực sự hiệu quả hay không."},{"en":"Her thesis addresses a crucial question in economics.","vi":"Luận án của cô giải quyết một câu hỏi mấu chốt trong kinh tế học."},{"en":"We still face the crucial question of how to fund it.","vi":"Chúng ta vẫn đối mặt câu hỏi mấu chốt là làm sao tài trợ cho nó."}]', '[]', NULL, '/ˈkruːʃəl ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 135, 'crucial role', 'vai trò thiết yếu', 'adj + n', '[{"en":"Parents play a crucial role in a child''s development.","vi":"Cha mẹ đóng vai trò thiết yếu trong sự phát triển của trẻ."},{"en":"Bees play a crucial role in pollinating many crops.","vi":"Ong đóng vai trò thiết yếu trong việc thụ phấn cho nhiều cây trồng."},{"en":"The internet plays a crucial role in spreading information.","vi":"Internet đóng vai trò thiết yếu trong việc lan truyền thông tin."}]', '[]', NULL, '/ˈkruːʃəl roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 136, 'cultural activity', 'hoạt động văn hóa', 'adj + n', '[{"en":"The festival offers a wide range of cultural activities.","vi":"Lễ hội mang đến nhiều hoạt động văn hóa đa dạng."},{"en":"Students join cultural activities to learn about other countries.","vi":"Sinh viên tham gia các hoạt động văn hóa để tìm hiểu về các nước khác."},{"en":"Music and dance are popular cultural activities in the region.","vi":"Âm nhạc và khiêu vũ là những hoạt động văn hóa phổ biến trong vùng."}]', '[]', NULL, '/ˈkʌltʃərəl ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 137, 'cultural aspect', 'khía cạnh văn hóa', 'adj + n', '[{"en":"The course explores the cultural aspects of language learning.","vi":"Khóa học khám phá các khía cạnh văn hóa của việc học ngôn ngữ."},{"en":"Travelers should respect the cultural aspects of each country.","vi":"Du khách nên tôn trọng các khía cạnh văn hóa của mỗi quốc gia."},{"en":"Her research focuses on the cultural aspects of food.","vi":"Nghiên cứu của cô tập trung vào các khía cạnh văn hóa của ẩm thực."}]', '[]', NULL, '/ˈkʌltʃərəl ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 138, 'cultural attitudes', 'thái độ văn hóa', 'adj + n', '[{"en":"Cultural attitudes toward work vary greatly between nations.","vi":"Thái độ văn hóa đối với công việc khác nhau rất nhiều giữa các quốc gia."},{"en":"The survey examined cultural attitudes about marriage and family.","vi":"Cuộc khảo sát xem xét thái độ văn hóa về hôn nhân và gia đình."},{"en":"Changing cultural attitudes have shaped modern parenting.","vi":"Thái độ văn hóa thay đổi đã định hình cách nuôi dạy con hiện đại."}]', '[]', NULL, '/ˈkʌltʃərəl ˈætɪtuːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 139, 'cultural background', 'nền tảng văn hóa', 'adj + n', '[{"en":"Students come from a variety of cultural backgrounds.","vi":"Sinh viên đến từ nhiều nền tảng văn hóa khác nhau."},{"en":"Her cultural background shaped how she viewed the issue.","vi":"Nền tảng văn hóa của cô định hình cách cô nhìn nhận vấn đề."},{"en":"Teachers should respect each student''s cultural background.","vi":"Giáo viên nên tôn trọng nền tảng văn hóa của mỗi học sinh."}]', '[]', NULL, '/ˈkʌltʃərəl ˈbækɡraʊnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 140, 'cultural boundary', 'ranh giới văn hóa', 'adj + n', '[{"en":"Music often crosses cultural boundaries with surprising ease.","vi":"Âm nhạc thường vượt qua ranh giới văn hóa một cách dễ dàng đáng ngạc nhiên."},{"en":"Globalization has blurred many traditional cultural boundaries.","vi":"Toàn cầu hóa đã làm mờ nhiều ranh giới văn hóa truyền thống."},{"en":"The project aims to break down cultural boundaries between groups.","vi":"Dự án nhằm phá vỡ các ranh giới văn hóa giữa các nhóm."}]', '[]', NULL, '/ˈkʌltʃərəl ˈbaʊndəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 141, 'cultural change', 'sự thay đổi văn hóa', 'adj + n', '[{"en":"Technology has driven rapid cultural change in recent decades.","vi":"Công nghệ đã thúc đẩy sự thay đổi văn hóa nhanh chóng trong các thập kỷ gần đây."},{"en":"Cultural change often happens slowly across generations.","vi":"Sự thay đổi văn hóa thường diễn ra chậm qua nhiều thế hệ."},{"en":"Immigration can be a powerful source of cultural change.","vi":"Di cư có thể là nguồn mạnh mẽ của sự thay đổi văn hóa."}]', '[]', NULL, '/ˈkʌltʃərəl tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 142, 'cultural context', 'bối cảnh văn hóa', 'adj + n', '[{"en":"Words can mean different things in another cultural context.","vi":"Từ ngữ có thể mang nghĩa khác trong một bối cảnh văn hóa khác."},{"en":"Understanding the cultural context helps interpret the poem.","vi":"Hiểu bối cảnh văn hóa giúp diễn giải bài thơ."},{"en":"Every artwork should be studied within its cultural context.","vi":"Mọi tác phẩm nghệ thuật nên được nghiên cứu trong bối cảnh văn hóa của nó."}]', '[]', NULL, '/ˈkʌltʃərəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 143, 'cultural differences', 'những khác biệt văn hóa', 'adj + n', '[{"en":"Cultural differences can cause misunderstandings in the workplace.","vi":"Những khác biệt văn hóa có thể gây hiểu lầm tại nơi làm việc."},{"en":"Travel teaches us to appreciate cultural differences.","vi":"Du lịch dạy chúng ta trân trọng những khác biệt văn hóa."},{"en":"The training program addresses cultural differences among staff.","vi":"Chương trình đào tạo giải quyết những khác biệt văn hóa giữa nhân viên."}]', '[]', NULL, '/ˈkʌltʃərəl ˈdɪfərənsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 144, 'cultural dimension', 'chiều kích văn hóa', 'adj + n', '[{"en":"The author ignores the cultural dimension of the conflict.","vi":"Tác giả bỏ qua chiều kích văn hóa của cuộc xung đột."},{"en":"Marketing must consider the cultural dimension of each market.","vi":"Tiếp thị phải xét đến chiều kích văn hóa của mỗi thị trường."},{"en":"Her study adds a cultural dimension to economic analysis.","vi":"Nghiên cứu của cô bổ sung chiều kích văn hóa vào phân tích kinh tế."}]', '[]', NULL, '/ˈkʌltʃərəl daɪˈmenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 145, 'cultural diversity', 'sự đa dạng văn hóa', 'adj + n', '[{"en":"The city is celebrated for its rich cultural diversity.","vi":"Thành phố được ca ngợi vì sự đa dạng văn hóa phong phú của nó."},{"en":"Schools benefit greatly from cultural diversity in the classroom.","vi":"Trường học hưởng lợi rất nhiều từ sự đa dạng văn hóa trong lớp."},{"en":"Cultural diversity encourages creativity and new ideas.","vi":"Sự đa dạng văn hóa khuyến khích sự sáng tạo và những ý tưởng mới."}]', '[]', NULL, '/ˈkʌltʃərəl daɪˈvɜːrsəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 146, 'cultural factors', 'các yếu tố văn hóa', 'adj + n', '[{"en":"Cultural factors strongly influence consumer behavior.","vi":"Các yếu tố văn hóa ảnh hưởng mạnh đến hành vi người tiêu dùng."},{"en":"The study controlled for cultural factors affecting health.","vi":"Nghiên cứu đã kiểm soát các yếu tố văn hóa ảnh hưởng đến sức khỏe."},{"en":"Cultural factors help explain differences in eating habits.","vi":"Các yếu tố văn hóa giúp giải thích khác biệt trong thói quen ăn uống."}]', '[]', NULL, '/ˈkʌltʃərəl ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 147, 'cultural heritage', 'di sản văn hóa', 'adj + n', '[{"en":"The temple is part of the nation''s cultural heritage.","vi":"Ngôi đền là một phần của di sản văn hóa quốc gia."},{"en":"Museums work hard to preserve our cultural heritage.","vi":"Các bảo tàng nỗ lực để bảo tồn di sản văn hóa của chúng ta."},{"en":"Local festivals keep cultural heritage alive for younger people.","vi":"Các lễ hội địa phương giữ cho di sản văn hóa sống động với người trẻ."}]', '[]', NULL, '/ˈkʌltʃərəl ˈherɪtɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 148, 'cultural history', 'lịch sử văn hóa', 'adj + n', '[{"en":"The lecture traced the cultural history of the region.","vi":"Bài giảng lần theo lịch sử văn hóa của vùng này."},{"en":"Her book explores the cultural history of coffee.","vi":"Cuốn sách của cô khám phá lịch sử văn hóa của cà phê."},{"en":"Understanding cultural history enriches our view of art.","vi":"Hiểu lịch sử văn hóa làm phong phú cách ta nhìn nghệ thuật."}]', '[]', NULL, '/ˈkʌltʃərəl ˈhɪstəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 149, 'cultural identity', 'bản sắc văn hóa', 'adj + n', '[{"en":"Language is closely tied to a person''s cultural identity.","vi":"Ngôn ngữ gắn chặt với bản sắc văn hóa của một người."},{"en":"Young immigrants often struggle to maintain their cultural identity.","vi":"Người nhập cư trẻ thường vật lộn để giữ gìn bản sắc văn hóa của mình."},{"en":"Traditional clothing expresses a strong cultural identity.","vi":"Trang phục truyền thống thể hiện một bản sắc văn hóa mạnh mẽ."}]', '[]', NULL, '/ˈkʌltʃərəl aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-3-01', 150, 'cultural influence', 'ảnh hưởng văn hóa', 'adj + n', '[{"en":"Foreign films have a strong cultural influence on teenagers.","vi":"Phim nước ngoài có ảnh hưởng văn hóa mạnh đến thanh thiếu niên."},{"en":"The region shows clear cultural influence from its neighbors.","vi":"Vùng này cho thấy ảnh hưởng văn hóa rõ rệt từ các nước láng giềng."},{"en":"Cuisine often reflects the cultural influence of past traders.","vi":"Ẩm thực thường phản ánh ảnh hưởng văn hóa của các thương nhân xưa."}]', '[]', NULL, '/ˈkʌltʃərəl ˈɪnfluəns/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-4-01', 'colloc-4', 'Cụm học thuật · Nhóm 4', 'Academic Collocation List (Pearson/PTE) — nhóm 4 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 1, 'cultural institution', 'thiết chế văn hóa', 'adj + n', '[{"en":"Libraries are important cultural institutions in every community.","vi":"Thư viện là những thiết chế văn hóa quan trọng trong mọi cộng đồng."},{"en":"The government funds several major cultural institutions.","vi":"Chính phủ tài trợ cho một số thiết chế văn hóa lớn."},{"en":"Museums serve as cultural institutions that educate the public.","vi":"Bảo tàng đóng vai trò thiết chế văn hóa giáo dục công chúng."}]', '[]', NULL, '/ˈkʌltʃərəl ˌɪnstɪˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 2, 'cultural issue', 'vấn đề văn hóa', 'adj + n', '[{"en":"The film raises important cultural issues about identity.","vi":"Bộ phim nêu lên những vấn đề văn hóa quan trọng về bản sắc."},{"en":"Managers must handle cultural issues in international teams.","vi":"Nhà quản lý phải xử lý các vấn đề văn hóa trong đội ngũ quốc tế."},{"en":"Language barriers are a common cultural issue for newcomers.","vi":"Rào cản ngôn ngữ là một vấn đề văn hóa phổ biến với người mới đến."}]', '[]', NULL, '/ˈkʌltʃərəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 3, 'cultural life', 'đời sống văn hóa', 'adj + n', '[{"en":"The city has a rich and vibrant cultural life.","vi":"Thành phố có một đời sống văn hóa phong phú và sôi động."},{"en":"Theaters and galleries enrich the cultural life of the town.","vi":"Nhà hát và phòng tranh làm phong phú đời sống văn hóa của thị trấn."},{"en":"Students contribute to campus cultural life through clubs.","vi":"Sinh viên đóng góp vào đời sống văn hóa của trường qua các câu lạc bộ."}]', '[]', NULL, '/ˈkʌltʃərəl laɪf/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 4, 'cultural norm', 'chuẩn mực văn hóa', 'adj + n', '[{"en":"Cultural norms determine how people greet one another.","vi":"Chuẩn mực văn hóa quyết định cách người ta chào hỏi nhau."},{"en":"Visitors should learn the local cultural norms before arriving.","vi":"Khách nên tìm hiểu chuẩn mực văn hóa địa phương trước khi đến."},{"en":"Breaking a cultural norm can cause unintended offense.","vi":"Vi phạm một chuẩn mực văn hóa có thể gây xúc phạm ngoài ý muốn."}]', '[]', NULL, '/ˈkʌltʃərəl nɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 5, 'cultural perspective', 'góc nhìn văn hóa', 'adj + n', '[{"en":"From a cultural perspective, the gift carries deep meaning.","vi":"Từ góc nhìn văn hóa, món quà mang ý nghĩa sâu sắc."},{"en":"The book offers a fresh cultural perspective on history.","vi":"Cuốn sách mang đến một góc nhìn văn hóa mới mẻ về lịch sử."},{"en":"Adopting a cultural perspective helps explain unusual customs.","vi":"Áp dụng góc nhìn văn hóa giúp giải thích các phong tục khác lạ."}]', '[]', NULL, '/ˈkʌltʃərəl pərˈspektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 6, 'cultural phenomenon', 'hiện tượng văn hóa', 'adj + n', '[{"en":"The song became a global cultural phenomenon overnight.","vi":"Bài hát trở thành một hiện tượng văn hóa toàn cầu chỉ sau một đêm."},{"en":"Social media is a cultural phenomenon worth studying closely.","vi":"Mạng xã hội là một hiện tượng văn hóa đáng nghiên cứu kỹ."},{"en":"Researchers analyzed the cultural phenomenon of viral videos.","vi":"Các nhà nghiên cứu phân tích hiện tượng văn hóa của video lan truyền."}]', '[]', NULL, '/ˈkʌltʃərəl fəˈnɑːmənɑːn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 7, 'cultural practice', 'tập quán văn hóa', 'adj + n', '[{"en":"Sharing meals is a common cultural practice in the village.","vi":"Cùng nhau dùng bữa là một tập quán văn hóa phổ biến ở làng."},{"en":"Some cultural practices are passed down for many centuries.","vi":"Một số tập quán văn hóa được truyền lại qua nhiều thế kỷ."},{"en":"The documentary records the cultural practices of the tribe.","vi":"Phim tài liệu ghi lại các tập quán văn hóa của bộ tộc."}]', '[]', NULL, '/ˈkʌltʃərəl ˈpræktɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 8, 'cultural significance', 'ý nghĩa văn hóa', 'adj + n', '[{"en":"The festival has great cultural significance for the community.","vi":"Lễ hội có ý nghĩa văn hóa lớn đối với cộng đồng."},{"en":"Scholars debate the cultural significance of the ancient site.","vi":"Các học giả tranh luận về ý nghĩa văn hóa của di chỉ cổ."},{"en":"The painting holds cultural significance beyond its beauty.","vi":"Bức tranh mang ý nghĩa văn hóa vượt xa vẻ đẹp của nó."}]', '[]', NULL, '/ˈkʌltʃərəl sɪɡˈnɪfɪkəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 9, 'cultural theory', 'lý thuyết văn hóa', 'adj + n', '[{"en":"The module introduces key ideas in cultural theory.","vi":"Học phần giới thiệu những ý tưởng chính trong lý thuyết văn hóa."},{"en":"Cultural theory examines how meaning is produced in society.","vi":"Lý thuyết văn hóa xem xét cách ý nghĩa được tạo ra trong xã hội."},{"en":"She drew on cultural theory to interpret the advertisement.","vi":"Cô vận dụng lý thuyết văn hóa để diễn giải mẩu quảng cáo."}]', '[]', NULL, '/ˈkʌltʃərəl ˈθɪri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 10, 'cultural tradition', 'truyền thống văn hóa', 'adj + n', '[{"en":"The family keeps many old cultural traditions alive.","vi":"Gia đình giữ gìn nhiều truyền thống văn hóa cũ."},{"en":"Cultural traditions help younger generations understand their roots.","vi":"Truyền thống văn hóa giúp thế hệ trẻ hiểu về cội nguồn của mình."},{"en":"Each region celebrates its own unique cultural traditions.","vi":"Mỗi vùng tôn vinh những truyền thống văn hóa độc đáo riêng."}]', '[]', NULL, '/ˈkʌltʃərəl trəˈdɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 11, 'cultural values', 'giá trị văn hóa', 'adj + n', '[{"en":"Cultural values shape how people define success.","vi":"Giá trị văn hóa định hình cách con người định nghĩa thành công."},{"en":"The school teaches respect for different cultural values.","vi":"Nhà trường dạy tôn trọng các giá trị văn hóa khác nhau."},{"en":"Advertising often reflects the cultural values of its audience.","vi":"Quảng cáo thường phản ánh giá trị văn hóa của khán giả."}]', '[]', NULL, '/ˈkʌltʃərəl ˈvæljuːz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 12, 'culturally specific', 'mang tính đặc thù văn hóa', 'adv + adj', '[{"en":"Some gestures are culturally specific and easily misread.","vi":"Một số cử chỉ mang tính đặc thù văn hóa và dễ bị hiểu sai."},{"en":"Humor is often culturally specific and hard to translate.","vi":"Sự hài hước thường mang tính đặc thù văn hóa và khó dịch."},{"en":"These rituals are culturally specific to that small region.","vi":"Những nghi lễ này mang tính đặc thù văn hóa của vùng nhỏ đó."}]', '[]', NULL, '/ˈkʌltʃərəli spəˈsɪfɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 13, 'current climate', 'bối cảnh hiện tại', 'adj + n', '[{"en":"In the current climate, many companies are cutting costs.","vi":"Trong bối cảnh hiện tại, nhiều công ty đang cắt giảm chi phí."},{"en":"The current economic climate makes investment risky.","vi":"Bối cảnh kinh tế hiện tại khiến việc đầu tư rủi ro."},{"en":"Researchers worry about the current political climate.","vi":"Các nhà nghiên cứu lo ngại về bối cảnh chính trị hiện tại."}]', '[]', NULL, '/ˈkɜːrənt ˈklaɪmət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 14, 'current issue', 'vấn đề thời sự', 'adj + n', '[{"en":"The seminar focuses on current issues in public health.","vi":"Buổi hội thảo tập trung vào các vấn đề thời sự trong y tế công cộng."},{"en":"Newspapers help students stay aware of current issues.","vi":"Báo chí giúp sinh viên nắm bắt các vấn đề thời sự."},{"en":"Climate change is one of the most pressing current issues.","vi":"Biến đổi khí hậu là một trong những vấn đề thời sự cấp bách nhất."}]', '[]', NULL, '/ˈkɜːrənt ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 15, 'current policy', 'chính sách hiện hành', 'adj + n', '[{"en":"The report criticizes the current policy on immigration.","vi":"Báo cáo chỉ trích chính sách hiện hành về nhập cư."},{"en":"Current policy does little to reduce traffic congestion.","vi":"Chính sách hiện hành làm rất ít để giảm ùn tắc giao thông."},{"en":"Experts recommend reviewing the current policy soon.","vi":"Các chuyên gia khuyến nghị sớm xem xét lại chính sách hiện hành."}]', '[]', NULL, '/ˈkɜːrənt ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 16, 'current research', 'nghiên cứu hiện nay', 'adj + n', '[{"en":"Current research suggests that exercise improves memory.","vi":"Nghiên cứu hiện nay cho thấy tập thể dục cải thiện trí nhớ."},{"en":"She reviewed the current research before writing her thesis.","vi":"Cô đã xem lại nghiên cứu hiện nay trước khi viết luận án."},{"en":"Current research focuses on renewable energy technologies.","vi":"Nghiên cứu hiện nay tập trung vào các công nghệ năng lượng tái tạo."}]', '[]', NULL, '/ˈkɜːrənt ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 17, 'current status', 'tình trạng hiện tại', 'adj + n', '[{"en":"The report describes the current status of the project.","vi":"Báo cáo mô tả tình trạng hiện tại của dự án."},{"en":"Please update me on the current status of the application.","vi":"Hãy cập nhật cho tôi về tình trạng hiện tại của đơn đăng ký."},{"en":"Scientists monitor the current status of endangered species.","vi":"Các nhà khoa học theo dõi tình trạng hiện tại của các loài nguy cấp."}]', '[]', NULL, '/ˈkɜːrənt ˈstætəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 18, 'current technology', 'công nghệ hiện tại', 'adj + n', '[{"en":"Current technology allows doctors to diagnose diseases earlier.","vi":"Công nghệ hiện tại cho phép bác sĩ chẩn đoán bệnh sớm hơn."},{"en":"The factory relies heavily on current technology to compete.","vi":"Nhà máy phụ thuộc nhiều vào công nghệ hiện tại để cạnh tranh."},{"en":"Current technology cannot yet solve this difficult problem.","vi":"Công nghệ hiện tại vẫn chưa thể giải quyết vấn đề khó này."}]', '[]', NULL, '/ˈkɜːrənt tekˈnɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 19, 'current trend', 'xu hướng hiện nay', 'adj + n', '[{"en":"The current trend is toward remote and flexible work.","vi":"Xu hướng hiện nay là làm việc từ xa và linh hoạt."},{"en":"Designers must keep up with the current trends.","vi":"Nhà thiết kế phải theo kịp các xu hướng hiện nay."},{"en":"The current trend in education favors active learning.","vi":"Xu hướng hiện nay trong giáo dục ưu tiên học tập chủ động."}]', '[]', NULL, '/ˈkɜːrənt trend/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 20, 'currently available', 'hiện đang có sẵn', 'adv + adj', '[{"en":"Several scholarships are currently available to new students.","vi":"Một số học bổng hiện đang có sẵn cho sinh viên mới."},{"en":"The treatment is not currently available in this country.","vi":"Phương pháp điều trị này hiện chưa có sẵn ở nước này."},{"en":"Only limited data is currently available on the topic.","vi":"Chỉ có lượng dữ liệu hạn chế hiện đang có sẵn về chủ đề này."}]', '[]', NULL, '/ˈkɜːrəntli əˈveɪləbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 21, 'daily living', 'sinh hoạt hằng ngày', 'adj + n', '[{"en":"The illness affects many tasks of daily living.","vi":"Căn bệnh ảnh hưởng đến nhiều việc trong sinh hoạt hằng ngày."},{"en":"Technology has changed the patterns of daily living.","vi":"Công nghệ đã thay đổi các nếp sinh hoạt hằng ngày."},{"en":"Therapists help patients regain skills for daily living.","vi":"Chuyên viên trị liệu giúp bệnh nhân lấy lại kỹ năng sinh hoạt hằng ngày."}]', '[]', NULL, '/ˈdeɪli ˈlɪvɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 22, 'data gathering', 'việc thu thập dữ liệu', 'n + n', '[{"en":"Data gathering took several months before analysis began.","vi":"Việc thu thập dữ liệu mất vài tháng trước khi bắt đầu phân tích."},{"en":"Surveys are a common method of data gathering.","vi":"Khảo sát là một phương pháp phổ biến để thu thập dữ liệu."},{"en":"Careful data gathering ensures more reliable results.","vi":"Việc thu thập dữ liệu cẩn thận đảm bảo kết quả đáng tin cậy hơn."}]', '[]', NULL, '/ˈdeɪtə ˈɡæðərɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 23, 'data set', 'tập dữ liệu', 'n + n', '[{"en":"The researchers analyzed a large data set of responses.","vi":"Các nhà nghiên cứu phân tích một tập dữ liệu lớn gồm các phản hồi."},{"en":"This data set contains information from over a thousand patients.","vi":"Tập dữ liệu này chứa thông tin từ hơn một nghìn bệnh nhân."},{"en":"Cleaning the data set removed many incomplete records.","vi":"Việc làm sạch tập dữ liệu đã loại bỏ nhiều bản ghi không đầy đủ."}]', '[]', NULL, '/ˈdeɪtə set/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 24, 'deal with an issue', 'giải quyết một vấn đề', 'v + n', '[{"en":"The committee met to deal with an issue about funding.","vi":"Ủy ban họp để giải quyết một vấn đề về tài trợ."},{"en":"Managers must learn to deal with an issue calmly.","vi":"Nhà quản lý phải học cách giải quyết một vấn đề một cách bình tĩnh."},{"en":"The essay explains how to deal with an issue systematically.","vi":"Bài luận giải thích cách giải quyết một vấn đề một cách có hệ thống."}]', '[]', NULL, '/diːl wɪð ən ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 25, 'deem appropriate', 'cho là phù hợp', 'v + adj', '[{"en":"Teachers may use whatever methods they deem appropriate.","vi":"Giáo viên có thể dùng bất kỳ phương pháp nào họ cho là phù hợp."},{"en":"The committee will take action as it deems appropriate.","vi":"Ủy ban sẽ hành động theo cách mà họ cho là phù hợp."},{"en":"You may cite any sources you deem appropriate.","vi":"Bạn có thể trích dẫn bất kỳ nguồn nào bạn cho là phù hợp."}]', '[]', NULL, '/diːm əˈproʊpriət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 26, 'deem necessary', 'cho là cần thiết', 'v + adj', '[{"en":"The doctor will order any tests she deems necessary.","vi":"Bác sĩ sẽ chỉ định bất kỳ xét nghiệm nào cô cho là cần thiết."},{"en":"Staff may take steps they deem necessary for safety.","vi":"Nhân viên có thể thực hiện các bước họ cho là cần thiết vì an toàn."},{"en":"The board approved the spending it deemed necessary.","vi":"Hội đồng đã phê duyệt khoản chi mà họ cho là cần thiết."}]', '[]', NULL, '/diːm ˈnesəseri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 27, 'deep understanding of', 'sự hiểu biết sâu sắc về', 'adj + n', '[{"en":"The course gives a deep understanding of human behavior.","vi":"Khóa học mang lại sự hiểu biết sâu sắc về hành vi con người."},{"en":"She has a deep understanding of historical events.","vi":"Cô có một sự hiểu biết sâu sắc về các sự kiện lịch sử."},{"en":"Good teaching builds a deep understanding of core concepts.","vi":"Việc dạy tốt xây dựng sự hiểu biết sâu sắc về các khái niệm cốt lõi."}]', '[]', NULL, '/diːp ˌʌndərˈstændɪŋ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 28, 'deeper level', 'tầng sâu hơn', 'adj + n', '[{"en":"The novel works on a deeper level than it first appears.","vi":"Cuốn tiểu thuyết hoạt động ở một tầng sâu hơn so với vẻ ngoài."},{"en":"We need to analyze the problem at a deeper level.","vi":"Chúng ta cần phân tích vấn đề ở một tầng sâu hơn."},{"en":"On a deeper level, the poem questions human freedom.","vi":"Ở tầng sâu hơn, bài thơ chất vấn về tự do của con người."}]', '[]', NULL, '/ˈdiːpər ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 29, 'deeply embedded', 'ăn sâu, gắn chặt', 'adv + vpp', '[{"en":"These beliefs are deeply embedded in the local culture.","vi":"Những niềm tin này ăn sâu trong văn hóa địa phương."},{"en":"Corruption was deeply embedded in the old system.","vi":"Tham nhũng đã ăn sâu trong hệ thống cũ."},{"en":"Such habits become deeply embedded over many years.","vi":"Những thói quen như vậy trở nên ăn sâu qua nhiều năm."}]', '[]', NULL, '/ˈdiːpli ɪmˈbedɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 30, 'deeply rooted', 'bắt rễ sâu', 'adv + vpp', '[{"en":"Their traditions are deeply rooted in ancient history.","vi":"Truyền thống của họ bắt rễ sâu trong lịch sử cổ xưa."},{"en":"The conflict is deeply rooted in economic inequality.","vi":"Cuộc xung đột bắt rễ sâu trong bất bình đẳng kinh tế."},{"en":"Prejudice can be deeply rooted and hard to change.","vi":"Định kiến có thể bắt rễ sâu và khó thay đổi."}]', '[]', NULL, '/ˈdiːpli ˈruːtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 31, 'defining characteristic', 'đặc điểm nhận diện', 'adj + n', '[{"en":"Curiosity is a defining characteristic of good scientists.","vi":"Tính tò mò là đặc điểm nhận diện của những nhà khoa học giỏi."},{"en":"The defining characteristic of mammals is their fur.","vi":"Đặc điểm nhận diện của động vật có vú là bộ lông của chúng."},{"en":"Flexibility became the defining characteristic of the new design.","vi":"Tính linh hoạt trở thành đặc điểm nhận diện của thiết kế mới."}]', '[]', NULL, '/dɪˈfaɪnɪŋ ˌkærəktəˈrɪstɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 32, 'defining concept', 'khái niệm cốt lõi', 'adj + n', '[{"en":"Freedom is a defining concept in modern political thought.","vi":"Tự do là một khái niệm cốt lõi trong tư tưởng chính trị hiện đại."},{"en":"The lecture explained the defining concept of the theory.","vi":"Bài giảng giải thích khái niệm cốt lõi của lý thuyết."},{"en":"Sustainability has become a defining concept in design.","vi":"Tính bền vững đã trở thành một khái niệm cốt lõi trong thiết kế."}]', '[]', NULL, '/dɪˈfaɪnɪŋ ˈkɑːnsept/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 33, 'defining feature', 'đặc trưng nổi bật', 'adj + n', '[{"en":"Strong rhythm is a defining feature of this music.","vi":"Nhịp điệu mạnh mẽ là đặc trưng nổi bật của loại nhạc này."},{"en":"The defining feature of the building is its glass roof.","vi":"Đặc trưng nổi bật của tòa nhà là mái kính của nó."},{"en":"Openness is the defining feature of their company culture.","vi":"Sự cởi mở là đặc trưng nổi bật của văn hóa công ty họ."}]', '[]', NULL, '/dɪˈfaɪnɪŋ ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 34, 'deliberate attempt', 'nỗ lực có chủ đích', 'adj + n', '[{"en":"The policy was a deliberate attempt to reduce poverty.","vi":"Chính sách này là một nỗ lực có chủ đích nhằm giảm nghèo."},{"en":"His remarks seemed a deliberate attempt to provoke debate.","vi":"Những lời của anh có vẻ là nỗ lực có chủ đích để khơi mào tranh luận."},{"en":"The redesign was a deliberate attempt to improve safety.","vi":"Việc thiết kế lại là một nỗ lực có chủ đích để cải thiện an toàn."}]', '[]', NULL, '/dɪˈlɪbərət əˈtempt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 35, 'democratic institution', 'thiết chế dân chủ', 'adj + n', '[{"en":"Free elections are a key democratic institution.","vi":"Bầu cử tự do là một thiết chế dân chủ then chốt."},{"en":"Strong democratic institutions protect citizens'' rights.","vi":"Các thiết chế dân chủ vững mạnh bảo vệ quyền của công dân."},{"en":"The reforms aimed to strengthen democratic institutions.","vi":"Các cải cách nhằm củng cố các thiết chế dân chủ."}]', '[]', NULL, '/ˌdeməˈkrætɪk ˌɪnstɪˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 36, 'democratic process', 'tiến trình dân chủ', 'adj + n', '[{"en":"Voting is a fundamental part of the democratic process.","vi":"Bỏ phiếu là một phần cơ bản của tiến trình dân chủ."},{"en":"Citizens take part in the democratic process through elections.","vi":"Công dân tham gia tiến trình dân chủ thông qua bầu cử."},{"en":"A free press supports a healthy democratic process.","vi":"Báo chí tự do hỗ trợ một tiến trình dân chủ lành mạnh."}]', '[]', NULL, '/ˌdeməˈkrætɪk ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 37, 'democratic society', 'xã hội dân chủ', 'adj + n', '[{"en":"Free speech is essential in a democratic society.","vi":"Tự do ngôn luận là điều thiết yếu trong một xã hội dân chủ."},{"en":"A democratic society depends on informed and active citizens.","vi":"Một xã hội dân chủ phụ thuộc vào công dân hiểu biết và năng động."},{"en":"Education plays a vital role in any democratic society.","vi":"Giáo dục đóng vai trò sống còn trong bất kỳ xã hội dân chủ nào."}]', '[]', NULL, '/ˌdeməˈkrætɪk səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 38, 'democratic state', 'nhà nước dân chủ', 'adj + n', '[{"en":"A democratic state guarantees basic rights to its people.","vi":"Một nhà nước dân chủ bảo đảm các quyền cơ bản cho người dân."},{"en":"The country became a democratic state after the reforms.","vi":"Đất nước trở thành một nhà nước dân chủ sau các cuộc cải cách."},{"en":"In a democratic state, leaders are chosen by the people.","vi":"Trong một nhà nước dân chủ, lãnh đạo do người dân lựa chọn."}]', '[]', NULL, '/ˌdeməˈkrætɪk steɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 39, 'demographic change', 'thay đổi nhân khẩu học', 'adj + n', '[{"en":"Demographic change is reshaping the country''s labor market.","vi":"Thay đổi nhân khẩu học đang định hình lại thị trường lao động của đất nước."},{"en":"An aging population is a major demographic change.","vi":"Dân số già hóa là một thay đổi nhân khẩu học lớn."},{"en":"Planners must prepare for rapid demographic change.","vi":"Các nhà hoạch định phải chuẩn bị cho thay đổi nhân khẩu học nhanh chóng."}]', '[]', NULL, '/ˌdeməˈɡræfɪk tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 40, 'demographic characteristics', 'đặc điểm nhân khẩu học', 'adj + n', '[{"en":"The survey recorded the demographic characteristics of each respondent.","vi":"Cuộc khảo sát ghi lại đặc điểm nhân khẩu học của từng người trả lời."},{"en":"Demographic characteristics include age, gender, and income.","vi":"Đặc điểm nhân khẩu học bao gồm tuổi, giới tính và thu nhập."},{"en":"Marketers study demographic characteristics to target customers.","vi":"Người làm tiếp thị nghiên cứu đặc điểm nhân khẩu học để nhắm khách hàng."}]', '[]', NULL, '/ˌdeməˈɡræfɪk ˌkærəktəˈrɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 41, 'demographic factor', 'yếu tố nhân khẩu học', 'adj + n', '[{"en":"Age is an important demographic factor in voting behavior.","vi":"Tuổi tác là một yếu tố nhân khẩu học quan trọng trong hành vi bỏ phiếu."},{"en":"The study controlled for several demographic factors.","vi":"Nghiên cứu đã kiểm soát một số yếu tố nhân khẩu học."},{"en":"Income is a demographic factor linked to health outcomes.","vi":"Thu nhập là một yếu tố nhân khẩu học liên quan đến kết quả sức khỏe."}]', '[]', NULL, '/ˌdeməˈɡræfɪk ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 42, 'demonstrate competence', 'thể hiện năng lực', 'v + n', '[{"en":"Candidates must demonstrate competence in basic mathematics.","vi":"Ứng viên phải thể hiện năng lực trong toán học cơ bản."},{"en":"The exam allows students to demonstrate competence in writing.","vi":"Kỳ thi cho phép sinh viên thể hiện năng lực viết."},{"en":"New nurses demonstrate competence before working alone.","vi":"Y tá mới thể hiện năng lực trước khi làm việc độc lập."}]', '[]', NULL, '/ˈdemənstreɪt ˈkɑːmpətəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 43, 'densely populated', 'đông dân cư', 'adv + vpp', '[{"en":"The city is one of the most densely populated in the world.","vi":"Thành phố này là một trong những nơi đông dân cư nhất thế giới."},{"en":"Densely populated areas often struggle with housing shortages.","vi":"Các khu vực đông dân cư thường gặp khó khăn với việc thiếu nhà ở."},{"en":"Disease spreads faster in densely populated regions.","vi":"Dịch bệnh lây lan nhanh hơn ở các vùng đông dân cư."}]', '[]', NULL, '/ˈdensli ˈpɑːpjuleɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 44, 'deny access to', 'từ chối quyền tiếp cận', 'v + n', '[{"en":"The system can deny access to unauthorized users.","vi":"Hệ thống có thể từ chối quyền tiếp cận với người dùng trái phép."},{"en":"Officials cannot deny access to public records without cause.","vi":"Quan chức không thể từ chối quyền tiếp cận hồ sơ công nếu không có lý do."},{"en":"The policy may deny access to certain restricted areas.","vi":"Chính sách có thể từ chối quyền tiếp cận vào một số khu vực hạn chế."}]', '[]', NULL, '/dɪˈnaɪ ˈækses tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 45, 'dependent variable', 'biến phụ thuộc', 'adj + n', '[{"en":"In this experiment, reaction time is the dependent variable.","vi":"Trong thí nghiệm này, thời gian phản ứng là biến phụ thuộc."},{"en":"Researchers measure the dependent variable after each trial.","vi":"Các nhà nghiên cứu đo biến phụ thuộc sau mỗi lần thử."},{"en":"The dependent variable changes as the input is adjusted.","vi":"Biến phụ thuộc thay đổi khi đầu vào được điều chỉnh."}]', '[]', NULL, '/dɪˈpendənt ˈveriəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 46, 'describe a method', 'mô tả một phương pháp', 'v + n', '[{"en":"The paper describes a method for measuring air quality.","vi":"Bài báo mô tả một phương pháp để đo chất lượng không khí."},{"en":"Please describe a method you used to collect the data.","vi":"Hãy mô tả một phương pháp bạn đã dùng để thu thập dữ liệu."},{"en":"The chapter describes a method for training new staff.","vi":"Chương này mô tả một phương pháp để đào tạo nhân viên mới."}]', '[]', NULL, '/dɪˈskraɪb ə ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 47, 'describe a process', 'mô tả một quá trình', 'v + n', '[{"en":"The diagram helps describe a process step by step.","vi":"Sơ đồ giúp mô tả một quá trình theo từng bước."},{"en":"Students learn to describe a process clearly in writing.","vi":"Sinh viên học cách mô tả một quá trình rõ ràng bằng văn bản."},{"en":"The video describes a process for recycling plastic.","vi":"Video mô tả một quá trình tái chế nhựa."}]', '[]', NULL, '/dɪˈskraɪb ə ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 48, 'describe a procedure', 'mô tả một quy trình', 'v + n', '[{"en":"The manual describes a procedure for installing the software safely.","vi":"Sách hướng dẫn mô tả quy trình cài đặt phần mềm một cách an toàn."},{"en":"She clearly describes a procedure that any nurse can follow.","vi":"Cô ấy mô tả rõ ràng một quy trình mà bất kỳ y tá nào cũng làm theo được."},{"en":"The paper describes a procedure used to collect the samples.","vi":"Bài báo mô tả quy trình được dùng để thu thập mẫu."}]', '[]', NULL, '/dɪˈskraɪb ə prəˈsiːdʒər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 49, 'descriptive statistics', 'thống kê mô tả', 'adj + n', '[{"en":"We used descriptive statistics to summarize the survey results.","vi":"Chúng tôi dùng thống kê mô tả để tóm tắt kết quả khảo sát."},{"en":"Descriptive statistics show the average score for each group.","vi":"Thống kê mô tả cho thấy điểm trung bình của từng nhóm."},{"en":"The report begins with descriptive statistics before deeper analysis.","vi":"Báo cáo bắt đầu bằng thống kê mô tả trước khi phân tích sâu hơn."}]', '[]', NULL, '/dɪˈskrɪptɪv stəˈtɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 50, 'desired outcome', 'kết quả mong muốn', 'adj + n', '[{"en":"The new policy did not produce the desired outcome.","vi":"Chính sách mới đã không tạo ra kết quả mong muốn."},{"en":"Careful planning helps you reach the desired outcome faster.","vi":"Lập kế hoạch kỹ giúp bạn đạt kết quả mong muốn nhanh hơn."},{"en":"Teachers adjust their methods to achieve the desired outcome.","vi":"Giáo viên điều chỉnh phương pháp để đạt được kết quả mong muốn."}]', '[]', NULL, '/dɪˈzaɪərd ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 51, 'detailed analysis', 'phân tích chi tiết', 'adj + n', '[{"en":"The thesis provides a detailed analysis of consumer behavior.","vi":"Luận văn đưa ra phân tích chi tiết về hành vi người tiêu dùng."},{"en":"A detailed analysis revealed several errors in the data.","vi":"Phân tích chi tiết đã phát hiện nhiều lỗi trong dữ liệu."},{"en":"Investors expect a detailed analysis before making decisions.","vi":"Nhà đầu tư cần phân tích chi tiết trước khi ra quyết định."}]', '[]', NULL, '/ˈdiːteɪld əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 52, 'detailed examination', 'sự khảo sát chi tiết', 'adj + n', '[{"en":"The book offers a detailed examination of ancient trade routes.","vi":"Cuốn sách khảo sát chi tiết các tuyến đường thương mại cổ đại."},{"en":"A detailed examination of the evidence supports her claim.","vi":"Việc khảo sát chi tiết bằng chứng ủng hộ lập luận của cô ấy."},{"en":"The doctor recommended a detailed examination of the samples.","vi":"Bác sĩ đề nghị khảo sát chi tiết các mẫu."}]', '[]', NULL, '/ˈdiːteɪld ɪɡˌzæməˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 53, 'detailed information', 'thông tin chi tiết', 'adj + n', '[{"en":"The website provides detailed information about each course.","vi":"Trang web cung cấp thông tin chi tiết về từng khóa học."},{"en":"Please send detailed information about the conference schedule.","vi":"Vui lòng gửi thông tin chi tiết về lịch hội nghị."},{"en":"Detailed information on the labels helps shoppers choose wisely.","vi":"Thông tin chi tiết trên nhãn giúp người mua chọn lựa khôn ngoan."}]', '[]', NULL, '/ˈdiːteɪld ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 54, 'detailed study', 'nghiên cứu chi tiết', 'adj + n', '[{"en":"They conducted a detailed study of local water quality.","vi":"Họ tiến hành một nghiên cứu chi tiết về chất lượng nước địa phương."},{"en":"A detailed study of the region took several years.","vi":"Một nghiên cứu chi tiết về khu vực này mất vài năm."},{"en":"The detailed study confirmed earlier findings about migration.","vi":"Nghiên cứu chi tiết đã xác nhận các phát hiện trước về di cư."}]', '[]', NULL, '/ˈdiːteɪld ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 55, 'develop a method', 'phát triển một phương pháp', 'v + n', '[{"en":"Researchers worked together to develop a method for testing.","vi":"Các nhà nghiên cứu hợp tác để phát triển một phương pháp kiểm tra."},{"en":"The team hopes to develop a method that saves time.","vi":"Nhóm hy vọng phát triển một phương pháp tiết kiệm thời gian."},{"en":"Scientists develop a method before running large experiments.","vi":"Các nhà khoa học phát triển một phương pháp trước khi làm thí nghiệm lớn."}]', '[]', NULL, '/dɪˈveləp ə ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 56, 'develop a strategy', 'xây dựng một chiến lược', 'v + n', '[{"en":"The company needs to develop a strategy for new markets.","vi":"Công ty cần xây dựng một chiến lược cho các thị trường mới."},{"en":"Students learn to develop a strategy before starting an essay.","vi":"Sinh viên học cách xây dựng một chiến lược trước khi viết tiểu luận."},{"en":"Managers develop a strategy to reduce costs each year.","vi":"Các quản lý xây dựng một chiến lược cắt giảm chi phí mỗi năm."}]', '[]', NULL, '/dɪˈveləp ə ˈstrætədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 57, 'develop a technique', 'phát triển một kỹ thuật', 'v + n', '[{"en":"The lab worked hard to develop a technique for imaging cells.","vi":"Phòng thí nghiệm nỗ lực phát triển một kỹ thuật chụp ảnh tế bào."},{"en":"Artists often develop a technique that becomes their signature.","vi":"Nghệ sĩ thường phát triển một kỹ thuật trở thành dấu ấn riêng."},{"en":"They aim to develop a technique cheaper than current ones.","vi":"Họ muốn phát triển một kỹ thuật rẻ hơn các kỹ thuật hiện có."}]', '[]', NULL, '/dɪˈveləp ə tekˈniːk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 58, 'develop a theory', 'xây dựng một lý thuyết', 'v + n', '[{"en":"Darwin spent years working to develop a theory of evolution.","vi":"Darwin mất nhiều năm để xây dựng một lý thuyết về tiến hóa."},{"en":"Economists develop a theory to explain how prices change.","vi":"Các nhà kinh tế xây dựng một lý thuyết giải thích giá cả thay đổi."},{"en":"She used the data to develop a theory about learning.","vi":"Cô ấy dùng dữ liệu để xây dựng một lý thuyết về việc học."}]', '[]', NULL, '/dɪˈveləp ə ˈθiːəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 59, 'develop an approach', 'phát triển một cách tiếp cận', 'v + n', '[{"en":"The school tried to develop an approach suited to young learners.","vi":"Trường cố gắng phát triển một cách tiếp cận phù hợp với học sinh nhỏ."},{"en":"We must develop an approach that respects local traditions.","vi":"Chúng ta phải phát triển một cách tiếp cận tôn trọng truyền thống địa phương."},{"en":"Therapists develop an approach tailored to each patient.","vi":"Nhà trị liệu phát triển một cách tiếp cận riêng cho từng bệnh nhân."}]', '[]', NULL, '/dɪˈveləp ən əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 60, 'develop an argument', 'triển khai một lập luận', 'v + n', '[{"en":"A good essay should develop an argument step by step.","vi":"Một bài luận hay nên triển khai một lập luận theo từng bước."},{"en":"She uses evidence to develop an argument for reform.","vi":"Cô ấy dùng bằng chứng để triển khai một lập luận cho cải cách."},{"en":"Lawyers develop an argument carefully before going to court.","vi":"Luật sư triển khai một lập luận cẩn thận trước khi ra tòa."}]', '[]', NULL, '/dɪˈveləp ən ˈɑːrɡjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 61, 'developmental process', 'quá trình phát triển', 'adj + n', '[{"en":"Language learning is a slow developmental process in children.","vi":"Việc học ngôn ngữ là một quá trình phát triển chậm ở trẻ em."},{"en":"The book explains each step of the developmental process.","vi":"Cuốn sách giải thích từng bước của quá trình phát triển."},{"en":"Stress can interrupt the normal developmental process of cells.","vi":"Căng thẳng có thể làm gián đoạn quá trình phát triển bình thường của tế bào."}]', '[]', NULL, '/dɪˌveləpˈmentəl ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 62, 'developmental stage', 'giai đoạn phát triển', 'adj + n', '[{"en":"Each developmental stage brings new skills for the child.","vi":"Mỗi giai đoạn phát triển mang lại những kỹ năng mới cho trẻ."},{"en":"The plant reaches a developmental stage where it flowers.","vi":"Cây đạt tới giai đoạn phát triển mà nó nở hoa."},{"en":"Teachers adapt lessons to the pupil''s developmental stage.","vi":"Giáo viên điều chỉnh bài học theo giai đoạn phát triển của học sinh."}]', '[]', NULL, '/dɪˌveləpˈmentəl steɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 63, 'diagnostic test', 'bài kiểm tra chẩn đoán', 'adj + n', '[{"en":"The doctor ordered a diagnostic test to confirm the illness.","vi":"Bác sĩ chỉ định một bài kiểm tra chẩn đoán để xác nhận bệnh."},{"en":"Students take a diagnostic test at the start of the course.","vi":"Sinh viên làm một bài kiểm tra chẩn đoán đầu khóa học."},{"en":"A simple diagnostic test can detect the problem early.","vi":"Một bài kiểm tra chẩn đoán đơn giản có thể phát hiện sớm vấn đề."}]', '[]', NULL, '/ˌdaɪəɡˈnɑːstɪk test/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 64, 'differ considerably', 'khác nhau đáng kể', 'v + adv', '[{"en":"Prices differ considerably between the two cities.","vi":"Giá cả khác nhau đáng kể giữa hai thành phố."},{"en":"Opinions on the matter differ considerably among experts.","vi":"Quan điểm về vấn đề này khác nhau đáng kể giữa các chuyên gia."},{"en":"The results differ considerably from those of earlier studies.","vi":"Kết quả khác nhau đáng kể so với các nghiên cứu trước."}]', '[]', NULL, '/ˈdɪfər kənˈsɪdərəbli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 65, 'differ significantly', 'khác nhau rõ rệt', 'v + adv', '[{"en":"The two groups differ significantly in their test scores.","vi":"Hai nhóm khác nhau rõ rệt về điểm kiểm tra."},{"en":"Climate patterns differ significantly from region to region.","vi":"Kiểu khí hậu khác nhau rõ rệt giữa các vùng."},{"en":"Male and female responses did not differ significantly.","vi":"Phản hồi của nam và nữ không khác nhau rõ rệt."}]', '[]', NULL, '/ˈdɪfər sɪɡˈnɪfɪkəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 66, 'differ widely', 'khác nhau rất nhiều', 'v + adv', '[{"en":"Customs differ widely from one country to another.","vi":"Phong tục khác nhau rất nhiều giữa các quốc gia."},{"en":"Estimates of the cost differ widely among analysts.","vi":"Các ước tính về chi phí khác nhau rất nhiều giữa các nhà phân tích."},{"en":"Teaching styles differ widely across the schools surveyed.","vi":"Phong cách giảng dạy khác nhau rất nhiều giữa các trường được khảo sát."}]', '[]', NULL, '/ˈdɪfər ˈwaɪdli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 67, 'digital information', 'thông tin số', 'adj + n', '[{"en":"Libraries now store vast amounts of digital information.","vi":"Các thư viện hiện lưu trữ lượng lớn thông tin số."},{"en":"Protecting digital information is a key concern for companies.","vi":"Bảo vệ thông tin số là mối quan tâm chính của các công ty."},{"en":"Digital information can be shared across the world instantly.","vi":"Thông tin số có thể được chia sẻ khắp thế giới ngay lập tức."}]', '[]', NULL, '/ˈdɪdʒətəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 68, 'digital media', 'phương tiện truyền thông số', 'adj + n', '[{"en":"Young people spend many hours using digital media daily.","vi":"Người trẻ dành nhiều giờ mỗi ngày để dùng truyền thông số."},{"en":"Digital media have changed how news reaches the public.","vi":"Truyền thông số đã thay đổi cách tin tức đến với công chúng."},{"en":"The course explores the impact of digital media on society.","vi":"Khóa học tìm hiểu tác động của truyền thông số lên xã hội."}]', '[]', NULL, '/ˈdɪdʒətəl ˈmiːdiə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 69, 'digital technology', 'công nghệ số', 'adj + n', '[{"en":"Digital technology has transformed the way we communicate.","vi":"Công nghệ số đã thay đổi cách chúng ta giao tiếp."},{"en":"Schools invest in digital technology to support learning.","vi":"Các trường đầu tư vào công nghệ số để hỗ trợ việc học."},{"en":"Many jobs now require basic digital technology skills.","vi":"Nhiều công việc hiện đòi hỏi kỹ năng công nghệ số cơ bản."}]', '[]', NULL, '/ˈdɪdʒətəl tekˈnɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 70, 'direct access', 'quyền truy cập trực tiếp', 'adj + n', '[{"en":"Members enjoy direct access to the research database.","vi":"Thành viên được quyền truy cập trực tiếp vào cơ sở dữ liệu nghiên cứu."},{"en":"The app gives users direct access to their account details.","vi":"Ứng dụng cho người dùng truy cập trực tiếp thông tin tài khoản."},{"en":"Patients now have direct access to their medical records.","vi":"Bệnh nhân giờ có quyền truy cập trực tiếp hồ sơ y tế của mình."}]', '[]', NULL, '/dɪˈrekt ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 71, 'direct communication', 'giao tiếp trực tiếp', 'adj + n', '[{"en":"Direct communication between teams prevents misunderstandings.","vi":"Giao tiếp trực tiếp giữa các nhóm ngăn ngừa hiểu lầm."},{"en":"The manager values direct communication with her staff.","vi":"Người quản lý coi trọng giao tiếp trực tiếp với nhân viên."},{"en":"Direct communication is often faster than long email chains.","vi":"Giao tiếp trực tiếp thường nhanh hơn những chuỗi email dài."}]', '[]', NULL, '/dɪˈrekt kəˌmjuːnɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 72, 'direct consequences', 'hậu quả trực tiếp', 'adj + n', '[{"en":"Pollution has direct consequences for public health.","vi":"Ô nhiễm có những hậu quả trực tiếp đối với sức khỏe cộng đồng."},{"en":"The policy had direct consequences for small businesses.","vi":"Chính sách đó đã gây hậu quả trực tiếp cho các doanh nghiệp nhỏ."},{"en":"Cutting funding had direct consequences for the program.","vi":"Việc cắt kinh phí gây hậu quả trực tiếp cho chương trình."}]', '[]', NULL, '/dɪˈrekt ˈkɑːnsəkwensəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 73, 'direct contact', 'tiếp xúc trực tiếp', 'adj + n', '[{"en":"The disease spreads through direct contact with the skin.","vi":"Bệnh lây lan qua tiếp xúc trực tiếp với da."},{"en":"Sales staff keep direct contact with their main clients.","vi":"Nhân viên bán hàng giữ tiếp xúc trực tiếp với khách hàng chính."},{"en":"Avoid direct contact between the chemical and your eyes.","vi":"Tránh để hóa chất tiếp xúc trực tiếp với mắt bạn."}]', '[]', NULL, '/dɪˈrekt ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 74, 'direct evidence', 'bằng chứng trực tiếp', 'adj + n', '[{"en":"There is direct evidence linking smoking to lung cancer.","vi":"Có bằng chứng trực tiếp liên hệ hút thuốc với ung thư phổi."},{"en":"The study found direct evidence of climate change effects.","vi":"Nghiên cứu tìm thấy bằng chứng trực tiếp về tác động biến đổi khí hậu."},{"en":"Without direct evidence, the theory remains unproven.","vi":"Nếu thiếu bằng chứng trực tiếp, lý thuyết vẫn chưa được chứng minh."}]', '[]', NULL, '/dɪˈrekt ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 75, 'direct impact', 'tác động trực tiếp', 'adj + n', '[{"en":"The new tax had a direct impact on household spending.","vi":"Thuế mới có tác động trực tiếp đến chi tiêu hộ gia đình."},{"en":"Sleep has a direct impact on a student''s performance.","vi":"Giấc ngủ có tác động trực tiếp đến kết quả của học sinh."},{"en":"The drought had a direct impact on local farmers.","vi":"Hạn hán có tác động trực tiếp đến nông dân địa phương."}]', '[]', NULL, '/dɪˈrekt ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 76, 'direct involvement', 'sự tham gia trực tiếp', 'adj + n', '[{"en":"The project succeeded thanks to direct involvement from staff.","vi":"Dự án thành công nhờ sự tham gia trực tiếp của nhân viên."},{"en":"Her direct involvement made the campaign far more effective.","vi":"Sự tham gia trực tiếp của cô ấy khiến chiến dịch hiệu quả hơn nhiều."},{"en":"The report questions the company''s direct involvement in the deal.","vi":"Báo cáo đặt nghi vấn về sự tham gia trực tiếp của công ty vào thương vụ."}]', '[]', NULL, '/dɪˈrekt ɪnˈvɑːlvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 77, 'direct link', 'mối liên hệ trực tiếp', 'adj + n', '[{"en":"Scientists found a direct link between diet and heart disease.","vi":"Các nhà khoa học tìm thấy mối liên hệ trực tiếp giữa ăn uống và bệnh tim."},{"en":"There is a direct link between exercise and better mood.","vi":"Có mối liên hệ trực tiếp giữa tập thể dục và tâm trạng tốt hơn."},{"en":"The data show a direct link between income and education.","vi":"Dữ liệu cho thấy mối liên hệ trực tiếp giữa thu nhập và học vấn."}]', '[]', NULL, '/dɪˈrekt lɪŋk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 78, 'direct observation', 'quan sát trực tiếp', 'adj + n', '[{"en":"The findings are based on direct observation of animal behavior.","vi":"Các phát hiện dựa trên quan sát trực tiếp hành vi động vật."},{"en":"Direct observation gives richer data than surveys alone.","vi":"Quan sát trực tiếp cho dữ liệu phong phú hơn so với chỉ khảo sát."},{"en":"Through direct observation, she recorded how children played.","vi":"Qua quan sát trực tiếp, cô ấy ghi lại cách trẻ em chơi."}]', '[]', NULL, '/dɪˈrekt ˌɑːbzərˈveɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 79, 'direct relationship', 'mối quan hệ trực tiếp', 'adj + n', '[{"en":"There is a direct relationship between price and demand.","vi":"Có mối quan hệ trực tiếp giữa giá cả và nhu cầu."},{"en":"The graph shows a direct relationship between the variables.","vi":"Biểu đồ cho thấy mối quan hệ trực tiếp giữa các biến số."},{"en":"Researchers noted a direct relationship between stress and sleep.","vi":"Các nhà nghiên cứu ghi nhận mối quan hệ trực tiếp giữa căng thẳng và giấc ngủ."}]', '[]', NULL, '/dɪˈrekt rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 80, 'direct role', 'vai trò trực tiếp', 'adj + n', '[{"en":"She played a direct role in shaping the new policy.","vi":"Cô ấy đóng vai trò trực tiếp trong việc định hình chính sách mới."},{"en":"Sunlight plays a direct role in plant growth.","vi":"Ánh nắng đóng vai trò trực tiếp trong sự phát triển của cây."},{"en":"The committee has a direct role in approving the budget.","vi":"Ủy ban có vai trò trực tiếp trong việc phê duyệt ngân sách."}]', '[]', NULL, '/dɪˈrekt roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 81, 'directly affect', 'ảnh hưởng trực tiếp', 'adv + v', '[{"en":"Interest rates directly affect the cost of borrowing money.","vi":"Lãi suất ảnh hưởng trực tiếp đến chi phí vay tiền."},{"en":"Diet and sleep directly affect how well students learn.","vi":"Ăn uống và giấc ngủ ảnh hưởng trực tiếp đến việc học của học sinh."},{"en":"Weather conditions directly affect crop yields each season.","vi":"Điều kiện thời tiết ảnh hưởng trực tiếp đến năng suất mùa màng."}]', '[]', NULL, '/dɪˈrektli əˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 82, 'directly affected', 'bị ảnh hưởng trực tiếp', 'adv + vpp', '[{"en":"Coastal towns were directly affected by the rising sea levels.","vi":"Các thị trấn ven biển bị ảnh hưởng trực tiếp bởi mực nước biển dâng."},{"en":"Workers directly affected by the closure received support.","vi":"Những công nhân bị ảnh hưởng trực tiếp bởi việc đóng cửa đã được hỗ trợ."},{"en":"Families directly affected by the flood need urgent help.","vi":"Các gia đình bị ảnh hưởng trực tiếp bởi lũ lụt cần giúp đỡ khẩn cấp."}]', '[]', NULL, '/dɪˈrektli əˈfektɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 83, 'directly connected to', 'kết nối trực tiếp với', 'adv + vpp', '[{"en":"The printer is directly connected to the main computer.","vi":"Máy in được kết nối trực tiếp với máy tính chính."},{"en":"Air quality is directly connected to public health outcomes.","vi":"Chất lượng không khí kết nối trực tiếp với sức khỏe cộng đồng."},{"en":"These two ideas are directly connected to each other.","vi":"Hai ý tưởng này kết nối trực tiếp với nhau."}]', '[]', NULL, '/dɪˈrektli kəˈnektɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 84, 'directly involved in', 'trực tiếp tham gia vào', 'adv + vpp', '[{"en":"She was directly involved in planning the conference.","vi":"Cô ấy trực tiếp tham gia vào việc lên kế hoạch hội nghị."},{"en":"Students directly involved in the project learned the most.","vi":"Những sinh viên trực tiếp tham gia vào dự án học được nhiều nhất."},{"en":"He was directly involved in the negotiations last year.","vi":"Ông ấy trực tiếp tham gia vào các cuộc đàm phán năm ngoái."}]', '[]', NULL, '/dɪˈrektli ɪnˈvɑːlvd ɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 85, 'directly linked to', 'liên hệ trực tiếp với', 'adv + vpp', '[{"en":"Poor diet is directly linked to many chronic diseases.","vi":"Ăn uống kém liên hệ trực tiếp với nhiều bệnh mãn tính."},{"en":"The rise in sales is directly linked to the advertising.","vi":"Doanh số tăng liên hệ trực tiếp với việc quảng cáo."},{"en":"Their success is directly linked to careful planning.","vi":"Thành công của họ liên hệ trực tiếp với việc lập kế hoạch kỹ lưỡng."}]', '[]', NULL, '/dɪˈrektli lɪŋkt tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 86, 'directly proportional to', 'tỷ lệ thuận trực tiếp với', 'adv + adj', '[{"en":"The force is directly proportional to the mass of the object.","vi":"Lực tỷ lệ thuận trực tiếp với khối lượng của vật."},{"en":"Pressure is directly proportional to temperature in this case.","vi":"Áp suất tỷ lệ thuận trực tiếp với nhiệt độ trong trường hợp này."},{"en":"Profit was directly proportional to the number of sales.","vi":"Lợi nhuận tỷ lệ thuận trực tiếp với số lượng bán ra."}]', '[]', NULL, '/dɪˈrektli prəˈpɔːrʃənəl tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 87, 'directly related to', 'liên quan trực tiếp đến', 'adv + vpp', '[{"en":"His complaint was directly related to the new schedule.","vi":"Khiếu nại của anh ấy liên quan trực tiếp đến lịch trình mới."},{"en":"The questions are directly related to the course content.","vi":"Các câu hỏi liên quan trực tiếp đến nội dung khóa học."},{"en":"Health problems here are directly related to air pollution.","vi":"Các vấn đề sức khỏe ở đây liên quan trực tiếp đến ô nhiễm không khí."}]', '[]', NULL, '/dɪˈrektli rɪˈleɪtɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 88, 'directly relevant to', 'liên quan thiết thực đến', 'adv + adj', '[{"en":"These findings are directly relevant to current policy debates.","vi":"Những phát hiện này liên quan thiết thực đến các tranh luận chính sách hiện nay."},{"en":"Choose examples that are directly relevant to your topic.","vi":"Hãy chọn ví dụ liên quan thiết thực đến chủ đề của bạn."},{"en":"The training was directly relevant to her daily work.","vi":"Khóa đào tạo liên quan thiết thực đến công việc hằng ngày của cô ấy."}]', '[]', NULL, '/dɪˈrektli ˈreləvənt tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 89, 'directly responsible for', 'chịu trách nhiệm trực tiếp về', 'adv + adj', '[{"en":"The manager is directly responsible for the team''s budget.","vi":"Người quản lý chịu trách nhiệm trực tiếp về ngân sách của nhóm."},{"en":"Smoking is directly responsible for many early deaths.","vi":"Hút thuốc chịu trách nhiệm trực tiếp cho nhiều ca tử vong sớm."},{"en":"She is directly responsible for training new employees.","vi":"Cô ấy chịu trách nhiệm trực tiếp về việc đào tạo nhân viên mới."}]', '[]', NULL, '/dɪˈrektli rɪˈspɑːnsəbəl fər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 90, 'disclose information', 'tiết lộ thông tin', 'v + n', '[{"en":"Companies must disclose information about their finances.","vi":"Các công ty phải tiết lộ thông tin về tài chính của mình."},{"en":"Doctors cannot disclose information without the patient''s consent.","vi":"Bác sĩ không thể tiết lộ thông tin khi chưa có sự đồng ý của bệnh nhân."},{"en":"The report refused to disclose information about its sources.","vi":"Báo cáo từ chối tiết lộ thông tin về nguồn của nó."}]', '[]', NULL, '/dɪsˈkloʊz ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 91, 'discuss a topic', 'thảo luận một chủ đề', 'v + n', '[{"en":"The class will discuss a topic chosen by the students.","vi":"Lớp học sẽ thảo luận một chủ đề do sinh viên chọn."},{"en":"We meet weekly to discuss a topic from the reading.","vi":"Chúng tôi gặp nhau hằng tuần để thảo luận một chủ đề trong bài đọc."},{"en":"It is hard to discuss a topic without enough background.","vi":"Thật khó để thảo luận một chủ đề khi thiếu kiến thức nền."}]', '[]', NULL, '/dɪˈskʌs ə ˈtɑːpɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 92, 'discuss an issue', 'thảo luận một vấn đề', 'v + n', '[{"en":"The committee met to discuss an issue raised by parents.","vi":"Ủy ban họp để thảo luận một vấn đề do phụ huynh nêu ra."},{"en":"It helps to discuss an issue calmly before deciding.","vi":"Thảo luận một vấn đề một cách bình tĩnh trước khi quyết định sẽ hữu ích."},{"en":"Leaders gathered to discuss an issue affecting the whole region.","vi":"Các lãnh đạo tụ họp để thảo luận một vấn đề ảnh hưởng cả khu vực."}]', '[]', NULL, '/dɪˈskʌs ən ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 93, 'disposable income', 'thu nhập khả dụng', 'adj + n', '[{"en":"Families with higher disposable income tend to travel more.","vi":"Các gia đình có thu nhập khả dụng cao hơn thường đi du lịch nhiều hơn."},{"en":"Rising prices have reduced people''s disposable income.","vi":"Giá cả tăng đã làm giảm thu nhập khả dụng của người dân."},{"en":"Young workers often spend much of their disposable income.","vi":"Người lao động trẻ thường tiêu phần lớn thu nhập khả dụng của họ."}]', '[]', NULL, '/dɪˈspoʊzəbəl ˈɪnkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 94, 'distinct group', 'nhóm riêng biệt', 'adj + n', '[{"en":"The study divided the patients into three distinct groups.","vi":"Nghiên cứu chia bệnh nhân thành ba nhóm riêng biệt."},{"en":"Each distinct group followed its own set of rules.","vi":"Mỗi nhóm riêng biệt tuân theo bộ quy tắc riêng của mình."},{"en":"The data revealed a distinct group of frequent users.","vi":"Dữ liệu cho thấy một nhóm riêng biệt gồm người dùng thường xuyên."}]', '[]', NULL, '/dɪˈstɪŋkt ɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 95, 'distinct type', 'loại riêng biệt', 'adj + n', '[{"en":"Researchers identified two distinct types of cells.","vi":"Các nhà nghiên cứu xác định được hai loại tế bào riêng biệt."},{"en":"Each distinct type of soil supports different plants.","vi":"Mỗi loại đất riêng biệt thích hợp với những cây khác nhau."},{"en":"The museum displays a distinct type of ancient pottery.","vi":"Bảo tàng trưng bày một loại gốm cổ riêng biệt."}]', '[]', NULL, '/dɪˈstɪŋkt taɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 96, 'distinctive feature', 'đặc điểm nổi bật', 'adj + n', '[{"en":"The bright colors are a distinctive feature of this bird.","vi":"Màu sắc sặc sỡ là đặc điểm nổi bật của loài chim này."},{"en":"Strong arches are a distinctive feature of the architecture.","vi":"Các vòm lớn là đặc điểm nổi bật của lối kiến trúc này."},{"en":"Her clear writing style is a distinctive feature of her work.","vi":"Lối viết rõ ràng là đặc điểm nổi bật trong tác phẩm của cô ấy."}]', '[]', NULL, '/dɪˈstɪŋktɪv ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 97, 'distinguishing feature', 'đặc điểm phân biệt', 'adj + n', '[{"en":"The long tail is the distinguishing feature of this species.","vi":"Cái đuôi dài là đặc điểm phân biệt của loài này."},{"en":"Price is the main distinguishing feature between the two models.","vi":"Giá cả là đặc điểm phân biệt chính giữa hai mẫu xe."},{"en":"A distinguishing feature of the report is its clear charts.","vi":"Một đặc điểm phân biệt của báo cáo là các biểu đồ rõ ràng."}]', '[]', NULL, '/dɪˈstɪŋɡwɪʃɪŋ ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 98, 'diverse background', 'xuất thân đa dạng', 'adj + n', '[{"en":"The students come from a diverse background of cultures.","vi":"Các sinh viên đến từ nhiều nền văn hóa với xuất thân đa dạng."},{"en":"Her diverse background helps her understand many viewpoints.","vi":"Xuất thân đa dạng giúp cô ấy hiểu nhiều quan điểm khác nhau."},{"en":"Employers value staff with a diverse background and skills.","vi":"Nhà tuyển dụng coi trọng nhân viên có xuất thân và kỹ năng đa dạng."}]', '[]', NULL, '/dɪˈvɜːrs ˈbækɡraʊnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 99, 'diverse group', 'nhóm đa dạng', 'adj + n', '[{"en":"The class is a diverse group of learners from many countries.","vi":"Lớp học là một nhóm đa dạng gồm người học từ nhiều quốc gia."},{"en":"A diverse group often produces more creative ideas.","vi":"Một nhóm đa dạng thường tạo ra nhiều ý tưởng sáng tạo hơn."},{"en":"The panel included a diverse group of experts and citizens.","vi":"Hội đồng gồm một nhóm đa dạng các chuyên gia và người dân."}]', '[]', NULL, '/dɪˈvɜːrs ɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 100, 'diverse range of', 'loạt đa dạng các', 'adj + n', '[{"en":"The shop sells a diverse range of organic products.","vi":"Cửa hàng bán một loạt đa dạng các sản phẩm hữu cơ."},{"en":"The course covers a diverse range of historical topics.","vi":"Khóa học bao quát một loạt đa dạng các chủ đề lịch sử."},{"en":"Volunteers came from a diverse range of professions.","vi":"Các tình nguyện viên đến từ một loạt đa dạng các nghề nghiệp."}]', '[]', NULL, '/dɪˈvɜːrs reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 101, 'dividing line', 'ranh giới phân chia', 'adj + n', '[{"en":"The river forms a natural dividing line between the regions.","vi":"Con sông tạo thành ranh giới phân chia tự nhiên giữa các vùng."},{"en":"There is a thin dividing line between humor and rudeness.","vi":"Có một ranh giới phân chia mong manh giữa hài hước và thô lỗ."},{"en":"Age is not a clear dividing line for these opinions.","vi":"Tuổi tác không phải ranh giới phân chia rõ ràng cho những quan điểm này."}]', '[]', NULL, '/dɪˈvaɪdɪŋ laɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 102, 'documentary evidence', 'bằng chứng tài liệu', 'adj + n', '[{"en":"The historian relied on documentary evidence from old letters.","vi":"Nhà sử học dựa vào bằng chứng tài liệu từ những lá thư cũ."},{"en":"Documentary evidence supported the claims made in court.","vi":"Bằng chứng tài liệu ủng hộ các tuyên bố đưa ra tại tòa."},{"en":"Without documentary evidence, the story is hard to verify.","vi":"Nếu thiếu bằng chứng tài liệu, câu chuyện rất khó kiểm chứng."}]', '[]', NULL, '/ˌdɑːkjəˈmentəri ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 103, 'domestic market', 'thị trường nội địa', 'adj + n', '[{"en":"The company focuses mainly on the domestic market.","vi":"Công ty tập trung chủ yếu vào thị trường nội địa."},{"en":"Cheap imports have hurt the domestic market for textiles.","vi":"Hàng nhập rẻ đã gây tổn hại cho thị trường dệt may nội địa."},{"en":"Strong demand in the domestic market boosted local jobs.","vi":"Nhu cầu mạnh ở thị trường nội địa thúc đẩy việc làm địa phương."}]', '[]', NULL, '/dəˈmestɪk ˈmɑːrkɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 104, 'domestic sphere', 'phạm vi gia đình', 'adj + n', '[{"en":"In the past, women were largely confined to the domestic sphere.","vi":"Trong quá khứ, phụ nữ phần lớn bị giới hạn trong phạm vi gia đình."},{"en":"The book studies work done within the domestic sphere.","vi":"Cuốn sách nghiên cứu công việc trong phạm vi gia đình."},{"en":"Modern roles blur the line around the domestic sphere.","vi":"Các vai trò hiện đại làm mờ ranh giới của phạm vi gia đình."}]', '[]', NULL, '/dəˈmestɪk sfɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 105, 'domestic violence', 'bạo lực gia đình', 'adj + n', '[{"en":"The charity helps victims of domestic violence find safety.","vi":"Tổ chức từ thiện giúp nạn nhân bạo lực gia đình tìm nơi an toàn."},{"en":"New laws aim to reduce cases of domestic violence.","vi":"Các luật mới nhằm giảm số vụ bạo lực gia đình."},{"en":"Domestic violence often goes unreported for many years.","vi":"Bạo lực gia đình thường không được báo cáo trong nhiều năm."}]', '[]', NULL, '/dəˈmestɪk ˈvaɪələns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 106, 'dominant culture', 'văn hóa chủ đạo', 'adj + n', '[{"en":"Immigrants often adapt to the dominant culture over time.","vi":"Người nhập cư thường thích nghi với văn hóa chủ đạo theo thời gian."},{"en":"The dominant culture shapes what is shown in the media.","vi":"Văn hóa chủ đạo định hình những gì được thể hiện trên truyền thông."},{"en":"Smaller traditions can be lost within a dominant culture.","vi":"Các truyền thống nhỏ có thể bị mai một trong một văn hóa chủ đạo."}]', '[]', NULL, '/ˈdɑːmɪnənt ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 107, 'dominant discourse', 'diễn ngôn chủ đạo', 'adj + n', '[{"en":"The essay challenges the dominant discourse on poverty.","vi":"Bài luận thách thức diễn ngôn chủ đạo về đói nghèo."},{"en":"Media often reinforce the dominant discourse of a society.","vi":"Truyền thông thường củng cố diễn ngôn chủ đạo của một xã hội."},{"en":"Scholars question the dominant discourse around success.","vi":"Các học giả đặt nghi vấn về diễn ngôn chủ đạo quanh sự thành công."}]', '[]', NULL, '/ˈdɑːmɪnənt ˈdɪskɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 108, 'dominant form', 'hình thức chủ đạo', 'adj + n', '[{"en":"Television was once the dominant form of entertainment.","vi":"Truyền hình từng là hình thức giải trí chủ đạo."},{"en":"Email remains the dominant form of business communication.","vi":"Email vẫn là hình thức giao tiếp chủ đạo trong kinh doanh."},{"en":"Cash is no longer the dominant form of payment here.","vi":"Tiền mặt không còn là hình thức thanh toán chủ đạo ở đây."}]', '[]', NULL, '/ˈdɑːmɪnənt fɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 109, 'dominant group', 'nhóm thống trị', 'adj + n', '[{"en":"The dominant group often controls access to resources.","vi":"Nhóm thống trị thường kiểm soát quyền tiếp cận tài nguyên."},{"en":"Policies sometimes favor the dominant group in society.","vi":"Các chính sách đôi khi ưu ái nhóm thống trị trong xã hội."},{"en":"Members of the dominant group rarely notice their advantages.","vi":"Các thành viên của nhóm thống trị hiếm khi nhận ra lợi thế của mình."}]', '[]', NULL, '/ˈdɑːmɪnənt ɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 110, 'dominant ideology', 'hệ tư tưởng chủ đạo', 'adj + n', '[{"en":"The dominant ideology of the era praised free trade.","vi":"Hệ tư tưởng chủ đạo của thời kỳ đó ca ngợi tự do thương mại."},{"en":"Schools can quietly pass on the dominant ideology.","vi":"Trường học có thể âm thầm truyền tải hệ tư tưởng chủ đạo."},{"en":"Artists sometimes resist the dominant ideology of their time.","vi":"Nghệ sĩ đôi khi chống lại hệ tư tưởng chủ đạo của thời đại mình."}]', '[]', NULL, '/ˈdɑːmɪnənt ˌaɪdiˈɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 111, 'dominant paradigm', 'mô hình chủ đạo', 'adj + n', '[{"en":"The dominant paradigm in physics shifted after Einstein.","vi":"Mô hình chủ đạo trong vật lý đã thay đổi sau Einstein."},{"en":"Her research questions the dominant paradigm in economics.","vi":"Nghiên cứu của cô ấy đặt nghi vấn về mô hình chủ đạo trong kinh tế học."},{"en":"A new dominant paradigm can take decades to take hold.","vi":"Một mô hình chủ đạo mới có thể mất hàng thập kỷ để được chấp nhận."}]', '[]', NULL, '/ˈdɑːmɪnənt ˈpærədaɪm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 112, 'dominant position', 'vị thế thống trị', 'adj + n', '[{"en":"The firm holds a dominant position in the software market.","vi":"Công ty giữ vị thế thống trị trên thị trường phần mềm."},{"en":"Their dominant position allowed them to set high prices.","vi":"Vị thế thống trị cho phép họ đặt giá cao."},{"en":"A dominant position in trade gave the city great wealth.","vi":"Vị thế thống trị trong thương mại mang lại cho thành phố sự giàu có lớn."}]', '[]', NULL, '/ˈdɑːmɪnənt pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 113, 'dominant role', 'vai trò chủ đạo', 'adj + n', '[{"en":"Oil plays a dominant role in the country''s economy.","vi":"Dầu mỏ đóng vai trò chủ đạo trong nền kinh tế của đất nước."},{"en":"She took a dominant role in leading the discussion.","vi":"Cô ấy đảm nhận vai trò chủ đạo trong việc dẫn dắt thảo luận."},{"en":"Technology now has a dominant role in modern education.","vi":"Công nghệ giờ đây đóng vai trò chủ đạo trong giáo dục hiện đại."}]', '[]', NULL, '/ˈdɑːmɪnənt roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 114, 'dramatic change', 'sự thay đổi mạnh mẽ', 'adj + n', '[{"en":"The city has seen a dramatic change over the past decade.","vi":"Thành phố đã chứng kiến sự thay đổi mạnh mẽ trong thập kỷ qua."},{"en":"New technology brought a dramatic change to farming.","vi":"Công nghệ mới mang lại sự thay đổi mạnh mẽ cho ngành nông nghiệp."},{"en":"There was a dramatic change in attitudes after the campaign.","vi":"Đã có một sự thay đổi mạnh mẽ trong thái độ sau chiến dịch."}]', '[]', NULL, '/drəˈmætɪk tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 115, 'dramatic effect', 'tác động mạnh mẽ', 'adj + n', '[{"en":"The new law had a dramatic effect on small businesses.","vi":"Luật mới có tác động mạnh mẽ đến các doanh nghiệp nhỏ."},{"en":"Good lighting can have a dramatic effect on a photo.","vi":"Ánh sáng tốt có thể tạo tác động mạnh mẽ lên một bức ảnh."},{"en":"Exercise had a dramatic effect on her overall health.","vi":"Tập thể dục có tác động mạnh mẽ đến sức khỏe tổng thể của cô ấy."}]', '[]', NULL, '/drəˈmætɪk ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 116, 'dramatic increase', 'sự gia tăng mạnh mẽ', 'adj + n', '[{"en":"There was a dramatic increase in online sales last year.","vi":"Đã có sự gia tăng mạnh mẽ về doanh số trực tuyến năm ngoái."},{"en":"The report shows a dramatic increase in energy prices.","vi":"Báo cáo cho thấy sự gia tăng mạnh mẽ về giá năng lượng."},{"en":"A dramatic increase in users strained the company''s servers.","vi":"Sự gia tăng mạnh mẽ về người dùng gây áp lực lên máy chủ của công ty."}]', '[]', NULL, '/drəˈmætɪk ˈɪnkriːs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 117, 'draw attention to', 'thu hút sự chú ý đến', 'v + n', '[{"en":"The campaign aims to draw attention to climate change.","vi":"Chiến dịch nhằm thu hút sự chú ý đến biến đổi khí hậu."},{"en":"She used bright colors to draw attention to the poster.","vi":"Cô ấy dùng màu sắc tươi sáng để thu hút sự chú ý đến tấm áp phích."},{"en":"The author wants to draw attention to a forgotten issue.","vi":"Tác giả muốn thu hút sự chú ý đến một vấn đề bị lãng quên."}]', '[]', NULL, '/drɔː əˈtenʃən tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 118, 'draw a conclusion', 'rút ra một kết luận', 'v + n', '[{"en":"It is too early to draw a conclusion from this data.","vi":"Còn quá sớm để rút ra một kết luận từ dữ liệu này."},{"en":"Readers can draw a conclusion based on the evidence given.","vi":"Người đọc có thể rút ra một kết luận dựa trên bằng chứng đã nêu."},{"en":"Scientists draw a conclusion only after repeated testing.","vi":"Các nhà khoa học chỉ rút ra một kết luận sau nhiều lần kiểm tra."}]', '[]', NULL, '/drɔː ə kənˈkluːʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 119, 'draw a distinction', 'phân biệt rõ ràng', 'v + n', '[{"en":"The author draws a distinction between belief and knowledge.","vi":"Tác giả phân biệt rõ ràng giữa niềm tin và kiến thức."},{"en":"We must draw a distinction between cause and correlation.","vi":"Chúng ta phải phân biệt rõ ràng giữa nguyên nhân và mối tương quan."},{"en":"It helps to draw a distinction between needs and wants.","vi":"Việc phân biệt rõ ràng giữa nhu cầu và mong muốn rất hữu ích."}]', '[]', NULL, '/drɔː ə dɪˈstɪŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 120, 'draw a line', 'vạch ra ranh giới', 'v + n', '[{"en":"It is hard to draw a line between work and rest.","vi":"Thật khó để vạch ra ranh giới giữa công việc và nghỉ ngơi."},{"en":"Parents should draw a line on screen time for children.","vi":"Cha mẹ nên vạch ra ranh giới về thời gian dùng màn hình cho trẻ."},{"en":"The law draws a line between free speech and harm.","vi":"Luật pháp vạch ra ranh giới giữa tự do ngôn luận và gây hại."}]', '[]', NULL, '/drɔː ə laɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 121, 'driving force', 'động lực chính', 'adj + n', '[{"en":"Innovation is the driving force behind the company''s success.","vi":"Đổi mới là động lực chính đằng sau thành công của công ty."},{"en":"Curiosity was the driving force in her research career.","vi":"Sự tò mò là động lực chính trong sự nghiệp nghiên cứu của cô ấy."},{"en":"Trade became the driving force of the region''s growth.","vi":"Thương mại trở thành động lực chính cho sự tăng trưởng của khu vực."}]', '[]', NULL, '/ˈdraɪvɪŋ fɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 122, 'due process', 'trình tự pháp lý đúng đắn', 'adj + n', '[{"en":"Every citizen is entitled to due process under the law.","vi":"Mỗi công dân đều có quyền được hưởng trình tự pháp lý đúng đắn."},{"en":"The court ensured due process before reaching a verdict.","vi":"Tòa án bảo đảm trình tự pháp lý đúng đắn trước khi đưa ra phán quyết."},{"en":"Skipping due process can make a decision unlawful.","vi":"Bỏ qua trình tự pháp lý đúng đắn có thể khiến quyết định trái luật."}]', '[]', NULL, '/duː ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 123, 'dynamic equilibrium', 'cân bằng động', 'adj + n', '[{"en":"The reaction reaches a dynamic equilibrium after a few minutes.","vi":"Phản ứng đạt tới trạng thái cân bằng động sau vài phút."},{"en":"In dynamic equilibrium, forward and reverse rates are equal.","vi":"Trong cân bằng động, tốc độ thuận và nghịch bằng nhau."},{"en":"Ecosystems often exist in a fragile dynamic equilibrium.","vi":"Các hệ sinh thái thường tồn tại trong một cân bằng động mong manh."}]', '[]', NULL, '/daɪˈnæmɪk ˌiːkwəˈlɪbriəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 124, 'dynamic nature', 'bản chất năng động', 'adj + n', '[{"en":"The dynamic nature of language makes it hard to fix rules.","vi":"Bản chất năng động của ngôn ngữ khiến việc cố định quy tắc rất khó."},{"en":"Markets change quickly due to their dynamic nature.","vi":"Thị trường thay đổi nhanh do bản chất năng động của nó."},{"en":"The dynamic nature of the field demands constant learning.","vi":"Bản chất năng động của lĩnh vực này đòi hỏi việc học liên tục."}]', '[]', NULL, '/daɪˈnæmɪk ˈneɪtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 125, 'dynamic process', 'quá trình năng động', 'adj + n', '[{"en":"Learning is a dynamic process that continues throughout life.","vi":"Học tập là một quá trình năng động kéo dài suốt đời."},{"en":"Cell growth is a dynamic process influenced by many factors.","vi":"Sự phát triển của tế bào là quá trình năng động chịu nhiều yếu tố tác động."},{"en":"Culture is a dynamic process, always shifting over time.","vi":"Văn hóa là một quá trình năng động, luôn thay đổi theo thời gian."}]', '[]', NULL, '/daɪˈnæmɪk ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 126, 'dynamic system', 'hệ thống động', 'adj + n', '[{"en":"The climate is a dynamic system with many feedback loops.","vi":"Khí hậu là một hệ thống động với nhiều vòng phản hồi."},{"en":"Engineers model the bridge as a dynamic system under load.","vi":"Các kỹ sư mô hình hóa cây cầu như một hệ thống động khi chịu tải."},{"en":"A market is a dynamic system shaped by countless decisions.","vi":"Thị trường là một hệ thống động được định hình bởi vô số quyết định."}]', '[]', NULL, '/daɪˈnæmɪk ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 127, 'earlier discussion', 'phần thảo luận trước đó', 'adj + n', '[{"en":"As noted in the earlier discussion, the data are limited.","vi":"Như đã nêu trong phần thảo luận trước đó, dữ liệu còn hạn chế."},{"en":"This section builds on the earlier discussion of causes.","vi":"Phần này dựa trên phần thảo luận trước đó về các nguyên nhân."},{"en":"The earlier discussion raised several unanswered questions.","vi":"Phần thảo luận trước đó đã nêu ra nhiều câu hỏi chưa được giải đáp."}]', '[]', NULL, '/ˈɜːrliər dɪˈskʌʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 128, 'earlier period', 'thời kỳ trước đó', 'adj + n', '[{"en":"These customs date back to an earlier period in history.","vi":"Những phong tục này có từ một thời kỳ trước đó trong lịch sử."},{"en":"Wages were much lower during the earlier period studied.","vi":"Tiền lương thấp hơn nhiều trong thời kỳ trước đó được nghiên cứu."},{"en":"Art from the earlier period shows simpler designs.","vi":"Nghệ thuật từ thời kỳ trước đó cho thấy những thiết kế đơn giản hơn."}]', '[]', NULL, '/ˈɜːrliər ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 129, 'earlier research', 'nghiên cứu trước đó', 'adj + n', '[{"en":"These results confirm the findings of earlier research.","vi":"Những kết quả này xác nhận các phát hiện của nghiên cứu trước đó."},{"en":"Earlier research had ignored the role of social factors.","vi":"Nghiên cứu trước đó đã bỏ qua vai trò của các yếu tố xã hội."},{"en":"Her study builds directly on earlier research in the field.","vi":"Nghiên cứu của cô ấy dựa trực tiếp vào nghiên cứu trước đó trong lĩnh vực này."}]', '[]', NULL, '/ˈɜːrliər ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 130, 'earlier stage', 'giai đoạn trước đó', 'adj + n', '[{"en":"Problems are easier to fix at an earlier stage.","vi":"Các vấn đề dễ khắc phục hơn ở một giai đoạn trước đó."},{"en":"At an earlier stage, the plan looked very different.","vi":"Ở một giai đoạn trước đó, kế hoạch trông rất khác."},{"en":"Doctors aim to detect the disease at an earlier stage.","vi":"Bác sĩ hướng tới phát hiện bệnh ở một giai đoạn trước đó."}]', '[]', NULL, '/ˈɜːrliər steɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 131, 'earlier study', 'nghiên cứu trước đó', 'adj + n', '[{"en":"An earlier study reached very different conclusions about the topic.","vi":"Một nghiên cứu trước đó đã đưa ra những kết luận rất khác về chủ đề này."},{"en":"We compared our results with an earlier study from 2010.","vi":"Chúng tôi đã so sánh kết quả với một nghiên cứu trước đó từ năm 2010."},{"en":"The earlier study used a much smaller sample size.","vi":"Nghiên cứu trước đó dùng cỡ mẫu nhỏ hơn nhiều."}]', '[]', NULL, '/ˈɜːrliər ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 132, 'earlier times', 'thời kỳ trước đây', 'adj + n', '[{"en":"In earlier times, most people lived in rural villages.","vi":"Vào thời kỳ trước đây, hầu hết mọi người sống ở làng quê."},{"en":"Trade was much slower in earlier times than today.","vi":"Việc buôn bán chậm hơn nhiều vào thời kỳ trước đây so với ngày nay."},{"en":"These traditions date back to much earlier times.","vi":"Những truyền thống này có từ những thời kỳ trước đây rất lâu."}]', '[]', NULL, '/ˈɜːrliər taɪmz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 133, 'earlier version', 'phiên bản trước đó', 'adj + n', '[{"en":"An earlier version of the software lacked this feature.","vi":"Một phiên bản trước đó của phần mềm thiếu tính năng này."},{"en":"The earlier version of the report contained several errors.","vi":"Phiên bản trước đó của báo cáo chứa một số lỗi."},{"en":"Reviewers had read an earlier version of the paper.","vi":"Người bình duyệt đã đọc một phiên bản trước đó của bài báo."}]', '[]', NULL, '/ˈɜːrliər ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 134, 'earlier work', 'công trình trước đó', 'adj + n', '[{"en":"Her earlier work focused mainly on childhood language development.","vi":"Công trình trước đó của bà tập trung chủ yếu vào sự phát triển ngôn ngữ ở trẻ em."},{"en":"This paper builds directly on the author''s earlier work.","vi":"Bài báo này được xây dựng trực tiếp trên công trình trước đó của tác giả."},{"en":"Earlier work in this field had largely been ignored.","vi":"Các công trình trước đó trong lĩnh vực này phần lớn bị bỏ qua."}]', '[]', NULL, '/ˈɜːrliər wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 135, 'early decades', 'những thập niên đầu', 'adj + n', '[{"en":"The early decades of the century saw rapid industrial growth.","vi":"Những thập niên đầu của thế kỷ chứng kiến sự tăng trưởng công nghiệp nhanh chóng."},{"en":"Computers were rare during the early decades of the field.","vi":"Máy tính rất hiếm trong những thập niên đầu của lĩnh vực này."},{"en":"In the early decades, the company employed only ten workers.","vi":"Trong những thập niên đầu, công ty chỉ thuê mười nhân công."}]', '[]', NULL, '/ˈɜːrli ˈdekeɪdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 136, 'early study', 'nghiên cứu ban đầu', 'adj + n', '[{"en":"An early study suggested a link between diet and sleep.","vi":"Một nghiên cứu ban đầu cho thấy mối liên hệ giữa chế độ ăn và giấc ngủ."},{"en":"Each early study relied on rather limited data.","vi":"Mỗi nghiên cứu ban đầu đều dựa trên dữ liệu khá hạn chế."},{"en":"The early study laid the groundwork for later research.","vi":"Nghiên cứu ban đầu đã đặt nền móng cho các nghiên cứu về sau."}]', '[]', NULL, '/ˈɜːrli ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 137, 'easily accessible', 'dễ tiếp cận', 'adv + adj', '[{"en":"The library makes its archives easily accessible to students.","vi":"Thư viện làm cho kho lưu trữ dễ tiếp cận với sinh viên."},{"en":"Public transport keeps the city center easily accessible.","vi":"Giao thông công cộng giúp trung tâm thành phố dễ tiếp cận."},{"en":"Online resources are easily accessible from any device.","vi":"Tài nguyên trực tuyến dễ tiếp cận từ bất kỳ thiết bị nào."}]', '[]', NULL, '/ˈiːzəli əkˈsesəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 138, 'easily identified', 'dễ nhận ra', 'adv + vpp', '[{"en":"The error was easily identified during the first review.","vi":"Lỗi này dễ dàng được nhận ra trong lần kiểm tra đầu tiên."},{"en":"These patterns are easily identified in the raw data.","vi":"Những mẫu hình này dễ được nhận ra trong dữ liệu thô."},{"en":"Affected plants can be easily identified by their spots.","vi":"Cây bị ảnh hưởng có thể dễ dàng được nhận ra qua các đốm."}]', '[]', NULL, '/ˈiːzəli aɪˈdentɪfaɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 139, 'easily understood', 'dễ hiểu', 'adv + vpp', '[{"en":"The instructions were clear and easily understood by everyone.","vi":"Hướng dẫn rõ ràng và mọi người dễ dàng hiểu được."},{"en":"Good charts make complex data easily understood.","vi":"Biểu đồ tốt giúp dữ liệu phức tạp trở nên dễ hiểu."},{"en":"The concept is easily understood once examples are given.","vi":"Khái niệm này dễ hiểu khi đã có ví dụ."}]', '[]', NULL, '/ˈiːzəli ˌʌndərˈstʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 140, 'easy access', 'sự tiếp cận dễ dàng', 'adj + n', '[{"en":"Students need easy access to reliable academic sources.","vi":"Sinh viên cần sự tiếp cận dễ dàng với các nguồn học thuật đáng tin cậy."},{"en":"The app gives users easy access to their records.","vi":"Ứng dụng cho người dùng sự tiếp cận dễ dàng đến hồ sơ của họ."},{"en":"Easy access to clean water improves community health.","vi":"Sự tiếp cận dễ dàng với nước sạch cải thiện sức khỏe cộng đồng."}]', '[]', NULL, '/ˈiːzi ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 141, 'economic activity', 'hoạt động kinh tế', 'adj + n', '[{"en":"The pandemic sharply reduced economic activity across the region.","vi":"Đại dịch đã làm giảm mạnh hoạt động kinh tế trên toàn khu vực."},{"en":"Tourism remains the main economic activity on the island.","vi":"Du lịch vẫn là hoạt động kinh tế chính trên đảo."},{"en":"Lower interest rates can boost economic activity quickly.","vi":"Lãi suất thấp hơn có thể thúc đẩy hoạt động kinh tế nhanh chóng."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 142, 'economic affairs', 'các vấn đề kinh tế', 'adj + n', '[{"en":"The minister is responsible for the nation''s economic affairs.","vi":"Bộ trưởng chịu trách nhiệm về các vấn đề kinh tế của quốc gia."},{"en":"The committee advises the government on economic affairs.","vi":"Ủy ban tư vấn cho chính phủ về các vấn đề kinh tế."},{"en":"Newspapers devote whole sections to economic affairs.","vi":"Báo chí dành cả những chuyên mục cho các vấn đề kinh tế."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk əˈferz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 143, 'economic analysis', 'phân tích kinh tế', 'adj + n', '[{"en":"A careful economic analysis showed the project was unprofitable.","vi":"Một phân tích kinh tế cẩn thận cho thấy dự án không có lãi."},{"en":"The report includes a detailed economic analysis of costs.","vi":"Báo cáo bao gồm một phân tích kinh tế chi tiết về chi phí."},{"en":"Economic analysis helps governments plan future budgets.","vi":"Phân tích kinh tế giúp các chính phủ lập kế hoạch ngân sách tương lai."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 144, 'economic benefits', 'lợi ích kinh tế', 'adj + n', '[{"en":"The new factory brought clear economic benefits to the town.","vi":"Nhà máy mới mang lại lợi ích kinh tế rõ rệt cho thị trấn."},{"en":"Researchers measured the economic benefits of better education.","vi":"Các nhà nghiên cứu đo lường lợi ích kinh tế của giáo dục tốt hơn."},{"en":"Renewable energy offers long-term economic benefits.","vi":"Năng lượng tái tạo mang lại lợi ích kinh tế lâu dài."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈbenɪfɪts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 145, 'economic change', 'sự thay đổi kinh tế', 'adj + n', '[{"en":"Rapid economic change forced many workers to retrain.","vi":"Sự thay đổi kinh tế nhanh chóng buộc nhiều công nhân phải học lại nghề."},{"en":"The study tracks economic change over three decades.","vi":"Nghiên cứu theo dõi sự thay đổi kinh tế trong ba thập kỷ."},{"en":"Technology often drives deep economic change in society.","vi":"Công nghệ thường thúc đẩy sự thay đổi kinh tế sâu sắc trong xã hội."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 146, 'economic conditions', 'điều kiện kinh tế', 'adj + n', '[{"en":"Poor economic conditions made it hard to find work.","vi":"Điều kiện kinh tế kém khiến việc tìm kiếm công việc trở nên khó khăn."},{"en":"Investment decisions depend heavily on current economic conditions.","vi":"Quyết định đầu tư phụ thuộc nhiều vào điều kiện kinh tế hiện tại."},{"en":"Economic conditions improved steadily after the reforms.","vi":"Điều kiện kinh tế cải thiện đều đặn sau các cải cách."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 147, 'economic consequences', 'hậu quả kinh tế', 'adj + n', '[{"en":"The war had severe economic consequences for both nations.","vi":"Cuộc chiến gây ra hậu quả kinh tế nghiêm trọng cho cả hai quốc gia."},{"en":"Policymakers must consider the economic consequences of higher taxes.","vi":"Các nhà hoạch định phải cân nhắc hậu quả kinh tế của việc tăng thuế."},{"en":"Climate change carries far-reaching economic consequences.","vi":"Biến đổi khí hậu mang lại những hậu quả kinh tế sâu rộng."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈkɑːnsɪkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 148, 'economic context', 'bối cảnh kinh tế', 'adj + n', '[{"en":"These reforms must be understood in their economic context.","vi":"Những cải cách này phải được hiểu trong bối cảnh kinh tế của chúng."},{"en":"The author describes the wider economic context of the period.","vi":"Tác giả mô tả bối cảnh kinh tế rộng lớn hơn của thời kỳ đó."},{"en":"Decisions made sense within the economic context of the time.","vi":"Các quyết định trở nên hợp lý trong bối cảnh kinh tế thời bấy giờ."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 149, 'economic crisis', 'khủng hoảng kinh tế', 'adj + n', '[{"en":"The economic crisis left millions of people unemployed.","vi":"Cuộc khủng hoảng kinh tế khiến hàng triệu người thất nghiệp."},{"en":"Governments struggled to respond to the economic crisis.","vi":"Các chính phủ chật vật ứng phó với cuộc khủng hoảng kinh tế."},{"en":"The 2008 economic crisis reshaped global financial regulation.","vi":"Cuộc khủng hoảng kinh tế năm 2008 đã định hình lại quy định tài chính toàn cầu."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈkraɪsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-4-01', 150, 'economic exploitation', 'sự bóc lột kinh tế', 'adj + n', '[{"en":"The book examines the economic exploitation of colonial workers.","vi":"Cuốn sách xem xét sự bóc lột kinh tế đối với công nhân thuộc địa."},{"en":"Weak laws allowed widespread economic exploitation of migrants.","vi":"Luật lệ yếu kém cho phép sự bóc lột kinh tế tràn lan đối với người di cư."},{"en":"Activists campaigned against the economic exploitation of children.","vi":"Các nhà hoạt động vận động chống lại sự bóc lột kinh tế đối với trẻ em."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˌeksplɔɪˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-5-01', 'colloc-5', 'Cụm học thuật · Nhóm 5', 'Academic Collocation List (Pearson/PTE) — nhóm 5 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 1, 'economic factors', 'các yếu tố kinh tế', 'adj + n', '[{"en":"Several economic factors influenced the family''s decision to move.","vi":"Một số yếu tố kinh tế ảnh hưởng đến quyết định chuyển nhà của gia đình."},{"en":"The study controlled for economic factors such as income.","vi":"Nghiên cứu đã kiểm soát các yếu tố kinh tế như thu nhập."},{"en":"Economic factors alone cannot explain the trend.","vi":"Các yếu tố kinh tế đơn thuần không thể giải thích xu hướng này."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 2, 'economic forces', 'các lực lượng kinh tế', 'adj + n', '[{"en":"Powerful economic forces shaped the city''s rapid growth.","vi":"Những lực lượng kinh tế mạnh mẽ định hình sự phát triển nhanh của thành phố."},{"en":"Global economic forces affect small local businesses too.","vi":"Các lực lượng kinh tế toàn cầu cũng tác động đến doanh nghiệp địa phương nhỏ."},{"en":"The decline resulted from forces beyond local control.","vi":"Sự suy giảm bắt nguồn từ những lực lượng nằm ngoài tầm kiểm soát địa phương."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈfɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 3, 'economic goal', 'mục tiêu kinh tế', 'adj + n', '[{"en":"Reducing unemployment is the government''s main economic goal.","vi":"Giảm tỷ lệ thất nghiệp là mục tiêu kinh tế chính của chính phủ."},{"en":"The plan balances social and economic goals carefully.","vi":"Kế hoạch cân bằng cẩn thận giữa mục tiêu xã hội và kinh tế."},{"en":"Each economic goal must be measurable and realistic.","vi":"Mỗi mục tiêu kinh tế phải đo lường được và thực tế."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ɡoʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 4, 'economic growth', 'tăng trưởng kinh tế', 'adj + n', '[{"en":"Strong economic growth created thousands of new jobs.","vi":"Tăng trưởng kinh tế mạnh mẽ tạo ra hàng nghìn việc làm mới."},{"en":"Education investment supports long-term economic growth.","vi":"Đầu tư vào giáo dục hỗ trợ tăng trưởng kinh tế lâu dài."},{"en":"Economic growth slowed sharply during the recession.","vi":"Tăng trưởng kinh tế chững lại rõ rệt trong thời kỳ suy thoái."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ɡroʊθ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 5, 'economic inequality', 'bất bình đẳng kinh tế', 'adj + n', '[{"en":"Economic inequality has widened in many developed countries.","vi":"Bất bình đẳng kinh tế đã gia tăng ở nhiều nước phát triển."},{"en":"The policy aims to reduce growing economic inequality.","vi":"Chính sách nhằm giảm bớt sự bất bình đẳng kinh tế ngày càng tăng."},{"en":"High economic inequality can fuel social unrest.","vi":"Bất bình đẳng kinh tế cao có thể thổi bùng bất ổn xã hội."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˌɪnɪˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 6, 'economic integration', 'hội nhập kinh tế', 'adj + n', '[{"en":"Economic integration allowed goods to move freely between countries.","vi":"Hội nhập kinh tế cho phép hàng hóa lưu thông tự do giữa các nước."},{"en":"The treaty promotes deeper economic integration in the region.","vi":"Hiệp ước thúc đẩy hội nhập kinh tế sâu rộng hơn trong khu vực."},{"en":"Economic integration can lower prices for consumers.","vi":"Hội nhập kinh tế có thể giảm giá cho người tiêu dùng."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˌɪntɪˈɡreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 7, 'economic interests', 'lợi ích kinh tế', 'adj + n', '[{"en":"The two nations share important economic interests.","vi":"Hai quốc gia chia sẻ những lợi ích kinh tế quan trọng."},{"en":"Critics argue the law protects narrow economic interests.","vi":"Các nhà phê bình cho rằng luật này bảo vệ những lợi ích kinh tế hẹp hòi."},{"en":"Companies often lobby to defend their economic interests.","vi":"Các công ty thường vận động hành lang để bảo vệ lợi ích kinh tế."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈɪntrəsts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 8, 'economic policy', 'chính sách kinh tế', 'adj + n', '[{"en":"The new economic policy aims to control inflation.","vi":"Chính sách kinh tế mới nhằm kiểm soát lạm phát."},{"en":"Economists disagreed sharply about the government''s economic policy.","vi":"Các nhà kinh tế bất đồng gay gắt về chính sách kinh tế của chính phủ."},{"en":"Sound economic policy can stabilize a fragile market.","vi":"Chính sách kinh tế hợp lý có thể ổn định một thị trường mong manh."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 9, 'economic power', 'sức mạnh kinh tế', 'adj + n', '[{"en":"The country''s economic power grew rapidly after the reforms.","vi":"Sức mạnh kinh tế của quốc gia tăng nhanh sau các cải cách."},{"en":"Large corporations wield enormous economic power today.","vi":"Các tập đoàn lớn nắm giữ sức mạnh kinh tế khổng lồ ngày nay."},{"en":"Economic power often translates into political influence.","vi":"Sức mạnh kinh tế thường chuyển thành ảnh hưởng chính trị."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 10, 'economic prosperity', 'sự thịnh vượng kinh tế', 'adj + n', '[{"en":"Stable institutions are essential for lasting economic prosperity.","vi":"Các thể chế ổn định là điều thiết yếu cho sự thịnh vượng kinh tế bền vững."},{"en":"Trade brought a period of remarkable economic prosperity.","vi":"Thương mại mang lại một thời kỳ thịnh vượng kinh tế đáng kể."},{"en":"Many factors contribute to a region''s economic prosperity.","vi":"Nhiều yếu tố góp phần vào sự thịnh vượng kinh tế của một vùng."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk prɑːˈsperəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 11, 'economic reform', 'cải cách kinh tế', 'adj + n', '[{"en":"Economic reform opened the country to foreign investment.","vi":"Cải cách kinh tế đã mở cửa đất nước cho đầu tư nước ngoài."},{"en":"The government promised sweeping economic reform after the election.","vi":"Chính phủ hứa hẹn cải cách kinh tế sâu rộng sau bầu cử."},{"en":"Economic reform often faces strong political resistance.","vi":"Cải cách kinh tế thường vấp phải sự phản kháng chính trị mạnh mẽ."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk rɪˈfɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 12, 'economic relations', 'quan hệ kinh tế', 'adj + n', '[{"en":"The agreement strengthened economic relations between the two states.","vi":"Hiệp định củng cố quan hệ kinh tế giữa hai quốc gia."},{"en":"Tensions damaged economic relations across the border.","vi":"Căng thẳng làm tổn hại quan hệ kinh tế xuyên biên giới."},{"en":"Trade fairs help build new economic relations.","vi":"Hội chợ thương mại giúp xây dựng quan hệ kinh tế mới."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk rɪˈleɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 13, 'economic relationships', 'các mối quan hệ kinh tế', 'adj + n', '[{"en":"Global trade creates complex economic relationships between nations.","vi":"Thương mại toàn cầu tạo ra các mối quan hệ kinh tế phức tạp giữa các nước."},{"en":"The chapter analyzes economic relationships within rural communities.","vi":"Chương này phân tích các mối quan hệ kinh tế trong cộng đồng nông thôn."},{"en":"Trust underpins long-term economic relationships between firms.","vi":"Niềm tin là nền tảng cho các mối quan hệ kinh tế lâu dài giữa các công ty."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk rɪˈleɪʃənʃɪps/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 14, 'economic resources', 'nguồn lực kinh tế', 'adj + n', '[{"en":"The region lacks the economic resources to rebuild quickly.","vi":"Khu vực thiếu nguồn lực kinh tế để tái thiết nhanh chóng."},{"en":"Wealthy families can devote more economic resources to education.","vi":"Gia đình giàu có thể dành nhiều nguồn lực kinh tế hơn cho giáo dục."},{"en":"Scarce economic resources must be allocated carefully.","vi":"Nguồn lực kinh tế khan hiếm phải được phân bổ cẩn thận."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 15, 'economic sector', 'khu vực kinh tế', 'adj + n', '[{"en":"The service economic sector now employs most urban workers.","vi":"Khu vực kinh tế dịch vụ hiện thuê hầu hết lao động đô thị."},{"en":"Each economic sector responded differently to the new tax.","vi":"Mỗi khu vực kinh tế phản ứng khác nhau với loại thuế mới."},{"en":"The report focuses on the agricultural economic sector.","vi":"Báo cáo tập trung vào khu vực kinh tế nông nghiệp."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈsektər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 16, 'economic stability', 'sự ổn định kinh tế', 'adj + n', '[{"en":"Low inflation contributes to long-term economic stability.","vi":"Lạm phát thấp góp phần vào sự ổn định kinh tế lâu dài."},{"en":"Investors prefer countries with strong economic stability.","vi":"Nhà đầu tư ưa chuộng các nước có sự ổn định kinh tế vững chắc."},{"en":"The crisis threatened the region''s fragile economic stability.","vi":"Cuộc khủng hoảng đe dọa sự ổn định kinh tế mong manh của khu vực."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk stəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 17, 'economic status', 'địa vị kinh tế', 'adj + n', '[{"en":"A family''s economic status often affects children''s opportunities.","vi":"Địa vị kinh tế của một gia đình thường ảnh hưởng đến cơ hội của con cái."},{"en":"The survey grouped respondents by economic status.","vi":"Cuộc khảo sát phân nhóm người trả lời theo địa vị kinh tế."},{"en":"Education can help people improve their economic status.","vi":"Giáo dục có thể giúp con người cải thiện địa vị kinh tế."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈstætəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 18, 'economic structure', 'cấu trúc kinh tế', 'adj + n', '[{"en":"Industrialization transformed the country''s entire economic structure.","vi":"Công nghiệp hóa đã biến đổi toàn bộ cấu trúc kinh tế của đất nước."},{"en":"The economic structure shifted from farming to manufacturing.","vi":"Cấu trúc kinh tế chuyển từ nông nghiệp sang sản xuất."},{"en":"A rigid economic structure can slow needed change.","vi":"Một cấu trúc kinh tế cứng nhắc có thể làm chậm những thay đổi cần thiết."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 19, 'economic success', 'thành công kinh tế', 'adj + n', '[{"en":"The firm''s economic success depended on constant innovation.","vi":"Thành công kinh tế của công ty phụ thuộc vào sự đổi mới liên tục."},{"en":"Education is widely seen as a path to economic success.","vi":"Giáo dục được xem rộng rãi là con đường dẫn đến thành công kinh tế."},{"en":"The country''s economic success attracted skilled migrants.","vi":"Thành công kinh tế của đất nước thu hút lao động lành nghề."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk səkˈses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 20, 'economic system', 'hệ thống kinh tế', 'adj + n', '[{"en":"A market economic system relies on supply and demand.","vi":"Một hệ thống kinh tế thị trường dựa vào cung và cầu."},{"en":"The reforms gradually changed the entire economic system.","vi":"Các cải cách dần dần thay đổi toàn bộ hệ thống kinh tế."},{"en":"Every economic system distributes resources in its own way.","vi":"Mỗi hệ thống kinh tế phân phối nguồn lực theo cách riêng."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 21, 'economic theory', 'lý thuyết kinh tế', 'adj + n', '[{"en":"The professor explained the economic theory behind inflation.","vi":"Giáo sư giải thích lý thuyết kinh tế đằng sau lạm phát."},{"en":"Classical economic theory assumes that people act rationally.","vi":"Lý thuyết kinh tế cổ điển giả định rằng con người hành động một cách lý trí."},{"en":"Real markets rarely behave as economic theory predicts.","vi":"Thị trường thực hiếm khi diễn ra như lý thuyết kinh tế dự đoán."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈθiːəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 22, 'economic value', 'giá trị kinh tế', 'adj + n', '[{"en":"Forests have ecological as well as economic value.","vi":"Rừng có giá trị sinh thái cũng như giá trị kinh tế."},{"en":"The study estimated the economic value of clean air.","vi":"Nghiên cứu ước tính giá trị kinh tế của không khí sạch."},{"en":"Skilled labor adds significant economic value to products.","vi":"Lao động lành nghề tạo thêm giá trị kinh tế đáng kể cho sản phẩm."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 23, 'economic welfare', 'phúc lợi kinh tế', 'adj + n', '[{"en":"The policy aims to improve the economic welfare of citizens.","vi":"Chính sách nhằm cải thiện phúc lợi kinh tế của người dân."},{"en":"Free trade can raise the economic welfare of a nation.","vi":"Thương mại tự do có thể nâng cao phúc lợi kinh tế của một quốc gia."},{"en":"Economists debate how best to measure economic welfare.","vi":"Các nhà kinh tế tranh luận về cách đo lường phúc lợi kinh tế tốt nhất."}]', '[]', NULL, '/ˌiːkəˈnɑːmɪk ˈwelfer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 24, 'educational institution', 'cơ sở giáo dục', 'adj + n', '[{"en":"Every educational institution must meet basic safety standards.","vi":"Mọi cơ sở giáo dục đều phải đáp ứng các tiêu chuẩn an toàn cơ bản."},{"en":"The university is the city''s oldest educational institution.","vi":"Trường đại học là cơ sở giáo dục lâu đời nhất của thành phố."},{"en":"Funding for educational institutions was cut last year.","vi":"Ngân sách cho các cơ sở giáo dục bị cắt giảm năm ngoái."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˌɪnstɪˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 25, 'educational opportunity', 'cơ hội giáo dục', 'adj + n', '[{"en":"Scholarships give poorer students better educational opportunity.","vi":"Học bổng mang lại cho học sinh nghèo cơ hội giáo dục tốt hơn."},{"en":"The program expands educational opportunity in rural areas.","vi":"Chương trình mở rộng cơ hội giáo dục ở các vùng nông thôn."},{"en":"Equal educational opportunity remains a central policy goal.","vi":"Cơ hội giáo dục bình đẳng vẫn là một mục tiêu chính sách trọng tâm."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 26, 'educational policy', 'chính sách giáo dục', 'adj + n', '[{"en":"A new educational policy raised the school leaving age.","vi":"Một chính sách giáo dục mới đã nâng độ tuổi rời trường."},{"en":"Educational policy should respond to changing labor markets.","vi":"Chính sách giáo dục nên thích ứng với thị trường lao động đang thay đổi."},{"en":"Researchers evaluated the impact of recent educational policy.","vi":"Các nhà nghiên cứu đánh giá tác động của chính sách giáo dục gần đây."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 27, 'educational program', 'chương trình giáo dục', 'adj + n', '[{"en":"The charity runs an educational program for young refugees.","vi":"Tổ chức từ thiện điều hành một chương trình giáo dục cho người tị nạn trẻ."},{"en":"An effective educational program needs trained, motivated teachers.","vi":"Một chương trình giáo dục hiệu quả cần giáo viên được đào tạo và đầy nhiệt huyết."},{"en":"The educational program improved students'' reading scores.","vi":"Chương trình giáo dục đã cải thiện điểm đọc của học sinh."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˈproʊɡræm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 28, 'educational provision', 'việc cung cấp giáo dục', 'adj + n', '[{"en":"Educational provision in remote regions is often inadequate.","vi":"Việc cung cấp giáo dục ở các vùng xa thường không đầy đủ."},{"en":"The council improved educational provision for disabled children.","vi":"Hội đồng cải thiện việc cung cấp giáo dục cho trẻ em khuyết tật."},{"en":"Funding gaps led to uneven educational provision nationwide.","vi":"Thiếu hụt ngân sách dẫn đến việc cung cấp giáo dục không đồng đều trên cả nước."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl prəˈvɪʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 29, 'educational qualification', 'bằng cấp giáo dục', 'adj + n', '[{"en":"Many jobs now require a higher educational qualification.","vi":"Nhiều công việc hiện đòi hỏi bằng cấp giáo dục cao hơn."},{"en":"Her educational qualifications opened doors to better careers.","vi":"Bằng cấp giáo dục của cô mở ra cánh cửa cho những nghề nghiệp tốt hơn."},{"en":"Employers verify each applicant''s educational qualifications carefully.","vi":"Nhà tuyển dụng kiểm tra cẩn thận bằng cấp giáo dục của từng ứng viên."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˌkwɑːlɪfɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 30, 'educational research', 'nghiên cứu giáo dục', 'adj + n', '[{"en":"Educational research informs how teachers design their lessons.","vi":"Nghiên cứu giáo dục định hướng cách giáo viên thiết kế bài giảng."},{"en":"She published widely in the field of educational research.","vi":"Bà đã công bố nhiều bài trong lĩnh vực nghiên cứu giáo dục."},{"en":"Recent educational research questions traditional grading methods.","vi":"Nghiên cứu giáo dục gần đây đặt câu hỏi về phương pháp chấm điểm truyền thống."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 31, 'educational setting', 'môi trường giáo dục', 'adj + n', '[{"en":"The method works well in any educational setting.","vi":"Phương pháp này hoạt động tốt trong bất kỳ môi trường giáo dục nào."},{"en":"Children behave differently across various educational settings.","vi":"Trẻ em cư xử khác nhau trong các môi trường giáo dục khác nhau."},{"en":"Technology is now common in most educational settings.","vi":"Công nghệ hiện phổ biến trong hầu hết các môi trường giáo dục."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˈsetɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 32, 'educational system', 'hệ thống giáo dục', 'adj + n', '[{"en":"The country''s educational system ranks among the best globally.","vi":"Hệ thống giáo dục của đất nước thuộc hàng tốt nhất thế giới."},{"en":"Reforming an entire educational system takes many years.","vi":"Cải cách toàn bộ một hệ thống giáo dục mất nhiều năm."},{"en":"The educational system struggles to fund rural schools.","vi":"Hệ thống giáo dục chật vật trong việc tài trợ cho trường học nông thôn."}]', '[]', NULL, '/ˌedʒuˈkeɪʃənəl ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 33, 'effective communication', 'giao tiếp hiệu quả', 'adj + n', '[{"en":"Effective communication is essential for successful teamwork.","vi":"Giao tiếp hiệu quả là điều thiết yếu cho làm việc nhóm thành công."},{"en":"The course teaches students effective communication skills.","vi":"Khóa học dạy sinh viên các kỹ năng giao tiếp hiệu quả."},{"en":"Misunderstandings arise when effective communication breaks down.","vi":"Hiểu lầm nảy sinh khi giao tiếp hiệu quả bị đổ vỡ."}]', '[]', NULL, '/ɪˈfektɪv kəˌmjuːnɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 34, 'effective implementation', 'việc triển khai hiệu quả', 'adj + n', '[{"en":"Effective implementation of the plan requires steady funding.","vi":"Việc triển khai hiệu quả kế hoạch đòi hỏi nguồn ngân sách ổn định."},{"en":"Good policy fails without effective implementation on the ground.","vi":"Chính sách tốt sẽ thất bại nếu không có việc triển khai hiệu quả trên thực tế."},{"en":"Training staff is key to effective implementation.","vi":"Đào tạo nhân viên là chìa khóa cho việc triển khai hiệu quả."}]', '[]', NULL, '/ɪˈfektɪv ˌɪmplɪmenˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 35, 'effective intervention', 'biện pháp can thiệp hiệu quả', 'adj + n', '[{"en":"Early support proved an effective intervention for struggling readers.","vi":"Hỗ trợ sớm tỏ ra là một biện pháp can thiệp hiệu quả cho học sinh đọc kém."},{"en":"The trial tested an effective intervention against childhood obesity.","vi":"Thử nghiệm kiểm tra một biện pháp can thiệp hiệu quả chống béo phì ở trẻ em."},{"en":"An effective intervention can prevent the disease from spreading.","vi":"Một biện pháp can thiệp hiệu quả có thể ngăn bệnh lây lan."}]', '[]', NULL, '/ɪˈfektɪv ˌɪntərˈvenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 36, 'effective management', 'sự quản lý hiệu quả', 'adj + n', '[{"en":"Effective management of resources reduced the project''s costs.","vi":"Sự quản lý hiệu quả các nguồn lực đã giảm chi phí dự án."},{"en":"The hospital is praised for its effective management.","vi":"Bệnh viện được khen ngợi vì sự quản lý hiệu quả."},{"en":"Effective management requires clear communication and planning.","vi":"Sự quản lý hiệu quả đòi hỏi giao tiếp và lập kế hoạch rõ ràng."}]', '[]', NULL, '/ɪˈfektɪv ˈmænɪdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 37, 'effective method', 'phương pháp hiệu quả', 'adj + n', '[{"en":"Repetition is an effective method for learning vocabulary.","vi":"Lặp lại là một phương pháp hiệu quả để học từ vựng."},{"en":"The study identified the most effective method of teaching reading.","vi":"Nghiên cứu xác định phương pháp hiệu quả nhất để dạy đọc."},{"en":"Vaccination remains an effective method of disease prevention.","vi":"Tiêm chủng vẫn là một phương pháp hiệu quả để phòng bệnh."}]', '[]', NULL, '/ɪˈfektɪv ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 38, 'effective participation', 'sự tham gia hiệu quả', 'adj + n', '[{"en":"Effective participation in meetings requires careful preparation.","vi":"Sự tham gia hiệu quả vào các cuộc họp đòi hỏi sự chuẩn bị kỹ lưỡng."},{"en":"The system encourages effective participation by all citizens.","vi":"Hệ thống khuyến khích sự tham gia hiệu quả của mọi công dân."},{"en":"Language barriers can limit effective participation in class.","vi":"Rào cản ngôn ngữ có thể hạn chế sự tham gia hiệu quả trong lớp."}]', '[]', NULL, '/ɪˈfektɪv pɑːrˌtɪsɪˈpeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 39, 'effective policy', 'chính sách hiệu quả', 'adj + n', '[{"en":"An effective policy needs both funding and public support.","vi":"Một chính sách hiệu quả cần cả ngân sách lẫn sự ủng hộ của công chúng."},{"en":"The government introduced an effective policy to cut emissions.","vi":"Chính phủ đưa ra một chính sách hiệu quả để cắt giảm khí thải."},{"en":"Effective policy depends on accurate, up-to-date data.","vi":"Chính sách hiệu quả phụ thuộc vào dữ liệu chính xác và cập nhật."}]', '[]', NULL, '/ɪˈfektɪv ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 40, 'effective treatment', 'phương pháp điều trị hiệu quả', 'adj + n', '[{"en":"Doctors are searching for an effective treatment for the virus.","vi":"Các bác sĩ đang tìm kiếm một phương pháp điều trị hiệu quả cho loại virus này."},{"en":"Early diagnosis allows more effective treatment of cancer.","vi":"Chẩn đoán sớm cho phép điều trị ung thư hiệu quả hơn."},{"en":"The new drug offers an effective treatment with few side effects.","vi":"Loại thuốc mới mang lại phương pháp điều trị hiệu quả với ít tác dụng phụ."}]', '[]', NULL, '/ɪˈfektɪv ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 41, 'electronic access', 'truy cập điện tử', 'adj + n', '[{"en":"The library provides electronic access to thousands of journals.","vi":"Thư viện cung cấp truy cập điện tử đến hàng nghìn tạp chí."},{"en":"Students gain electronic access to course materials online.","vi":"Sinh viên có truy cập điện tử đến tài liệu khóa học trực tuyến."},{"en":"Electronic access lets researchers work from anywhere.","vi":"Truy cập điện tử cho phép nhà nghiên cứu làm việc từ bất cứ đâu."}]', '[]', NULL, '/ɪˌlekˈtrɑːnɪk ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 42, 'electronic communication', 'giao tiếp điện tử', 'adj + n', '[{"en":"Electronic communication has largely replaced traditional letters.","vi":"Giao tiếp điện tử đã phần lớn thay thế thư từ truyền thống."},{"en":"The company relies on electronic communication between offices.","vi":"Công ty dựa vào giao tiếp điện tử giữa các văn phòng."},{"en":"Electronic communication allows instant contact across continents.","vi":"Giao tiếp điện tử cho phép liên lạc tức thời giữa các châu lục."}]', '[]', NULL, '/ɪˌlekˈtrɑːnɪk kəˌmjuːnɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 43, 'electronic media', 'phương tiện truyền thông điện tử', 'adj + n', '[{"en":"Young people get most of their news from electronic media.","vi":"Người trẻ tiếp nhận hầu hết tin tức từ phương tiện truyền thông điện tử."},{"en":"Electronic media now shape public opinion more than newspapers.","vi":"Phương tiện truyền thông điện tử định hình dư luận nhiều hơn báo giấy."},{"en":"The study examines advertising in electronic media.","vi":"Nghiên cứu xem xét quảng cáo trên phương tiện truyền thông điện tử."}]', '[]', NULL, '/ɪˌlekˈtrɑːnɪk ˈmiːdiə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 44, 'electronic resources', 'tài nguyên điện tử', 'adj + n', '[{"en":"The university invests heavily in electronic resources each year.","vi":"Trường đại học đầu tư mạnh vào tài nguyên điện tử mỗi năm."},{"en":"Electronic resources make rare documents widely available.","vi":"Tài nguyên điện tử giúp các tài liệu hiếm có sẵn rộng rãi."},{"en":"Teachers integrate electronic resources into their lessons.","vi":"Giáo viên tích hợp tài nguyên điện tử vào bài giảng."}]', '[]', NULL, '/ɪˌlekˈtrɑːnɪk ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 45, 'electronic version', 'phiên bản điện tử', 'adj + n', '[{"en":"An electronic version of the book is available online.","vi":"Một phiên bản điện tử của cuốn sách có sẵn trực tuyến."},{"en":"The electronic version includes searchable footnotes and links.","vi":"Phiên bản điện tử bao gồm chú thích và liên kết có thể tìm kiếm."},{"en":"Readers can download the electronic version for free.","vi":"Độc giả có thể tải phiên bản điện tử miễn phí."}]', '[]', NULL, '/ɪˌlekˈtrɑːnɪk ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 46, 'emotional impact', 'tác động cảm xúc', 'adj + n', '[{"en":"The film had a powerful emotional impact on viewers.","vi":"Bộ phim có tác động cảm xúc mạnh mẽ đến người xem."},{"en":"Researchers studied the emotional impact of long-term illness.","vi":"Các nhà nghiên cứu nghiên cứu tác động cảm xúc của bệnh kéo dài."},{"en":"Losing a job can have a lasting emotional impact.","vi":"Mất việc có thể để lại tác động cảm xúc lâu dài."}]', '[]', NULL, '/ɪˈmoʊʃənəl ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 47, 'emotional intelligence', 'trí tuệ cảm xúc', 'adj + n', '[{"en":"Good leaders often show high emotional intelligence.","vi":"Những nhà lãnh đạo giỏi thường thể hiện trí tuệ cảm xúc cao."},{"en":"Emotional intelligence helps people manage stress at work.","vi":"Trí tuệ cảm xúc giúp con người kiểm soát căng thẳng trong công việc."},{"en":"Schools increasingly teach emotional intelligence to young children.","vi":"Các trường ngày càng dạy trí tuệ cảm xúc cho trẻ nhỏ."}]', '[]', NULL, '/ɪˈmoʊʃənəl ɪnˈtelɪdʒəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 48, 'emotional reaction', 'phản ứng cảm xúc', 'adj + n', '[{"en":"The news provoked a strong emotional reaction from the public.","vi":"Tin tức gây ra phản ứng cảm xúc mạnh mẽ từ công chúng."},{"en":"Her emotional reaction surprised everyone in the room.","vi":"Phản ứng cảm xúc của cô khiến mọi người trong phòng bất ngờ."},{"en":"The experiment measured each participant''s emotional reaction.","vi":"Thí nghiệm đo lường phản ứng cảm xúc của từng người tham gia."}]', '[]', NULL, '/ɪˈmoʊʃənəl riˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 49, 'emotional response', 'phản hồi cảm xúc', 'adj + n', '[{"en":"Music can trigger a deep emotional response in listeners.","vi":"Âm nhạc có thể khơi gợi phản hồi cảm xúc sâu sắc nơi người nghe."},{"en":"Advertisers try to create a positive emotional response.","vi":"Các nhà quảng cáo cố gắng tạo ra phản hồi cảm xúc tích cực."},{"en":"The study recorded children''s emotional responses to images.","vi":"Nghiên cứu ghi lại phản hồi cảm xúc của trẻ em với hình ảnh."}]', '[]', NULL, '/ɪˈmoʊʃənəl rɪˈspɑːns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 50, 'emotional support', 'hỗ trợ tinh thần', 'adj + n', '[{"en":"Friends provided valuable emotional support during her illness.","vi":"Bạn bè đã mang lại sự hỗ trợ tinh thần quý giá trong lúc cô bị bệnh."},{"en":"The group offers emotional support to grieving families.","vi":"Nhóm cung cấp hỗ trợ tinh thần cho những gia đình đang đau buồn."},{"en":"Children need emotional support as well as material care.","vi":"Trẻ em cần hỗ trợ tinh thần cũng như sự chăm sóc vật chất."}]', '[]', NULL, '/ɪˈmoʊʃənəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 51, 'empirical data', 'dữ liệu thực nghiệm', 'adj + n', '[{"en":"The theory is now supported by solid empirical data.","vi":"Lý thuyết hiện được hỗ trợ bởi dữ liệu thực nghiệm vững chắc."},{"en":"They collected empirical data from over a thousand patients.","vi":"Họ thu thập dữ liệu thực nghiệm từ hơn một nghìn bệnh nhân."},{"en":"Without empirical data, the claim remains mere speculation.","vi":"Nếu không có dữ liệu thực nghiệm, lập luận chỉ là phỏng đoán."}]', '[]', NULL, '/ɪmˈpɪrɪkəl ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 52, 'empirical evidence', 'bằng chứng thực nghiệm', 'adj + n', '[{"en":"There is strong empirical evidence linking smoking to cancer.","vi":"Có bằng chứng thực nghiệm mạnh mẽ liên hệ hút thuốc với ung thư."},{"en":"The hypothesis lacks sufficient empirical evidence to be accepted.","vi":"Giả thuyết thiếu bằng chứng thực nghiệm đầy đủ để được chấp nhận."},{"en":"Empirical evidence should guide policy decisions.","vi":"Bằng chứng thực nghiệm nên định hướng các quyết định chính sách."}]', '[]', NULL, '/ɪmˈpɪrɪkəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 53, 'empirical investigation', 'cuộc điều tra thực nghiệm', 'adj + n', '[{"en":"The claim deserves a careful empirical investigation.","vi":"Lập luận này xứng đáng được điều tra thực nghiệm cẩn thận."},{"en":"Their empirical investigation involved years of fieldwork.","vi":"Cuộc điều tra thực nghiệm của họ kéo dài nhiều năm thực địa."},{"en":"An empirical investigation tested the model against real cases.","vi":"Một cuộc điều tra thực nghiệm đã kiểm chứng mô hình với các trường hợp thực."}]', '[]', NULL, '/ɪmˈpɪrɪkəl ɪnˌvestɪˈɡeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 54, 'empirical research', 'nghiên cứu thực nghiệm', 'adj + n', '[{"en":"Empirical research is based on observation and experiment.","vi":"Nghiên cứu thực nghiệm dựa trên quan sát và thí nghiệm."},{"en":"Little empirical research exists on this specific question.","vi":"Có rất ít nghiên cứu thực nghiệm về câu hỏi cụ thể này."},{"en":"The journal publishes only rigorous empirical research.","vi":"Tạp chí chỉ công bố các nghiên cứu thực nghiệm chặt chẽ."}]', '[]', NULL, '/ɪmˈpɪrɪkəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 55, 'empirical study', 'nghiên cứu thực nghiệm', 'adj + n', '[{"en":"The empirical study surveyed five hundred small businesses.","vi":"Nghiên cứu thực nghiệm khảo sát năm trăm doanh nghiệp nhỏ."},{"en":"An empirical study confirmed the predicted relationship.","vi":"Một nghiên cứu thực nghiệm đã xác nhận mối quan hệ được dự đoán."},{"en":"Few empirical studies have tested this assumption directly.","vi":"Rất ít nghiên cứu thực nghiệm đã kiểm chứng giả định này một cách trực tiếp."}]', '[]', NULL, '/ɪmˈpɪrɪkəl ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 56, 'empirical support', 'sự ủng hộ thực nghiệm', 'adj + n', '[{"en":"The model has gained growing empirical support over time.","vi":"Mô hình ngày càng nhận được sự ủng hộ thực nghiệm theo thời gian."},{"en":"There is little empirical support for that bold claim.","vi":"Có rất ít sự ủng hộ thực nghiệm cho lập luận táo bạo đó."},{"en":"Recent experiments provide strong empirical support for the theory.","vi":"Các thí nghiệm gần đây cung cấp sự ủng hộ thực nghiệm mạnh mẽ cho lý thuyết."}]', '[]', NULL, '/ɪmˈpɪrɪkəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 57, 'empirical work', 'công trình thực nghiệm', 'adj + n', '[{"en":"Her empirical work focused on classroom behavior.","vi":"Công trình thực nghiệm của bà tập trung vào hành vi trong lớp học."},{"en":"The chapter reviews recent empirical work in the field.","vi":"Chương này điểm lại các công trình thực nghiệm gần đây trong lĩnh vực."},{"en":"More empirical work is needed to settle the debate.","vi":"Cần thêm các công trình thực nghiệm để giải quyết cuộc tranh luận."}]', '[]', NULL, '/ɪmˈpɪrɪkəl wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 58, 'employ a method', 'sử dụng một phương pháp', 'v + n', '[{"en":"The researchers employ a method that combines surveys and interviews.","vi":"Các nhà nghiên cứu sử dụng một phương pháp kết hợp khảo sát và phỏng vấn."},{"en":"We employ a method designed to reduce measurement error.","vi":"Chúng tôi sử dụng một phương pháp được thiết kế để giảm sai số đo lường."},{"en":"Scientists often employ a method tested in earlier studies.","vi":"Các nhà khoa học thường sử dụng một phương pháp đã được kiểm chứng trong các nghiên cứu trước."}]', '[]', NULL, '/ɪmˈplɔɪ ə ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 59, 'employ a technique', 'sử dụng một kỹ thuật', 'v + n', '[{"en":"Surgeons employ a technique that minimizes blood loss.","vi":"Các bác sĩ phẫu thuật sử dụng một kỹ thuật giảm thiểu mất máu."},{"en":"The artist employs a technique borrowed from traditional painting.","vi":"Người nghệ sĩ sử dụng một kỹ thuật vay mượn từ hội họa truyền thống."},{"en":"We employ a technique to test the sample for purity.","vi":"Chúng tôi sử dụng một kỹ thuật để kiểm tra độ tinh khiết của mẫu."}]', '[]', NULL, '/ɪmˈplɔɪ ə tekˈniːk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 60, 'employment opportunities', 'cơ hội việc làm', 'n + n', '[{"en":"The new factory created many employment opportunities locally.","vi":"Nhà máy mới tạo ra nhiều cơ hội việc làm tại địa phương."},{"en":"Better education expands employment opportunities for young people.","vi":"Giáo dục tốt hơn mở rộng cơ hội việc làm cho người trẻ."},{"en":"Rural areas often offer fewer employment opportunities.","vi":"Các vùng nông thôn thường có ít cơ hội việc làm hơn."}]', '[]', NULL, '/ɪmˈplɔɪmənt ˌɑːpərˈtuːnətiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 61, 'encounter difficulties', 'gặp phải khó khăn', 'v + n', '[{"en":"New students often encounter difficulties adjusting to university life.","vi":"Sinh viên mới thường gặp phải khó khăn khi thích nghi với đời sống đại học."},{"en":"The team encountered difficulties when collecting the data.","vi":"Nhóm gặp phải khó khăn khi thu thập dữ liệu."},{"en":"Migrants frequently encounter difficulties finding stable housing.","vi":"Người di cư thường gặp phải khó khăn trong việc tìm chỗ ở ổn định."}]', '[]', NULL, '/ɪnˈkaʊntər ˈdɪfɪkəltiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 62, 'encounter problems', 'gặp phải vấn đề', 'v + n', '[{"en":"Engineers encountered problems during the bridge''s construction.","vi":"Các kỹ sư gặp phải vấn đề trong quá trình xây dựng cây cầu."},{"en":"If you encounter problems, contact technical support immediately.","vi":"Nếu bạn gặp phải vấn đề, hãy liên hệ bộ phận hỗ trợ kỹ thuật ngay."},{"en":"Researchers may encounter problems with unreliable equipment.","vi":"Các nhà nghiên cứu có thể gặp phải vấn đề với thiết bị không đáng tin cậy."}]', '[]', NULL, '/ɪnˈkaʊntər ˈprɑːbləmz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 63, 'encourage the development of', 'thúc đẩy sự phát triển của', 'v + n', '[{"en":"The program aims to encourage the development of critical thinking.","vi":"Chương trình nhằm thúc đẩy sự phát triển của tư duy phản biện."},{"en":"Grants encourage the development of renewable energy technologies.","vi":"Các khoản tài trợ thúc đẩy sự phát triển của công nghệ năng lượng tái tạo."},{"en":"Good teaching can encourage the development of independent learners.","vi":"Dạy tốt có thể thúc đẩy sự phát triển của những người học tự lập."}]', '[]', NULL, '/ɪnˈkɜːrɪdʒ ðə dɪˈveləpmənt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 64, 'engage in an activity', 'tham gia vào một hoạt động', 'v + n', '[{"en":"Students who engage in an activity tend to remember it better.","vi":"Học sinh tham gia vào một hoạt động thường nhớ nó lâu hơn."},{"en":"We encourage children to engage in an activity that builds confidence.","vi":"Chúng tôi khuyến khích trẻ tham gia một hoạt động giúp xây dựng sự tự tin."},{"en":"Volunteers may engage in an activity outside their usual job duties.","vi":"Tình nguyện viên có thể tham gia một hoạt động ngoài nhiệm vụ thường ngày."}]', '[]', NULL, '/ɪnˈɡeɪdʒ ɪn ən ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 65, 'enhance learning', 'nâng cao việc học', 'v + n', '[{"en":"Interactive games can enhance learning for young children significantly.","vi":"Trò chơi tương tác có thể nâng cao việc học cho trẻ nhỏ đáng kể."},{"en":"Teachers use technology to enhance learning across all subjects.","vi":"Giáo viên dùng công nghệ để nâng cao việc học ở mọi môn."},{"en":"Regular feedback helps enhance learning and keeps students motivated.","vi":"Phản hồi thường xuyên giúp nâng cao việc học và duy trì động lực."}]', '[]', NULL, '/ɪnˈhæns ˈlɜːrnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 66, 'enhance performance', 'cải thiện hiệu suất', 'v + n', '[{"en":"Proper training can enhance performance in nearly every sport.","vi":"Tập luyện đúng cách có thể cải thiện hiệu suất ở hầu hết các môn thể thao."},{"en":"The new software was designed to enhance performance under heavy load.","vi":"Phần mềm mới được thiết kế để cải thiện hiệu suất khi tải nặng."},{"en":"Good sleep is known to enhance performance and concentration.","vi":"Ngủ đủ giấc được biết là giúp cải thiện hiệu suất và sự tập trung."}]', '[]', NULL, '/ɪnˈhæns pərˈfɔːrməns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 67, 'enormous amount of', 'một lượng khổng lồ', 'adj + n', '[{"en":"The project required an enormous amount of time and effort.","vi":"Dự án đòi hỏi một lượng khổng lồ thời gian và công sức."},{"en":"Researchers gathered an enormous amount of data over five years.","vi":"Các nhà nghiên cứu thu thập một lượng dữ liệu khổng lồ trong năm năm."},{"en":"An enormous amount of money was spent on the new stadium.","vi":"Một lượng tiền khổng lồ đã được chi cho sân vận động mới."}]', '[]', NULL, '/ɪˈnɔːrməs əˈmaʊnt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 68, 'enormous impact', 'tác động to lớn', 'adj + n', '[{"en":"The invention of the internet had an enormous impact on society.","vi":"Sự ra đời của internet đã có tác động to lớn lên xã hội."},{"en":"Her research made an enormous impact on modern medicine.","vi":"Nghiên cứu của cô đã tạo ra tác động to lớn lên y học hiện đại."},{"en":"Climate change is having an enormous impact on coastal cities.","vi":"Biến đổi khí hậu đang gây tác động to lớn lên các thành phố ven biển."}]', '[]', NULL, '/ɪˈnɔːrməs ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 69, 'entire period', 'toàn bộ thời kỳ', 'adj + n', '[{"en":"She studied abroad for the entire period of her degree.","vi":"Cô học ở nước ngoài suốt toàn bộ thời kỳ học vị của mình."},{"en":"Sales remained steady throughout the entire period of the year.","vi":"Doanh số ổn định suốt toàn bộ thời kỳ trong năm."},{"en":"The museum documents the entire period of the city''s growth.","vi":"Bảo tàng ghi lại toàn bộ thời kỳ phát triển của thành phố."}]', '[]', NULL, '/ɪnˈtaɪər ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 70, 'entire range of', 'toàn bộ phạm vi', 'adj + n', '[{"en":"The store offers the entire range of products from the brand.","vi":"Cửa hàng cung cấp toàn bộ phạm vi sản phẩm của thương hiệu."},{"en":"Her essay covered the entire range of arguments on the topic.","vi":"Bài luận của cô bao quát toàn bộ phạm vi lập luận về chủ đề này."},{"en":"The course explores the entire range of human emotions.","vi":"Khóa học khám phá toàn bộ phạm vi cảm xúc của con người."}]', '[]', NULL, '/ɪnˈtaɪər reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 71, 'entirely clear', 'hoàn toàn rõ ràng', 'adv + adj', '[{"en":"It is not entirely clear why the experiment failed.","vi":"Vẫn chưa hoàn toàn rõ ràng tại sao thí nghiệm thất bại."},{"en":"The instructions were not entirely clear to the new students.","vi":"Hướng dẫn không hoàn toàn rõ ràng với các học sinh mới."},{"en":"Her reasons for leaving were never entirely clear to us.","vi":"Lý do cô ra đi chưa bao giờ hoàn toàn rõ ràng với chúng tôi."}]', '[]', NULL, '/ɪnˈtaɪərli klɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 72, 'entirely different', 'hoàn toàn khác biệt', 'adv + adj', '[{"en":"The two theories lead to entirely different conclusions.","vi":"Hai lý thuyết dẫn đến những kết luận hoàn toàn khác biệt."},{"en":"Life in the countryside is entirely different from the city.","vi":"Cuộc sống ở nông thôn hoàn toàn khác biệt với thành phố."},{"en":"After the trip, she returned with an entirely different outlook.","vi":"Sau chuyến đi, cô trở về với một cái nhìn hoàn toàn khác biệt."}]', '[]', NULL, '/ɪnˈtaɪərli ˈdɪfrənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 73, 'entirely new', 'hoàn toàn mới', 'adv + adj', '[{"en":"The discovery opened up an entirely new field of study.","vi":"Phát hiện này mở ra một lĩnh vực nghiên cứu hoàn toàn mới."},{"en":"We need an entirely new approach to solve this problem.","vi":"Chúng ta cần một cách tiếp cận hoàn toàn mới để giải quyết vấn đề này."},{"en":"The company launched an entirely new line of products.","vi":"Công ty ra mắt một dòng sản phẩm hoàn toàn mới."}]', '[]', NULL, '/ɪnˈtaɪərli nuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 74, 'environmental changes', 'những thay đổi môi trường', 'adj + n', '[{"en":"Scientists study how species adapt to environmental changes.","vi":"Các nhà khoa học nghiên cứu cách loài thích nghi với những thay đổi môi trường."},{"en":"Environmental changes over decades have altered local farming.","vi":"Những thay đổi môi trường qua nhiều thập kỷ đã làm thay đổi nông nghiệp địa phương."},{"en":"The report tracks environmental changes in the Arctic region.","vi":"Báo cáo theo dõi những thay đổi môi trường ở vùng Bắc Cực."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˈtʃeɪndʒɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 75, 'environmental concern', 'mối quan ngại về môi trường', 'adj + n', '[{"en":"Pollution from factories is a major environmental concern today.","vi":"Ô nhiễm từ nhà máy là một mối quan ngại lớn về môi trường ngày nay."},{"en":"Plastic waste has become a serious environmental concern worldwide.","vi":"Rác thải nhựa đã trở thành mối quan ngại nghiêm trọng về môi trường toàn cầu."},{"en":"The new policy addresses growing environmental concern among citizens.","vi":"Chính sách mới giải quyết mối quan ngại môi trường ngày càng tăng của người dân."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl kənˈsɜːrn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 76, 'environmental consequences', 'hậu quả về môi trường', 'adj + n', '[{"en":"Mining can have severe environmental consequences for nearby rivers.","vi":"Khai thác mỏ có thể gây hậu quả môi trường nghiêm trọng cho các con sông gần đó."},{"en":"The study examines the environmental consequences of deforestation.","vi":"Nghiên cứu xem xét hậu quả về môi trường của nạn phá rừng."},{"en":"Few people considered the environmental consequences of the dam.","vi":"Ít người cân nhắc đến hậu quả môi trường của con đập."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˈkɑːnsəkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 77, 'environmental damage', 'thiệt hại về môi trường', 'adj + n', '[{"en":"The oil spill caused widespread environmental damage along the coast.","vi":"Vụ tràn dầu gây thiệt hại môi trường trên diện rộng dọc bờ biển."},{"en":"Stricter laws aim to reduce environmental damage from industry.","vi":"Luật nghiêm ngặt hơn nhằm giảm thiệt hại môi trường từ công nghiệp."},{"en":"Reversing environmental damage can take many decades.","vi":"Khắc phục thiệt hại môi trường có thể mất nhiều thập kỷ."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˈdæmɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 78, 'environmental degradation', 'sự suy thoái môi trường', 'adj + n', '[{"en":"Rapid urban growth often leads to environmental degradation.","vi":"Đô thị hóa nhanh thường dẫn đến sự suy thoái môi trường."},{"en":"The article links poverty with environmental degradation in rural areas.","vi":"Bài viết liên hệ đói nghèo với sự suy thoái môi trường ở vùng nông thôn."},{"en":"Conservation programs try to slow environmental degradation.","vi":"Các chương trình bảo tồn cố gắng làm chậm sự suy thoái môi trường."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˌdeɡrəˈdeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 79, 'environmental effects', 'các tác động môi trường', 'adj + n', '[{"en":"The committee assessed the environmental effects of the highway.","vi":"Ủy ban đánh giá các tác động môi trường của con đường cao tốc."},{"en":"Researchers measured the environmental effects of the chemical.","vi":"Các nhà nghiên cứu đo lường các tác động môi trường của hóa chất."},{"en":"We must understand the environmental effects before building begins.","vi":"Chúng ta phải hiểu các tác động môi trường trước khi khởi công."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ɪˈfekts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 80, 'environmental factors', 'các yếu tố môi trường', 'adj + n', '[{"en":"Environmental factors can influence a child''s development greatly.","vi":"Các yếu tố môi trường có thể ảnh hưởng lớn đến sự phát triển của trẻ."},{"en":"The study controlled for environmental factors such as temperature.","vi":"Nghiên cứu kiểm soát các yếu tố môi trường như nhiệt độ."},{"en":"Both genetic and environmental factors shape human behavior.","vi":"Cả yếu tố di truyền và môi trường đều định hình hành vi con người."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 81, 'environmental impact', 'tác động môi trường', 'adj + n', '[{"en":"Every new factory must submit an environmental impact report.","vi":"Mỗi nhà máy mới phải nộp báo cáo tác động môi trường."},{"en":"Electric cars have a smaller environmental impact than petrol ones.","vi":"Xe điện có tác động môi trường nhỏ hơn xe chạy xăng."},{"en":"The company aims to lower its environmental impact by half.","vi":"Công ty đặt mục tiêu giảm một nửa tác động môi trường của mình."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 82, 'environmental issues', 'các vấn đề môi trường', 'adj + n', '[{"en":"Young people are increasingly aware of environmental issues.","vi":"Giới trẻ ngày càng nhận thức rõ về các vấn đề môi trường."},{"en":"The debate focused on environmental issues facing the city.","vi":"Cuộc tranh luận tập trung vào các vấn đề môi trường mà thành phố đối mặt."},{"en":"Schools now include environmental issues in their curriculum.","vi":"Các trường học giờ đưa các vấn đề môi trường vào chương trình giảng dạy."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˈɪʃuːz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 83, 'environmental policy', 'chính sách môi trường', 'adj + n', '[{"en":"The government announced a new environmental policy this week.","vi":"Chính phủ công bố một chính sách môi trường mới trong tuần này."},{"en":"A strong environmental policy can protect natural resources.","vi":"Một chính sách môi trường mạnh mẽ có thể bảo vệ tài nguyên thiên nhiên."},{"en":"Critics argued that the environmental policy did not go far enough.","vi":"Những người chỉ trích cho rằng chính sách môi trường chưa đủ mạnh."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 84, 'environmental pollution', 'ô nhiễm môi trường', 'adj + n', '[{"en":"Environmental pollution from traffic harms people''s health daily.","vi":"Ô nhiễm môi trường từ giao thông gây hại cho sức khỏe mỗi ngày."},{"en":"The factory was fined for causing environmental pollution.","vi":"Nhà máy bị phạt vì gây ô nhiễm môi trường."},{"en":"Reducing environmental pollution requires cooperation between nations.","vi":"Giảm ô nhiễm môi trường đòi hỏi sự hợp tác giữa các quốc gia."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl pəˈluːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 85, 'environmental protection', 'bảo vệ môi trường', 'adj + n', '[{"en":"Environmental protection has become a global priority in recent years.","vi":"Bảo vệ môi trường đã trở thành ưu tiên toàn cầu trong những năm gần đây."},{"en":"The agency is responsible for environmental protection nationwide.","vi":"Cơ quan này chịu trách nhiệm bảo vệ môi trường trên toàn quốc."},{"en":"Many companies now invest heavily in environmental protection.","vi":"Nhiều công ty hiện đầu tư mạnh vào bảo vệ môi trường."}]', '[]', NULL, '/ɪnˌvaɪrənˈmentəl prəˈtekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 86, 'equal access', 'quyền tiếp cận bình đẳng', 'adj + n', '[{"en":"The policy guarantees equal access to education for all children.","vi":"Chính sách đảm bảo quyền tiếp cận giáo dục bình đẳng cho mọi trẻ em."},{"en":"Everyone should have equal access to clean drinking water.","vi":"Mọi người nên có quyền tiếp cận bình đẳng với nước uống sạch."},{"en":"The library provides equal access to digital resources for students.","vi":"Thư viện cung cấp quyền tiếp cận bình đẳng tới tài nguyên số cho sinh viên."}]', '[]', NULL, '/ˈiːkwəl ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 87, 'equal opportunity', 'cơ hội bình đẳng', 'adj + n', '[{"en":"The company promotes equal opportunity for all job applicants.","vi":"Công ty đề cao cơ hội bình đẳng cho mọi ứng viên xin việc."},{"en":"Equal opportunity in employment is protected by national law.","vi":"Cơ hội bình đẳng trong việc làm được luật pháp quốc gia bảo vệ."},{"en":"Schools should give every student an equal opportunity to succeed.","vi":"Trường học nên trao cho mỗi học sinh cơ hội bình đẳng để thành công."}]', '[]', NULL, '/ˈiːkwəl ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 88, 'equal status', 'địa vị bình đẳng', 'adj + n', '[{"en":"The treaty granted both languages equal status in the region.","vi":"Hiệp ước trao cho cả hai ngôn ngữ địa vị bình đẳng trong khu vực."},{"en":"Women fought for years to gain equal status in society.","vi":"Phụ nữ đấu tranh nhiều năm để giành địa vị bình đẳng trong xã hội."},{"en":"Both partners enjoy equal status within the organization.","vi":"Cả hai đối tác có địa vị bình đẳng trong tổ chức."}]', '[]', NULL, '/ˈiːkwəl ˈstætəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 89, 'equal treatment', 'sự đối xử bình đẳng', 'adj + n', '[{"en":"All employees deserve equal treatment regardless of their background.","vi":"Mọi nhân viên xứng đáng được đối xử bình đẳng bất kể xuất thân."},{"en":"The law demands equal treatment of men and women at work.","vi":"Luật yêu cầu sự đối xử bình đẳng giữa nam và nữ tại nơi làm việc."},{"en":"Patients expect equal treatment from every hospital in the country.","vi":"Bệnh nhân mong đợi sự đối xử bình đẳng từ mọi bệnh viện trong nước."}]', '[]', NULL, '/ˈiːkwəl ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 90, 'equally important', 'quan trọng như nhau', 'adv + adj', '[{"en":"Both reading and writing skills are equally important for students.","vi":"Cả kỹ năng đọc và viết đều quan trọng như nhau với học sinh."},{"en":"Diet and exercise are equally important for good health.","vi":"Chế độ ăn và tập luyện đều quan trọng như nhau cho sức khỏe tốt."},{"en":"It is equally important to listen as well as to speak.","vi":"Lắng nghe cũng quan trọng như nhau so với việc nói."}]', '[]', NULL, '/ˈiːkwəli ɪmˈpɔːrtənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 91, 'equally likely', 'có khả năng ngang nhau', 'adv + adj', '[{"en":"Both outcomes are equally likely when the coin is fair.","vi":"Cả hai kết quả đều có khả năng ngang nhau khi đồng xu công bằng."},{"en":"Men and women are equally likely to choose this career.","vi":"Nam và nữ có khả năng ngang nhau khi chọn nghề này."},{"en":"It is equally likely that either team will win the match.","vi":"Khả năng ngang nhau cho việc đội nào cũng có thể thắng trận đấu."}]', '[]', NULL, '/ˈiːkwəli ˈlaɪkli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 92, 'equally true', 'cũng đúng như vậy', 'adv + adj', '[{"en":"The rule is equally true for beginners and experts alike.","vi":"Quy tắc này cũng đúng như vậy với cả người mới và chuyên gia."},{"en":"What applies to one country is equally true for another.","vi":"Điều áp dụng cho một quốc gia cũng đúng như vậy với quốc gia khác."},{"en":"This statement is equally true in theory and in practice.","vi":"Phát biểu này cũng đúng như vậy cả trên lý thuyết lẫn thực tế."}]', '[]', NULL, '/ˈiːkwəli truː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 93, 'equally valid', 'có giá trị ngang nhau', 'adv + adj', '[{"en":"Both interpretations of the poem seem equally valid to me.","vi":"Cả hai cách diễn giải bài thơ với tôi đều có giá trị ngang nhau."},{"en":"Her argument is equally valid despite using different evidence.","vi":"Lập luận của cô có giá trị ngang nhau dù dùng bằng chứng khác."},{"en":"These two methods are equally valid for solving the equation.","vi":"Hai phương pháp này có giá trị ngang nhau để giải phương trình."}]', '[]', NULL, '/ˈiːkwəli ˈvælɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 94, 'essential component', 'thành phần thiết yếu', 'adj + n', '[{"en":"Trust is an essential component of any healthy relationship.","vi":"Lòng tin là thành phần thiết yếu của mọi mối quan hệ lành mạnh."},{"en":"Water is an essential component of every living cell.","vi":"Nước là thành phần thiết yếu của mọi tế bào sống."},{"en":"Practice is an essential component of learning a language.","vi":"Luyện tập là thành phần thiết yếu của việc học một ngôn ngữ."}]', '[]', NULL, '/ɪˈsenʃəl kəmˈpoʊnənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 95, 'essential element', 'yếu tố thiết yếu', 'adj + n', '[{"en":"Clear communication is an essential element of good teamwork.","vi":"Giao tiếp rõ ràng là yếu tố thiết yếu của làm việc nhóm tốt."},{"en":"Suspense is an essential element of a gripping novel.","vi":"Sự hồi hộp là yếu tố thiết yếu của một cuốn tiểu thuyết hấp dẫn."},{"en":"Sunlight is an essential element for healthy plant growth.","vi":"Ánh nắng là yếu tố thiết yếu cho sự phát triển khỏe mạnh của cây."}]', '[]', NULL, '/ɪˈsenʃəl ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 96, 'essential feature', 'đặc điểm thiết yếu', 'adj + n', '[{"en":"Flexibility is an essential feature of the new software design.","vi":"Sự linh hoạt là đặc điểm thiết yếu của thiết kế phần mềm mới."},{"en":"Symmetry is an essential feature of many traditional buildings.","vi":"Sự đối xứng là đặc điểm thiết yếu của nhiều tòa nhà truyền thống."},{"en":"Repetition is an essential feature of effective advertising.","vi":"Sự lặp lại là đặc điểm thiết yếu của quảng cáo hiệu quả."}]', '[]', NULL, '/ɪˈsenʃəl ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 97, 'essential function', 'chức năng thiết yếu', 'adj + n', '[{"en":"The heart performs an essential function in the human body.","vi":"Tim thực hiện một chức năng thiết yếu trong cơ thể con người."},{"en":"Storing memory is an essential function of the brain.","vi":"Lưu trữ ký ức là chức năng thiết yếu của não bộ."},{"en":"Filtering waste is an essential function of the kidneys.","vi":"Lọc chất thải là chức năng thiết yếu của thận."}]', '[]', NULL, '/ɪˈsenʃəl ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 98, 'essential information', 'thông tin thiết yếu', 'adj + n', '[{"en":"The first page contains all the essential information you need.","vi":"Trang đầu chứa tất cả thông tin thiết yếu bạn cần."},{"en":"Always read the essential information before signing any contract.","vi":"Hãy luôn đọc thông tin thiết yếu trước khi ký bất kỳ hợp đồng nào."},{"en":"The guide highlights essential information for new travelers.","vi":"Cẩm nang nêu bật thông tin thiết yếu cho khách du lịch mới."}]', '[]', NULL, '/ɪˈsenʃəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 99, 'essential role', 'vai trò thiết yếu', 'adj + n', '[{"en":"Teachers play an essential role in shaping young minds.","vi":"Giáo viên đóng vai trò thiết yếu trong việc định hình tư duy trẻ."},{"en":"Bees serve an essential role in pollinating crops.","vi":"Ong giữ vai trò thiết yếu trong việc thụ phấn cho cây trồng."},{"en":"Sleep has an essential role in maintaining good health.","vi":"Giấc ngủ có vai trò thiết yếu trong việc duy trì sức khỏe tốt."}]', '[]', NULL, '/ɪˈsenʃəl roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 100, 'establish a relationship', 'thiết lập một mối quan hệ', 'v + n', '[{"en":"Companies work hard to establish a relationship with new clients.","vi":"Các công ty nỗ lực để thiết lập một mối quan hệ với khách hàng mới."},{"en":"It takes time to establish a relationship built on trust.","vi":"Cần thời gian để thiết lập một mối quan hệ dựa trên lòng tin."},{"en":"The two nations sought to establish a relationship after the war.","vi":"Hai quốc gia tìm cách thiết lập một mối quan hệ sau chiến tranh."}]', '[]', NULL, '/ɪˈstæblɪʃ ə rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 101, 'established order', 'trật tự đã được thiết lập', 'adj + n', '[{"en":"The revolution challenged the established order of the time.","vi":"Cuộc cách mạng thách thức trật tự đã được thiết lập của thời đó."},{"en":"Many feared that the reforms would upset the established order.","vi":"Nhiều người lo rằng cải cách sẽ phá vỡ trật tự đã được thiết lập."},{"en":"New ideas often clash with the established order in society.","vi":"Ý tưởng mới thường xung đột với trật tự đã được thiết lập trong xã hội."}]', '[]', NULL, '/ɪˈstæblɪʃt ˈɔːrdər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 102, 'established practice', 'thông lệ đã được thiết lập', 'adj + n', '[{"en":"Reviewing the literature first is established practice in research.","vi":"Đọc tài liệu trước là thông lệ đã được thiết lập trong nghiên cứu."},{"en":"It is established practice to back up data every evening.","vi":"Sao lưu dữ liệu mỗi tối là thông lệ đã được thiết lập."},{"en":"Following the established practice helps avoid common mistakes.","vi":"Tuân theo thông lệ đã được thiết lập giúp tránh các lỗi phổ biến."}]', '[]', NULL, '/ɪˈstæblɪʃt ˈpræktɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 103, 'established principle', 'nguyên tắc đã được thiết lập', 'adj + n', '[{"en":"Fair trial is an established principle in most legal systems.","vi":"Xét xử công bằng là nguyên tắc đã được thiết lập trong hầu hết hệ thống pháp luật."},{"en":"The theory rests on a well established principle of physics.","vi":"Lý thuyết dựa trên một nguyên tắc vật lý đã được thiết lập vững chắc."},{"en":"Respect for others is an established principle in our school.","vi":"Tôn trọng người khác là nguyên tắc đã được thiết lập ở trường chúng tôi."}]', '[]', NULL, '/ɪˈstæblɪʃt ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 104, 'ethical consideration', 'cân nhắc về đạo đức', 'adj + n', '[{"en":"Every medical trial must take ethical consideration into account.","vi":"Mọi thử nghiệm y khoa phải tính đến cân nhắc về đạo đức."},{"en":"Ethical consideration guided the researchers throughout the study.","vi":"Cân nhắc về đạo đức dẫn dắt các nhà nghiên cứu suốt cuộc nghiên cứu."},{"en":"The committee discussed ethical consideration before approving funding.","vi":"Ủy ban bàn về cân nhắc đạo đức trước khi phê duyệt tài trợ."}]', '[]', NULL, '/ˈeθɪkəl kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 105, 'ethical dilemma', 'tình huống tiến thoái lưỡng nan về đạo đức', 'adj + n', '[{"en":"The doctor faced a difficult ethical dilemma over the treatment.","vi":"Bác sĩ đối mặt với một tình huống lưỡng nan về đạo đức trong việc điều trị."},{"en":"Journalists often confront an ethical dilemma when reporting tragedies.","vi":"Nhà báo thường gặp tình huống lưỡng nan về đạo đức khi đưa tin bi kịch."},{"en":"The novel explores an ethical dilemma about loyalty and truth.","vi":"Cuốn tiểu thuyết khám phá tình huống lưỡng nan về đạo đức giữa lòng trung thành và sự thật."}]', '[]', NULL, '/ˈeθɪkəl dɪˈlemə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 106, 'ethical issue', 'vấn đề đạo đức', 'adj + n', '[{"en":"Cloning raises a serious ethical issue for many scientists.","vi":"Nhân bản đặt ra một vấn đề đạo đức nghiêm trọng với nhiều nhà khoa học."},{"en":"The class debated an ethical issue surrounding artificial intelligence.","vi":"Lớp học tranh luận về một vấn đề đạo đức xoay quanh trí tuệ nhân tạo."},{"en":"Privacy has become a major ethical issue in the digital age.","vi":"Quyền riêng tư đã trở thành vấn đề đạo đức lớn trong thời đại số."}]', '[]', NULL, '/ˈeθɪkəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 107, 'ethical principle', 'nguyên tắc đạo đức', 'adj + n', '[{"en":"Honesty is a basic ethical principle taught to every child.","vi":"Trung thực là một nguyên tắc đạo đức cơ bản dạy cho mọi đứa trẻ."},{"en":"The profession is guided by a strict ethical principle of care.","vi":"Nghề này được dẫn dắt bởi một nguyên tắc đạo đức nghiêm ngặt về sự chăm sóc."},{"en":"Respecting consent is a key ethical principle in research.","vi":"Tôn trọng sự đồng ý là nguyên tắc đạo đức then chốt trong nghiên cứu."}]', '[]', NULL, '/ˈeθɪkəl ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 108, 'ethical problem', 'vấn đề đạo đức', 'adj + n', '[{"en":"Using animals in testing poses a real ethical problem.","vi":"Dùng động vật để thử nghiệm đặt ra một vấn đề đạo đức thực sự."},{"en":"The lawyer saw an ethical problem with accepting the case.","vi":"Luật sư nhận ra một vấn đề đạo đức khi nhận vụ án này."},{"en":"Sharing private data creates a clear ethical problem for firms.","vi":"Chia sẻ dữ liệu riêng tư tạo ra một vấn đề đạo đức rõ ràng cho doanh nghiệp."}]', '[]', NULL, '/ˈeθɪkəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 109, 'ethical question', 'câu hỏi đạo đức', 'adj + n', '[{"en":"The discovery raises a difficult ethical question for scientists.","vi":"Phát hiện này đặt ra một câu hỏi đạo đức khó cho các nhà khoa học."},{"en":"Whether to tell the truth was a tough ethical question.","vi":"Có nên nói sự thật hay không là một câu hỏi đạo đức khó."},{"en":"The film leaves the audience with a powerful ethical question.","vi":"Bộ phim để lại cho khán giả một câu hỏi đạo đức mạnh mẽ."}]', '[]', NULL, '/ˈeθɪkəl ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 110, 'ethnic community', 'cộng đồng dân tộc', 'adj + n', '[{"en":"The festival celebrates the traditions of each ethnic community.","vi":"Lễ hội tôn vinh truyền thống của mỗi cộng đồng dân tộc."},{"en":"The city is home to a large ethnic community from Asia.","vi":"Thành phố là nơi sinh sống của một cộng đồng dân tộc lớn từ châu Á."},{"en":"Local schools serve children from every ethnic community nearby.","vi":"Trường học địa phương phục vụ trẻ em từ mọi cộng đồng dân tộc lân cận."}]', '[]', NULL, '/ˈeθnɪk kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 111, 'ethnic differences', 'sự khác biệt về dân tộc', 'adj + n', '[{"en":"The study examined ethnic differences in eating habits.","vi":"Nghiên cứu xem xét sự khác biệt về dân tộc trong thói quen ăn uống."},{"en":"Respecting ethnic differences strengthens harmony in the workplace.","vi":"Tôn trọng sự khác biệt về dân tộc củng cố sự hòa hợp nơi làm việc."},{"en":"Ethnic differences should be celebrated rather than feared.","vi":"Sự khác biệt về dân tộc nên được tôn vinh thay vì lo ngại."}]', '[]', NULL, '/ˈeθnɪk ˈdɪfrənsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 112, 'ethnic diversity', 'sự đa dạng dân tộc', 'adj + n', '[{"en":"The city is famous for its rich ethnic diversity.","vi":"Thành phố nổi tiếng với sự đa dạng dân tộc phong phú."},{"en":"Ethnic diversity brings new ideas and cuisines to the region.","vi":"Sự đa dạng dân tộc mang đến ý tưởng và ẩm thực mới cho khu vực."},{"en":"The university values ethnic diversity among its students.","vi":"Trường đại học coi trọng sự đa dạng dân tộc trong sinh viên."}]', '[]', NULL, '/ˈeθnɪk daɪˈvɜːrsəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 113, 'ethnic group', 'nhóm dân tộc', 'adj + n', '[{"en":"Each ethnic group in the country has its own language.","vi":"Mỗi nhóm dân tộc trong nước có ngôn ngữ riêng."},{"en":"The survey included people from every major ethnic group.","vi":"Cuộc khảo sát bao gồm người từ mọi nhóm dân tộc chính."},{"en":"This ethnic group has lived in the mountains for centuries.","vi":"Nhóm dân tộc này đã sống ở vùng núi trong nhiều thế kỷ."}]', '[]', NULL, '/ˈeθnɪk ɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 114, 'ethnic identity', 'bản sắc dân tộc', 'adj + n', '[{"en":"Language plays a key role in shaping ethnic identity.","vi":"Ngôn ngữ đóng vai trò then chốt trong việc định hình bản sắc dân tộc."},{"en":"Many people take pride in their ethnic identity and heritage.","vi":"Nhiều người tự hào về bản sắc dân tộc và di sản của mình."},{"en":"Migration can complicate a person''s sense of ethnic identity.","vi":"Di cư có thể làm phức tạp cảm nhận về bản sắc dân tộc của một người."}]', '[]', NULL, '/ˈeθnɪk aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 115, 'ethnic minority', 'dân tộc thiểu số', 'adj + n', '[{"en":"The government introduced programs to support each ethnic minority.","vi":"Chính phủ giới thiệu các chương trình hỗ trợ mỗi dân tộc thiểu số."},{"en":"Members of the ethnic minority preserve their ancient customs.","vi":"Các thành viên dân tộc thiểu số gìn giữ phong tục cổ xưa của họ."},{"en":"The report studied access to healthcare among ethnic minority groups.","vi":"Báo cáo nghiên cứu việc tiếp cận y tế trong các nhóm dân tộc thiểu số."}]', '[]', NULL, '/ˈeθnɪk maɪˈnɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 116, 'ethnic origin', 'nguồn gốc dân tộc', 'adj + n', '[{"en":"Job applicants should not be judged by their ethnic origin.","vi":"Ứng viên không nên bị đánh giá dựa trên nguồn gốc dân tộc của họ."},{"en":"The form asks respondents to state their ethnic origin.","vi":"Biểu mẫu yêu cầu người trả lời nêu nguồn gốc dân tộc của mình."},{"en":"People of every ethnic origin are welcome at the event.","vi":"Mọi người thuộc mọi nguồn gốc dân tộc đều được chào đón tại sự kiện."}]', '[]', NULL, '/ˈeθnɪk ˈɔːrɪdʒɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 117, 'ever changing', 'luôn thay đổi', 'adv + adj', '[{"en":"Technology operates in an ever changing global marketplace.","vi":"Công nghệ vận hành trong một thị trường toàn cầu luôn thay đổi."},{"en":"Fashion trends are ever changing and hard to predict.","vi":"Xu hướng thời trang luôn thay đổi và khó dự đoán."},{"en":"Teachers must adapt to the ever changing needs of students.","vi":"Giáo viên phải thích nghi với nhu cầu luôn thay đổi của học sinh."}]', '[]', NULL, '/ˈevər ˈtʃeɪndʒɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 118, 'ever increasing', 'không ngừng gia tăng', 'adv + adj', '[{"en":"The company faces ever increasing demand for its products.","vi":"Công ty đối mặt với nhu cầu không ngừng gia tăng đối với sản phẩm."},{"en":"There is an ever increasing amount of data to manage.","vi":"Có một lượng dữ liệu không ngừng gia tăng cần quản lý."},{"en":"Cities struggle with the ever increasing cost of housing.","vi":"Các thành phố vật lộn với chi phí nhà ở không ngừng gia tăng."}]', '[]', NULL, '/ˈevər ɪnˈkriːsɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 119, 'evolutionary process', 'quá trình tiến hóa', 'adj + n', '[{"en":"The evolutionary process shaped the wings of birds over time.","vi":"Quá trình tiến hóa đã định hình đôi cánh của chim theo thời gian."},{"en":"Language develops through a slow evolutionary process across generations.","vi":"Ngôn ngữ phát triển qua một quá trình tiến hóa chậm qua các thế hệ."},{"en":"Scientists trace the evolutionary process using fossil evidence.","vi":"Các nhà khoa học truy nguyên quá trình tiến hóa bằng bằng chứng hóa thạch."}]', '[]', NULL, '/ˌevəˈluːʃəneri ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 120, 'evolutionary theory', 'thuyết tiến hóa', 'adj + n', '[{"en":"Evolutionary theory explains how species change over many generations.","vi":"Thuyết tiến hóa giải thích cách các loài thay đổi qua nhiều thế hệ."},{"en":"Darwin''s evolutionary theory transformed the study of biology.","vi":"Thuyết tiến hóa của Darwin đã làm thay đổi việc nghiên cứu sinh học."},{"en":"The professor lectured on evolutionary theory for two hours.","vi":"Giáo sư giảng về thuyết tiến hóa trong hai giờ."}]', '[]', NULL, '/ˌevəˈluːʃəneri ˈθɪəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 121, 'examine the role of', 'xem xét vai trò của', 'v + n', '[{"en":"This essay will examine the role of women in the revolution.","vi":"Bài luận này sẽ xem xét vai trò của phụ nữ trong cuộc cách mạng."},{"en":"Researchers examine the role of stress in causing illness.","vi":"Các nhà nghiên cứu xem xét vai trò của căng thẳng trong việc gây bệnh."},{"en":"The chapter examines the role of media in shaping opinion.","vi":"Chương này xem xét vai trò của truyền thông trong việc định hình dư luận."}]', '[]', NULL, '/ɪɡˈzæmɪn ðə roʊl əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 122, 'exceptional case', 'trường hợp ngoại lệ', 'adj + n', '[{"en":"The committee approved the request only as an exceptional case.","vi":"Ủy ban chỉ chấp thuận yêu cầu như một trường hợp ngoại lệ."},{"en":"Refunds are given solely in an exceptional case like illness.","vi":"Hoàn tiền chỉ được thực hiện trong trường hợp ngoại lệ như ốm đau."},{"en":"Her recovery was an exceptional case that surprised the doctors.","vi":"Sự hồi phục của cô là trường hợp ngoại lệ khiến các bác sĩ ngạc nhiên."}]', '[]', NULL, '/ɪkˈsepʃənəl keɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 123, 'exceptional circumstances', 'hoàn cảnh đặc biệt', 'adj + n', '[{"en":"Late submissions are accepted only under exceptional circumstances.","vi":"Nộp muộn chỉ được chấp nhận trong hoàn cảnh đặc biệt."},{"en":"The law allows exceptions in exceptional circumstances such as war.","vi":"Luật cho phép ngoại lệ trong hoàn cảnh đặc biệt như chiến tranh."},{"en":"Only in exceptional circumstances will the deadline be extended.","vi":"Hạn chót chỉ được gia hạn trong hoàn cảnh đặc biệt."}]', '[]', NULL, '/ɪkˈsepʃənəl ˈsɜːrkəmstænsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 124, 'exercise authority', 'thực thi quyền lực', 'v + n', '[{"en":"The manager must exercise authority fairly over the whole team.","vi":"Người quản lý phải thực thi quyền lực một cách công bằng với cả nhóm."},{"en":"Judges exercise authority granted to them by the constitution.","vi":"Các thẩm phán thực thi quyền lực được hiến pháp trao cho họ."},{"en":"A good leader knows when to exercise authority and when to listen.","vi":"Một lãnh đạo giỏi biết khi nào nên thực thi quyền lực và khi nào nên lắng nghe."}]', '[]', NULL, '/ˈeksərsaɪz əˈθɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 125, 'existing data', 'dữ liệu hiện có', 'adj + n', '[{"en":"The researchers analyzed existing data before collecting new samples.","vi":"Các nhà nghiên cứu phân tích dữ liệu hiện có trước khi thu thập mẫu mới."},{"en":"Existing data suggests a strong link between diet and health.","vi":"Dữ liệu hiện có cho thấy mối liên hệ chặt chẽ giữa chế độ ăn và sức khỏe."},{"en":"We reviewed existing data to identify gaps in the literature.","vi":"Chúng tôi rà soát dữ liệu hiện có để tìm lỗ hổng trong tài liệu."}]', '[]', NULL, '/ɪɡˈzɪstɪŋ ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 126, 'existing research', 'nghiên cứu hiện có', 'adj + n', '[{"en":"Existing research supports the idea that exercise improves mood.","vi":"Nghiên cứu hiện có ủng hộ ý kiến rằng tập thể dục cải thiện tâm trạng."},{"en":"Her thesis builds on existing research in the field.","vi":"Luận văn của cô dựa trên nghiên cứu hiện có trong lĩnh vực này."},{"en":"The author criticized gaps in the existing research on the topic.","vi":"Tác giả phê phán những lỗ hổng trong nghiên cứu hiện có về chủ đề này."}]', '[]', NULL, '/ɪɡˈzɪstɪŋ ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 127, 'existing structure', 'cấu trúc hiện có', 'adj + n', '[{"en":"The plan adds a new wing to the existing structure.","vi":"Kế hoạch xây thêm một cánh mới vào cấu trúc hiện có."},{"en":"Engineers tested whether the existing structure could bear the load.","vi":"Các kỹ sư kiểm tra xem cấu trúc hiện có có chịu được tải trọng không."},{"en":"Reform should improve, not destroy, the existing structure of government.","vi":"Cải cách nên cải thiện, không phá hủy, cấu trúc hiện có của chính quyền."}]', '[]', NULL, '/ɪɡˈzɪstɪŋ ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 128, 'expand rapidly', 'mở rộng nhanh chóng', 'v + adv', '[{"en":"The city began to expand rapidly after the railway opened.","vi":"Thành phố bắt đầu mở rộng nhanh chóng sau khi tuyến đường sắt mở."},{"en":"Online businesses can expand rapidly with little upfront cost.","vi":"Doanh nghiệp trực tuyến có thể mở rộng nhanh chóng với chi phí ban đầu thấp."},{"en":"The population continued to expand rapidly throughout the century.","vi":"Dân số tiếp tục mở rộng nhanh chóng suốt thế kỷ."}]', '[]', NULL, '/ɪkˈspænd ˈræpɪdli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 129, 'experience difficulties', 'gặp khó khăn', 'v + n', '[{"en":"Many students experience difficulties when starting university life.","vi":"Nhiều sinh viên gặp khó khăn khi bắt đầu cuộc sống đại học."},{"en":"Small firms often experience difficulties during an economic downturn.","vi":"Các doanh nghiệp nhỏ thường gặp khó khăn trong thời kỳ suy thoái kinh tế."},{"en":"Travelers may experience difficulties with the local language.","vi":"Du khách có thể gặp khó khăn với ngôn ngữ địa phương."}]', '[]', NULL, '/ɪkˈspɪriəns ˈdɪfɪkəltiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 130, 'experience problems', 'gặp vấn đề', 'v + n', '[{"en":"Users may experience problems if the software is not updated.","vi":"Người dùng có thể gặp vấn đề nếu phần mềm không được cập nhật."},{"en":"The factory began to experience problems with old machinery.","vi":"Nhà máy bắt đầu gặp vấn đề với máy móc cũ."},{"en":"Patients sometimes experience problems sleeping after the surgery.","vi":"Bệnh nhân đôi khi gặp vấn đề về giấc ngủ sau phẫu thuật."}]', '[]', NULL, '/ɪkˈspɪriəns ˈprɑːbləmz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 131, 'experiential learning', 'học tập qua trải nghiệm', 'adj + n', '[{"en":"Experiential learning lets students gain skills through real practice.","vi":"Học tập qua trải nghiệm cho phép sinh viên có kỹ năng qua thực hành thực tế."},{"en":"The internship is built around experiential learning in the field.","vi":"Kỳ thực tập được xây dựng quanh việc học tập qua trải nghiệm thực tế."},{"en":"Teachers use experiential learning to make lessons more engaging.","vi":"Giáo viên dùng học tập qua trải nghiệm để bài học hấp dẫn hơn."}]', '[]', NULL, '/ɪkˌspɪriˈenʃəl ˈlɜːrnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 132, 'experimental conditions', 'điều kiện thí nghiệm', 'adj + n', '[{"en":"The results were the same under different experimental conditions.","vi":"Kết quả vẫn giống nhau dưới các điều kiện thí nghiệm khác nhau."},{"en":"Scientists carefully controlled the experimental conditions in the lab.","vi":"Các nhà khoa học kiểm soát cẩn thận điều kiện thí nghiệm trong phòng lab."},{"en":"Changing the experimental conditions altered the outcome significantly.","vi":"Thay đổi điều kiện thí nghiệm đã làm kết quả thay đổi đáng kể."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 133, 'experimental data', 'dữ liệu thí nghiệm', 'adj + n', '[{"en":"The team published its experimental data in a leading journal.","vi":"Nhóm đã công bố dữ liệu thí nghiệm của mình trên một tạp chí hàng đầu."},{"en":"Experimental data confirmed the predictions of the new model.","vi":"Dữ liệu thí nghiệm xác nhận các dự đoán của mô hình mới."},{"en":"They compared experimental data with results from earlier studies.","vi":"Họ so sánh dữ liệu thí nghiệm với kết quả từ các nghiên cứu trước."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 134, 'experimental design', 'thiết kế thí nghiệm', 'adj + n', '[{"en":"A flawed experimental design can lead to misleading conclusions.","vi":"Thiết kế thí nghiệm sai sót có thể dẫn đến kết luận sai lệch."},{"en":"The professor praised the student''s careful experimental design.","vi":"Giáo sư khen ngợi thiết kế thí nghiệm cẩn thận của sinh viên."},{"en":"Good experimental design controls for as many variables as possible.","vi":"Thiết kế thí nghiệm tốt kiểm soát càng nhiều biến càng tốt."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl dɪˈzaɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 135, 'experimental evidence', 'bằng chứng thực nghiệm', 'adj + n', '[{"en":"There is strong experimental evidence supporting the theory.","vi":"Có bằng chứng thực nghiệm mạnh mẽ ủng hộ lý thuyết này."},{"en":"The claim lacks any solid experimental evidence so far.","vi":"Cho đến nay tuyên bố này thiếu bằng chứng thực nghiệm vững chắc."},{"en":"New experimental evidence challenged the long held assumption.","vi":"Bằng chứng thực nghiệm mới thách thức giả định tồn tại lâu nay."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 136, 'experimental method', 'phương pháp thực nghiệm', 'adj + n', '[{"en":"The experimental method allows scientists to test their hypotheses.","vi":"Phương pháp thực nghiệm cho phép các nhà khoa học kiểm chứng giả thuyết."},{"en":"She explained the experimental method clearly in the report.","vi":"Cô giải thích rõ ràng phương pháp thực nghiệm trong báo cáo."},{"en":"Psychology adopted the experimental method from the natural sciences.","vi":"Tâm lý học đã tiếp nhận phương pháp thực nghiệm từ khoa học tự nhiên."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 137, 'experimental research', 'nghiên cứu thực nghiệm', 'adj + n', '[{"en":"Experimental research often requires a controlled laboratory setting.","vi":"Nghiên cứu thực nghiệm thường đòi hỏi môi trường phòng lab được kiểm soát."},{"en":"Her experimental research focuses on memory and aging.","vi":"Nghiên cứu thực nghiệm của cô tập trung vào trí nhớ và quá trình lão hóa."},{"en":"The grant funds experimental research into renewable energy.","vi":"Khoản tài trợ cấp vốn cho nghiên cứu thực nghiệm về năng lượng tái tạo."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 138, 'experimental results', 'kết quả thí nghiệm', 'adj + n', '[{"en":"The experimental results matched the theoretical predictions closely.","vi":"Kết quả thí nghiệm khớp chặt với các dự đoán lý thuyết."},{"en":"Researchers repeated the test to confirm the experimental results.","vi":"Các nhà nghiên cứu lặp lại bài kiểm tra để xác nhận kết quả thí nghiệm."},{"en":"The experimental results were surprising and sparked further study.","vi":"Kết quả thí nghiệm đầy bất ngờ và khơi mào cho nghiên cứu thêm."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl rɪˈzʌlts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 139, 'experimental study', 'nghiên cứu thí nghiệm', 'adj + n', '[{"en":"The experimental study involved two hundred volunteers over a year.","vi":"Nghiên cứu thí nghiệm có hai trăm tình nguyện viên trong một năm."},{"en":"An experimental study tested the new drug on healthy adults.","vi":"Một nghiên cứu thí nghiệm thử thuốc mới trên những người trưởng thành khỏe mạnh."},{"en":"The experimental study produced clear and reliable findings.","vi":"Nghiên cứu thí nghiệm đã cho ra kết quả rõ ràng và đáng tin cậy."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 140, 'experimental work', 'công việc thí nghiệm', 'adj + n', '[{"en":"Most of her experimental work was carried out at night.","vi":"Phần lớn công việc thí nghiệm của cô được thực hiện vào ban đêm."},{"en":"The paper combines theory with detailed experimental work.","vi":"Bài báo kết hợp lý thuyết với công việc thí nghiệm chi tiết."},{"en":"Funding cuts delayed the experimental work for several months.","vi":"Việc cắt giảm ngân sách đã làm chậm công việc thí nghiệm vài tháng."}]', '[]', NULL, '/ɪkˌsperɪˈmentəl wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 141, 'expert opinion', 'ý kiến chuyên gia', 'n + n', '[{"en":"The court relied on expert opinion to reach its verdict.","vi":"Tòa án dựa vào ý kiến chuyên gia để đưa ra phán quyết."},{"en":"Before deciding, the company sought expert opinion on the matter.","vi":"Trước khi quyết định, công ty đã tìm kiếm ý kiến chuyên gia về vấn đề này."},{"en":"Expert opinion is divided on the safety of the new method.","vi":"Ý kiến chuyên gia bị chia rẽ về độ an toàn của phương pháp mới."}]', '[]', NULL, '/ˈekspɜːrt əˈpɪnjən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 142, 'explanatory power', 'khả năng giải thích', 'adj + n', '[{"en":"A good theory has strong explanatory power across many cases.","vi":"Một lý thuyết tốt có khả năng giải thích mạnh trong nhiều trường hợp."},{"en":"The model''s explanatory power impressed the review committee.","vi":"Khả năng giải thích của mô hình đã gây ấn tượng với hội đồng thẩm định."},{"en":"Critics argued the framework lacked real explanatory power.","vi":"Những người chỉ trích cho rằng khung lý thuyết thiếu khả năng giải thích thực sự."}]', '[]', NULL, '/ɪkˈsplænətɔːri ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 143, 'explore further', 'khám phá sâu hơn', 'v + adv', '[{"en":"The findings are promising, but we must explore further.","vi":"Những phát hiện này đầy hứa hẹn, nhưng chúng ta phải khám phá sâu hơn."},{"en":"The author invites readers to explore further in later chapters.","vi":"Tác giả mời độc giả khám phá sâu hơn ở các chương sau."},{"en":"Researchers plan to explore further how stress affects memory.","vi":"Các nhà nghiên cứu dự định khám phá sâu hơn cách căng thẳng ảnh hưởng trí nhớ."}]', '[]', NULL, '/ɪkˈsplɔːr ˈfɜːrðər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 144, 'explore an issue', 'tìm hiểu một vấn đề', 'v + n', '[{"en":"The seminar gave us time to explore an issue in depth.","vi":"Buổi hội thảo cho chúng tôi thời gian để tìm hiểu một vấn đề sâu sắc."},{"en":"Documentaries often explore an issue that the news overlooks.","vi":"Phim tài liệu thường tìm hiểu một vấn đề mà tin tức bỏ qua."},{"en":"Her essay sets out to explore an issue facing modern cities.","vi":"Bài luận của cô nhằm tìm hiểu một vấn đề mà các thành phố hiện đại đối mặt."}]', '[]', NULL, '/ɪkˈsplɔːr ən ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 145, 'extended period', 'khoảng thời gian kéo dài', 'adj + n', '[{"en":"Sitting for an extended period can harm your back over time.","vi":"Ngồi trong một khoảng thời gian kéo dài có thể hại lưng theo thời gian."},{"en":"The drought lasted for an extended period across the region.","vi":"Đợt hạn hán kéo dài trong một khoảng thời gian dài khắp khu vực."},{"en":"She trained over an extended period before the competition.","vi":"Cô tập luyện trong một khoảng thời gian kéo dài trước cuộc thi."}]', '[]', NULL, '/ɪkˈstendɪd ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 146, 'extensive research', 'nghiên cứu sâu rộng', 'adj + n', '[{"en":"The book is based on extensive research into local history.","vi":"Cuốn sách dựa trên nghiên cứu sâu rộng về lịch sử địa phương."},{"en":"Extensive research has shown the benefits of regular exercise.","vi":"Nghiên cứu sâu rộng đã chỉ ra lợi ích của việc tập thể dục đều đặn."},{"en":"She conducted extensive research before writing her dissertation.","vi":"Cô tiến hành nghiên cứu sâu rộng trước khi viết luận án của mình."}]', '[]', NULL, '/ɪkˈstensɪv ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 147, 'extensively used', 'được sử dụng rộng rãi', 'adv + vpp', '[{"en":"This method is extensively used in modern medical research today.","vi":"Phương pháp này được sử dụng rộng rãi trong nghiên cứu y học hiện đại."},{"en":"Solar panels are now extensively used across many rural communities.","vi":"Tấm pin mặt trời nay được sử dụng rộng rãi ở nhiều vùng nông thôn."},{"en":"The software is extensively used by students writing their theses.","vi":"Phần mềm này được sinh viên dùng rộng rãi khi viết luận văn."}]', '[]', NULL, '/ɪkˈstensɪvli juːzd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 148, 'external environment', 'môi trường bên ngoài', 'adj + n', '[{"en":"Companies must adapt quickly to changes in the external environment.","vi":"Các công ty phải nhanh chóng thích nghi với thay đổi của môi trường bên ngoài."},{"en":"The external environment shapes how organisms behave and survive.","vi":"Môi trường bên ngoài định hình cách sinh vật ứng xử và tồn tại."},{"en":"Analyzing the external environment helps managers plan effective strategies.","vi":"Phân tích môi trường bên ngoài giúp nhà quản lý hoạch định chiến lược hiệu quả."}]', '[]', NULL, '/ɪkˈstɜːrnəl ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 149, 'external factors', 'các yếu tố bên ngoài', 'adj + n', '[{"en":"External factors such as weather strongly affected the harvest this year.","vi":"Các yếu tố bên ngoài như thời tiết đã ảnh hưởng mạnh đến vụ mùa năm nay."},{"en":"Researchers tried to isolate the external factors influencing the results.","vi":"Các nhà nghiên cứu cố tách riêng các yếu tố bên ngoài tác động đến kết quả."},{"en":"Economic external factors can quickly change a company''s profit margins.","vi":"Các yếu tố kinh tế bên ngoài có thể nhanh chóng thay đổi lợi nhuận công ty."}]', '[]', NULL, '/ɪkˈstɜːrnəl ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-5-01', 150, 'external forces', 'các lực bên ngoài', 'adj + n', '[{"en":"External forces caused the bridge to collapse during the storm.","vi":"Các lực bên ngoài khiến cây cầu sụp đổ trong cơn bão."},{"en":"The nation''s politics were shaped by powerful external forces.","vi":"Nền chính trị của quốc gia bị các lực bên ngoài mạnh mẽ định hình."},{"en":"Engineers calculate how external forces act upon a structure.","vi":"Kỹ sư tính toán cách các lực bên ngoài tác động lên một kết cấu."}]', '[]', NULL, '/ɪkˈstɜːrnəl ˈfɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-6-01', 'colloc-6', 'Cụm học thuật · Nhóm 6', 'Academic Collocation List (Pearson/PTE) — nhóm 6 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 1, 'external influences', 'các ảnh hưởng bên ngoài', 'adj + n', '[{"en":"Children''s behavior is shaped by many external influences over time.","vi":"Hành vi của trẻ được hình thành bởi nhiều ảnh hưởng bên ngoài theo thời gian."},{"en":"The study examined external influences on consumer spending habits.","vi":"Nghiên cứu xem xét các ảnh hưởng bên ngoài đến thói quen chi tiêu của người tiêu dùng."},{"en":"Artists often resist external influences to preserve their original style.","vi":"Nghệ sĩ thường chống lại các ảnh hưởng bên ngoài để giữ phong cách riêng."}]', '[]', NULL, '/ɪkˈstɜːrnəl ˈɪnfluənsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 2, 'external source', 'nguồn bên ngoài', 'adj + n', '[{"en":"The data came from an external source outside the laboratory.","vi":"Dữ liệu đến từ một nguồn bên ngoài phòng thí nghiệm."},{"en":"Always cite any external source you use in your essay.","vi":"Hãy luôn trích dẫn mọi nguồn bên ngoài bạn dùng trong bài luận."},{"en":"The company secured funding from an external source last month.","vi":"Công ty đã huy động vốn từ một nguồn bên ngoài tháng trước."}]', '[]', NULL, '/ɪkˈstɜːrnəl sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 3, 'external threat', 'mối đe dọa từ bên ngoài', 'adj + n', '[{"en":"The government strengthened defenses against any possible external threat.","vi":"Chính phủ củng cố phòng thủ trước mọi mối đe dọa có thể từ bên ngoài."},{"en":"An external threat often unites people who once disagreed.","vi":"Mối đe dọa từ bên ngoài thường gắn kết những người từng bất đồng."},{"en":"Cybersecurity teams monitor systems for any external threat constantly.","vi":"Đội an ninh mạng liên tục giám sát hệ thống để phát hiện mối đe dọa bên ngoài."}]', '[]', NULL, '/ɪkˈstɜːrnəl θret/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 4, 'external world', 'thế giới bên ngoài', 'adj + n', '[{"en":"Our senses connect the mind to the external world around us.","vi":"Các giác quan kết nối tâm trí ta với thế giới bên ngoài."},{"en":"Philosophers long debated how we truly know the external world.","vi":"Các triết gia từ lâu tranh luận về cách ta thực sự biết thế giới bên ngoài."},{"en":"Isolated communities sometimes lose contact with the external world.","vi":"Các cộng đồng biệt lập đôi khi mất liên lạc với thế giới bên ngoài."}]', '[]', NULL, '/ɪkˈstɜːrnəl wɜːrld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 5, 'extract data', 'trích xuất dữ liệu', 'v + n', '[{"en":"Analysts extract data from large surveys to find useful patterns.","vi":"Các nhà phân tích trích xuất dữ liệu từ khảo sát lớn để tìm quy luật."},{"en":"The program can extract data from thousands of files automatically.","vi":"Chương trình có thể tự động trích xuất dữ liệu từ hàng nghìn tệp."},{"en":"Researchers extract data carefully before running statistical tests.","vi":"Các nhà nghiên cứu trích xuất dữ liệu cẩn thận trước khi chạy kiểm định thống kê."}]', '[]', NULL, '/ɪkˈstrækt ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 6, 'extract information', 'trích xuất thông tin', 'v + n', '[{"en":"Good readers extract information quickly from complex academic texts.","vi":"Người đọc giỏi trích xuất thông tin nhanh từ các văn bản học thuật phức tạp."},{"en":"Detectives extract information from witnesses to reconstruct the events.","vi":"Thám tử khai thác thông tin từ nhân chứng để dựng lại sự việc."},{"en":"The tool helps you extract information from scanned documents easily.","vi":"Công cụ này giúp bạn trích xuất thông tin từ tài liệu quét dễ dàng."}]', '[]', NULL, '/ɪkˈstrækt ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 7, 'extremely complex', 'cực kỳ phức tạp', 'adv + adj', '[{"en":"The human brain is an extremely complex biological system.","vi":"Bộ não con người là một hệ thống sinh học cực kỳ phức tạp."},{"en":"International trade negotiations are often extremely complex and slow.","vi":"Đàm phán thương mại quốc tế thường cực kỳ phức tạp và chậm chạp."},{"en":"The mathematical proof turned out to be extremely complex.","vi":"Chứng minh toán học hóa ra lại cực kỳ phức tạp."}]', '[]', NULL, '/ɪkˈstriːmli kəmˈpleks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 8, 'extremely powerful', 'cực kỳ mạnh mẽ', 'adv + adj', '[{"en":"Modern supercomputers are extremely powerful and process huge datasets.","vi":"Siêu máy tính hiện đại cực kỳ mạnh mẽ và xử lý lượng dữ liệu khổng lồ."},{"en":"The speech delivered an extremely powerful message about equality.","vi":"Bài phát biểu truyền tải một thông điệp cực kỳ mạnh mẽ về bình đẳng."},{"en":"Volcanic eruptions release extremely powerful bursts of energy.","vi":"Núi lửa phun trào giải phóng những luồng năng lượng cực kỳ mạnh mẽ."}]', '[]', NULL, '/ɪkˈstriːmli ˈpaʊərfəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 9, 'extremely sensitive', 'cực kỳ nhạy cảm', 'adv + adj', '[{"en":"The instrument is extremely sensitive to even tiny temperature changes.","vi":"Thiết bị này cực kỳ nhạy cảm với cả những thay đổi nhiệt độ nhỏ nhất."},{"en":"Discussions about religion can be extremely sensitive in some cultures.","vi":"Các cuộc bàn luận về tôn giáo có thể cực kỳ nhạy cảm ở một số nền văn hóa."},{"en":"Newborn babies have extremely sensitive skin that needs gentle care.","vi":"Trẻ sơ sinh có làn da cực kỳ nhạy cảm cần được chăm sóc nhẹ nhàng."}]', '[]', NULL, '/ɪkˈstriːmli ˈsensətɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 10, 'extremely useful', 'cực kỳ hữu ích', 'adv + adj', '[{"en":"This dictionary app is extremely useful for learning new vocabulary.","vi":"Ứng dụng từ điển này cực kỳ hữu ích để học từ vựng mới."},{"en":"Her feedback was extremely useful when I revised the report.","vi":"Góp ý của cô ấy cực kỳ hữu ích khi tôi sửa lại báo cáo."},{"en":"The map proved extremely useful while exploring the old city.","vi":"Tấm bản đồ tỏ ra cực kỳ hữu ích khi khám phá thành phố cổ."}]', '[]', NULL, '/ɪkˈstriːmli ˈjuːsfəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 11, 'extremely valuable', 'cực kỳ quý giá', 'adv + adj', '[{"en":"The internship gave me extremely valuable experience for my career.","vi":"Kỳ thực tập đã cho tôi kinh nghiệm cực kỳ quý giá cho sự nghiệp."},{"en":"These ancient manuscripts are extremely valuable to historians.","vi":"Những bản thảo cổ này cực kỳ quý giá đối với các nhà sử học."},{"en":"Clean drinking water is an extremely valuable resource worldwide.","vi":"Nước uống sạch là một nguồn tài nguyên cực kỳ quý giá trên toàn cầu."}]', '[]', NULL, '/ɪkˈstriːmli ˈvæljuəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 12, 'face difficulties', 'đối mặt với khó khăn', 'v + n', '[{"en":"Many new immigrants face difficulties when learning a foreign language.","vi":"Nhiều người nhập cư mới đối mặt với khó khăn khi học ngoại ngữ."},{"en":"Small businesses often face difficulties during an economic downturn.","vi":"Doanh nghiệp nhỏ thường đối mặt với khó khăn trong thời kỳ suy thoái kinh tế."},{"en":"Students who face difficulties should ask their teachers for help.","vi":"Sinh viên gặp khó khăn nên nhờ giáo viên giúp đỡ."}]', '[]', NULL, '/feɪs ˈdɪfɪkəltiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 13, 'face discrimination', 'đối mặt với sự phân biệt đối xử', 'v + n', '[{"en":"Minority workers sometimes face discrimination in hiring and promotion.","vi":"Người lao động thiểu số đôi khi đối mặt với phân biệt khi tuyển dụng và thăng chức."},{"en":"Laws were passed so people no longer face discrimination at work.","vi":"Các luật được ban hành để mọi người không còn bị phân biệt đối xử tại nơi làm việc."},{"en":"Many disabled citizens still face discrimination in everyday life.","vi":"Nhiều công dân khuyết tật vẫn đối mặt với sự phân biệt trong cuộc sống hằng ngày."}]', '[]', NULL, '/feɪs dɪˌskrɪmɪˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 14, 'face a challenge', 'đối mặt với một thử thách', 'v + n', '[{"en":"Every leader must face a challenge with courage and patience.","vi":"Mọi nhà lãnh đạo đều phải đối mặt với một thử thách bằng lòng can đảm và kiên nhẫn."},{"en":"The team will face a challenge adapting to the new system.","vi":"Cả nhóm sẽ đối mặt với một thử thách khi thích nghi với hệ thống mới."},{"en":"Athletes often face a challenge returning after a serious injury.","vi":"Vận động viên thường đối mặt với một thử thách khi trở lại sau chấn thương nặng."}]', '[]', NULL, '/feɪs ə ˈtʃælɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 15, 'face a dilemma', 'đối mặt với một tình huống tiến thoái lưỡng nan', 'v + n', '[{"en":"Doctors sometimes face a dilemma when patients refuse treatment.","vi":"Bác sĩ đôi khi đối mặt với tình huống khó xử khi bệnh nhân từ chối điều trị."},{"en":"Parents often face a dilemma balancing work and family time.","vi":"Cha mẹ thường đối mặt với tình huống khó xử khi cân bằng công việc và gia đình."},{"en":"The manager will face a dilemma choosing between two strong candidates.","vi":"Người quản lý sẽ rơi vào thế khó khi chọn giữa hai ứng viên xuất sắc."}]', '[]', NULL, '/feɪs ə dɪˈlemə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 16, 'face a problem', 'đối mặt với một vấn đề', 'v + n', '[{"en":"Engineers had to face a problem with the bridge''s design.","vi":"Các kỹ sư phải đối mặt với một vấn đề trong thiết kế cây cầu."},{"en":"When you face a problem, try breaking it into smaller parts.","vi":"Khi đối mặt với một vấn đề, hãy thử chia nhỏ nó ra."},{"en":"Coastal cities now face a problem caused by rising sea levels.","vi":"Các thành phố ven biển nay đối mặt với một vấn đề do mực nước biển dâng."}]', '[]', NULL, '/feɪs ə ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 17, 'facial expression', 'biểu cảm khuôn mặt', 'adj + n', '[{"en":"A friendly facial expression can make a strong first impression.","vi":"Một biểu cảm khuôn mặt thân thiện có thể tạo ấn tượng đầu mạnh mẽ."},{"en":"Researchers study how facial expression reveals hidden emotions.","vi":"Các nhà nghiên cứu tìm hiểu cách biểu cảm khuôn mặt bộc lộ cảm xúc giấu kín."},{"en":"Her facial expression showed surprise when she heard the news.","vi":"Biểu cảm khuôn mặt cô ấy lộ vẻ ngạc nhiên khi nghe tin."}]', '[]', NULL, '/ˈfeɪʃəl ɪkˈspreʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 18, 'facilitate the development of', 'tạo điều kiện cho sự phát triển của', 'v + n', '[{"en":"Good infrastructure helps facilitate the development of rural economies.","vi":"Cơ sở hạ tầng tốt giúp tạo điều kiện cho sự phát triển của kinh tế nông thôn."},{"en":"Reading widely can facilitate the development of critical thinking.","vi":"Đọc rộng có thể tạo điều kiện cho sự phát triển của tư duy phản biện."},{"en":"Government grants facilitate the development of clean energy technology.","vi":"Các khoản trợ cấp của chính phủ thúc đẩy sự phát triển của công nghệ năng lượng sạch."}]', '[]', NULL, '/fəˈsɪlɪteɪt ðə dɪˈveləpmənt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 19, 'factual information', 'thông tin thực tế, chính xác', 'adj + n', '[{"en":"A good encyclopedia provides reliable factual information on many topics.","vi":"Một cuốn bách khoa tốt cung cấp thông tin thực tế đáng tin về nhiều chủ đề."},{"en":"Journalists must separate factual information from personal opinion.","vi":"Nhà báo phải tách thông tin thực tế khỏi quan điểm cá nhân."},{"en":"The report contains factual information drawn from official records.","vi":"Báo cáo chứa thông tin thực tế lấy từ hồ sơ chính thức."}]', '[]', NULL, '/ˈfæktʃuəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 20, 'fair treatment', 'sự đối xử công bằng', 'adj + n', '[{"en":"All employees deserve fair treatment regardless of their background.","vi":"Mọi nhân viên đều xứng đáng được đối xử công bằng bất kể xuất thân."},{"en":"The new policy guarantees fair treatment for every customer.","vi":"Chính sách mới bảo đảm sự đối xử công bằng cho mọi khách hàng."},{"en":"Prisoners are entitled to fair treatment under international law.","vi":"Tù nhân được quyền đối xử công bằng theo luật quốc tế."}]', '[]', NULL, '/fer ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 21, 'fairly clear', 'khá rõ ràng', 'adv + adj', '[{"en":"The instructions were fairly clear, so few students asked questions.","vi":"Hướng dẫn khá rõ ràng nên ít sinh viên đặt câu hỏi."},{"en":"It is fairly clear that the experiment supported the hypothesis.","vi":"Khá rõ ràng rằng thí nghiệm đã ủng hộ giả thuyết."},{"en":"Her explanation made the difficult concept fairly clear to everyone.","vi":"Lời giải thích của cô làm khái niệm khó trở nên khá rõ với mọi người."}]', '[]', NULL, '/ˈferli klɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 22, 'fairly common', 'khá phổ biến', 'adv + adj', '[{"en":"This kind of error is fairly common among beginning writers.","vi":"Loại lỗi này khá phổ biến ở những người mới tập viết."},{"en":"Mild allergies are fairly common and usually easy to manage.","vi":"Dị ứng nhẹ khá phổ biến và thường dễ kiểm soát."},{"en":"Working from home has become fairly common in recent years.","vi":"Làm việc tại nhà đã trở nên khá phổ biến trong những năm gần đây."}]', '[]', NULL, '/ˈferli ˈkɑːmən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 23, 'fairly obvious', 'khá rõ ràng, dễ thấy', 'adv + adj', '[{"en":"The reason for the failure was fairly obvious to the team.","vi":"Nguyên nhân thất bại khá rõ ràng đối với cả nhóm."},{"en":"It seems fairly obvious that more practice improves performance.","vi":"Có vẻ khá rõ ràng rằng luyện tập nhiều hơn giúp cải thiện kết quả."},{"en":"The connection between the two events was fairly obvious.","vi":"Mối liên hệ giữa hai sự kiện khá dễ thấy."}]', '[]', NULL, '/ˈferli ˈɑːbviəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 24, 'fairly straightforward', 'khá đơn giản, dễ hiểu', 'adv + adj', '[{"en":"The assembly process is fairly straightforward if you follow the steps.","vi":"Quá trình lắp ráp khá đơn giản nếu bạn làm theo các bước."},{"en":"The exam questions were fairly straightforward and well organized.","vi":"Các câu hỏi trong bài thi khá đơn giản và được sắp xếp hợp lý."},{"en":"Setting up the account is fairly straightforward for most users.","vi":"Việc thiết lập tài khoản khá đơn giản với đa số người dùng."}]', '[]', NULL, '/ˈferli ˌstreɪtˈfɔːrwərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 25, 'fall into the category of', 'thuộc vào loại, xếp vào nhóm', 'v + n', '[{"en":"These plants fall into the category of tropical evergreen species.","vi":"Những cây này thuộc vào loại cây thường xanh nhiệt đới."},{"en":"Such expenses fall into the category of long-term investments.","vi":"Những chi phí như vậy được xếp vào nhóm đầu tư dài hạn."},{"en":"Her work seems to fall into the category of modern art.","vi":"Tác phẩm của cô dường như thuộc vào loại nghệ thuật hiện đại."}]', '[]', NULL, '/fɔːl ˈɪntə ðə ˈkætəɡɔːri əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 26, 'far removed from', 'khác xa, cách xa với', 'adv + vpp', '[{"en":"The theory is far removed from the realities of daily life.","vi":"Lý thuyết này khác xa với thực tế của đời sống hằng ngày."},{"en":"His childhood village felt far removed from the busy capital.","vi":"Ngôi làng thời thơ ấu của anh cách xa thủ đô nhộn nhịp."},{"en":"The final design was far removed from the original sketch.","vi":"Bản thiết kế cuối khác xa với bản phác thảo ban đầu."}]', '[]', NULL, '/fɑːr rɪˈmuːvd frəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 27, 'federal agency', 'cơ quan liên bang', 'adj + n', '[{"en":"A federal agency was created to oversee national food safety.","vi":"Một cơ quan liên bang được lập ra để giám sát an toàn thực phẩm quốc gia."},{"en":"Each federal agency must report its spending to Congress yearly.","vi":"Mỗi cơ quan liên bang phải báo cáo chi tiêu cho Quốc hội hằng năm."},{"en":"The federal agency investigated the cause of the airplane accident.","vi":"Cơ quan liên bang đã điều tra nguyên nhân vụ tai nạn máy bay."}]', '[]', NULL, '/ˈfedərəl ˈeɪdʒənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 28, 'federal government', 'chính phủ liên bang', 'adj + n', '[{"en":"The federal government collects taxes to fund national programs.","vi":"Chính phủ liên bang thu thuế để tài trợ cho các chương trình quốc gia."},{"en":"Disaster relief is usually coordinated by the federal government.","vi":"Cứu trợ thảm họa thường do chính phủ liên bang điều phối."},{"en":"The federal government passed new laws to protect the environment.","vi":"Chính phủ liên bang đã thông qua luật mới để bảo vệ môi trường."}]', '[]', NULL, '/ˈfedərəl ˈɡʌvərnmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 29, 'federal state', 'nhà nước liên bang', 'adj + n', '[{"en":"In a federal state, power is shared between regional governments.","vi":"Trong một nhà nước liên bang, quyền lực được chia sẻ giữa các chính quyền vùng."},{"en":"Germany is a federal state made up of sixteen regions.","vi":"Đức là một nhà nước liên bang gồm mười sáu vùng."},{"en":"A federal state must balance local autonomy with national unity.","vi":"Một nhà nước liên bang phải cân bằng quyền tự trị địa phương với sự thống nhất quốc gia."}]', '[]', NULL, '/ˈfedərəl steɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 30, 'feminist movement', 'phong trào nữ quyền', 'adj + n', '[{"en":"The feminist movement fought hard for women''s voting rights.","vi":"Phong trào nữ quyền đã đấu tranh mạnh mẽ cho quyền bầu cử của phụ nữ."},{"en":"Historians study how the feminist movement changed workplace laws.","vi":"Các nhà sử học nghiên cứu cách phong trào nữ quyền thay đổi luật lao động."},{"en":"The feminist movement inspired many writers in the twentieth century.","vi":"Phong trào nữ quyền đã truyền cảm hứng cho nhiều nhà văn thế kỷ hai mươi."}]', '[]', NULL, '/ˈfemənɪst ˈmuːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 31, 'field research', 'nghiên cứu thực địa', 'n + n', '[{"en":"The biologist spent six months doing field research in the rainforest.","vi":"Nhà sinh học dành sáu tháng nghiên cứu thực địa trong rừng mưa."},{"en":"Field research often gives insights that lab studies cannot provide.","vi":"Nghiên cứu thực địa thường mang lại hiểu biết mà nghiên cứu trong phòng không có."},{"en":"Students conducted field research by interviewing local farmers directly.","vi":"Sinh viên thực hiện nghiên cứu thực địa bằng cách phỏng vấn trực tiếp nông dân địa phương."}]', '[]', NULL, '/fiːld ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 32, 'final analysis', 'phân tích cuối cùng', 'adj + n', '[{"en":"The final analysis confirmed that the treatment was effective.","vi":"Phân tích cuối cùng xác nhận rằng phương pháp điều trị có hiệu quả."},{"en":"In the final analysis, both approaches reached similar conclusions.","vi":"Xét đến cùng, cả hai cách tiếp cận đều đi đến kết luận tương tự."},{"en":"The team presented its final analysis at the research conference.","vi":"Nhóm đã trình bày phân tích cuối cùng tại hội nghị nghiên cứu."}]', '[]', NULL, '/ˈfaɪnəl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 33, 'final answer', 'câu trả lời cuối cùng', 'adj + n', '[{"en":"Check your calculations carefully before writing the final answer.","vi":"Hãy kiểm tra phép tính cẩn thận trước khi viết câu trả lời cuối cùng."},{"en":"The committee gave its final answer after a long discussion.","vi":"Ủy ban đưa ra câu trả lời cuối cùng sau một cuộc thảo luận dài."},{"en":"She thought carefully and then gave her final answer.","vi":"Cô suy nghĩ kỹ rồi đưa ra câu trả lời cuối cùng."}]', '[]', NULL, '/ˈfaɪnəl ˈænsər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 34, 'final chapter', 'chương cuối', 'adj + n', '[{"en":"The final chapter summarizes the main arguments of the book.","vi":"Chương cuối tóm tắt các luận điểm chính của cuốn sách."},{"en":"Readers were surprised by the twist in the final chapter.","vi":"Độc giả bất ngờ trước cú lật ở chương cuối."},{"en":"She wrote the final chapter of her thesis last week.","vi":"Cô đã viết chương cuối của luận văn vào tuần trước."}]', '[]', NULL, '/ˈfaɪnəl ˈtʃæptər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 35, 'final decision', 'quyết định cuối cùng', 'adj + n', '[{"en":"The board will make its final decision at tomorrow''s meeting.","vi":"Hội đồng sẽ đưa ra quyết định cuối cùng trong cuộc họp ngày mai."},{"en":"After much debate, the judge announced the final decision.","vi":"Sau nhiều tranh luận, thẩm phán đã công bố quyết định cuối cùng."},{"en":"The final decision rests with the head of the department.","vi":"Quyết định cuối cùng thuộc về trưởng khoa."}]', '[]', NULL, '/ˈfaɪnəl dɪˈsɪʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 36, 'final outcome', 'kết quả cuối cùng', 'adj + n', '[{"en":"No one could predict the final outcome of the election.","vi":"Không ai có thể dự đoán kết quả cuối cùng của cuộc bầu cử."},{"en":"The final outcome depended on several unpredictable factors.","vi":"Kết quả cuối cùng phụ thuộc vào vài yếu tố khó lường."},{"en":"Both teams worked hard, but the final outcome was a draw.","vi":"Cả hai đội đều cố gắng, nhưng kết quả cuối cùng là hòa."}]', '[]', NULL, '/ˈfaɪnəl ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 37, 'final phase', 'giai đoạn cuối', 'adj + n', '[{"en":"The project has now entered its final phase of testing.","vi":"Dự án nay đã bước vào giai đoạn cuối của quá trình thử nghiệm."},{"en":"During the final phase, the team checks every detail carefully.","vi":"Trong giai đoạn cuối, nhóm kiểm tra cẩn thận từng chi tiết."},{"en":"Construction reached its final phase ahead of the deadline.","vi":"Việc xây dựng đã đến giai đoạn cuối trước thời hạn."}]', '[]', NULL, '/ˈfaɪnəl feɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 38, 'final point', 'điểm cuối cùng, luận điểm cuối', 'adj + n', '[{"en":"As a final point, the author urges readers to take action.","vi":"Như một luận điểm cuối, tác giả kêu gọi độc giả hành động."},{"en":"The speaker saved her strongest argument for the final point.","vi":"Diễn giả dành luận điểm mạnh nhất cho phần cuối cùng."},{"en":"Let me make one final point before we end the discussion.","vi":"Hãy để tôi nêu một điểm cuối cùng trước khi kết thúc thảo luận."}]', '[]', NULL, '/ˈfaɪnəl pɔɪnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 39, 'final position', 'vị trí cuối cùng', 'adj + n', '[{"en":"The runner secured the final position in the national rankings.","vi":"Vận động viên giành được vị trí cuối cùng trong bảng xếp hạng quốc gia."},{"en":"Scientists measured the final position of the moving object.","vi":"Các nhà khoa học đo vị trí cuối cùng của vật chuyển động."},{"en":"After negotiations, both sides clarified their final position.","vi":"Sau đàm phán, cả hai bên làm rõ lập trường cuối cùng của mình."}]', '[]', NULL, '/ˈfaɪnəl pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 40, 'final product', 'sản phẩm cuối cùng', 'adj + n', '[{"en":"The final product must pass quality checks before being sold.","vi":"Sản phẩm cuối cùng phải qua kiểm tra chất lượng trước khi được bán."},{"en":"Customers care more about the final product than the process.","vi":"Khách hàng quan tâm đến sản phẩm cuối cùng hơn là quy trình."},{"en":"The team was proud of the final product they created.","vi":"Cả nhóm tự hào về sản phẩm cuối cùng mà họ tạo ra."}]', '[]', NULL, '/ˈfaɪnəl ˈprɑːdʌkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 41, 'final result', 'kết quả cuối cùng', 'adj + n', '[{"en":"The final result of the experiment matched the team''s predictions.","vi":"Kết quả cuối cùng của thí nghiệm khớp với dự đoán của nhóm."},{"en":"Students waited anxiously for the final result of the exam.","vi":"Sinh viên hồi hộp chờ kết quả cuối cùng của kỳ thi."},{"en":"The final result showed a clear improvement over last year.","vi":"Kết quả cuối cùng cho thấy sự cải thiện rõ rệt so với năm ngoái."}]', '[]', NULL, '/ˈfaɪnəl rɪˈzʌlt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 42, 'final section', 'phần cuối', 'adj + n', '[{"en":"The final section of the report lists recommendations for managers.","vi":"Phần cuối của báo cáo liệt kê các khuyến nghị cho nhà quản lý."},{"en":"Please read the final section carefully before the exam.","vi":"Hãy đọc kỹ phần cuối trước khi thi."},{"en":"The final section of the test covers grammar and vocabulary.","vi":"Phần cuối của bài kiểm tra bao gồm ngữ pháp và từ vựng."}]', '[]', NULL, '/ˈfaɪnəl ˈsekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 43, 'final stage', 'giai đoạn cuối', 'adj + n', '[{"en":"The negotiations have now reached their final stage.","vi":"Các cuộc đàm phán nay đã đến giai đoạn cuối."},{"en":"In the final stage, the caterpillar transforms into a butterfly.","vi":"Ở giai đoạn cuối, sâu bướm biến thành con bướm."},{"en":"We are in the final stage of preparing the new course.","vi":"Chúng tôi đang ở giai đoạn cuối của việc chuẩn bị khóa học mới."}]', '[]', NULL, '/ˈfaɪnəl steɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 44, 'final step', 'bước cuối cùng', 'adj + n', '[{"en":"The final step is to submit your application before the deadline.","vi":"Bước cuối cùng là nộp đơn của bạn trước hạn chót."},{"en":"Cooling the mixture is the final step in the procedure.","vi":"Làm nguội hỗn hợp là bước cuối cùng trong quy trình."},{"en":"After editing, the final step is to publish the article.","vi":"Sau khi biên tập, bước cuối cùng là xuất bản bài viết."}]', '[]', NULL, '/ˈfaɪnəl step/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 45, 'final version', 'phiên bản cuối cùng', 'adj + n', '[{"en":"Please send me the final version of the document by Friday.","vi":"Vui lòng gửi tôi phiên bản cuối cùng của tài liệu trước thứ Sáu."},{"en":"The final version of the software fixed all major bugs.","vi":"Phiên bản cuối cùng của phần mềm đã sửa mọi lỗi lớn."},{"en":"She revised the essay three times before the final version.","vi":"Cô sửa bài luận ba lần trước khi có phiên bản cuối cùng."}]', '[]', NULL, '/ˈfaɪnəl ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 46, 'financial affairs', 'công việc, vấn đề tài chính', 'adj + n', '[{"en":"An accountant helps the family manage its financial affairs.","vi":"Một kế toán viên giúp gia đình quản lý các vấn đề tài chính."},{"en":"The company kept its financial affairs strictly confidential.","vi":"Công ty giữ các vấn đề tài chính của mình hoàn toàn bí mật."},{"en":"Good record-keeping makes managing financial affairs much easier.","vi":"Việc lưu hồ sơ tốt khiến quản lý tài chính dễ dàng hơn nhiều."}]', '[]', NULL, '/faɪˈnænʃəl əˈferz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 47, 'financial assistance', 'hỗ trợ tài chính', 'adj + n', '[{"en":"Many students rely on financial assistance to pay their tuition.","vi":"Nhiều sinh viên dựa vào hỗ trợ tài chính để trả học phí."},{"en":"The charity offers financial assistance to families in need.","vi":"Tổ chức từ thiện cung cấp hỗ trợ tài chính cho các gia đình khó khăn."},{"en":"Governments provided financial assistance after the natural disaster.","vi":"Các chính phủ đã cung cấp hỗ trợ tài chính sau thảm họa thiên nhiên."}]', '[]', NULL, '/faɪˈnænʃəl əˈsɪstəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 48, 'financial institution', 'tổ chức tài chính', 'adj + n', '[{"en":"A bank is the most common type of financial institution.","vi":"Ngân hàng là loại tổ chức tài chính phổ biến nhất."},{"en":"Every financial institution must follow strict government regulations.","vi":"Mọi tổ chức tài chính phải tuân theo các quy định nghiêm ngặt của chính phủ."},{"en":"The financial institution offered low interest rates to borrowers.","vi":"Tổ chức tài chính này cung cấp lãi suất thấp cho người vay."}]', '[]', NULL, '/faɪˈnænʃəl ˌɪnstɪˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 49, 'financial management', 'quản lý tài chính', 'adj + n', '[{"en":"Sound financial management is essential for any successful business.","vi":"Quản lý tài chính tốt là điều thiết yếu cho mọi doanh nghiệp thành công."},{"en":"The course teaches basic financial management to young entrepreneurs.","vi":"Khóa học dạy quản lý tài chính cơ bản cho các doanh nhân trẻ."},{"en":"Poor financial management led the company into serious debt.","vi":"Quản lý tài chính kém đã đẩy công ty vào nợ nần nghiêm trọng."}]', '[]', NULL, '/faɪˈnænʃəl ˈmænɪdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 50, 'financial market', 'thị trường tài chính', 'adj + n', '[{"en":"The financial market reacted strongly to the central bank''s decision.","vi":"Thị trường tài chính phản ứng mạnh với quyết định của ngân hàng trung ương."},{"en":"Investors watch the financial market closely for new opportunities.","vi":"Nhà đầu tư theo dõi sát thị trường tài chính để tìm cơ hội mới."},{"en":"A stable financial market encourages long-term economic growth.","vi":"Một thị trường tài chính ổn định khuyến khích tăng trưởng kinh tế dài hạn."}]', '[]', NULL, '/faɪˈnænʃəl ˈmɑːrkɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 51, 'financial problem', 'vấn đề tài chính', 'adj + n', '[{"en":"The family faced a serious financial problem after losing work.","vi":"Gia đình đối mặt với một vấn đề tài chính nghiêm trọng sau khi mất việc."},{"en":"Careful budgeting can help you avoid a financial problem.","vi":"Lập ngân sách cẩn thận có thể giúp bạn tránh vấn đề tài chính."},{"en":"The small business solved its financial problem with a loan.","vi":"Doanh nghiệp nhỏ đã giải quyết vấn đề tài chính bằng một khoản vay."}]', '[]', NULL, '/faɪˈnænʃəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 52, 'financial resources', 'nguồn lực tài chính', 'adj + n', '[{"en":"The school lacks the financial resources to hire more teachers.","vi":"Trường thiếu nguồn lực tài chính để thuê thêm giáo viên."},{"en":"Limited financial resources forced the team to delay the project.","vi":"Nguồn lực tài chính hạn hẹp buộc nhóm phải hoãn dự án."},{"en":"Wealthy nations have greater financial resources for research.","vi":"Các quốc gia giàu có có nhiều nguồn lực tài chính hơn cho nghiên cứu."}]', '[]', NULL, '/faɪˈnænʃəl ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 53, 'financial support', 'hỗ trợ tài chính', 'adj + n', '[{"en":"The scholarship provides financial support for talented students.","vi":"Học bổng cung cấp hỗ trợ tài chính cho các sinh viên tài năng."},{"en":"Without financial support, the research project would have stopped.","vi":"Nếu không có hỗ trợ tài chính, dự án nghiên cứu đã phải dừng lại."},{"en":"Parents often give financial support to children at university.","vi":"Cha mẹ thường hỗ trợ tài chính cho con khi học đại học."}]', '[]', NULL, '/faɪˈnænʃəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 54, 'find evidence', 'tìm thấy bằng chứng', 'v + n', '[{"en":"Scientists hope to find evidence of water on distant planets.","vi":"Các nhà khoa học hy vọng tìm thấy bằng chứng về nước trên các hành tinh xa."},{"en":"Investigators worked hard to find evidence of the crime.","vi":"Các điều tra viên nỗ lực tìm bằng chứng về tội ác."},{"en":"Researchers could not find evidence to support the old theory.","vi":"Các nhà nghiên cứu không tìm thấy bằng chứng ủng hộ lý thuyết cũ."}]', '[]', NULL, '/faɪnd ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 55, 'find information', 'tìm thông tin', 'v + n', '[{"en":"You can find information about the course on the website.","vi":"Bạn có thể tìm thông tin về khóa học trên trang web."},{"en":"Librarians help students find information for their research projects.","vi":"Thủ thư giúp sinh viên tìm thông tin cho các dự án nghiên cứu."},{"en":"It is easy to find information online, but verify the sources.","vi":"Tìm thông tin trực tuyến rất dễ, nhưng hãy kiểm chứng nguồn."}]', '[]', NULL, '/faɪnd ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 56, 'finite number', 'số lượng hữu hạn', 'adj + n', '[{"en":"There is only a finite number of seats in the lecture hall.","vi":"Chỉ có một số lượng ghế hữu hạn trong giảng đường."},{"en":"The planet holds a finite number of natural resources.","vi":"Hành tinh chỉ chứa một lượng tài nguyên thiên nhiên hữu hạn."},{"en":"A game with a finite number of moves must eventually end.","vi":"Một trò chơi có số nước đi hữu hạn cuối cùng phải kết thúc."}]', '[]', NULL, '/ˈfaɪnaɪt ˈnʌmbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 57, 'firmly established', 'được thiết lập vững chắc', 'adv + vpp', '[{"en":"The theory is now firmly established in modern physics.","vi":"Lý thuyết này nay đã được thiết lập vững chắc trong vật lý hiện đại."},{"en":"Their reputation became firmly established after years of hard work.","vi":"Danh tiếng của họ trở nên vững chắc sau nhiều năm nỗ lực."},{"en":"The company is firmly established as a leader in technology.","vi":"Công ty đã khẳng định vững chắc vị trí dẫn đầu trong ngành công nghệ."}]', '[]', NULL, '/ˈfɜːrmli ɪˈstæblɪʃt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 58, 'first author', 'tác giả chính (đứng tên đầu)', 'adj + n', '[{"en":"She was the first author of the highly cited research paper.","vi":"Cô là tác giả chính của bài nghiên cứu được trích dẫn nhiều."},{"en":"The first author usually does most of the project''s work.","vi":"Tác giả đứng đầu thường làm phần lớn công việc của dự án."},{"en":"As first author, he presented the findings at the conference.","vi":"Là tác giả chính, anh đã trình bày các phát hiện tại hội nghị."}]', '[]', NULL, '/fɜːrst ˈɔːθər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 59, 'first contact', 'lần tiếp xúc đầu tiên', 'adj + n', '[{"en":"The first contact between the two cultures changed history forever.","vi":"Lần tiếp xúc đầu tiên giữa hai nền văn hóa đã thay đổi lịch sử mãi mãi."},{"en":"Make a good impression during your first contact with clients.","vi":"Hãy tạo ấn tượng tốt trong lần tiếp xúc đầu tiên với khách hàng."},{"en":"The receptionist is often the first contact for new visitors.","vi":"Lễ tân thường là người tiếp xúc đầu tiên với khách mới."}]', '[]', NULL, '/fɜːrst ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 60, 'first draft', 'bản nháp đầu tiên', 'adj + n', '[{"en":"The first draft of an essay is rarely perfect or polished.","vi":"Bản nháp đầu tiên của một bài luận hiếm khi hoàn hảo hay trau chuốt."},{"en":"She finished the first draft of her novel last month.","vi":"Cô đã hoàn thành bản nháp đầu tiên của tiểu thuyết tháng trước."},{"en":"Always revise your first draft before submitting the final paper.","vi":"Hãy luôn sửa bản nháp đầu tiên trước khi nộp bài cuối cùng."}]', '[]', NULL, '/fɜːrst dræft/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 61, 'first encounter', 'lần gặp gỡ đầu tiên', 'adj + n', '[{"en":"Their first encounter took place at an academic conference abroad.","vi":"Lần gặp gỡ đầu tiên của họ diễn ra tại một hội nghị học thuật ở nước ngoài."},{"en":"My first encounter with classical music was at a school concert.","vi":"Lần đầu tiên tôi tiếp xúc với nhạc cổ điển là tại buổi hòa nhạc trường."},{"en":"The book describes the explorer''s first encounter with the tribe.","vi":"Cuốn sách mô tả lần gặp gỡ đầu tiên của nhà thám hiểm với bộ tộc."}]', '[]', NULL, '/fɜːrst ɪnˈkaʊntər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 62, 'first generation', 'thế hệ đầu tiên', 'adj + n', '[{"en":"She is the first generation in her family to attend university.","vi":"Cô là thế hệ đầu tiên trong gia đình được học đại học."},{"en":"The first generation of smartphones was bulky and very expensive.","vi":"Thế hệ điện thoại thông minh đầu tiên cồng kềnh và rất đắt."},{"en":"First generation immigrants often work hard to support their children.","vi":"Người nhập cư thế hệ đầu thường làm việc chăm chỉ để nuôi con."}]', '[]', NULL, '/fɜːrst ˌdʒenəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 63, 'first impression', 'ấn tượng đầu tiên', 'adj + n', '[{"en":"A polite greeting helps create a good first impression.","vi":"Một lời chào lịch sự giúp tạo ấn tượng đầu tiên tốt."},{"en":"First impression often influences how we judge new people.","vi":"Ấn tượng đầu tiên thường ảnh hưởng đến cách ta đánh giá người mới."},{"en":"Her confident speech made a strong first impression on the panel.","vi":"Bài phát biểu tự tin của cô tạo ấn tượng đầu mạnh với ban giám khảo."}]', '[]', NULL, '/fɜːrst ɪmˈpreʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 64, 'first phase', 'giai đoạn đầu tiên', 'adj + n', '[{"en":"The first phase of the project focuses on collecting data.","vi":"Giai đoạn đầu tiên của dự án tập trung vào thu thập dữ liệu."},{"en":"During the first phase, the team trained all new staff.","vi":"Trong giai đoạn đầu, nhóm đã đào tạo toàn bộ nhân viên mới."},{"en":"The first phase of construction was completed ahead of schedule.","vi":"Giai đoạn đầu tiên của việc xây dựng được hoàn thành trước hạn."}]', '[]', NULL, '/fɜːrst feɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 65, 'first priority', 'ưu tiên hàng đầu', 'adj + n', '[{"en":"Safety should always be the first priority on any worksite.","vi":"An toàn luôn phải là ưu tiên hàng đầu tại mọi công trường."},{"en":"Her first priority was finishing the report before the deadline.","vi":"Ưu tiên hàng đầu của cô là hoàn thành báo cáo trước hạn chót."},{"en":"Improving education remains the government''s first priority this year.","vi":"Cải thiện giáo dục vẫn là ưu tiên hàng đầu của chính phủ năm nay."}]', '[]', NULL, '/fɜːrst praɪˈɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 66, 'flexible approach', 'cách tiếp cận linh hoạt', 'adj + n', '[{"en":"A flexible approach allows teachers to meet different students'' needs.","vi":"Cách tiếp cận linh hoạt giúp giáo viên đáp ứng nhu cầu khác nhau của học sinh."},{"en":"The company adopted a flexible approach to remote working.","vi":"Công ty áp dụng cách tiếp cận linh hoạt với việc làm từ xa."},{"en":"Solving complex problems often requires a flexible approach.","vi":"Giải quyết các vấn đề phức tạp thường đòi hỏi cách tiếp cận linh hoạt."}]', '[]', NULL, '/ˈfleksəbəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 67, 'focal point', 'tâm điểm, điểm trọng tâm', 'adj + n', '[{"en":"The fireplace is the focal point of the entire living room.","vi":"Lò sưởi là tâm điểm của toàn bộ phòng khách."},{"en":"Climate change has become the focal point of recent debates.","vi":"Biến đổi khí hậu đã trở thành tâm điểm của các cuộc tranh luận gần đây."},{"en":"The tower serves as the focal point of the historic city.","vi":"Ngọn tháp là điểm trọng tâm của thành phố cổ."}]', '[]', NULL, '/ˈfoʊkəl pɔɪnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 68, 'focus attention on', 'tập trung sự chú ý vào', 'v + n', '[{"en":"The campaign aims to focus attention on childhood nutrition.","vi":"Chiến dịch nhằm tập trung sự chú ý vào dinh dưỡng cho trẻ em."},{"en":"Teachers should focus attention on the weakest students first.","vi":"Giáo viên nên tập trung sự chú ý vào những học sinh yếu nhất trước."},{"en":"The report tries to focus attention on rising energy costs.","vi":"Báo cáo cố gắng tập trung sự chú ý vào chi phí năng lượng tăng cao."}]', '[]', NULL, '/ˈfoʊkəs əˈtenʃən ɑːn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 69, 'focus on an aspect', 'tập trung vào một khía cạnh', 'v + n', '[{"en":"This chapter will focus on an aspect of language learning.","vi":"Chương này sẽ tập trung vào một khía cạnh của việc học ngôn ngữ."},{"en":"The study chose to focus on an aspect of consumer behavior.","vi":"Nghiên cứu chọn tập trung vào một khía cạnh của hành vi người tiêu dùng."},{"en":"Try to focus on an aspect you find genuinely interesting.","vi":"Hãy cố tập trung vào một khía cạnh mà bạn thực sự thấy thú vị."}]', '[]', NULL, '/ˈfoʊkəs ɑːn ən ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 70, 'follow a format', 'tuân theo một định dạng', 'v + n', '[{"en":"All essays must follow a format set by the department.","vi":"Mọi bài luận phải tuân theo một định dạng do khoa quy định."},{"en":"Scientific reports usually follow a format with clear sections.","vi":"Báo cáo khoa học thường tuân theo một định dạng có các phần rõ ràng."},{"en":"Please follow a format consistent with the official guidelines.","vi":"Hãy tuân theo một định dạng nhất quán với hướng dẫn chính thức."}]', '[]', NULL, '/ˈfɑːloʊ ə ˈfɔːrmæt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 71, 'follow a procedure', 'tuân theo một quy trình', 'v + n', '[{"en":"Lab workers must follow a procedure to ensure everyone''s safety.","vi":"Nhân viên phòng thí nghiệm phải tuân theo một quy trình để đảm bảo an toàn cho mọi người."},{"en":"Always follow a procedure carefully when handling dangerous chemicals.","vi":"Hãy luôn tuân theo một quy trình cẩn thận khi xử lý hóa chất nguy hiểm."},{"en":"Nurses follow a procedure when preparing patients for surgery.","vi":"Y tá tuân theo một quy trình khi chuẩn bị cho bệnh nhân phẫu thuật."}]', '[]', NULL, '/ˈfɑːloʊ ə prəˈsiːdʒər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 72, 'follow instructions', 'làm theo hướng dẫn', 'v + n', '[{"en":"Students who follow instructions carefully usually make fewer mistakes.","vi":"Học sinh làm theo hướng dẫn cẩn thận thường mắc ít lỗi hơn."},{"en":"Please follow instructions on the label before taking the medicine.","vi":"Hãy làm theo hướng dẫn trên nhãn trước khi uống thuốc."},{"en":"He failed the test because he did not follow instructions.","vi":"Anh ấy trượt bài kiểm tra vì không làm theo hướng dẫn."}]', '[]', NULL, '/ˈfɑːloʊ ɪnˈstrʌkʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 73, 'following chapter', 'chương tiếp theo', 'adj + n', '[{"en":"The following chapter explains the method in much greater detail.","vi":"Chương tiếp theo giải thích phương pháp một cách chi tiết hơn nhiều."},{"en":"These ideas will be developed further in the following chapter.","vi":"Những ý tưởng này sẽ được phát triển thêm trong chương tiếp theo."},{"en":"The following chapter presents the results of the survey.","vi":"Chương tiếp theo trình bày kết quả của cuộc khảo sát."}]', '[]', NULL, '/ˈfɑːloʊɪŋ ˈtʃæptər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 74, 'foreign currency', 'ngoại tệ', 'adj + n', '[{"en":"Travelers should exchange foreign currency before leaving the airport.","vi":"Du khách nên đổi ngoại tệ trước khi rời sân bay."},{"en":"The bank charges a small fee for foreign currency transactions.","vi":"Ngân hàng thu một khoản phí nhỏ cho các giao dịch ngoại tệ."},{"en":"Exports earn the country valuable foreign currency each year.","vi":"Xuất khẩu mang lại cho đất nước nguồn ngoại tệ quý giá mỗi năm."}]', '[]', NULL, '/ˈfɔːrən ˈkɜːrənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 75, 'foreign investment', 'đầu tư nước ngoài', 'adj + n', '[{"en":"Foreign investment helped the country build new roads and factories.","vi":"Đầu tư nước ngoài đã giúp đất nước xây dựng đường sá và nhà máy mới."},{"en":"The government introduced policies to attract more foreign investment.","vi":"Chính phủ đưa ra chính sách để thu hút thêm đầu tư nước ngoài."},{"en":"Foreign investment can create many jobs in developing economies.","vi":"Đầu tư nước ngoài có thể tạo nhiều việc làm ở các nền kinh tế đang phát triển."}]', '[]', NULL, '/ˈfɔːrən ɪnˈvestmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 76, 'foreign investor', 'nhà đầu tư nước ngoài', 'adj + n', '[{"en":"A foreign investor bought a large share of the company.","vi":"Một nhà đầu tư nước ngoài đã mua phần lớn cổ phần của công ty."},{"en":"Stable laws make a country attractive to every foreign investor.","vi":"Luật pháp ổn định khiến một quốc gia hấp dẫn với mọi nhà đầu tư nước ngoài."},{"en":"The foreign investor hopes to expand the business across Asia.","vi":"Nhà đầu tư nước ngoài hy vọng mở rộng kinh doanh khắp châu Á."}]', '[]', NULL, '/ˈfɔːrən ɪnˈvestər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 77, 'foreign policy', 'chính sách đối ngoại', 'adj + n', '[{"en":"The new president promised major changes in foreign policy.","vi":"Tân tổng thống hứa hẹn những thay đổi lớn trong chính sách đối ngoại."},{"en":"Foreign policy decisions can affect trade with many countries.","vi":"Các quyết định về chính sách đối ngoại có thể ảnh hưởng đến thương mại với nhiều nước."},{"en":"Students debated the country''s foreign policy during the seminar.","vi":"Sinh viên tranh luận về chính sách đối ngoại của đất nước trong buổi hội thảo."}]', '[]', NULL, '/ˈfɔːrən ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 78, 'formal structure', 'cấu trúc chính thức, trang trọng', 'adj + n', '[{"en":"A good essay needs a clear and formal structure throughout.","vi":"Một bài luận tốt cần một cấu trúc rõ ràng và trang trọng xuyên suốt."},{"en":"The organization has a formal structure with several departments.","vi":"Tổ chức có một cấu trúc chính thức gồm nhiều phòng ban."},{"en":"Classical music often follows a strict and formal structure.","vi":"Nhạc cổ điển thường tuân theo một cấu trúc nghiêm ngặt và trang trọng."}]', '[]', NULL, '/ˈfɔːrməl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 79, 'free access', 'quyền truy cập miễn phí', 'adj + n', '[{"en":"Students enjoy free access to the university''s online library.","vi":"Sinh viên được truy cập miễn phí vào thư viện trực tuyến của trường."},{"en":"The policy guarantees free access to public health services.","vi":"Chính sách bảo đảm quyền truy cập miễn phí vào dịch vụ y tế công."},{"en":"Researchers value free access to peer-reviewed academic journals.","vi":"Các nhà nghiên cứu coi trọng quyền truy cập miễn phí vào tạp chí học thuật."}]', '[]', NULL, '/friː ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 80, 'free movement', 'sự di chuyển tự do', 'adj + n', '[{"en":"The treaty allows free movement of workers between member states.","vi":"Hiệp ước cho phép lao động di chuyển tự do giữa các nước thành viên."},{"en":"Free movement of goods boosts trade across the region.","vi":"Sự di chuyển tự do của hàng hóa thúc đẩy thương mại trong khu vực."},{"en":"Border controls can restrict the free movement of people.","vi":"Việc kiểm soát biên giới có thể hạn chế sự di chuyển tự do của con người."}]', '[]', NULL, '/friː ˈmuːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 81, 'freely available', 'có sẵn miễn phí, dễ dàng tiếp cận', 'adv + adj', '[{"en":"The software is freely available for download on the website.","vi":"Phần mềm này có sẵn miễn phí để tải về trên trang web."},{"en":"Much of the data is freely available to other researchers.","vi":"Phần lớn dữ liệu được cung cấp miễn phí cho các nhà nghiên cứu khác."},{"en":"These resources are freely available through the public archive.","vi":"Các tài nguyên này có sẵn miễn phí qua kho lưu trữ công cộng."}]', '[]', NULL, '/ˈfriːli əˈveɪləbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 82, 'frequently cited', 'được trích dẫn thường xuyên', 'adv + vpp', '[{"en":"This article is frequently cited in studies of language learning.","vi":"Bài báo này được trích dẫn thường xuyên trong các nghiên cứu về học ngôn ngữ."},{"en":"Her work remains frequently cited by scholars in the field.","vi":"Công trình của bà vẫn được các học giả trong ngành trích dẫn thường xuyên."},{"en":"Frequently cited papers tend to shape later research directions.","vi":"Những bài báo được trích dẫn nhiều thường định hình hướng nghiên cứu về sau."}]', '[]', NULL, '/ˈfriːkwəntli ˈsaɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 83, 'frequently found', 'thường thấy, hay bắt gặp', 'adv + vpp', '[{"en":"This species is frequently found in shallow coastal waters.","vi":"Loài này thường thấy ở vùng nước nông ven biển."},{"en":"Such errors are frequently found in students'' early drafts.","vi":"Những lỗi như vậy thường thấy trong các bản nháp đầu của sinh viên."},{"en":"The compound is frequently found in volcanic rock samples.","vi":"Hợp chất này hay bắt gặp trong các mẫu đá núi lửa."}]', '[]', NULL, '/ˈfriːkwəntli faʊnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 84, 'frequently referred to', 'thường được nhắc đến, hay được viện dẫn', 'adv + vpp', '[{"en":"This theory is frequently referred to in economics textbooks.","vi":"Lý thuyết này thường được nhắc đến trong các giáo trình kinh tế."},{"en":"The case is frequently referred to during legal seminars.","vi":"Vụ án này hay được viện dẫn trong các buổi hội thảo pháp lý."},{"en":"His model is frequently referred to as a classic example.","vi":"Mô hình của ông thường được nhắc đến như một ví dụ kinh điển."}]', '[]', NULL, '/ˈfriːkwəntli rɪˈfɜːrd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 85, 'frequently used', 'thường được sử dụng', 'adv + vpp', '[{"en":"This method is frequently used in qualitative research studies.","vi":"Phương pháp này thường được sử dụng trong các nghiên cứu định tính."},{"en":"The term is frequently used by economists to describe inflation.","vi":"Thuật ngữ này thường được các nhà kinh tế dùng để mô tả lạm phát."},{"en":"Frequently used phrases can make essays sound repetitive.","vi":"Những cụm từ được dùng nhiều có thể khiến bài luận nghe lặp lại."}]', '[]', NULL, '/ˈfriːkwəntli juːzd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 86, 'fulfil an obligation', 'thực hiện một nghĩa vụ', 'v + n', '[{"en":"The company must fulfil an obligation to protect its customers.","vi":"Công ty phải thực hiện nghĩa vụ bảo vệ khách hàng của mình."},{"en":"Citizens fulfil an obligation by paying their taxes on time.","vi":"Công dân thực hiện một nghĩa vụ bằng cách nộp thuế đúng hạn."},{"en":"Failing to fulfil an obligation can lead to legal consequences.","vi":"Không thực hiện nghĩa vụ có thể dẫn đến hậu quả pháp lý."}]', '[]', NULL, '/fʊlˈfɪl ən ˌɑːblɪˈɡeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 87, 'full analysis', 'sự phân tích đầy đủ, toàn diện', 'adj + n', '[{"en":"A full analysis of the data revealed several unexpected patterns.","vi":"Một phân tích đầy đủ về dữ liệu cho thấy nhiều mô hình bất ngờ."},{"en":"The report includes a full analysis of the survey results.","vi":"Báo cáo bao gồm một phân tích toàn diện về kết quả khảo sát."},{"en":"A full analysis is needed before drawing any firm conclusions.","vi":"Cần một phân tích đầy đủ trước khi rút ra kết luận chắc chắn."}]', '[]', NULL, '/fʊl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 88, 'full employment', 'toàn dụng lao động (mọi người có việc làm)', 'adj + n', '[{"en":"The government aims to achieve full employment within a decade.","vi":"Chính phủ đặt mục tiêu đạt toàn dụng lao động trong một thập kỷ."},{"en":"Full employment often puts upward pressure on wages.","vi":"Toàn dụng lao động thường tạo áp lực tăng lên tiền lương."},{"en":"Economists debate whether full employment is truly attainable.","vi":"Các nhà kinh tế tranh luận liệu toàn dụng lao động có thực sự đạt được."}]', '[]', NULL, '/fʊl ɪmˈplɔɪmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 89, 'full information', 'thông tin đầy đủ', 'adj + n', '[{"en":"Patients should receive full information before agreeing to treatment.","vi":"Bệnh nhân nên nhận thông tin đầy đủ trước khi đồng ý điều trị."},{"en":"The website provides full information about admission requirements.","vi":"Trang web cung cấp thông tin đầy đủ về yêu cầu tuyển sinh."},{"en":"Decisions made without full information are often unreliable.","vi":"Quyết định đưa ra mà thiếu thông tin đầy đủ thường không đáng tin."}]', '[]', NULL, '/fʊl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 90, 'full participation', 'sự tham gia đầy đủ, trọn vẹn', 'adj + n', '[{"en":"The program encourages full participation from every team member.","vi":"Chương trình khuyến khích sự tham gia đầy đủ của từng thành viên."},{"en":"Full participation in class improves students'' speaking confidence.","vi":"Tham gia đầy đủ trong lớp giúp sinh viên tự tin hơn khi nói."},{"en":"Equal access ensures the full participation of disabled citizens.","vi":"Tiếp cận bình đẳng bảo đảm sự tham gia trọn vẹn của người khuyết tật."}]', '[]', NULL, '/fʊl pɑːrˌtɪsɪˈpeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 91, 'full potential', 'tiềm năng đầy đủ, trọn vẹn', 'adj + n', '[{"en":"Good teaching helps students reach their full potential.","vi":"Việc giảng dạy tốt giúp sinh viên phát huy hết tiềm năng của mình."},{"en":"The technology has not yet realized its full potential.","vi":"Công nghệ này vẫn chưa phát huy hết tiềm năng của nó."},{"en":"Investment is required for the region to achieve full potential.","vi":"Cần đầu tư để khu vực đạt được tiềm năng trọn vẹn của mình."}]', '[]', NULL, '/fʊl pəˈtenʃəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 92, 'full range of', 'đầy đủ các loại, toàn bộ phạm vi', 'adj + n', '[{"en":"The course covers a full range of research methods.","vi":"Khóa học bao quát đầy đủ các phương pháp nghiên cứu."},{"en":"The clinic offers a full range of medical services.","vi":"Phòng khám cung cấp đầy đủ các loại dịch vụ y tế."},{"en":"Students explore a full range of viewpoints in the seminar.","vi":"Sinh viên khám phá toàn bộ phạm vi quan điểm trong buổi hội thảo."}]', '[]', NULL, '/fʊl reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 93, 'fuller discussion', 'sự bàn luận sâu rộng hơn', 'adj + n', '[{"en":"A fuller discussion of these issues appears in chapter four.","vi":"Một bàn luận sâu rộng hơn về các vấn đề này nằm ở chương bốn."},{"en":"The topic deserves a fuller discussion than space allows here.","vi":"Chủ đề này đáng được bàn luận sâu hơn so với khuôn khổ ở đây."},{"en":"Reviewers asked for a fuller discussion of the limitations.","vi":"Người phản biện yêu cầu bàn luận đầy đủ hơn về các hạn chế."}]', '[]', NULL, '/ˈfʊlər dɪˈskʌʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 94, 'fully aware', 'hoàn toàn nhận thức được, ý thức rõ', 'adv + adj', '[{"en":"The researchers were fully aware of the study''s limitations.","vi":"Các nhà nghiên cứu hoàn toàn nhận thức được những hạn chế của nghiên cứu."},{"en":"Participants were fully aware of the risks before joining.","vi":"Người tham gia ý thức rõ về các rủi ro trước khi tham gia."},{"en":"Managers should be fully aware of local labor laws.","vi":"Người quản lý nên hoàn toàn nắm rõ luật lao động địa phương."}]', '[]', NULL, '/ˈfʊli əˈwer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 95, 'fully developed', 'phát triển hoàn chỉnh, đầy đủ', 'adv + vpp', '[{"en":"The theory is not yet fully developed and needs more testing.","vi":"Lý thuyết này chưa được phát triển hoàn chỉnh và cần kiểm chứng thêm."},{"en":"A fully developed argument requires strong supporting evidence.","vi":"Một lập luận phát triển đầy đủ cần có bằng chứng hỗ trợ vững chắc."},{"en":"The embryo''s organs are not fully developed at this stage.","vi":"Các cơ quan của phôi chưa phát triển hoàn chỉnh ở giai đoạn này."}]', '[]', NULL, '/ˈfʊli dɪˈveləpt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 96, 'fully informed', 'được thông tin đầy đủ', 'adv + vpp', '[{"en":"Voters must be fully informed before making such decisions.","vi":"Cử tri phải được thông tin đầy đủ trước khi đưa ra quyết định đó."},{"en":"The consent form ensures patients are fully informed.","vi":"Mẫu đồng ý bảo đảm rằng bệnh nhân được thông tin đầy đủ."},{"en":"A fully informed choice depends on access to reliable data.","vi":"Một lựa chọn được thông tin đầy đủ phụ thuộc vào dữ liệu đáng tin cậy."}]', '[]', NULL, '/ˈfʊli ɪnˈfɔːrmd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 97, 'fully integrated', 'được tích hợp hoàn toàn', 'adv + vpp', '[{"en":"The new software is fully integrated with existing systems.","vi":"Phần mềm mới được tích hợp hoàn toàn với các hệ thống hiện có."},{"en":"Immigrants who are fully integrated tend to find work faster.","vi":"Người nhập cư hòa nhập hoàn toàn thường tìm được việc nhanh hơn."},{"en":"The modules are fully integrated into a single curriculum.","vi":"Các học phần được tích hợp hoàn toàn vào một chương trình duy nhất."}]', '[]', NULL, '/ˈfʊli ˈɪntɪˌɡreɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 98, 'fully realized', 'được hiện thực hóa trọn vẹn', 'adv + vpp', '[{"en":"The project''s benefits were never fully realized in practice.","vi":"Lợi ích của dự án chưa bao giờ được hiện thực hóa trọn vẹn trên thực tế."},{"en":"Her ambitions were fully realized only after years of work.","vi":"Hoài bão của cô chỉ được hiện thực hóa trọn vẹn sau nhiều năm nỗ lực."},{"en":"The potential of renewable energy is not yet fully realized.","vi":"Tiềm năng của năng lượng tái tạo vẫn chưa được khai thác trọn vẹn."}]', '[]', NULL, '/ˈfʊli ˈriːəˌlaɪzd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 99, 'fully understand', 'hiểu một cách đầy đủ, thấu hiểu', 'adv + v', '[{"en":"Scientists do not yet fully understand how the disease spreads.","vi":"Các nhà khoa học vẫn chưa hiểu đầy đủ cách bệnh lây lan."},{"en":"To fully understand the results, read the methods section first.","vi":"Để hiểu trọn vẹn kết quả, hãy đọc phần phương pháp trước."},{"en":"Students must fully understand the theory before applying it.","vi":"Sinh viên phải thấu hiểu lý thuyết trước khi áp dụng nó."}]', '[]', NULL, '/ˈfʊli ˌʌndərˈstænd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 100, 'functional requirement', 'yêu cầu chức năng', 'adj + n', '[{"en":"Each functional requirement must be tested before the launch.","vi":"Mỗi yêu cầu chức năng phải được kiểm thử trước khi ra mắt."},{"en":"The team documented every functional requirement of the system.","vi":"Nhóm đã ghi lại từng yêu cầu chức năng của hệ thống."},{"en":"A missing functional requirement can delay the whole project.","vi":"Thiếu một yêu cầu chức năng có thể làm chậm cả dự án."}]', '[]', NULL, '/ˈfʌŋkʃənəl rɪˈkwaɪərmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 101, 'fundamental aspect', 'khía cạnh căn bản, cốt lõi', 'adj + n', '[{"en":"Trust is a fundamental aspect of any successful partnership.","vi":"Niềm tin là một khía cạnh căn bản của bất kỳ quan hệ hợp tác nào."},{"en":"The essay overlooks a fundamental aspect of the problem.","vi":"Bài luận bỏ qua một khía cạnh cốt lõi của vấn đề."},{"en":"Memory is a fundamental aspect of human learning.","vi":"Trí nhớ là một khía cạnh căn bản của việc học ở con người."}]', '[]', NULL, '/ˌfʌndəˈmentəl ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 102, 'fundamental assumption', 'giả định nền tảng', 'adj + n', '[{"en":"The model rests on a fundamental assumption about human behavior.","vi":"Mô hình dựa trên một giả định nền tảng về hành vi con người."},{"en":"Critics challenged the fundamental assumption of the study.","vi":"Giới phê bình đã chất vấn giả định nền tảng của nghiên cứu."},{"en":"Every fundamental assumption should be stated clearly upfront.","vi":"Mỗi giả định nền tảng cần được nêu rõ ràng ngay từ đầu."}]', '[]', NULL, '/ˌfʌndəˈmentəl əˈsʌmpʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 103, 'fundamental change', 'sự thay đổi căn bản', 'adj + n', '[{"en":"The reform brought a fundamental change to the education system.","vi":"Cuộc cải cách đã mang lại sự thay đổi căn bản cho hệ thống giáo dục."},{"en":"Technology has caused a fundamental change in how we work.","vi":"Công nghệ đã tạo ra một thay đổi căn bản trong cách chúng ta làm việc."},{"en":"Such a fundamental change requires broad public support.","vi":"Một thay đổi căn bản như vậy cần sự ủng hộ rộng rãi của công chúng."}]', '[]', NULL, '/ˌfʌndəˈmentəl tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 104, 'fundamental component', 'thành phần cốt lõi', 'adj + n', '[{"en":"Feedback is a fundamental component of effective teaching.","vi":"Phản hồi là một thành phần cốt lõi của việc giảng dạy hiệu quả."},{"en":"Water is a fundamental component of every living cell.","vi":"Nước là một thành phần cốt lõi của mọi tế bào sống."},{"en":"Trust forms a fundamental component of stable economies.","vi":"Niềm tin tạo nên một thành phần cốt lõi của nền kinh tế ổn định."}]', '[]', NULL, '/ˌfʌndəˈmentəl kəmˈpoʊnənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 105, 'fundamental difference', 'sự khác biệt căn bản', 'adj + n', '[{"en":"There is a fundamental difference between the two approaches.","vi":"Có một sự khác biệt căn bản giữa hai cách tiếp cận."},{"en":"The study highlights a fundamental difference in cell structure.","vi":"Nghiên cứu làm nổi bật một khác biệt căn bản trong cấu trúc tế bào."},{"en":"A fundamental difference in values caused the disagreement.","vi":"Một khác biệt căn bản về giá trị đã gây ra sự bất đồng."}]', '[]', NULL, '/ˌfʌndəˈmentəl ˈdɪfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 106, 'fundamental importance', 'tầm quan trọng căn bản', 'adj + n', '[{"en":"Clean water is of fundamental importance to public health.","vi":"Nước sạch có tầm quan trọng căn bản đối với sức khỏe cộng đồng."},{"en":"These findings are of fundamental importance to the field.","vi":"Những phát hiện này có tầm quan trọng căn bản đối với ngành."},{"en":"Education is of fundamental importance to economic growth.","vi":"Giáo dục có tầm quan trọng căn bản đối với tăng trưởng kinh tế."}]', '[]', NULL, '/ˌfʌndəˈmentəl ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 107, 'fundamental principle', 'nguyên tắc căn bản', 'adj + n', '[{"en":"Equality before the law is a fundamental principle of democracy.","vi":"Bình đẳng trước pháp luật là một nguyên tắc căn bản của nền dân chủ."},{"en":"The experiment illustrates a fundamental principle of physics.","vi":"Thí nghiệm minh họa một nguyên tắc căn bản của vật lý."},{"en":"Respect for evidence is a fundamental principle of science.","vi":"Tôn trọng bằng chứng là một nguyên tắc căn bản của khoa học."}]', '[]', NULL, '/ˌfʌndəˈmentəl ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 108, 'fundamental problem', 'vấn đề căn bản, cốt lõi', 'adj + n', '[{"en":"The fundamental problem is a lack of reliable data.","vi":"Vấn đề căn bản là sự thiếu hụt dữ liệu đáng tin cậy."},{"en":"Critics argue the plan ignores the fundamental problem entirely.","vi":"Giới phê bình cho rằng kế hoạch hoàn toàn bỏ qua vấn đề cốt lõi."},{"en":"Solving the fundamental problem requires long-term investment.","vi":"Giải quyết vấn đề căn bản đòi hỏi đầu tư dài hạn."}]', '[]', NULL, '/ˌfʌndəˈmentəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 109, 'fundamental question', 'câu hỏi căn bản, cốt lõi', 'adj + n', '[{"en":"The study addresses a fundamental question about human memory.","vi":"Nghiên cứu giải quyết một câu hỏi căn bản về trí nhớ con người."},{"en":"A fundamental question remains: who should pay for this?","vi":"Một câu hỏi cốt lõi vẫn còn đó: ai sẽ chi trả cho việc này?"},{"en":"Philosophers have long debated this fundamental question.","vi":"Các triết gia từ lâu đã tranh luận về câu hỏi căn bản này."}]', '[]', NULL, '/ˌfʌndəˈmentəl ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 110, 'fundamentally different', 'khác nhau về căn bản', 'adv + adj', '[{"en":"The two theories are fundamentally different in their assumptions.","vi":"Hai lý thuyết khác nhau về căn bản trong các giả định của chúng."},{"en":"Online learning is fundamentally different from classroom teaching.","vi":"Học trực tuyến khác về căn bản so với giảng dạy trên lớp."},{"en":"Their conclusions were fundamentally different despite similar data.","vi":"Kết luận của họ khác nhau về căn bản dù dùng dữ liệu tương tự."}]', '[]', NULL, '/ˌfʌndəˈmentəli ˈdɪfərənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 111, 'further analysis', 'sự phân tích thêm', 'adj + n', '[{"en":"Further analysis is needed to confirm these preliminary results.","vi":"Cần phân tích thêm để xác nhận những kết quả sơ bộ này."},{"en":"Further analysis revealed a strong link between the variables.","vi":"Phân tích thêm cho thấy mối liên hệ chặt chẽ giữa các biến số."},{"en":"The data was set aside for further analysis next year.","vi":"Dữ liệu được giữ lại để phân tích thêm vào năm sau."}]', '[]', NULL, '/ˈfɜːrðər əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 112, 'further consideration', 'sự cân nhắc thêm', 'adj + n', '[{"en":"The proposal requires further consideration before any approval.","vi":"Đề xuất cần được cân nhắc thêm trước khi được phê duyệt."},{"en":"These factors deserve further consideration in future studies.","vi":"Những yếu tố này đáng được cân nhắc thêm trong các nghiên cứu sau."},{"en":"The committee postponed the decision for further consideration.","vi":"Ủy ban hoãn quyết định để cân nhắc thêm."}]', '[]', NULL, '/ˈfɜːrðər kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 113, 'further development', 'sự phát triển thêm', 'adj + n', '[{"en":"The prototype needs further development before it can be sold.","vi":"Bản mẫu cần được phát triển thêm trước khi có thể bán ra."},{"en":"Funding was secured for the further development of the vaccine.","vi":"Đã có kinh phí cho việc phát triển thêm loại vắc-xin này."},{"en":"These ideas offer scope for further development in later chapters.","vi":"Những ý tưởng này mở ra hướng phát triển thêm ở các chương sau."}]', '[]', NULL, '/ˈfɜːrðər dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 114, 'further divided into', 'được chia nhỏ thêm thành', 'adv + vpp', '[{"en":"Each category is further divided into three smaller subgroups.","vi":"Mỗi nhóm được chia nhỏ thêm thành ba phân nhóm nhỏ hơn."},{"en":"The sample was further divided into control and test groups.","vi":"Mẫu được chia nhỏ thêm thành nhóm đối chứng và nhóm thử nghiệm."},{"en":"The chapter is further divided into clearly labeled sections.","vi":"Chương này được chia nhỏ thêm thành các phần được dán nhãn rõ ràng."}]', '[]', NULL, '/ˈfɜːrðər dɪˈvaɪdɪd ˈɪntə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 115, 'further evidence', 'bằng chứng bổ sung', 'adj + n', '[{"en":"Further evidence is required to support this bold claim.","vi":"Cần bằng chứng bổ sung để hỗ trợ cho khẳng định táo bạo này."},{"en":"Recent fossils provide further evidence for the theory.","vi":"Các hóa thạch gần đây cung cấp bằng chứng bổ sung cho lý thuyết."},{"en":"The trial gathered further evidence of the drug''s safety.","vi":"Cuộc thử nghiệm đã thu thập thêm bằng chứng về độ an toàn của thuốc."}]', '[]', NULL, '/ˈfɜːrðər ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 116, 'further explanation', 'lời giải thích thêm', 'adj + n', '[{"en":"These terms require further explanation for the general reader.","vi":"Những thuật ngữ này cần được giải thích thêm cho độc giả phổ thông."},{"en":"The teacher offered further explanation after the lecture.","vi":"Giáo viên đưa ra lời giải thích thêm sau bài giảng."},{"en":"No further explanation was given for the sudden change.","vi":"Không có lời giải thích thêm nào cho sự thay đổi đột ngột."}]', '[]', NULL, '/ˈfɜːrðər ˌekspləˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 117, 'further information', 'thông tin thêm', 'adj + n', '[{"en":"For further information, please contact the admissions office.","vi":"Để biết thêm thông tin, vui lòng liên hệ phòng tuyển sinh."},{"en":"The appendix provides further information about the methodology.","vi":"Phụ lục cung cấp thông tin thêm về phương pháp luận."},{"en":"Further information is available on the project''s website.","vi":"Thông tin thêm có sẵn trên trang web của dự án."}]', '[]', NULL, '/ˈfɜːrðər ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 118, 'further investigation', 'sự điều tra, tìm hiểu thêm', 'adj + n', '[{"en":"These anomalies warrant further investigation by the research team.","vi":"Những bất thường này cần được nhóm nghiên cứu tìm hiểu thêm."},{"en":"The police are conducting further investigation into the case.","vi":"Cảnh sát đang tiến hành điều tra thêm về vụ việc."},{"en":"Further investigation may reveal the cause of the failure.","vi":"Việc tìm hiểu thêm có thể làm rõ nguyên nhân của sự cố."}]', '[]', NULL, '/ˈfɜːrðər ɪnˌvestɪˈɡeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 119, 'further research', 'nghiên cứu thêm', 'adj + n', '[{"en":"Further research is needed to confirm the link conclusively.","vi":"Cần nghiên cứu thêm để xác nhận mối liên hệ một cách chắc chắn."},{"en":"The paper suggests several directions for further research.","vi":"Bài báo gợi ý một số hướng cho nghiên cứu thêm."},{"en":"Further research could explore the long-term effects of the drug.","vi":"Nghiên cứu thêm có thể khám phá tác động dài hạn của loại thuốc."}]', '[]', NULL, '/ˈfɜːrðər ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 120, 'further study', 'sự nghiên cứu, học tập thêm', 'adj + n', '[{"en":"This topic clearly merits further study in future projects.","vi":"Chủ đề này rõ ràng xứng đáng được nghiên cứu thêm trong các dự án sau."},{"en":"Many graduates pursue further study at the master''s level.","vi":"Nhiều sinh viên tốt nghiệp theo học thêm ở bậc thạc sĩ."},{"en":"Further study is required to understand the full effects.","vi":"Cần nghiên cứu thêm để hiểu hết các tác động."}]', '[]', NULL, '/ˈfɜːrðər ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 121, 'future development', 'sự phát triển trong tương lai', 'adj + n', '[{"en":"The report outlines plans for the future development of the city.","vi":"Báo cáo phác thảo các kế hoạch phát triển thành phố trong tương lai."},{"en":"Investment today supports the future development of the region.","vi":"Đầu tư hôm nay hỗ trợ sự phát triển của khu vực trong tương lai."},{"en":"These findings will guide the future development of the product.","vi":"Những phát hiện này sẽ định hướng phát triển sản phẩm trong tương lai."}]', '[]', NULL, '/ˈfjuːtʃər dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 122, 'future prospects', 'triển vọng tương lai', 'adj + n', '[{"en":"A degree can greatly improve a graduate''s future prospects.","vi":"Một tấm bằng có thể cải thiện đáng kể triển vọng tương lai của sinh viên."},{"en":"The report assesses the future prospects of the industry.","vi":"Báo cáo đánh giá triển vọng tương lai của ngành công nghiệp."},{"en":"Economic uncertainty has dimmed the country''s future prospects.","vi":"Sự bất ổn kinh tế đã làm lu mờ triển vọng tương lai của đất nước."}]', '[]', NULL, '/ˈfjuːtʃər ˈprɑːspekts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 123, 'future research', 'nghiên cứu trong tương lai', 'adj + n', '[{"en":"Future research should examine a larger and more diverse sample.","vi":"Nghiên cứu trong tương lai nên xem xét một mẫu lớn và đa dạng hơn."},{"en":"The authors propose several questions for future research.","vi":"Các tác giả đề xuất một số câu hỏi cho nghiên cứu trong tương lai."},{"en":"Future research could test the model in other countries.","vi":"Nghiên cứu trong tương lai có thể kiểm chứng mô hình ở các nước khác."}]', '[]', NULL, '/ˈfjuːtʃər ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 124, 'future study', 'nghiên cứu sau này', 'adj + n', '[{"en":"A future study might explore the role of motivation here.","vi":"Một nghiên cứu sau này có thể khám phá vai trò của động lực ở đây."},{"en":"The findings provide a foundation for future study of the topic.","vi":"Những phát hiện này tạo nền tảng cho nghiên cứu sau này về chủ đề."},{"en":"Any future study should control for these confounding factors.","vi":"Mọi nghiên cứu sau này nên kiểm soát các yếu tố gây nhiễu này."}]', '[]', NULL, '/ˈfjuːtʃər ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 125, 'gain access to', 'có được quyền truy cập vào', 'v + n', '[{"en":"Students can gain access to the database with their library card.","vi":"Sinh viên có thể truy cập cơ sở dữ liệu bằng thẻ thư viện của mình."},{"en":"Hackers tried to gain access to the company''s private servers.","vi":"Tin tặc đã cố truy cập vào các máy chủ riêng của công ty."},{"en":"Researchers struggled to gain access to the remote region.","vi":"Các nhà nghiên cứu chật vật để tiếp cận được vùng xa xôi này."}]', '[]', NULL, '/ɡeɪn ˈækses tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 126, 'gain information', 'thu được thông tin', 'v + n', '[{"en":"Interviews help researchers gain information about people''s habits.","vi":"Phỏng vấn giúp nhà nghiên cứu thu được thông tin về thói quen của mọi người."},{"en":"We gain information about the past by studying old documents.","vi":"Chúng ta thu được thông tin về quá khứ qua việc nghiên cứu tài liệu cũ."},{"en":"Surveys are a quick way to gain information from many people.","vi":"Khảo sát là cách nhanh để thu được thông tin từ nhiều người."}]', '[]', NULL, '/ɡeɪn ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 127, 'gain insight into', 'có được hiểu biết sâu sắc về', 'v + n', '[{"en":"The study helps us gain insight into consumer decision-making.","vi":"Nghiên cứu giúp ta hiểu sâu hơn về cách người tiêu dùng ra quyết định."},{"en":"Fieldwork allowed her to gain insight into local traditions.","vi":"Công tác thực địa giúp cô hiểu sâu sắc về phong tục địa phương."},{"en":"Interviews gain insight into how patients experience illness.","vi":"Phỏng vấn giúp hiểu sâu về cách bệnh nhân trải nghiệm bệnh tật."}]', '[]', NULL, '/ɡeɪn ˈɪnsaɪt ˈɪntə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 128, 'gather data', 'thu thập dữ liệu', 'v + n', '[{"en":"The team used surveys to gather data from rural households.","vi":"Nhóm dùng khảo sát để thu thập dữ liệu từ các hộ gia đình nông thôn."},{"en":"Sensors gather data on temperature throughout the day.","vi":"Các cảm biến thu thập dữ liệu về nhiệt độ suốt cả ngày."},{"en":"It took six months to gather data for the study.","vi":"Phải mất sáu tháng để thu thập dữ liệu cho nghiên cứu."}]', '[]', NULL, '/ˈɡæðər ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 129, 'gather information', 'thu thập thông tin', 'v + n', '[{"en":"Journalists gather information from a wide range of sources.","vi":"Nhà báo thu thập thông tin từ nhiều nguồn khác nhau."},{"en":"The committee will gather information before making a decision.","vi":"Ủy ban sẽ thu thập thông tin trước khi đưa ra quyết định."},{"en":"Online tools make it easier to gather information quickly.","vi":"Các công cụ trực tuyến giúp thu thập thông tin nhanh chóng hơn."}]', '[]', NULL, '/ˈɡæðər ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 130, 'gender equality', 'bình đẳng giới', 'n + n', '[{"en":"The policy aims to promote gender equality in the workplace.","vi":"Chính sách nhằm thúc đẩy bình đẳng giới tại nơi làm việc."},{"en":"Many countries have made progress toward gender equality.","vi":"Nhiều quốc gia đã đạt tiến bộ trong việc hướng tới bình đẳng giới."},{"en":"Education plays a key role in achieving gender equality.","vi":"Giáo dục đóng vai trò quan trọng trong việc đạt bình đẳng giới."}]', '[]', NULL, '/ˈdʒendər ɪˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 131, 'gender stereotype', 'định kiến giới', 'n + n', '[{"en":"Advertisements often reinforce a common gender stereotype.","vi":"Quảng cáo thường củng cố một định kiến giới phổ biến."},{"en":"The study examined how a gender stereotype affects career choice.","vi":"Nghiên cứu xem xét cách định kiến giới ảnh hưởng đến lựa chọn nghề nghiệp."},{"en":"Teachers should avoid promoting any gender stereotype in class.","vi":"Giáo viên nên tránh cổ xúy bất kỳ định kiến giới nào trong lớp."}]', '[]', NULL, '/ˈdʒendər ˈsteriəˌtaɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 132, 'general agreement', 'sự nhất trí chung', 'adj + n', '[{"en":"There is general agreement that the policy needs reform.","vi":"Có sự nhất trí chung rằng chính sách này cần được cải cách."},{"en":"The experts reached general agreement on the main causes.","vi":"Các chuyên gia đã đạt được sự nhất trí chung về các nguyên nhân chính."},{"en":"Despite some debate, general agreement emerged on the goals.","vi":"Dù còn tranh luận, sự nhất trí chung đã hình thành về các mục tiêu."}]', '[]', NULL, '/ˈdʒenərəl əˈɡriːmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 133, 'general approach', 'cách tiếp cận chung', 'adj + n', '[{"en":"The chapter outlines a general approach to solving the problem.","vi":"Chương này phác thảo một cách tiếp cận chung để giải quyết vấn đề."},{"en":"Their general approach combines theory with practical examples.","vi":"Cách tiếp cận chung của họ kết hợp lý thuyết với ví dụ thực tế."},{"en":"A general approach may not suit every individual case.","vi":"Một cách tiếp cận chung có thể không phù hợp với mọi trường hợp."}]', '[]', NULL, '/ˈdʒenərəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 134, 'general argument', 'lập luận tổng quát', 'adj + n', '[{"en":"The book''s general argument is that culture shapes economics.","vi":"Lập luận tổng quát của cuốn sách là văn hóa định hình kinh tế."},{"en":"Her general argument holds even when the details differ.","vi":"Lập luận tổng quát của bà vẫn đúng ngay cả khi chi tiết khác nhau."},{"en":"Critics accepted the general argument but questioned the evidence.","vi":"Giới phê bình chấp nhận lập luận tổng quát nhưng nghi ngờ bằng chứng."}]', '[]', NULL, '/ˈdʒenərəl ˈɑːrɡjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 135, 'general aspect', 'khía cạnh chung', 'adj + n', '[{"en":"The lecture covered a general aspect of climate science.","vi":"Bài giảng đề cập đến một khía cạnh chung của khoa học khí hậu."},{"en":"We start with a general aspect before examining the details.","vi":"Chúng ta bắt đầu với một khía cạnh chung trước khi xem xét chi tiết."},{"en":"This general aspect applies across many different cultures.","vi":"Khía cạnh chung này áp dụng cho nhiều nền văn hóa khác nhau."}]', '[]', NULL, '/ˈdʒenərəl ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 136, 'general category', 'loại chung, hạng mục chung', 'adj + n', '[{"en":"These responses fall into one broad general category.","vi":"Những phản hồi này thuộc về một loại chung rộng lớn."},{"en":"The survey grouped answers into a few general categories.","vi":"Khảo sát nhóm các câu trả lời vào vài hạng mục chung."},{"en":"Each general category is defined clearly in the methods section.","vi":"Mỗi loại chung được định nghĩa rõ ràng trong phần phương pháp."}]', '[]', NULL, '/ˈdʒenərəl ˈkætəˌɡɔːri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 137, 'general conclusion', 'kết luận chung', 'adj + n', '[{"en":"The general conclusion is that early intervention works best.","vi":"Kết luận chung là can thiệp sớm mang lại hiệu quả tốt nhất."},{"en":"From these results we can draw a clear general conclusion.","vi":"Từ những kết quả này, ta có thể rút ra một kết luận chung rõ ràng."},{"en":"The general conclusion holds despite a few exceptions.","vi":"Kết luận chung vẫn đúng dù có một vài ngoại lệ."}]', '[]', NULL, '/ˈdʒenərəl kənˈkluːʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 138, 'general consensus', 'sự đồng thuận chung', 'adj + n', '[{"en":"The general consensus among scientists is that the data is solid.","vi":"Sự đồng thuận chung giữa các nhà khoa học là dữ liệu đáng tin cậy."},{"en":"There is a general consensus that the reform improved schools.","vi":"Có sự đồng thuận chung rằng cải cách đã cải thiện trường học."},{"en":"The committee reached a general consensus after long debate.","vi":"Ủy ban đạt được sự đồng thuận chung sau cuộc tranh luận dài."}]', '[]', NULL, '/ˈdʒenərəl kənˈsensəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 139, 'general definition', 'định nghĩa chung', 'adj + n', '[{"en":"The author begins with a general definition of culture.","vi":"Tác giả bắt đầu bằng một định nghĩa chung về văn hóa."},{"en":"A general definition helps readers follow the argument.","vi":"Một định nghĩa chung giúp người đọc theo dõi lập luận."},{"en":"We need a general definition before discussing specific cases.","vi":"Ta cần một định nghĩa chung trước khi bàn về các trường hợp cụ thể."}]', '[]', NULL, '/ˈdʒenərəl ˌdefɪˈnɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 140, 'general feature', 'đặc điểm chung', 'adj + n', '[{"en":"Repetition is a general feature of early childhood learning.","vi":"Sự lặp lại là một đặc điểm chung của việc học ở trẻ nhỏ."},{"en":"The report describes a general feature shared by all the cases.","vi":"Báo cáo mô tả một đặc điểm chung của tất cả các trường hợp."},{"en":"This general feature appears across many language families.","vi":"Đặc điểm chung này xuất hiện ở nhiều ngữ hệ khác nhau."}]', '[]', NULL, '/ˈdʒenərəl ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 141, 'general formula', 'công thức tổng quát', 'adj + n', '[{"en":"The chapter derives a general formula for the area of a polygon.","vi":"Chương này suy ra một công thức tổng quát cho diện tích đa giác."},{"en":"A general formula lets us solve many similar problems quickly.","vi":"Một công thức tổng quát giúp ta giải nhanh nhiều bài tương tự."},{"en":"From the examples, students develop a general formula themselves.","vi":"Từ các ví dụ, sinh viên tự xây dựng một công thức tổng quát."}]', '[]', NULL, '/ˈdʒenərəl ˈfɔːrmjələ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 142, 'general overview', 'cái nhìn tổng quan chung', 'adj + n', '[{"en":"The introduction gives a general overview of the topic.","vi":"Phần mở đầu đưa ra cái nhìn tổng quan chung về chủ đề."},{"en":"This section offers a general overview before the detailed analysis.","vi":"Phần này cung cấp cái nhìn tổng quan trước khi phân tích chi tiết."},{"en":"She began the talk with a general overview of the findings.","vi":"Cô bắt đầu bài nói bằng cái nhìn tổng quan về các phát hiện."}]', '[]', NULL, '/ˈdʒenərəl ˈoʊvərˌvjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 143, 'general principle', 'nguyên tắc chung', 'adj + n', '[{"en":"The same general principle applies to most chemical reactions.","vi":"Cùng một nguyên tắc chung áp dụng cho hầu hết các phản ứng hóa học."},{"en":"As a general principle, claims must be supported by evidence.","vi":"Theo nguyên tắc chung, mọi khẳng định phải có bằng chứng hỗ trợ."},{"en":"Students should grasp the general principle before the details.","vi":"Sinh viên nên nắm nguyên tắc chung trước khi học chi tiết."}]', '[]', NULL, '/ˈdʒenərəl ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 144, 'general statement', 'phát biểu chung chung', 'adj + n', '[{"en":"Avoid a vague general statement and provide specific evidence.","vi":"Tránh phát biểu chung chung mơ hồ và hãy đưa ra bằng chứng cụ thể."},{"en":"The essay opens with a general statement about modern cities.","vi":"Bài luận mở đầu bằng một phát biểu chung về các thành phố hiện đại."},{"en":"A general statement should be narrowed into a clear thesis.","vi":"Một phát biểu chung nên được thu hẹp thành một luận điểm rõ ràng."}]', '[]', NULL, '/ˈdʒenərəl ˈsteɪtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 145, 'general tendency', 'xu hướng chung', 'adj + n', '[{"en":"The data shows a general tendency toward higher prices.","vi":"Dữ liệu cho thấy một xu hướng chung là giá tăng cao hơn."},{"en":"There is a general tendency for cities to expand outward.","vi":"Có một xu hướng chung là các thành phố mở rộng ra bên ngoài."},{"en":"The study identified a general tendency among younger voters.","vi":"Nghiên cứu xác định một xu hướng chung ở các cử tri trẻ tuổi."}]', '[]', NULL, '/ˈdʒenərəl ˈtendənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 146, 'general theory', 'lý thuyết tổng quát', 'adj + n', '[{"en":"Einstein''s general theory transformed our view of gravity.","vi":"Lý thuyết tổng quát của Einstein đã thay đổi quan niệm về trọng lực."},{"en":"The book proposes a general theory of social change.","vi":"Cuốn sách đề xuất một lý thuyết tổng quát về biến đổi xã hội."},{"en":"A general theory must account for a wide range of cases.","vi":"Một lý thuyết tổng quát phải giải thích được nhiều trường hợp khác nhau."}]', '[]', NULL, '/ˈdʒenərəl ˈθɪəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 147, 'general trend', 'xu thế chung', 'adj + n', '[{"en":"The graph reveals a general trend of rising temperatures.","vi":"Biểu đồ cho thấy một xu thế chung là nhiệt độ ngày càng tăng."},{"en":"Despite yearly variation, the general trend is upward.","vi":"Dù dao động theo năm, xu thế chung vẫn là đi lên."},{"en":"The general trend points to greater use of renewable energy.","vi":"Xu thế chung cho thấy việc sử dụng năng lượng tái tạo nhiều hơn."}]', '[]', NULL, '/ˈdʒenərəl trend/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 148, 'generally accepted', 'được công nhận rộng rãi', 'adv + vpp', '[{"en":"It is generally accepted that exercise benefits mental health.","vi":"Người ta công nhận rộng rãi rằng tập thể dục có lợi cho sức khỏe tinh thần."},{"en":"These methods are generally accepted in clinical research.","vi":"Những phương pháp này được công nhận rộng rãi trong nghiên cứu lâm sàng."},{"en":"The theory is now generally accepted by most economists.","vi":"Lý thuyết này giờ đây được hầu hết các nhà kinh tế công nhận."}]', '[]', NULL, '/ˈdʒenərəli əkˈseptɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 149, 'generally agree', 'nhìn chung đồng ý', 'adv + v', '[{"en":"Experts generally agree that the policy reduced pollution.","vi":"Các chuyên gia nhìn chung đồng ý rằng chính sách đã giảm ô nhiễm."},{"en":"Historians generally agree on the main causes of the war.","vi":"Các sử gia nhìn chung đồng ý về các nguyên nhân chính của cuộc chiến."},{"en":"Researchers generally agree that more data is needed.","vi":"Các nhà nghiên cứu nhìn chung đồng ý rằng cần thêm dữ liệu."}]', '[]', NULL, '/ˈdʒenərəli əˈɡriː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-6-01', 150, 'generally assumed', 'thường được cho rằng', 'adv + vpp', '[{"en":"It is generally assumed that prices will rise over time.","vi":"Người ta thường cho rằng giá sẽ tăng theo thời gian."},{"en":"It was generally assumed the experiment would fail.","vi":"Người ta thường cho rằng thí nghiệm sẽ thất bại."},{"en":"These assumptions are generally assumed without much evidence.","vi":"Những giả định này thường được cho là đúng mà thiếu bằng chứng."}]', '[]', NULL, '/ˈdʒenərəli əˈsuːmd/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-7-01', 'colloc-7', 'Cụm học thuật · Nhóm 7', 'Academic Collocation List (Pearson/PTE) — nhóm 7 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 1, 'generally considered', 'thường được xem là', 'adv + vpp', '[{"en":"This is generally considered the most reliable method available.","vi":"Đây thường được xem là phương pháp đáng tin cậy nhất hiện có."},{"en":"She is generally considered an expert in her field.","vi":"Bà thường được xem là một chuyên gia trong lĩnh vực của mình."},{"en":"The novel is generally considered a masterpiece of the era.","vi":"Cuốn tiểu thuyết thường được xem là một kiệt tác của thời đại."}]', '[]', NULL, '/ˈdʒenərəli kənˈsɪdərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 2, 'generally found', 'thường thấy, nhìn chung gặp', 'adv + vpp', '[{"en":"These minerals are generally found near volcanic regions.","vi":"Những khoáng chất này thường thấy gần các vùng núi lửa."},{"en":"Such behavior is generally found in highly social animals.","vi":"Hành vi như vậy nhìn chung gặp ở các loài vật có tính xã hội cao."},{"en":"The pattern is generally found across most age groups.","vi":"Mô hình này thường thấy ở hầu hết các nhóm tuổi."}]', '[]', NULL, '/ˈdʒenərəli faʊnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 3, 'generally known as', 'thường được gọi là', 'adv + vpp', '[{"en":"The condition is generally known as the common cold.","vi":"Tình trạng này thường được gọi là cảm lạnh thông thường."},{"en":"This region is generally known as the country''s industrial heart.","vi":"Vùng này thường được gọi là trái tim công nghiệp của đất nước."},{"en":"The process is generally known as natural selection.","vi":"Quá trình này thường được gọi là chọn lọc tự nhiên."}]', '[]', NULL, '/ˈdʒenərəli noʊn əz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 4, 'genetic variation', 'sự biến dị di truyền', 'adj + n', '[{"en":"Genetic variation helps a population adapt to changing conditions.","vi":"Sự biến dị di truyền giúp quần thể thích nghi với điều kiện thay đổi."},{"en":"The study measured genetic variation across several populations.","vi":"Nghiên cứu đo lường sự biến dị di truyền giữa nhiều quần thể."},{"en":"Low genetic variation can make a species vulnerable to disease.","vi":"Biến dị di truyền thấp có thể khiến loài dễ tổn thương trước bệnh tật."}]', '[]', NULL, '/dʒəˈnetɪk ˌveriˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 5, 'geographic al area', 'khu vực địa lý', 'adj + n', '[{"en":"The survey covered a wide geographic al area of the country.","vi":"Cuộc khảo sát bao phủ một khu vực địa lý rộng lớn của đất nước."},{"en":"Rainfall varies greatly from one geographic al area to another.","vi":"Lượng mưa khác nhau rất nhiều giữa các khu vực địa lý."},{"en":"The disease was limited to a small geographic al area.","vi":"Dịch bệnh chỉ giới hạn trong một khu vực địa lý nhỏ."}]', '[]', NULL, '/ˌdʒiːəˈɡræfɪkəl ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 6, 'geographic al distribution', 'sự phân bố theo địa lý', 'adj + n', '[{"en":"The map shows the geographic al distribution of the species.","vi":"Bản đồ cho thấy sự phân bố theo địa lý của loài này."},{"en":"Researchers studied the geographic al distribution of the disease.","vi":"Các nhà nghiên cứu nghiên cứu sự phân bố theo địa lý của dịch bệnh."},{"en":"The geographic al distribution of wealth remains highly uneven.","vi":"Sự phân bố của cải theo địa lý vẫn rất không đồng đều."}]', '[]', NULL, '/ˌdʒiːəˈɡræfɪkəl ˌdɪstrɪˈbjuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 7, 'geographic al location', 'vị trí địa lý', 'adj + n', '[{"en":"The city''s geographic al location made it a major trading hub.","vi":"Vị trí địa lý của thành phố biến nó thành một trung tâm thương mại lớn."},{"en":"Climate depends heavily on a region''s geographic al location.","vi":"Khí hậu phụ thuộc nhiều vào vị trí địa lý của một vùng."},{"en":"Its geographic al location gives the port a strategic advantage.","vi":"Vị trí địa lý mang lại cho cảng này một lợi thế chiến lược."}]', '[]', NULL, '/ˌdʒiːəˈɡræfɪkəl loʊˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 8, 'get involved with', 'tham gia vào, dính líu đến', 'v + adj', '[{"en":"Students are encouraged to get involved with campus activities.","vi":"Sinh viên được khuyến khích tham gia vào các hoạt động trong trường."},{"en":"She wanted to get involved with the local research project.","vi":"Cô muốn tham gia vào dự án nghiên cứu của địa phương."},{"en":"Volunteers get involved with the program to gain experience.","vi":"Các tình nguyện viên tham gia vào chương trình để có kinh nghiệm."}]', '[]', NULL, '/ɡet ɪnˈvɑːlvd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 9, 'give access to', 'cấp quyền truy cập, cho tiếp cận', 'v + n', '[{"en":"The membership gives access to thousands of academic articles.","vi":"Tư cách thành viên cho phép truy cập hàng nghìn bài báo học thuật."},{"en":"The new bridge gives access to remote mountain villages.","vi":"Cây cầu mới giúp tiếp cận các bản làng vùng núi xa xôi."},{"en":"The pass gives access to all areas of the conference.","vi":"Thẻ vào cổng cho phép tiếp cận mọi khu vực của hội nghị."}]', '[]', NULL, '/ɡɪv ˈækses tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 10, 'give consent', 'đưa ra sự đồng ý, chấp thuận', 'v + n', '[{"en":"Patients must give consent before any procedure begins.","vi":"Bệnh nhân phải đưa ra sự đồng ý trước khi bắt đầu bất kỳ thủ thuật nào."},{"en":"Participants gave consent after reading the information sheet.","vi":"Người tham gia đã chấp thuận sau khi đọc bản thông tin."},{"en":"Parents must give consent for children to join the study.","vi":"Phụ huynh phải đồng ý để trẻ em tham gia vào nghiên cứu."}]', '[]', NULL, '/ɡɪv kənˈsent/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 11, 'give consideration', 'cân nhắc, xem xét kỹ', 'v + n', '[{"en":"The committee will give consideration to every proposal before deciding.","vi":"Ủy ban sẽ cân nhắc mọi đề xuất trước khi quyết định."},{"en":"Please give consideration to the safety risks involved here.","vi":"Hãy xem xét kỹ các rủi ro an toàn liên quan ở đây."},{"en":"Researchers must give consideration to ethical issues in their studies.","vi":"Các nhà nghiên cứu phải cân nhắc các vấn đề đạo đức trong nghiên cứu."}]', '[]', NULL, '/ɡɪv kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 12, 'give emphasis', 'nhấn mạnh, chú trọng', 'v + n', '[{"en":"The teacher gives emphasis to grammar in every writing lesson.","vi":"Giáo viên chú trọng ngữ pháp trong mỗi bài học viết."},{"en":"This report gives emphasis to the long-term economic effects.","vi":"Báo cáo này nhấn mạnh các tác động kinh tế dài hạn."},{"en":"Modern programs give emphasis to practical skills over theory.","vi":"Các chương trình hiện đại chú trọng kỹ năng thực hành hơn lý thuyết."}]', '[]', NULL, '/ɡɪv ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 13, 'give evidence', 'đưa ra bằng chứng, làm chứng', 'v + n', '[{"en":"The witness agreed to give evidence at the trial tomorrow.","vi":"Nhân chứng đồng ý làm chứng tại phiên tòa ngày mai."},{"en":"These experiments give evidence that the theory is correct.","vi":"Các thí nghiệm này đưa ra bằng chứng rằng lý thuyết là đúng."},{"en":"Students must give evidence to support each claim they make.","vi":"Sinh viên phải đưa ra bằng chứng cho mỗi luận điểm họ nêu."}]', '[]', NULL, '/ɡɪv ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 14, 'give feedback', 'đưa ra phản hồi, nhận xét', 'v + n', '[{"en":"The tutor will give feedback on your essay by Friday.","vi":"Gia sư sẽ đưa ra phản hồi về bài luận của bạn trước thứ Sáu."},{"en":"Managers should give feedback that is clear and constructive.","vi":"Quản lý nên đưa ra phản hồi rõ ràng và mang tính xây dựng."},{"en":"Peers give feedback to each other during the workshop sessions.","vi":"Các bạn học đưa ra nhận xét cho nhau trong các buổi hội thảo."}]', '[]', NULL, '/ɡɪv ˈfiːdbæk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 15, 'give priority to', 'ưu tiên cho', 'v + n', '[{"en":"The hospital gives priority to patients with serious conditions.","vi":"Bệnh viện ưu tiên cho những bệnh nhân có tình trạng nghiêm trọng."},{"en":"We should give priority to reducing pollution in cities.","vi":"Chúng ta nên ưu tiên cho việc giảm ô nhiễm ở các thành phố."},{"en":"The policy gives priority to families with low incomes.","vi":"Chính sách ưu tiên cho các gia đình có thu nhập thấp."}]', '[]', NULL, '/ɡɪv praɪˈɔːrəti tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 16, 'give guidance', 'đưa ra hướng dẫn, chỉ dẫn', 'v + n', '[{"en":"The advisor gives guidance to students choosing their courses.","vi":"Cố vấn đưa ra hướng dẫn cho sinh viên đang chọn môn học."},{"en":"This handbook gives guidance on writing a research proposal.","vi":"Sổ tay này đưa ra hướng dẫn về cách viết đề cương nghiên cứu."},{"en":"Experienced staff give guidance to new employees every week.","vi":"Nhân viên giàu kinh nghiệm chỉ dẫn cho người mới mỗi tuần."}]', '[]', NULL, '/ɡɪv ˈɡaɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 17, 'give information', 'cung cấp thông tin', 'v + n', '[{"en":"The website gives information about visa rules for travelers.","vi":"Trang web cung cấp thông tin về quy định thị thực cho khách du lịch."},{"en":"Please give information about your previous work experience.","vi":"Vui lòng cung cấp thông tin về kinh nghiệm làm việc trước đây của bạn."},{"en":"The survey gives information on how customers use the product.","vi":"Cuộc khảo sát cung cấp thông tin về cách khách hàng dùng sản phẩm."}]', '[]', NULL, '/ɡɪv ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 18, 'give insight into', 'giúp hiểu sâu về, cho cái nhìn sâu sắc về', 'v + n', '[{"en":"The interviews give insight into how teenagers use social media.","vi":"Các cuộc phỏng vấn giúp hiểu sâu về cách thanh thiếu niên dùng mạng xã hội."},{"en":"Her diary gives insight into life during the war.","vi":"Nhật ký của cô cho cái nhìn sâu sắc về cuộc sống thời chiến."},{"en":"These results give insight into the causes of the problem.","vi":"Những kết quả này giúp hiểu sâu về nguyên nhân của vấn đề."}]', '[]', NULL, '/ɡɪv ˈɪnsaɪt ˈɪntə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 19, 'give a presentation', 'thuyết trình, trình bày', 'v + n', '[{"en":"Each student must give a presentation at the end of term.","vi":"Mỗi sinh viên phải thuyết trình vào cuối học kỳ."},{"en":"She will give a presentation on renewable energy next week.","vi":"Cô ấy sẽ thuyết trình về năng lượng tái tạo vào tuần tới."},{"en":"The manager gave a presentation about the new sales strategy.","vi":"Quản lý đã trình bày về chiến lược bán hàng mới."}]', '[]', NULL, '/ɡɪv ə ˌprezənˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 20, 'give an explanation', 'đưa ra lời giải thích', 'v + n', '[{"en":"The author gives an explanation for the unexpected results.","vi":"Tác giả đưa ra lời giải thích cho những kết quả bất ngờ."},{"en":"Can you give an explanation of how this machine works?","vi":"Bạn có thể giải thích máy này hoạt động thế nào không?"},{"en":"The teacher gave an explanation that everyone could understand.","vi":"Giáo viên đưa ra lời giải thích mà ai cũng có thể hiểu."}]', '[]', NULL, '/ɡɪv ən ˌekspləˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 21, 'give an indication of', 'cho thấy dấu hiệu về, biểu thị', 'v + n', '[{"en":"The early data gives an indication of future market trends.","vi":"Dữ liệu ban đầu cho thấy dấu hiệu về xu hướng thị trường tương lai."},{"en":"His tone gave an indication of how serious the matter was.","vi":"Giọng điệu của anh biểu thị mức độ nghiêm trọng của vấn đề."},{"en":"These figures give an indication of the company''s overall health.","vi":"Những con số này cho thấy dấu hiệu về tình hình chung của công ty."}]', '[]', NULL, '/ɡɪv ən ˌɪndɪˈkeɪʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 22, 'give an overview of', 'đưa ra cái nhìn tổng quan về', 'v + n', '[{"en":"The first chapter gives an overview of the whole subject.","vi":"Chương đầu đưa ra cái nhìn tổng quan về toàn bộ chủ đề."},{"en":"She gave an overview of the project before the discussion.","vi":"Cô ấy đưa ra cái nhìn tổng quan về dự án trước khi thảo luận."},{"en":"This article gives an overview of recent climate research.","vi":"Bài viết này đưa ra cái nhìn tổng quan về nghiên cứu khí hậu gần đây."}]', '[]', NULL, '/ɡɪv ən ˈoʊvərvjuː əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 23, 'give somebody an impression', 'tạo cho ai đó ấn tượng', 'v + n', '[{"en":"The opening scene gives the reader an impression of danger.","vi":"Cảnh mở đầu tạo cho người đọc ấn tượng về sự nguy hiểm."},{"en":"His confident speech gave us an impression of real expertise.","vi":"Bài phát biểu tự tin của anh tạo cho chúng tôi ấn tượng về sự chuyên môn."},{"en":"The bright office gave visitors an impression of success.","vi":"Văn phòng sáng sủa tạo cho khách tham quan ấn tượng về sự thành công."}]', '[]', NULL, '/ɡɪv ˈsʌmbɑːdi ən ɪmˈpreʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 24, 'give somebody treatment', 'điều trị cho ai đó', 'v + n', '[{"en":"The doctors gave the patient treatment as soon as possible.","vi":"Các bác sĩ điều trị cho bệnh nhân càng sớm càng tốt."},{"en":"Nurses give every child treatment with great care here.","vi":"Các y tá điều trị cho từng đứa trẻ rất cẩn thận ở đây."},{"en":"The clinic gives poorer families treatment at no cost.","vi":"Phòng khám điều trị cho các gia đình nghèo hơn miễn phí."}]', '[]', NULL, '/ɡɪv ˈsʌmbɑːdi ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 25, 'given information', 'thông tin đã cho, thông tin sẵn có', 'adj + n', '[{"en":"Use the given information to calculate the final answer.","vi":"Hãy dùng thông tin đã cho để tính ra đáp án cuối cùng."},{"en":"The given information was not enough to solve the case.","vi":"Thông tin sẵn có không đủ để giải quyết vụ việc."},{"en":"Students must analyze the given information before answering.","vi":"Sinh viên phải phân tích thông tin đã cho trước khi trả lời."}]', '[]', NULL, '/ˈɡɪvən ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 26, 'given period', 'khoảng thời gian nhất định', 'adj + n', '[{"en":"The chart shows sales during a given period of time.","vi":"Biểu đồ cho thấy doanh số trong một khoảng thời gian nhất định."},{"en":"Within any given period, prices can rise or fall.","vi":"Trong bất kỳ khoảng thời gian nhất định nào, giá có thể tăng hoặc giảm."},{"en":"We measured rainfall over a given period of six months.","vi":"Chúng tôi đo lượng mưa trong khoảng thời gian sáu tháng nhất định."}]', '[]', NULL, '/ˈɡɪvən ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 27, 'global capitalism', 'chủ nghĩa tư bản toàn cầu', 'adj + n', '[{"en":"Global capitalism has reshaped how goods are produced worldwide.","vi":"Chủ nghĩa tư bản toàn cầu đã định hình lại cách hàng hóa được sản xuất."},{"en":"Critics argue that global capitalism widens the gap between nations.","vi":"Người phê bình cho rằng chủ nghĩa tư bản toàn cầu nới rộng khoảng cách giữa các quốc gia."},{"en":"The course examines the rise of global capitalism after 1980.","vi":"Khóa học xem xét sự trỗi dậy của chủ nghĩa tư bản toàn cầu sau năm 1980."}]', '[]', NULL, '/ˈɡloʊbəl ˈkæpɪtəlɪzəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 28, 'global context', 'bối cảnh toàn cầu', 'adj + n', '[{"en":"We must understand this issue within a global context.","vi":"Chúng ta phải hiểu vấn đề này trong bối cảnh toàn cầu."},{"en":"In a global context, education standards vary widely between countries.","vi":"Trong bối cảnh toàn cầu, tiêu chuẩn giáo dục khác nhau nhiều giữa các nước."},{"en":"The author places local events in a broader global context.","vi":"Tác giả đặt các sự kiện địa phương vào bối cảnh toàn cầu rộng hơn."}]', '[]', NULL, '/ˈɡloʊbəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 29, 'global culture', 'văn hóa toàn cầu', 'adj + n', '[{"en":"The internet has helped create a shared global culture.","vi":"Internet đã giúp tạo nên một nền văn hóa toàn cầu chung."},{"en":"Some fear that global culture is erasing local traditions.","vi":"Một số người lo rằng văn hóa toàn cầu đang xóa bỏ truyền thống địa phương."},{"en":"Music and films spread global culture across many borders.","vi":"Âm nhạc và phim ảnh lan truyền văn hóa toàn cầu qua nhiều biên giới."}]', '[]', NULL, '/ˈɡloʊbəl ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 30, 'global economy', 'nền kinh tế toàn cầu', 'adj + n', '[{"en":"Rising oil prices affect the entire global economy quickly.","vi":"Giá dầu tăng ảnh hưởng nhanh đến toàn bộ nền kinh tế toàn cầu."},{"en":"The global economy slowed during the recent financial crisis.","vi":"Nền kinh tế toàn cầu chậm lại trong cuộc khủng hoảng tài chính gần đây."},{"en":"Many countries depend on each other in the global economy.","vi":"Nhiều quốc gia phụ thuộc lẫn nhau trong nền kinh tế toàn cầu."}]', '[]', NULL, '/ˈɡloʊbəl ɪˈkɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 31, 'global issue', 'vấn đề toàn cầu', 'adj + n', '[{"en":"Climate change is a global issue affecting every nation.","vi":"Biến đổi khí hậu là một vấn đề toàn cầu ảnh hưởng đến mọi quốc gia."},{"en":"Poverty remains a serious global issue despite economic growth.","vi":"Nghèo đói vẫn là một vấn đề toàn cầu nghiêm trọng dù kinh tế tăng trưởng."},{"en":"The conference focused on global issues such as disease and hunger.","vi":"Hội nghị tập trung vào các vấn đề toàn cầu như bệnh tật và nạn đói."}]', '[]', NULL, '/ˈɡloʊbəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 32, 'global market', 'thị trường toàn cầu', 'adj + n', '[{"en":"The company sells its products in the global market today.","vi":"Công ty bán sản phẩm của mình trên thị trường toàn cầu hiện nay."},{"en":"Competition in the global market keeps prices relatively low.","vi":"Sự cạnh tranh trên thị trường toàn cầu giữ giá tương đối thấp."},{"en":"Small firms struggle to enter the global market alone.","vi":"Các doanh nghiệp nhỏ khó tự mình thâm nhập thị trường toàn cầu."}]', '[]', NULL, '/ˈɡloʊbəl ˈmɑːrkət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 33, 'global marketplace', 'thương trường toàn cầu', 'adj + n', '[{"en":"Companies must innovate to survive in the global marketplace.","vi":"Các công ty phải đổi mới để tồn tại trên thương trường toàn cầu."},{"en":"The internet connects buyers and sellers in the global marketplace.","vi":"Internet kết nối người mua và người bán trên thương trường toàn cầu."},{"en":"Brand reputation matters greatly in the global marketplace.","vi":"Uy tín thương hiệu rất quan trọng trên thương trường toàn cầu."}]', '[]', NULL, '/ˈɡloʊbəl ˈmɑːrkətpleɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 34, 'global media', 'truyền thông toàn cầu', 'adj + n', '[{"en":"Global media can spread news across the world within seconds.","vi":"Truyền thông toàn cầu có thể lan tin khắp thế giới trong vài giây."},{"en":"Global media shapes how people view distant conflicts.","vi":"Truyền thông toàn cầu định hình cách con người nhìn nhận các xung đột ở xa."},{"en":"A few large firms control much of the global media.","vi":"Vài tập đoàn lớn kiểm soát phần lớn truyền thông toàn cầu."}]', '[]', NULL, '/ˈɡloʊbəl ˈmiːdiə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 35, 'global network', 'mạng lưới toàn cầu', 'adj + n', '[{"en":"The airline operates a global network of busy routes.","vi":"Hãng hàng không vận hành một mạng lưới đường bay bận rộn toàn cầu."},{"en":"Scientists share data through a global network of laboratories.","vi":"Các nhà khoa học chia sẻ dữ liệu qua một mạng lưới phòng thí nghiệm toàn cầu."},{"en":"A global network of volunteers supports the relief effort.","vi":"Một mạng lưới tình nguyện viên toàn cầu hỗ trợ công tác cứu trợ."}]', '[]', NULL, '/ˈɡloʊbəl ˈnetwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 36, 'global perspective', 'góc nhìn toàn cầu', 'adj + n', '[{"en":"Studying abroad gave her a truly global perspective.","vi":"Việc du học đã mang lại cho cô ấy một góc nhìn toàn cầu thực sự."},{"en":"A global perspective helps us see problems beyond our borders.","vi":"Góc nhìn toàn cầu giúp chúng ta nhìn vấn đề vượt ra ngoài biên giới."},{"en":"The book adopts a global perspective on economic development.","vi":"Cuốn sách áp dụng góc nhìn toàn cầu về phát triển kinh tế."}]', '[]', NULL, '/ˈɡloʊbəl pərˈspektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 37, 'global shift', 'sự dịch chuyển toàn cầu', 'adj + n', '[{"en":"There has been a global shift toward renewable energy sources.","vi":"Đã có một sự dịch chuyển toàn cầu hướng tới nguồn năng lượng tái tạo."},{"en":"The report describes a global shift in manufacturing to Asia.","vi":"Báo cáo mô tả sự dịch chuyển toàn cầu của sản xuất sang châu Á."},{"en":"A global shift in attitudes has improved environmental awareness.","vi":"Sự dịch chuyển toàn cầu trong thái độ đã nâng cao ý thức môi trường."}]', '[]', NULL, '/ˈɡloʊbəl ʃɪft/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 38, 'global structure', 'cấu trúc toàn cầu', 'adj + n', '[{"en":"The global structure of trade has changed over recent decades.","vi":"Cấu trúc toàn cầu của thương mại đã thay đổi trong các thập kỷ gần đây."},{"en":"Researchers study the global structure of financial markets.","vi":"Các nhà nghiên cứu nghiên cứu cấu trúc toàn cầu của thị trường tài chính."},{"en":"A clear global structure helps the organization coordinate work.","vi":"Một cấu trúc toàn cầu rõ ràng giúp tổ chức phối hợp công việc."}]', '[]', NULL, '/ˈɡloʊbəl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 39, 'global trade', 'thương mại toàn cầu', 'adj + n', '[{"en":"Global trade allows countries to exchange goods they lack.","vi":"Thương mại toàn cầu cho phép các nước trao đổi hàng hóa họ thiếu."},{"en":"The crisis caused a sharp fall in global trade.","vi":"Cuộc khủng hoảng khiến thương mại toàn cầu sụt giảm mạnh."},{"en":"New agreements aim to make global trade fairer for all.","vi":"Các thỏa thuận mới nhằm làm cho thương mại toàn cầu công bằng hơn."}]', '[]', NULL, '/ˈɡloʊbəl treɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 40, 'global village', 'ngôi làng toàn cầu', 'adj + n', '[{"en":"Technology has turned the world into a global village.","vi":"Công nghệ đã biến thế giới thành một ngôi làng toàn cầu."},{"en":"In the global village, news travels almost instantly everywhere.","vi":"Trong ngôi làng toàn cầu, tin tức lan đi gần như tức thì khắp nơi."},{"en":"The idea of a global village highlights how connected we are.","vi":"Ý tưởng về ngôi làng toàn cầu nhấn mạnh chúng ta kết nối ra sao."}]', '[]', NULL, '/ˈɡloʊbəl ˈvɪlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 41, 'government control', 'sự kiểm soát của chính phủ', 'n + n', '[{"en":"The industry operated under strict government control for years.","vi":"Ngành công nghiệp này hoạt động dưới sự kiểm soát chặt của chính phủ nhiều năm."},{"en":"Some argue that government control limits business innovation.","vi":"Một số người cho rằng sự kiểm soát của chính phủ hạn chế đổi mới kinh doanh."},{"en":"Prices fell after government control of the market ended.","vi":"Giá giảm sau khi sự kiểm soát thị trường của chính phủ chấm dứt."}]', '[]', NULL, '/ˈɡʌvərnmənt kənˈtroʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 42, 'government department', 'bộ, cơ quan chính phủ', 'n + n', '[{"en":"Each government department manages a different area of policy.","vi":"Mỗi cơ quan chính phủ quản lý một lĩnh vực chính sách khác nhau."},{"en":"She works for the government department in charge of transport.","vi":"Cô ấy làm việc cho bộ chính phủ phụ trách giao thông."},{"en":"The government department published its annual budget yesterday.","vi":"Cơ quan chính phủ đã công bố ngân sách hàng năm hôm qua."}]', '[]', NULL, '/ˈɡʌvərnmənt dɪˈpɑːrtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 43, 'government expenditure', 'chi tiêu của chính phủ', 'n + n', '[{"en":"Government expenditure on health rose sharply over the decade.","vi":"Chi tiêu của chính phủ cho y tế tăng mạnh trong thập kỷ qua."},{"en":"High government expenditure can lead to a large national debt.","vi":"Chi tiêu cao của chính phủ có thể dẫn đến nợ quốc gia lớn."},{"en":"The report analyzes government expenditure across several countries.","vi":"Báo cáo phân tích chi tiêu của chính phủ ở nhiều quốc gia."}]', '[]', NULL, '/ˈɡʌvərnmənt ɪkˈspendɪtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 44, 'government intervention', 'sự can thiệp của chính phủ', 'n + n', '[{"en":"Government intervention helped stabilize the banking system.","vi":"Sự can thiệp của chính phủ đã giúp ổn định hệ thống ngân hàng."},{"en":"Economists disagree about how much government intervention is wise.","vi":"Các nhà kinh tế bất đồng về mức độ can thiệp hợp lý của chính phủ."},{"en":"Without government intervention, the crisis might have worsened.","vi":"Nếu không có sự can thiệp của chính phủ, khủng hoảng có thể tệ hơn."}]', '[]', NULL, '/ˈɡʌvərnmənt ˌɪntərˈvenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 45, 'government policy', 'chính sách của chính phủ', 'n + n', '[{"en":"Government policy on education changed after the election.","vi":"Chính sách giáo dục của chính phủ thay đổi sau cuộc bầu cử."},{"en":"The new government policy aims to reduce air pollution.","vi":"Chính sách mới của chính phủ nhằm giảm ô nhiễm không khí."},{"en":"Critics say government policy ignores the needs of rural areas.","vi":"Người chỉ trích nói chính sách của chính phủ bỏ qua nhu cầu vùng nông thôn."}]', '[]', NULL, '/ˈɡʌvərnmənt ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 46, 'graphical representation', 'biểu diễn bằng đồ thị', 'adj + n', '[{"en":"A graphical representation makes the trend easier to understand.","vi":"Một biểu diễn bằng đồ thị giúp xu hướng dễ hiểu hơn."},{"en":"The report includes a graphical representation of the survey data.","vi":"Báo cáo gồm một biểu diễn bằng đồ thị của dữ liệu khảo sát."},{"en":"Students created a graphical representation of their results.","vi":"Sinh viên đã tạo một biểu diễn bằng đồ thị cho kết quả của họ."}]', '[]', NULL, '/ˈɡræfɪkəl ˌreprɪzenˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 47, 'great accuracy', 'độ chính xác cao', 'adj + n', '[{"en":"The new instrument measures temperature with great accuracy.","vi":"Thiết bị mới đo nhiệt độ với độ chính xác cao."},{"en":"She translated the document with great accuracy and care.","vi":"Cô ấy dịch tài liệu với độ chính xác cao và cẩn thận."},{"en":"The model predicts rainfall with surprisingly great accuracy.","vi":"Mô hình dự đoán lượng mưa với độ chính xác cao đáng ngạc nhiên."}]', '[]', NULL, '/ɡreɪt ˈækjərəsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 48, 'great diversity', 'sự đa dạng lớn', 'adj + n', '[{"en":"The region shows great diversity in its plants and animals.","vi":"Vùng này thể hiện sự đa dạng lớn về thực vật và động vật."},{"en":"There is great diversity of opinion among the experts.","vi":"Có sự đa dạng lớn về quan điểm giữa các chuyên gia."},{"en":"The city is known for the great diversity of its people.","vi":"Thành phố nổi tiếng với sự đa dạng lớn của cư dân."}]', '[]', NULL, '/ɡreɪt daɪˈvɜːrsəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 49, 'great impact', 'tác động lớn', 'adj + n', '[{"en":"The invention of the internet had a great impact on society.","vi":"Việc phát minh ra internet đã có tác động lớn đến xã hội."},{"en":"Her research has had a great impact on modern medicine.","vi":"Nghiên cứu của cô đã có tác động lớn đến y học hiện đại."},{"en":"Early childhood experiences have a great impact on later life.","vi":"Những trải nghiệm thời thơ ấu có tác động lớn đến cuộc sống về sau."}]', '[]', NULL, '/ɡreɪt ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 50, 'great majority', 'đại đa số', 'adj + n', '[{"en":"The great majority of students passed the final exam easily.","vi":"Đại đa số sinh viên dễ dàng vượt qua kỳ thi cuối kỳ."},{"en":"In the survey, the great majority supported the new plan.","vi":"Trong cuộc khảo sát, đại đa số ủng hộ kế hoạch mới."},{"en":"The great majority of accidents happen on busy roads.","vi":"Đại đa số tai nạn xảy ra trên những con đường đông đúc."}]', '[]', NULL, '/ɡreɪt məˈdʒɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 51, 'great potential', 'tiềm năng lớn', 'adj + n', '[{"en":"Solar energy has great potential to power future cities.","vi":"Năng lượng mặt trời có tiềm năng lớn để cung cấp điện cho các thành phố tương lai."},{"en":"The young player shows great potential as a future star.","vi":"Cầu thủ trẻ thể hiện tiềm năng lớn để trở thành ngôi sao tương lai."},{"en":"This region has great potential for tourism and agriculture.","vi":"Vùng này có tiềm năng lớn cho du lịch và nông nghiệp."}]', '[]', NULL, '/ɡreɪt pəˈtenʃəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 52, 'great proportion of', 'tỷ lệ lớn của', 'adj + n', '[{"en":"A great proportion of the budget goes to staff salaries.","vi":"Một tỷ lệ lớn ngân sách dành cho lương nhân viên."},{"en":"A great proportion of the population lives in coastal cities.","vi":"Một tỷ lệ lớn dân số sống ở các thành phố ven biển."},{"en":"A great proportion of the data was lost in the failure.","vi":"Một tỷ lệ lớn dữ liệu đã bị mất trong sự cố."}]', '[]', NULL, '/ɡreɪt prəˈpɔːrʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 53, 'great range of', 'nhiều loại, phạm vi rộng của', 'adj + n', '[{"en":"The library offers a great range of books on history.","vi":"Thư viện cung cấp nhiều loại sách về lịch sử."},{"en":"The store sells a great range of products at low prices.","vi":"Cửa hàng bán nhiều loại sản phẩm với giá rẻ."},{"en":"The course covers a great range of topics in biology.","vi":"Khóa học bao quát phạm vi rộng các chủ đề trong sinh học."}]', '[]', NULL, '/ɡreɪt reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 54, 'great significance', 'tầm quan trọng lớn', 'adj + n', '[{"en":"The discovery is of great significance to medical science.","vi":"Phát hiện này có tầm quan trọng lớn đối với khoa học y tế."},{"en":"The treaty had great significance for peace in the region.","vi":"Hiệp ước có tầm quan trọng lớn đối với hòa bình trong khu vực."},{"en":"These findings hold great significance for future research.","vi":"Những phát hiện này có tầm quan trọng lớn cho nghiên cứu tương lai."}]', '[]', NULL, '/ɡreɪt sɪɡˈnɪfɪkəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 55, 'greater autonomy', 'quyền tự chủ lớn hơn', 'adj + n', '[{"en":"The reforms gave local councils greater autonomy over budgets.","vi":"Các cải cách trao cho hội đồng địa phương quyền tự chủ lớn hơn về ngân sách."},{"en":"Workers asked for greater autonomy in planning their tasks.","vi":"Người lao động yêu cầu quyền tự chủ lớn hơn trong việc lập kế hoạch công việc."},{"en":"Greater autonomy can improve both motivation and creativity.","vi":"Quyền tự chủ lớn hơn có thể cải thiện cả động lực và sự sáng tạo."}]', '[]', NULL, '/ˈɡreɪtər ɔːˈtɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 56, 'greater awareness', 'nhận thức cao hơn', 'adj + n', '[{"en":"The campaign created greater awareness of mental health issues.","vi":"Chiến dịch tạo ra nhận thức cao hơn về các vấn đề sức khỏe tâm thần."},{"en":"There is now greater awareness of the dangers of smoking.","vi":"Hiện đã có nhận thức cao hơn về tác hại của hút thuốc."},{"en":"Education leads to greater awareness of environmental problems.","vi":"Giáo dục dẫn đến nhận thức cao hơn về các vấn đề môi trường."}]', '[]', NULL, '/ˈɡreɪtər əˈwernəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 57, 'greater emphasis', 'sự nhấn mạnh nhiều hơn', 'adj + n', '[{"en":"Schools now place greater emphasis on critical thinking skills.","vi":"Các trường giờ đây nhấn mạnh nhiều hơn vào kỹ năng tư duy phản biện."},{"en":"The company puts greater emphasis on customer satisfaction.","vi":"Công ty đặt sự nhấn mạnh nhiều hơn vào sự hài lòng của khách hàng."},{"en":"We need greater emphasis on prevention rather than treatment.","vi":"Chúng ta cần nhấn mạnh nhiều hơn vào phòng ngừa thay vì điều trị."}]', '[]', NULL, '/ˈɡreɪtər ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 58, 'greater equality', 'sự bình đẳng lớn hơn', 'adj + n', '[{"en":"The law aims to create greater equality between men and women.","vi":"Luật nhằm tạo sự bình đẳng lớn hơn giữa nam và nữ."},{"en":"Many reforms were introduced to promote greater equality.","vi":"Nhiều cải cách được đưa ra để thúc đẩy sự bình đẳng lớn hơn."},{"en":"Greater equality in education benefits the whole society.","vi":"Sự bình đẳng lớn hơn trong giáo dục mang lại lợi ích cho cả xã hội."}]', '[]', NULL, '/ˈɡreɪtər ɪˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 59, 'greater flexibility', 'sự linh hoạt cao hơn', 'adj + n', '[{"en":"Remote work offers employees greater flexibility in their schedules.","vi":"Làm việc từ xa mang lại cho nhân viên sự linh hoạt cao hơn về lịch trình."},{"en":"The new system allows greater flexibility in choosing courses.","vi":"Hệ thống mới cho phép sự linh hoạt cao hơn trong việc chọn môn học."},{"en":"Greater flexibility helps companies respond to sudden changes.","vi":"Sự linh hoạt cao hơn giúp công ty ứng phó với thay đổi đột ngột."}]', '[]', NULL, '/ˈɡreɪtər ˌfleksəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 60, 'greater likelihood', 'khả năng cao hơn', 'adj + n', '[{"en":"Regular exercise brings a greater likelihood of good health.","vi":"Tập thể dục đều đặn mang lại khả năng cao hơn về sức khỏe tốt."},{"en":"Students who read often have a greater likelihood of success.","vi":"Sinh viên đọc nhiều có khả năng thành công cao hơn."},{"en":"Poor diet is linked to a greater likelihood of disease.","vi":"Chế độ ăn kém liên quan đến khả năng mắc bệnh cao hơn."}]', '[]', NULL, '/ˈɡreɪtər ˈlaɪklihʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 61, 'greatly enhance', 'nâng cao đáng kể', 'adv + v', '[{"en":"Good lighting can greatly enhance the quality of photographs.","vi":"Ánh sáng tốt có thể nâng cao đáng kể chất lượng ảnh chụp."},{"en":"New software will greatly enhance the team''s productivity.","vi":"Phần mềm mới sẽ nâng cao đáng kể năng suất của nhóm."},{"en":"Studying abroad can greatly enhance your career prospects.","vi":"Du học có thể nâng cao đáng kể triển vọng nghề nghiệp của bạn."}]', '[]', NULL, '/ˈɡreɪtli ɪnˈhæns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 62, 'greatly increase', 'tăng đáng kể', 'adv + v', '[{"en":"Smoking can greatly increase the risk of lung disease.","vi":"Hút thuốc có thể tăng đáng kể nguy cơ mắc bệnh phổi."},{"en":"The new road will greatly increase traffic into the town.","vi":"Con đường mới sẽ làm tăng đáng kể lượng xe vào thị trấn."},{"en":"Advertising can greatly increase sales of a new product.","vi":"Quảng cáo có thể tăng đáng kể doanh số của sản phẩm mới."}]', '[]', NULL, '/ˈɡreɪtli ɪnˈkriːs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 63, 'greatly influenced by', 'chịu ảnh hưởng lớn bởi', 'adv + vpp', '[{"en":"Her writing was greatly influenced by classical literature.","vi":"Văn của cô chịu ảnh hưởng lớn bởi văn học cổ điển."},{"en":"The artist was greatly influenced by his travels abroad.","vi":"Người nghệ sĩ chịu ảnh hưởng lớn bởi những chuyến đi nước ngoài."},{"en":"Modern science was greatly influenced by ancient Greek thinkers.","vi":"Khoa học hiện đại chịu ảnh hưởng lớn bởi các nhà tư tưởng Hy Lạp cổ."}]', '[]', NULL, '/ˈɡreɪtli ˈɪnfluənst baɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 64, 'greatly reduced', 'giảm đáng kể', 'adv + vpp', '[{"en":"Pollution was greatly reduced after the new law passed.","vi":"Ô nhiễm đã giảm đáng kể sau khi luật mới được thông qua."},{"en":"The risk of infection is greatly reduced by washing hands.","vi":"Nguy cơ nhiễm trùng giảm đáng kể nhờ rửa tay."},{"en":"Travel time was greatly reduced once the bridge opened.","vi":"Thời gian di chuyển giảm đáng kể khi cây cầu được khánh thành."}]', '[]', NULL, '/ˈɡreɪtli rɪˈduːst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 65, 'grow rapidly', 'phát triển nhanh chóng', 'v + adv', '[{"en":"The city''s population began to grow rapidly after 1990.","vi":"Dân số thành phố bắt đầu phát triển nhanh chóng sau năm 1990."},{"en":"Online businesses can grow rapidly with the right strategy.","vi":"Các doanh nghiệp trực tuyến có thể phát triển nhanh chóng với chiến lược đúng."},{"en":"Demand for electric cars continues to grow rapidly worldwide.","vi":"Nhu cầu về ô tô điện tiếp tục phát triển nhanh chóng trên toàn cầu."}]', '[]', NULL, '/ɡroʊ ˈræpɪdli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 66, 'growing awareness', 'nhận thức ngày càng tăng', 'adj + n', '[{"en":"There is growing awareness of the effects of climate change.","vi":"Có nhận thức ngày càng tăng về các tác động của biến đổi khí hậu."},{"en":"Growing awareness of healthy eating has changed shopping habits.","vi":"Nhận thức ngày càng tăng về ăn uống lành mạnh đã thay đổi thói quen mua sắm."},{"en":"The campaign reflects growing awareness of online safety.","vi":"Chiến dịch phản ánh nhận thức ngày càng tăng về an toàn trực tuyến."}]', '[]', NULL, '/ˈɡroʊɪŋ əˈwernəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 67, 'growing trend', 'xu hướng ngày càng tăng', 'adj + n', '[{"en":"There is a growing trend toward working from home.","vi":"Có một xu hướng ngày càng tăng về làm việc tại nhà."},{"en":"A growing trend among young people is shopping online.","vi":"Một xu hướng ngày càng tăng trong giới trẻ là mua sắm trực tuyến."},{"en":"The report identifies a growing trend in renewable energy use.","vi":"Báo cáo chỉ ra một xu hướng ngày càng tăng về dùng năng lượng tái tạo."}]', '[]', NULL, '/ˈɡroʊɪŋ trend/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 68, 'guiding principle', 'nguyên tắc chỉ đạo', 'adj + n', '[{"en":"Honesty is the guiding principle of our entire organization.","vi":"Trung thực là nguyên tắc chỉ đạo của toàn bộ tổ chức chúng tôi."},{"en":"Fairness should be the guiding principle behind every decision.","vi":"Công bằng nên là nguyên tắc chỉ đạo đằng sau mỗi quyết định."},{"en":"The guiding principle of the law is to protect citizens.","vi":"Nguyên tắc chỉ đạo của luật là bảo vệ công dân."}]', '[]', NULL, '/ˈɡaɪdɪŋ ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 69, 'hardly surprising', 'chẳng có gì đáng ngạc nhiên', 'adv + adj', '[{"en":"It is hardly surprising that prices rose after the shortage.","vi":"Chẳng có gì đáng ngạc nhiên khi giá tăng sau tình trạng khan hiếm."},{"en":"Given the rain, the low turnout was hardly surprising.","vi":"Với trời mưa, lượng người tham dự thấp chẳng có gì đáng ngạc nhiên."},{"en":"It is hardly surprising that students prefer shorter lectures.","vi":"Chẳng có gì đáng ngạc nhiên khi sinh viên thích các bài giảng ngắn hơn."}]', '[]', NULL, '/ˈhɑːrdli sərˈpraɪzɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 70, 'have access to', 'có quyền tiếp cận, được sử dụng', 'v + n', '[{"en":"All students have access to the library''s online resources.","vi":"Tất cả sinh viên đều có quyền tiếp cận tài nguyên trực tuyến của thư viện."},{"en":"Many rural areas still do not have access to clean water.","vi":"Nhiều vùng nông thôn vẫn chưa được sử dụng nước sạch."},{"en":"Only managers have access to the confidential files.","vi":"Chỉ quản lý mới có quyền tiếp cận các hồ sơ mật."}]', '[]', NULL, '/hæv ˈækses tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 71, 'have consequences', 'gây ra hậu quả', 'v + n', '[{"en":"Every decision we make will have consequences for the future.","vi":"Mỗi quyết định chúng ta đưa ra đều sẽ gây ra hậu quả cho tương lai."},{"en":"Ignoring the warning could have serious consequences for everyone.","vi":"Bỏ qua cảnh báo có thể gây ra hậu quả nghiêm trọng cho mọi người."},{"en":"Poor planning often has consequences that are hard to fix.","vi":"Lập kế hoạch kém thường gây ra hậu quả khó khắc phục."}]', '[]', NULL, '/hæv ˈkɑːnsəkwensəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 72, 'have limitations', 'có hạn chế', 'v + n', '[{"en":"Every research method has limitations that we should recognize.","vi":"Mọi phương pháp nghiên cứu đều có hạn chế mà ta nên nhận ra."},{"en":"The study has limitations because the sample was quite small.","vi":"Nghiên cứu có hạn chế vì mẫu khá nhỏ."},{"en":"Even the best technology has limitations in extreme conditions.","vi":"Ngay cả công nghệ tốt nhất cũng có hạn chế trong điều kiện khắc nghiệt."}]', '[]', NULL, '/hæv ˌlɪmɪˈteɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 73, 'have potential', 'có tiềm năng', 'v + n', '[{"en":"This new approach has potential to improve learning outcomes.","vi":"Cách tiếp cận mới này có tiềm năng cải thiện kết quả học tập."},{"en":"The young athlete clearly has potential to compete nationally.","vi":"Vận động viên trẻ rõ ràng có tiềm năng thi đấu cấp quốc gia."},{"en":"Renewable sources have potential to replace fossil fuels.","vi":"Các nguồn tái tạo có tiềm năng thay thế nhiên liệu hóa thạch."}]', '[]', NULL, '/hæv pəˈtenʃəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 74, 'have a strategy', 'có một chiến lược', 'v + n', '[{"en":"Successful companies always have a clear strategy for growth.","vi":"Các công ty thành công luôn có một chiến lược rõ ràng để phát triển."},{"en":"You should have a strategy before starting the negotiation.","vi":"Bạn nên có một chiến lược trước khi bắt đầu đàm phán."},{"en":"The team needs to have a strategy to handle the crisis.","vi":"Nhóm cần có một chiến lược để xử lý khủng hoảng."}]', '[]', NULL, '/hæv ə ˈstrætədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 75, 'have a tendency to', 'có xu hướng', 'v + n', '[{"en":"People have a tendency to remember bad news more easily.","vi":"Con người có xu hướng nhớ tin xấu dễ dàng hơn."},{"en":"New drivers have a tendency to brake too suddenly.","vi":"Tài xế mới có xu hướng phanh quá đột ngột."},{"en":"Prices have a tendency to rise during the holiday season.","vi":"Giá cả có xu hướng tăng trong mùa lễ hội."}]', '[]', NULL, '/hæv ə ˈtendənsi tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 76, 'have an obligation', 'có nghĩa vụ', 'v + n', '[{"en":"Companies have an obligation to protect their customers'' data.","vi":"Các công ty có nghĩa vụ bảo vệ dữ liệu của khách hàng."},{"en":"Citizens have an obligation to obey the laws of the country.","vi":"Công dân có nghĩa vụ tuân thủ pháp luật của đất nước."},{"en":"Teachers have an obligation to treat every student fairly.","vi":"Giáo viên có nghĩa vụ đối xử công bằng với mọi học sinh."}]', '[]', NULL, '/hæv ən ˌɑːblɪˈɡeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 77, 'heated debate', 'cuộc tranh luận gay gắt', 'adj + n', '[{"en":"The new policy sparked a heated debate among the students.","vi":"Chính sách mới làm dấy lên một cuộc tranh luận gay gắt giữa các sinh viên."},{"en":"There was a heated debate about how to spend the budget.","vi":"Đã có một cuộc tranh luận gay gắt về cách chi tiêu ngân sách."},{"en":"The topic of immigration often leads to heated debate.","vi":"Chủ đề nhập cư thường dẫn đến tranh luận gay gắt."}]', '[]', NULL, '/ˈhiːtəd dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 78, 'heavily influenced by', 'chịu ảnh hưởng mạnh bởi', 'adv + vpp', '[{"en":"The region''s cuisine is heavily influenced by neighboring countries.","vi":"Ẩm thực của vùng chịu ảnh hưởng mạnh bởi các nước láng giềng."},{"en":"His early music was heavily influenced by local folk songs.","vi":"Âm nhạc thời kỳ đầu của anh chịu ảnh hưởng mạnh bởi dân ca địa phương."},{"en":"Voters were heavily influenced by the candidate''s promises.","vi":"Cử tri chịu ảnh hưởng mạnh bởi những lời hứa của ứng viên."}]', '[]', NULL, '/ˈhevɪli ˈɪnfluənst baɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 79, 'hierarchical structure', 'cấu trúc thứ bậc', 'adj + n', '[{"en":"The army relies on a strict hierarchical structure of command.","vi":"Quân đội dựa vào một cấu trúc thứ bậc chỉ huy nghiêm ngặt."},{"en":"Many traditional companies still use a hierarchical structure.","vi":"Nhiều công ty truyền thống vẫn dùng cấu trúc thứ bậc."},{"en":"A hierarchical structure can slow down important decisions.","vi":"Cấu trúc thứ bậc có thể làm chậm các quyết định quan trọng."}]', '[]', NULL, '/ˌhaɪəˈrɑːrkɪkəl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 80, 'high concentration', 'nồng độ cao, sự tập trung cao', 'adj + n', '[{"en":"The water contained a high concentration of harmful chemicals.","vi":"Nước chứa nồng độ cao các hóa chất độc hại."},{"en":"There is a high concentration of factories near the river.","vi":"Có sự tập trung cao các nhà máy gần con sông."},{"en":"A high concentration of salt can damage most plants.","vi":"Nồng độ muối cao có thể gây hại cho hầu hết cây trồng."}]', '[]', NULL, '/haɪ ˌkɑːnsənˈtreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 81, 'high correlation', 'mối tương quan cao', 'adj + n', '[{"en":"There is a high correlation between exercise and good health.","vi":"Có mối tương quan cao giữa tập luyện và sức khỏe tốt."},{"en":"The study found a high correlation between income and education.","vi":"Nghiên cứu tìm thấy mối tương quan cao giữa thu nhập và học vấn."},{"en":"A high correlation does not always prove a direct cause.","vi":"Mối tương quan cao không phải lúc nào cũng chứng minh nguyên nhân trực tiếp."}]', '[]', NULL, '/haɪ ˌkɔːrəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 82, 'high expectations', 'kỳ vọng cao', 'adj + n', '[{"en":"Parents often have high expectations for their children''s grades.","vi":"Cha mẹ thường có kỳ vọng cao về điểm số của con cái."},{"en":"The new manager set high expectations for the whole team.","vi":"Quản lý mới đặt kỳ vọng cao cho toàn đội."},{"en":"High expectations can motivate students to work harder.","vi":"Kỳ vọng cao có thể thúc đẩy sinh viên cố gắng hơn."}]', '[]', NULL, '/haɪ ˌekspekˈteɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 83, 'high incidence', 'tỷ lệ xảy ra cao', 'adj + n', '[{"en":"The region has a high incidence of certain heart diseases.","vi":"Vùng này có tỷ lệ xảy ra cao của một số bệnh tim."},{"en":"Researchers studied the high incidence of accidents on that road.","vi":"Các nhà nghiên cứu nghiên cứu tỷ lệ tai nạn cao trên con đường đó."},{"en":"Poor housing is linked to a high incidence of illness.","vi":"Nhà ở kém liên quan đến tỷ lệ bệnh tật cao."}]', '[]', NULL, '/haɪ ˈɪnsɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 84, 'high intensity', 'cường độ cao', 'adj + n', '[{"en":"High intensity exercise can burn calories in a short time.","vi":"Bài tập cường độ cao có thể đốt calo trong thời gian ngắn."},{"en":"The storm hit the coast with surprisingly high intensity.","vi":"Cơn bão đổ bộ vào bờ biển với cường độ cao đáng ngạc nhiên."},{"en":"The light''s high intensity made it hard to look directly.","vi":"Cường độ cao của ánh sáng khiến khó nhìn trực tiếp."}]', '[]', NULL, '/haɪ ɪnˈtensəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 85, 'high level', 'mức độ cao', 'adj + n', '[{"en":"The job requires a high level of skill and patience.","vi":"Công việc đòi hỏi mức độ cao về kỹ năng và sự kiên nhẫn."},{"en":"There is a high level of trust between the two partners.","vi":"Có mức độ tin tưởng cao giữa hai đối tác."},{"en":"Athletes maintain a high level of fitness all year round.","vi":"Các vận động viên duy trì mức độ thể lực cao quanh năm."}]', '[]', NULL, '/haɪ ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 86, 'high order', 'bậc cao, cấp độ cao', 'adj + n', '[{"en":"The exam tests high order thinking rather than simple memory.","vi":"Kỳ thi kiểm tra tư duy bậc cao chứ không phải trí nhớ đơn giản."},{"en":"Solving the puzzle requires skills of a high order.","vi":"Giải câu đố này đòi hỏi các kỹ năng bậc cao."},{"en":"These tasks develop high order reasoning in young learners.","vi":"Những nhiệm vụ này phát triển lập luận bậc cao ở người học nhỏ tuổi."}]', '[]', NULL, '/haɪ ˈɔːrdər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 87, 'high percentage', 'tỷ lệ phần trăm cao', 'adj + n', '[{"en":"A high percentage of graduates found work within six months.","vi":"Một tỷ lệ phần trăm cao sinh viên tốt nghiệp tìm được việc trong sáu tháng."},{"en":"The survey showed a high percentage of satisfied customers.","vi":"Khảo sát cho thấy tỷ lệ phần trăm cao khách hàng hài lòng."},{"en":"A high percentage of energy is still wasted in old buildings.","vi":"Một tỷ lệ phần trăm cao năng lượng vẫn bị lãng phí trong tòa nhà cũ."}]', '[]', NULL, '/haɪ pərˈsentɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 88, 'high priority', 'ưu tiên cao', 'adj + n', '[{"en":"Reducing road accidents is a high priority for the government.","vi":"Giảm tai nạn giao thông là ưu tiên cao của chính phủ."},{"en":"The company gives high priority to customer safety.","vi":"Công ty dành ưu tiên cao cho sự an toàn của khách hàng."},{"en":"Clean water should be a high priority in poor regions.","vi":"Nước sạch nên là ưu tiên cao ở các vùng nghèo."}]', '[]', NULL, '/haɪ praɪˈɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 89, 'high probability', 'xác suất cao', 'adj + n', '[{"en":"There is a high probability of rain later this afternoon.","vi":"Có xác suất cao trời sẽ mưa vào chiều muộn nay."},{"en":"The model shows a high probability of further price increases.","vi":"Mô hình cho thấy xác suất cao giá sẽ tiếp tục tăng."},{"en":"There is a high probability that the experiment will succeed.","vi":"Có xác suất cao thí nghiệm sẽ thành công."}]', '[]', NULL, '/haɪ ˌprɑːbəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 90, 'high profile', 'nổi bật, được chú ý nhiều', 'adj + n', '[{"en":"The trial received high profile coverage in the national press.","vi":"Phiên tòa nhận được sự đưa tin nổi bật trên báo chí quốc gia."},{"en":"She took a high profile role in the campaign last year.","vi":"Cô đảm nhận một vai trò nổi bật trong chiến dịch năm ngoái."},{"en":"A high profile event attracted thousands of curious visitors.","vi":"Một sự kiện được chú ý nhiều thu hút hàng ngàn khách tò mò."}]', '[]', NULL, '/haɪ ˈproʊfaɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 91, 'high proportion of', 'tỷ lệ cao của', 'adj + n', '[{"en":"A high proportion of the workforce is now over fifty.","vi":"Một tỷ lệ cao lực lượng lao động hiện đã trên năm mươi tuổi."},{"en":"A high proportion of students study part time these days.","vi":"Một tỷ lệ cao sinh viên ngày nay học bán thời gian."},{"en":"A high proportion of the income comes from foreign tourists.","vi":"Một tỷ lệ cao thu nhập đến từ khách du lịch nước ngoài."}]', '[]', NULL, '/haɪ prəˈpɔːrʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 92, 'high quality', 'chất lượng cao', 'adj + n', '[{"en":"The company is known for its high quality products worldwide.","vi":"Công ty nổi tiếng với các sản phẩm chất lượng cao trên toàn cầu."},{"en":"High quality teaching makes a real difference to students.","vi":"Giảng dạy chất lượng cao tạo ra sự khác biệt thực sự cho sinh viên."},{"en":"We use only high quality materials to build these houses.","vi":"Chúng tôi chỉ dùng vật liệu chất lượng cao để xây những ngôi nhà này."}]', '[]', NULL, '/haɪ ˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 93, 'high rate', 'tỷ lệ cao', 'adj + n', '[{"en":"The country reports a high rate of youth unemployment.","vi":"Quốc gia này ghi nhận tỷ lệ thất nghiệp ở giới trẻ cao."},{"en":"A high rate of recovery suggests the treatment is working.","vi":"Tỷ lệ hồi phục cao cho thấy phương pháp điều trị có hiệu quả."},{"en":"Researchers noted a high rate of participation in the survey.","vi":"Các nhà nghiên cứu ghi nhận tỷ lệ tham gia khảo sát cao."}]', '[]', NULL, '/ˈhaɪ ˈreɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 94, 'high score', 'điểm số cao', 'adj + n', '[{"en":"Students with a high score on the test received scholarships.","vi":"Những học sinh đạt điểm số cao trong bài kiểm tra nhận học bổng."},{"en":"She achieved a high score despite limited preparation time.","vi":"Cô đạt điểm số cao dù thời gian ôn tập hạn chế."},{"en":"A high score reflects strong understanding of the material.","vi":"Điểm số cao phản ánh sự hiểu biết vững chắc về tài liệu."}]', '[]', NULL, '/ˈhaɪ ˈskɔːr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 95, 'high standard', 'tiêu chuẩn cao', 'adj + n', '[{"en":"The university maintains a high standard of academic writing.","vi":"Trường đại học duy trì tiêu chuẩn cao về viết học thuật."},{"en":"Employers expect a high standard of work from graduates.","vi":"Nhà tuyển dụng mong đợi tiêu chuẩn cao trong công việc từ sinh viên tốt nghiệp."},{"en":"Setting a high standard early helps students stay motivated.","vi":"Đặt tiêu chuẩn cao từ sớm giúp học sinh duy trì động lực."}]', '[]', NULL, '/ˈhaɪ ˈstændərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 96, 'high status', 'địa vị cao', 'adj + n', '[{"en":"Certain professions are associated with high status in society.","vi":"Một số nghề nghiệp gắn liền với địa vị cao trong xã hội."},{"en":"People of high status often influence community decisions.","vi":"Những người có địa vị cao thường ảnh hưởng đến quyết định của cộng đồng."},{"en":"The role carries high status but also heavy responsibility.","vi":"Vai trò này mang địa vị cao nhưng cũng nhiều trách nhiệm nặng nề."}]', '[]', NULL, '/ˈhaɪ ˈsteɪtəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 97, 'high turnover', 'tỷ lệ thay đổi nhân sự cao', 'adj + n', '[{"en":"The company struggles with high turnover among new employees.","vi":"Công ty gặp khó khăn với tỷ lệ thay đổi nhân sự cao ở nhân viên mới."},{"en":"High turnover increases the cost of training and recruitment.","vi":"Tỷ lệ nghỉ việc cao làm tăng chi phí đào tạo và tuyển dụng."},{"en":"Managers investigated why high turnover affected the department.","vi":"Quản lý điều tra lý do tỷ lệ thay nhân sự cao ảnh hưởng đến phòng ban."}]', '[]', NULL, '/ˈhaɪ ˈtɜːrnˌoʊvər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 98, 'high unemployment', 'tỷ lệ thất nghiệp cao', 'adj + n', '[{"en":"High unemployment can lead to widespread social unrest.","vi":"Tỷ lệ thất nghiệp cao có thể dẫn đến bất ổn xã hội rộng khắp."},{"en":"The region suffered from high unemployment after the factory closed.","vi":"Khu vực này chịu tỷ lệ thất nghiệp cao sau khi nhà máy đóng cửa."},{"en":"Economists linked high unemployment to the falling demand.","vi":"Các nhà kinh tế liên hệ tỷ lệ thất nghiệp cao với nhu cầu giảm sút."}]', '[]', NULL, '/ˈhaɪ ˌʌnɪmˈplɔɪmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 99, 'high value', 'giá trị cao', 'adj + n', '[{"en":"The museum protects artifacts of very high value.","vi":"Bảo tàng bảo vệ những hiện vật có giá trị rất cao."},{"en":"Employers place high value on communication skills.","vi":"Nhà tuyển dụng đặt giá trị cao vào kỹ năng giao tiếp."},{"en":"High value goods require careful handling during transport.","vi":"Hàng hóa giá trị cao cần được xử lý cẩn thận khi vận chuyển."}]', '[]', NULL, '/ˈhaɪ ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 100, 'high/er frequency', 'tần suất cao hơn', 'adj + n', '[{"en":"The disease appears with higher frequency in older populations.","vi":"Căn bệnh xuất hiện với tần suất cao hơn ở nhóm dân số lớn tuổi."},{"en":"Words of high frequency are easier for learners to recall.","vi":"Những từ có tần suất cao thì người học dễ nhớ lại hơn."},{"en":"Higher frequency of testing improved long-term retention.","vi":"Tần suất kiểm tra cao hơn giúp cải thiện khả năng ghi nhớ lâu dài."}]', '[]', NULL, '/ˈhaɪər ˈfriːkwənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 101, 'higher degree of', 'mức độ cao hơn của', 'adj + n', '[{"en":"The new method requires a higher degree of precision.","vi":"Phương pháp mới đòi hỏi mức độ chính xác cao hơn."},{"en":"Senior roles demand a higher degree of responsibility.","vi":"Các vị trí cấp cao đòi hỏi mức độ trách nhiệm cao hơn."},{"en":"Participants showed a higher degree of engagement this year.","vi":"Người tham gia thể hiện mức độ gắn kết cao hơn trong năm nay."}]', '[]', NULL, '/ˈhaɪər dɪˈɡriː əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 102, 'higher education', 'giáo dục đại học', 'adj + n', '[{"en":"Access to higher education has expanded over recent decades.","vi":"Cơ hội tiếp cận giáo dục đại học đã mở rộng trong các thập kỷ gần đây."},{"en":"Higher education prepares students for specialized careers.","vi":"Giáo dục đại học chuẩn bị cho sinh viên những nghề nghiệp chuyên môn."},{"en":"The cost of higher education remains a concern for families.","vi":"Chi phí giáo dục đại học vẫn là mối lo ngại đối với các gia đình."}]', '[]', NULL, '/ˈhaɪər ˌedʒəˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 103, 'highly charged', 'đầy căng thẳng (về cảm xúc)', 'adv + vpp', '[{"en":"The debate became highly charged as opinions clashed sharply.","vi":"Cuộc tranh luận trở nên đầy căng thẳng khi các ý kiến xung đột gay gắt."},{"en":"Highly charged topics require sensitive and careful discussion.","vi":"Những chủ đề đầy căng thẳng đòi hỏi sự thảo luận tế nhị và cẩn trọng."},{"en":"The meeting had a highly charged atmosphere from the start.","vi":"Cuộc họp có bầu không khí đầy căng thẳng ngay từ đầu."}]', '[]', NULL, '/ˈhaɪli ˈtʃɑːrdʒd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 104, 'highly competitive', 'có tính cạnh tranh cao', 'adv + adj', '[{"en":"The job market for graduates is highly competitive today.","vi":"Thị trường việc làm cho sinh viên tốt nghiệp hiện nay có tính cạnh tranh cao."},{"en":"Admission to the program is highly competitive each year.","vi":"Việc tuyển sinh vào chương trình có tính cạnh tranh cao mỗi năm."},{"en":"Firms operate in a highly competitive global environment.","vi":"Các công ty hoạt động trong môi trường toàn cầu cạnh tranh cao."}]', '[]', NULL, '/ˈhaɪli kəmˈpetətɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 105, 'highly complex', 'rất phức tạp', 'adv + adj', '[{"en":"The human brain is a highly complex biological system.","vi":"Bộ não con người là một hệ thống sinh học rất phức tạp."},{"en":"Climate models deal with highly complex interactions.","vi":"Các mô hình khí hậu xử lý những tương tác rất phức tạp."},{"en":"The legal case involved a highly complex set of rules.","vi":"Vụ kiện liên quan đến một tập hợp quy tắc rất phức tạp."}]', '[]', NULL, '/ˈhaɪli kəmˈpleks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 106, 'highly controversial', 'gây tranh cãi mạnh mẽ', 'adv + adj', '[{"en":"The proposed policy proved highly controversial among voters.","vi":"Chính sách được đề xuất tỏ ra gây tranh cãi mạnh mẽ trong giới cử tri."},{"en":"His research reached highly controversial conclusions.","vi":"Nghiên cứu của ông đưa ra những kết luận gây tranh cãi mạnh mẽ."},{"en":"The decision remains highly controversial even years later.","vi":"Quyết định này vẫn gây tranh cãi mạnh mẽ ngay cả nhiều năm sau."}]', '[]', NULL, '/ˈhaɪli ˌkɑːntrəˈvɜːrʃəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 107, 'highly correlated with', 'có tương quan chặt chẽ với', 'adv + vpp', '[{"en":"Income is highly correlated with educational attainment.","vi":"Thu nhập có tương quan chặt chẽ với trình độ học vấn."},{"en":"Sleep quality is highly correlated with daily performance.","vi":"Chất lượng giấc ngủ có tương quan chặt chẽ với hiệu suất hằng ngày."},{"en":"These two variables were highly correlated with each other.","vi":"Hai biến số này có tương quan chặt chẽ với nhau."}]', '[]', NULL, '/ˈhaɪli ˈkɔːrəˌleɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 108, 'highly critical', 'rất chỉ trích', 'adv + adj', '[{"en":"The report was highly critical of the government''s response.","vi":"Bản báo cáo rất chỉ trích cách phản ứng của chính phủ."},{"en":"Reviewers were highly critical of the study''s methodology.","vi":"Người phản biện rất chỉ trích phương pháp luận của nghiên cứu."},{"en":"She remained highly critical of the plan throughout the meeting.","vi":"Cô vẫn rất chỉ trích kế hoạch trong suốt cuộc họp."}]', '[]', NULL, '/ˈhaɪli ˈkrɪtɪkəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 109, 'highly dependent', 'phụ thuộc rất nhiều', 'adv + adj', '[{"en":"The economy is highly dependent on foreign investment.","vi":"Nền kinh tế phụ thuộc rất nhiều vào đầu tư nước ngoài."},{"en":"Crop yields are highly dependent on seasonal rainfall.","vi":"Sản lượng mùa màng phụ thuộc rất nhiều vào lượng mưa theo mùa."},{"en":"The outcome is highly dependent on careful planning.","vi":"Kết quả phụ thuộc rất nhiều vào việc lập kế hoạch cẩn thận."}]', '[]', NULL, '/ˈhaɪli dɪˈpendənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 110, 'highly desirable', 'rất đáng mong muốn', 'adv + adj', '[{"en":"Strong leadership skills are highly desirable in managers.","vi":"Kỹ năng lãnh đạo vững vàng rất đáng mong muốn ở các nhà quản lý."},{"en":"A quiet location makes the apartment highly desirable.","vi":"Vị trí yên tĩnh khiến căn hộ trở nên rất đáng mong muốn."},{"en":"Fluency in two languages is highly desirable for the role.","vi":"Thông thạo hai ngôn ngữ rất đáng mong muốn cho vị trí này."}]', '[]', NULL, '/ˈhaɪli dɪˈzaɪərəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 111, 'highly developed', 'phát triển cao', 'adv + vpp', '[{"en":"The region has a highly developed transport network.","vi":"Khu vực này có mạng lưới giao thông phát triển cao."},{"en":"Dolphins possess a highly developed sense of hearing.","vi":"Cá heo sở hữu khả năng nghe phát triển cao."},{"en":"Highly developed nations invest heavily in research.","vi":"Các quốc gia phát triển cao đầu tư mạnh vào nghiên cứu."}]', '[]', NULL, '/ˈhaɪli dɪˈveləpt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 112, 'highly educated', 'có học vấn cao', 'adv + vpp', '[{"en":"The company recruits highly educated specialists each year.","vi":"Công ty tuyển những chuyên gia có học vấn cao mỗi năm."},{"en":"A highly educated workforce drives economic innovation.","vi":"Một lực lượng lao động có học vấn cao thúc đẩy đổi mới kinh tế."},{"en":"Her parents were both highly educated professionals.","vi":"Cha mẹ cô đều là những chuyên gia có học vấn cao."}]', '[]', NULL, '/ˈhaɪli ˈedʒəˌkeɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 113, 'highly effective', 'rất hiệu quả', 'adv + adj', '[{"en":"The new vaccine proved highly effective in clinical trials.","vi":"Vắc-xin mới tỏ ra rất hiệu quả trong các thử nghiệm lâm sàng."},{"en":"Visual aids are a highly effective teaching tool.","vi":"Tài liệu trực quan là một công cụ giảng dạy rất hiệu quả."},{"en":"The campaign was highly effective at raising awareness.","vi":"Chiến dịch rất hiệu quả trong việc nâng cao nhận thức."}]', '[]', NULL, '/ˈhaɪli ɪˈfektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 114, 'highly efficient', 'rất hiệu suất', 'adv + adj', '[{"en":"The factory uses a highly efficient production process.","vi":"Nhà máy sử dụng quy trình sản xuất rất hiệu suất."},{"en":"Modern engines are highly efficient at converting fuel.","vi":"Động cơ hiện đại rất hiệu suất trong việc chuyển hóa nhiên liệu."},{"en":"Their highly efficient system reduced waste significantly.","vi":"Hệ thống rất hiệu suất của họ giảm lãng phí đáng kể."}]', '[]', NULL, '/ˈhaɪli ɪˈfɪʃənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 115, 'highly influential', 'có ảnh hưởng lớn', 'adv + adj', '[{"en":"Her book became highly influential in modern psychology.","vi":"Cuốn sách của bà trở nên có ảnh hưởng lớn trong tâm lý học hiện đại."},{"en":"He was a highly influential figure in the reform movement.","vi":"Ông là một nhân vật có ảnh hưởng lớn trong phong trào cải cách."},{"en":"The theory remains highly influential among economists.","vi":"Lý thuyết này vẫn có ảnh hưởng lớn trong giới kinh tế học."}]', '[]', NULL, '/ˈhaɪli ˌɪnfluˈenʃəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 116, 'highly likely', 'rất có khả năng', 'adv + adj', '[{"en":"It is highly likely that prices will rise next year.","vi":"Rất có khả năng giá sẽ tăng vào năm tới."},{"en":"Given the data, success seems highly likely now.","vi":"Với dữ liệu này, thành công có vẻ rất có khả năng xảy ra."},{"en":"A delay is highly likely due to the bad weather.","vi":"Sự chậm trễ rất có khả năng xảy ra do thời tiết xấu."}]', '[]', NULL, '/ˈhaɪli ˈlaɪkli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 117, 'highly problematic', 'rất có vấn đề', 'adv + adj', '[{"en":"The assumption proved highly problematic upon closer inspection.","vi":"Giả định này tỏ ra rất có vấn đề khi xem xét kỹ hơn."},{"en":"Using such small samples is highly problematic for accuracy.","vi":"Việc dùng mẫu nhỏ như vậy rất có vấn đề về độ chính xác."},{"en":"The definition is highly problematic and needs clarification.","vi":"Định nghĩa này rất có vấn đề và cần được làm rõ."}]', '[]', NULL, '/ˈhaɪli ˌprɑːbləˈmætɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 118, 'highly relevant', 'rất phù hợp, rất liên quan', 'adv + adj', '[{"en":"These findings are highly relevant to current policy debates.","vi":"Những phát hiện này rất liên quan đến các cuộc tranh luận chính sách hiện nay."},{"en":"The course content is highly relevant to my future career.","vi":"Nội dung khóa học rất phù hợp với sự nghiệp tương lai của tôi."},{"en":"His experience is highly relevant to the position offered.","vi":"Kinh nghiệm của anh rất phù hợp với vị trí được chào mời."}]', '[]', NULL, '/ˈhaɪli ˈreləvənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 119, 'highly selective', 'có tính chọn lọc cao', 'adv + adj', '[{"en":"The school has a highly selective admissions process.","vi":"Trường có quy trình tuyển sinh có tính chọn lọc cao."},{"en":"Editors are highly selective about which articles to publish.","vi":"Biên tập viên có tính chọn lọc cao về việc đăng bài nào."},{"en":"Memory can be highly selective about what it retains.","vi":"Trí nhớ có thể có tính chọn lọc cao về điều nó giữ lại."}]', '[]', NULL, '/ˈhaɪli sɪˈlektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 120, 'highly sensitive', 'rất nhạy cảm', 'adv + adj', '[{"en":"The instrument is highly sensitive to small temperature changes.","vi":"Thiết bị rất nhạy cảm với những thay đổi nhiệt độ nhỏ."},{"en":"The negotiations involve highly sensitive political issues.","vi":"Cuộc đàm phán liên quan đến những vấn đề chính trị rất nhạy cảm."},{"en":"Personal data is highly sensitive and must be protected.","vi":"Dữ liệu cá nhân rất nhạy cảm và phải được bảo vệ."}]', '[]', NULL, '/ˈhaɪli ˈsensətɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 121, 'highly significant', 'rất đáng kể, rất ý nghĩa', 'adv + adj', '[{"en":"The difference between groups was statistically highly significant.","vi":"Sự khác biệt giữa các nhóm có ý nghĩa thống kê rất đáng kể."},{"en":"This discovery is highly significant for cancer research.","vi":"Phát hiện này rất ý nghĩa đối với nghiên cứu ung thư."},{"en":"The event marked a highly significant moment in history.","vi":"Sự kiện này đánh dấu một khoảnh khắc rất ý nghĩa trong lịch sử."}]', '[]', NULL, '/ˈhaɪli sɪɡˈnɪfɪkənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 122, 'highly skilled', 'có tay nghề cao', 'adv + adj', '[{"en":"The hospital employs highly skilled surgeons and nurses.","vi":"Bệnh viện thuê những bác sĩ phẫu thuật và y tá có tay nghề cao."},{"en":"Highly skilled workers are in short supply in this sector.","vi":"Lao động có tay nghề cao đang thiếu hụt trong lĩnh vực này."},{"en":"The task demands a highly skilled and patient team.","vi":"Nhiệm vụ này đòi hỏi một đội ngũ có tay nghề cao và kiên nhẫn."}]', '[]', NULL, '/ˈhaɪli ˈskɪld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 123, 'highly sophisticated', 'rất tinh vi', 'adv + adj', '[{"en":"The lab uses highly sophisticated equipment for analysis.","vi":"Phòng thí nghiệm dùng thiết bị rất tinh vi để phân tích."},{"en":"Hackers deployed a highly sophisticated attack on the network.","vi":"Tin tặc triển khai một cuộc tấn công rất tinh vi vào mạng."},{"en":"The model relies on highly sophisticated mathematical methods.","vi":"Mô hình dựa trên những phương pháp toán học rất tinh vi."}]', '[]', NULL, '/ˈhaɪli səˈfɪstəˌkeɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 124, 'highly structured', 'có cấu trúc chặt chẽ', 'adv + vpp', '[{"en":"The program follows a highly structured weekly schedule.","vi":"Chương trình tuân theo một lịch trình hằng tuần có cấu trúc chặt chẽ."},{"en":"Young children often benefit from a highly structured routine.","vi":"Trẻ nhỏ thường hưởng lợi từ một thói quen có cấu trúc chặt chẽ."},{"en":"The interview was highly structured with fixed questions.","vi":"Cuộc phỏng vấn có cấu trúc chặt chẽ với những câu hỏi cố định."}]', '[]', NULL, '/ˈhaɪli ˈstrʌktʃərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 125, 'highly successful', 'rất thành công', 'adv + adj', '[{"en":"The fundraising campaign was highly successful this year.","vi":"Chiến dịch gây quỹ rất thành công trong năm nay."},{"en":"She built a highly successful career in journalism.","vi":"Cô đã xây dựng một sự nghiệp rất thành công trong báo chí."},{"en":"The treatment has been highly successful in trials.","vi":"Phương pháp điều trị đã rất thành công trong các thử nghiệm."}]', '[]', NULL, '/ˈhaɪli səkˈsesfəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 126, 'highly unlikely', 'rất khó xảy ra', 'adv + adj', '[{"en":"It is highly unlikely that the experiment will fail.","vi":"Rất khó có khả năng thí nghiệm sẽ thất bại."},{"en":"Such a coincidence is highly unlikely to occur twice.","vi":"Một sự trùng hợp như vậy rất khó xảy ra hai lần."},{"en":"A full recovery by tomorrow seems highly unlikely.","vi":"Việc hồi phục hoàn toàn vào ngày mai có vẻ rất khó xảy ra."}]', '[]', NULL, '/ˈhaɪli ʌnˈlaɪkli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 127, 'highly valued', 'được coi trọng cao', 'adv + vpp', '[{"en":"Honesty is highly valued in every professional setting.","vi":"Sự trung thực được coi trọng cao trong mọi môi trường nghề nghiệp."},{"en":"Practical experience is highly valued by most employers.","vi":"Kinh nghiệm thực tế được hầu hết nhà tuyển dụng coi trọng cao."},{"en":"Her opinion is highly valued within the research team.","vi":"Ý kiến của cô được coi trọng cao trong nhóm nghiên cứu."}]', '[]', NULL, '/ˈhaɪli ˈvæljuːd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 128, 'highly variable', 'rất biến thiên', 'adv + adj', '[{"en":"Rainfall in the region is highly variable from year to year.","vi":"Lượng mưa trong khu vực rất biến thiên qua từng năm."},{"en":"Test results were highly variable across the sample.","vi":"Kết quả kiểm tra rất biến thiên trong toàn bộ mẫu."},{"en":"Performance was highly variable depending on the conditions.","vi":"Hiệu suất rất biến thiên tùy thuộc vào điều kiện."}]', '[]', NULL, '/ˈhaɪli ˈveriəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 129, 'historical account', 'ghi chép lịch sử', 'adj + n', '[{"en":"The book offers a detailed historical account of the war.","vi":"Cuốn sách cung cấp một ghi chép lịch sử chi tiết về cuộc chiến."},{"en":"Her historical account drew on rare archival documents.","vi":"Ghi chép lịch sử của bà dựa trên những tài liệu lưu trữ hiếm."},{"en":"Each historical account reflects the writer''s own perspective.","vi":"Mỗi ghi chép lịch sử phản ánh góc nhìn riêng của người viết."}]', '[]', NULL, '/hɪˈstɔːrɪkəl əˈkaʊnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 130, 'historical analysis', 'phân tích lịch sử', 'adj + n', '[{"en":"A careful historical analysis reveals long-term economic trends.","vi":"Một phân tích lịch sử cẩn thận cho thấy các xu hướng kinh tế dài hạn."},{"en":"Her thesis combines statistics with historical analysis.","vi":"Luận văn của cô kết hợp thống kê với phân tích lịch sử."},{"en":"Historical analysis helps explain present-day social structures.","vi":"Phân tích lịch sử giúp giải thích các cấu trúc xã hội ngày nay."}]', '[]', NULL, '/hɪˈstɔːrɪkəl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 131, 'historical background', 'bối cảnh lịch sử', 'adj + n', '[{"en":"The chapter provides the historical background of the conflict.","vi":"Chương này cung cấp bối cảnh lịch sử của cuộc xung đột."},{"en":"Understanding the historical background clarifies the author''s view.","vi":"Hiểu bối cảnh lịch sử giúp làm rõ quan điểm của tác giả."},{"en":"She explained the historical background before the main argument.","vi":"Cô giải thích bối cảnh lịch sử trước khi trình bày lập luận chính."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈbækˌɡraʊnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 132, 'historical change', 'sự thay đổi lịch sử', 'adj + n', '[{"en":"The lecture traced major historical change across centuries.","vi":"Bài giảng theo dõi sự thay đổi lịch sử lớn qua nhiều thế kỷ."},{"en":"Technology has driven rapid historical change in society.","vi":"Công nghệ đã thúc đẩy sự thay đổi lịch sử nhanh chóng trong xã hội."},{"en":"Scholars debate the causes of this historical change.","vi":"Các học giả tranh luận về nguyên nhân của sự thay đổi lịch sử này."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈtʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 133, 'historical circumstances', 'hoàn cảnh lịch sử', 'adj + n', '[{"en":"The law emerged from very specific historical circumstances.","vi":"Đạo luật ra đời từ những hoàn cảnh lịch sử rất cụ thể."},{"en":"We must judge the decision within its historical circumstances.","vi":"Chúng ta phải đánh giá quyết định trong hoàn cảnh lịch sử của nó."},{"en":"Different historical circumstances shaped each nation''s path.","vi":"Những hoàn cảnh lịch sử khác nhau định hình con đường của mỗi quốc gia."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈsɜːrkəmˌstænsəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 134, 'historical context', 'ngữ cảnh lịch sử', 'adj + n', '[{"en":"The poem makes more sense in its historical context.","vi":"Bài thơ trở nên dễ hiểu hơn trong ngữ cảnh lịch sử của nó."},{"en":"Teachers should explain the historical context of each text.","vi":"Giáo viên nên giải thích ngữ cảnh lịch sử của mỗi văn bản."},{"en":"Ignoring the historical context can distort our interpretation.","vi":"Bỏ qua ngữ cảnh lịch sử có thể làm sai lệch cách diễn giải của ta."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 135, 'historical data', 'dữ liệu lịch sử', 'adj + n', '[{"en":"Analysts used historical data to forecast future demand.","vi":"Các nhà phân tích dùng dữ liệu lịch sử để dự báo nhu cầu tương lai."},{"en":"The model is trained on decades of historical data.","vi":"Mô hình được huấn luyện trên dữ liệu lịch sử của nhiều thập kỷ."},{"en":"Reliable historical data is essential for accurate predictions.","vi":"Dữ liệu lịch sử đáng tin cậy là thiết yếu cho dự đoán chính xác."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 136, 'historical development', 'sự phát triển lịch sử', 'adj + n', '[{"en":"The course traces the historical development of democracy.","vi":"Khóa học theo dõi sự phát triển lịch sử của nền dân chủ."},{"en":"She studied the historical development of modern medicine.","vi":"Cô nghiên cứu sự phát triển lịch sử của y học hiện đại."},{"en":"This map shows the historical development of the city.","vi":"Bản đồ này thể hiện sự phát triển lịch sử của thành phố."}]', '[]', NULL, '/hɪˈstɔːrɪkəl dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 137, 'historical event', 'sự kiện lịch sử', 'adj + n', '[{"en":"The museum commemorates an important historical event.","vi":"Bảo tàng tưởng niệm một sự kiện lịch sử quan trọng."},{"en":"Each historical event can be interpreted in many ways.","vi":"Mỗi sự kiện lịch sử có thể được diễn giải theo nhiều cách."},{"en":"The novel weaves fiction around a real historical event.","vi":"Cuốn tiểu thuyết đan xen hư cấu quanh một sự kiện lịch sử có thật."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ɪˈvent/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 138, 'historical evidence', 'bằng chứng lịch sử', 'adj + n', '[{"en":"Strong historical evidence supports the author''s main claim.","vi":"Bằng chứng lịch sử vững chắc ủng hộ luận điểm chính của tác giả."},{"en":"There is little historical evidence for this popular legend.","vi":"Có rất ít bằng chứng lịch sử cho truyền thuyết phổ biến này."},{"en":"Archaeologists gathered historical evidence from the ruins.","vi":"Các nhà khảo cổ thu thập bằng chứng lịch sử từ tàn tích."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈevədəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 139, 'historical factors', 'các yếu tố lịch sử', 'adj + n', '[{"en":"Several historical factors explain the region''s poverty.","vi":"Một số yếu tố lịch sử giải thích sự nghèo đói của khu vực."},{"en":"Historical factors continue to shape modern trade patterns.","vi":"Các yếu tố lịch sử tiếp tục định hình các mô hình thương mại hiện đại."},{"en":"The author weighs historical factors against economic ones.","vi":"Tác giả cân nhắc các yếu tố lịch sử so với yếu tố kinh tế."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 140, 'historical interpretation', 'cách diễn giải lịch sử', 'adj + n', '[{"en":"Her historical interpretation challenges the traditional view.","vi":"Cách diễn giải lịch sử của bà thách thức quan điểm truyền thống."},{"en":"Every historical interpretation reflects certain assumptions.","vi":"Mọi cách diễn giải lịch sử đều phản ánh những giả định nhất định."},{"en":"The debate centers on competing historical interpretations.","vi":"Cuộc tranh luận xoay quanh những cách diễn giải lịch sử trái ngược."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ɪnˌtɜːrprəˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 141, 'historical knowledge', 'kiến thức lịch sử', 'adj + n', '[{"en":"Solid historical knowledge helps students analyze sources.","vi":"Kiến thức lịch sử vững chắc giúp học sinh phân tích nguồn tư liệu."},{"en":"The exam tests both historical knowledge and analytical skill.","vi":"Kỳ thi kiểm tra cả kiến thức lịch sử lẫn kỹ năng phân tích."},{"en":"Historical knowledge deepens our understanding of the present.","vi":"Kiến thức lịch sử làm sâu sắc thêm sự hiểu biết của ta về hiện tại."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 142, 'historical period', 'giai đoạn lịch sử', 'adj + n', '[{"en":"The exhibition focuses on one specific historical period.","vi":"Triển lãm tập trung vào một giai đoạn lịch sử cụ thể."},{"en":"Art styles vary greatly across each historical period.","vi":"Phong cách nghệ thuật khác nhau rất nhiều qua mỗi giai đoạn lịch sử."},{"en":"She specializes in the historical period after the revolution.","vi":"Bà chuyên về giai đoạn lịch sử sau cuộc cách mạng."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 143, 'historical perspective', 'góc nhìn lịch sử', 'adj + n', '[{"en":"A historical perspective helps us understand current conflicts.","vi":"Một góc nhìn lịch sử giúp ta hiểu các xung đột hiện tại."},{"en":"The author writes from a broad historical perspective.","vi":"Tác giả viết từ một góc nhìn lịch sử rộng lớn."},{"en":"From a historical perspective, the policy is not new.","vi":"Xét từ góc nhìn lịch sử, chính sách này không hề mới."}]', '[]', NULL, '/hɪˈstɔːrɪkəl pərˈspektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 144, 'historical reality', 'thực tế lịch sử', 'adj + n', '[{"en":"The film sometimes departs from historical reality for drama.","vi":"Bộ phim đôi khi rời xa thực tế lịch sử để tạo kịch tính."},{"en":"Myths often blur the line with historical reality.","vi":"Thần thoại thường làm mờ ranh giới với thực tế lịch sử."},{"en":"Historians try to reconstruct historical reality from sources.","vi":"Các sử gia cố tái dựng thực tế lịch sử từ các nguồn tư liệu."}]', '[]', NULL, '/hɪˈstɔːrɪkəl riˈæləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 145, 'historical record', 'tư liệu lịch sử', 'adj + n', '[{"en":"The historical record contains few details about her life.","vi":"Tư liệu lịch sử chứa rất ít chi tiết về cuộc đời bà."},{"en":"Newspapers form an important part of the historical record.","vi":"Báo chí là một phần quan trọng của tư liệu lịch sử."},{"en":"This document fills a gap in the historical record.","vi":"Tài liệu này lấp đầy một khoảng trống trong tư liệu lịch sử."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈrekərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 146, 'historical roots', 'nguồn gốc lịch sử', 'adj + n', '[{"en":"The festival has deep historical roots in the region.","vi":"Lễ hội có nguồn gốc lịch sử sâu xa trong khu vực."},{"en":"The conflict''s historical roots stretch back many centuries.","vi":"Nguồn gốc lịch sử của cuộc xung đột kéo dài nhiều thế kỷ."},{"en":"Understanding its historical roots clarifies the tradition.","vi":"Hiểu nguồn gốc lịch sử giúp làm rõ truyền thống này."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈruːts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 147, 'historical study', 'nghiên cứu lịch sử', 'adj + n', '[{"en":"Her historical study examines trade in the medieval era.","vi":"Nghiên cứu lịch sử của bà khảo sát thương mại thời trung cổ."},{"en":"A thorough historical study requires patient archival work.","vi":"Một nghiên cứu lịch sử kỹ lưỡng đòi hỏi việc lưu trữ kiên nhẫn."},{"en":"The historical study won an award for original research.","vi":"Nghiên cứu lịch sử này đã đoạt giải vì tính sáng tạo."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 148, 'historical writing', 'lối viết sử, trước tác lịch sử', 'adj + n', '[{"en":"Good historical writing balances evidence with clear narrative.","vi":"Lối viết sử hay cân bằng giữa bằng chứng và lời kể rõ ràng."},{"en":"The course explores changing styles of historical writing.","vi":"Khóa học khám phá những phong cách viết sử đang thay đổi."},{"en":"Her historical writing is admired for its lively prose.","vi":"Trước tác lịch sử của bà được ngưỡng mộ vì văn phong sống động."}]', '[]', NULL, '/hɪˈstɔːrɪkəl ˈraɪtɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 149, 'historically specific', 'mang tính đặc thù lịch sử', 'adv + adj', '[{"en":"These ideas are historically specific to the modern era.","vi":"Những ý tưởng này mang tính đặc thù lịch sử của thời hiện đại."},{"en":"Such practices are historically specific and not universal.","vi":"Những thực hành như vậy mang tính đặc thù lịch sử, không phổ quát."},{"en":"The author treats gender roles as historically specific.","vi":"Tác giả coi vai trò giới như điều mang tính đặc thù lịch sử."}]', '[]', NULL, '/hɪˈstɔːrɪkli spəˈsɪfɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-7-01', 150, 'hold a conference', 'tổ chức một hội nghị', 'v + n', '[{"en":"The university plans to hold a conference on climate policy.","vi":"Trường đại học dự định tổ chức một hội nghị về chính sách khí hậu."},{"en":"They will hold a conference to present the new findings.","vi":"Họ sẽ tổ chức một hội nghị để trình bày các phát hiện mới."},{"en":"The institute holds a conference every spring for researchers.","vi":"Viện tổ chức một hội nghị mỗi mùa xuân cho các nhà nghiên cứu."}]', '[]', NULL, '/ˈhoʊld ə ˈkɑːnfərəns/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-8-01', 'colloc-8', 'Cụm học thuật · Nhóm 8', 'Academic Collocation List (Pearson/PTE) — nhóm 8 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 1, 'holistic approach', 'cách tiếp cận toàn diện', 'adj + n', '[{"en":"The clinic takes a holistic approach to patient care.","vi":"Phòng khám áp dụng cách tiếp cận toàn diện trong chăm sóc bệnh nhân."},{"en":"A holistic approach considers both mind and body together.","vi":"Cách tiếp cận toàn diện xem xét cả tâm trí lẫn cơ thể cùng nhau."},{"en":"Teachers favor a holistic approach to student development.","vi":"Giáo viên ưa chuộng cách tiếp cận toàn diện cho sự phát triển của học sinh."}]', '[]', NULL, '/hoʊˈlɪstɪk əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 2, 'homogeneous group', 'nhóm đồng nhất', 'adj + n', '[{"en":"The study compared a homogeneous group with a diverse one.","vi":"Nghiên cứu so sánh một nhóm đồng nhất với một nhóm đa dạng."},{"en":"Researchers selected a homogeneous group to reduce variation.","vi":"Các nhà nghiên cứu chọn một nhóm đồng nhất để giảm sự biến thiên."},{"en":"No society is truly a homogeneous group of people.","vi":"Không có xã hội nào thực sự là một nhóm người đồng nhất."}]', '[]', NULL, '/ˌhoʊməˈdʒiːniəs ˈɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 3, 'huge amount of', 'một lượng khổng lồ', 'adj + n', '[{"en":"The project generated a huge amount of useful data.","vi":"Dự án tạo ra một lượng dữ liệu hữu ích khổng lồ."},{"en":"Writing the thesis required a huge amount of effort.","vi":"Viết luận văn đòi hỏi một lượng nỗ lực khổng lồ."},{"en":"A huge amount of waste ends up in the ocean.","vi":"Một lượng rác khổng lồ cuối cùng trôi ra đại dương."}]', '[]', NULL, '/ˈhjuːdʒ əˈmaʊnt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 4, 'human activity', 'hoạt động của con người', 'adj + n', '[{"en":"Human activity is a major cause of climate change.","vi":"Hoạt động của con người là nguyên nhân chính gây biến đổi khí hậu."},{"en":"Satellites monitor human activity across the planet.","vi":"Vệ tinh theo dõi hoạt động của con người trên khắp hành tinh."},{"en":"Much human activity leaves a lasting mark on nature.","vi":"Nhiều hoạt động của con người để lại dấu ấn lâu dài lên thiên nhiên."}]', '[]', NULL, '/ˈhjuːmən ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 5, 'human behavior', 'hành vi của con người', 'adj + n', '[{"en":"Psychology seeks to explain patterns of human behavior.","vi":"Tâm lý học tìm cách giải thích các khuôn mẫu hành vi của con người."},{"en":"Economic models often simplify complex human behavior.","vi":"Các mô hình kinh tế thường đơn giản hóa hành vi phức tạp của con người."},{"en":"Culture strongly influences everyday human behavior.","vi":"Văn hóa ảnh hưởng mạnh đến hành vi thường ngày của con người."}]', '[]', NULL, '/ˈhjuːmən bɪˈheɪvjər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 6, 'human interaction', 'tương tác giữa người với người', 'adj + n', '[{"en":"Technology has changed the nature of human interaction.","vi":"Công nghệ đã thay đổi bản chất của tương tác giữa người với người."},{"en":"Face-to-face human interaction supports emotional well-being.","vi":"Tương tác trực tiếp giữa người với người hỗ trợ sức khỏe tinh thần."},{"en":"The study observed human interaction in public spaces.","vi":"Nghiên cứu quan sát tương tác giữa người với người ở nơi công cộng."}]', '[]', NULL, '/ˈhjuːmən ˌɪntərˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 7, 'human society', 'xã hội loài người', 'adj + n', '[{"en":"Language is fundamental to the development of human society.","vi":"Ngôn ngữ là nền tảng cho sự phát triển của xã hội loài người."},{"en":"Cooperation has shaped human society throughout history.","vi":"Sự hợp tác đã định hình xã hội loài người suốt chiều dài lịch sử."},{"en":"Technology continues to transform human society rapidly.","vi":"Công nghệ tiếp tục biến đổi xã hội loài người một cách nhanh chóng."}]', '[]', NULL, '/ˈhjuːmən səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 8, 'human species', 'loài người', 'adj + n', '[{"en":"The human species has spread across nearly every continent.","vi":"Loài người đã lan rộng khắp gần như mọi lục địa."},{"en":"Climate change poses a real threat to the human species.","vi":"Biến đổi khí hậu đặt ra mối đe dọa thực sự cho loài người."},{"en":"The human species evolved over hundreds of thousands of years.","vi":"Loài người tiến hóa qua hàng trăm nghìn năm."}]', '[]', NULL, '/ˈhjuːmən ˈspiːʃiːz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 9, 'ideally suited', 'rất phù hợp một cách lý tưởng', 'adv + vpp', '[{"en":"Her background makes her ideally suited for the role.","vi":"Nền tảng của cô khiến cô rất phù hợp một cách lý tưởng cho vai trò này."},{"en":"The climate is ideally suited to growing grapes.","vi":"Khí hậu rất lý tưởng để trồng nho."},{"en":"This tool is ideally suited for analyzing large datasets.","vi":"Công cụ này rất phù hợp lý tưởng để phân tích các tập dữ liệu lớn."}]', '[]', NULL, '/aɪˈdiːəli ˈsuːtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 10, 'identify factors', 'xác định các yếu tố', 'v + n', '[{"en":"The study aims to identify factors that affect performance.","vi":"Nghiên cứu nhằm xác định các yếu tố ảnh hưởng đến hiệu suất."},{"en":"Researchers tried to identify factors behind the decline.","vi":"Các nhà nghiên cứu cố xác định các yếu tố đằng sau sự suy giảm."},{"en":"It is hard to identify factors that act together.","vi":"Thật khó để xác định các yếu tố cùng tác động với nhau."}]', '[]', NULL, '/aɪˈdentəˌfaɪ ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 11, 'identify features', 'xác định các đặc điểm', 'v + n', '[{"en":"Students learn to identify features of academic texts.","vi":"Học sinh học cách xác định các đặc điểm của văn bản học thuật."},{"en":"The software can identify features in medical images.","vi":"Phần mềm có thể xác định các đặc điểm trong ảnh y khoa."},{"en":"We first identify features common to all the samples.","vi":"Trước tiên chúng tôi xác định các đặc điểm chung của mọi mẫu."}]', '[]', NULL, '/aɪˈdentəˌfaɪ ˈfiːtʃərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 12, 'identify a problem', 'xác định một vấn đề', 'v + n', '[{"en":"The first step is to identify a problem clearly.","vi":"Bước đầu tiên là xác định một vấn đề một cách rõ ràng."},{"en":"Engineers worked quickly to identify a problem in the system.","vi":"Các kỹ sư làm việc nhanh chóng để xác định một vấn đề trong hệ thống."},{"en":"Good researchers identify a problem worth solving.","vi":"Nhà nghiên cứu giỏi xác định một vấn đề đáng giải quyết."}]', '[]', NULL, '/aɪˈdentəˌfaɪ ə ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 13, 'identify a way', 'tìm ra một cách', 'v + n', '[{"en":"The team hopes to identify a way to cut costs.","vi":"Nhóm hy vọng tìm ra một cách để cắt giảm chi phí."},{"en":"Scientists must identify a way to test the hypothesis.","vi":"Các nhà khoa học phải tìm ra một cách để kiểm tra giả thuyết."},{"en":"We need to identify a way to engage younger readers.","vi":"Chúng ta cần tìm ra một cách để thu hút độc giả trẻ hơn."}]', '[]', NULL, '/aɪˈdentəˌfaɪ ə ˈweɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 14, 'identify an area', 'xác định một lĩnh vực', 'v + n', '[{"en":"The review helped identify an area needing more research.","vi":"Bài tổng quan giúp xác định một lĩnh vực cần nghiên cứu thêm."},{"en":"Managers should identify an area for immediate improvement.","vi":"Quản lý nên xác định một lĩnh vực cần cải thiện ngay."},{"en":"She tried to identify an area where she could specialize.","vi":"Cô cố xác định một lĩnh vực mà mình có thể chuyên sâu."}]', '[]', NULL, '/aɪˈdentəˌfaɪ ən ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 15, 'identify an issue', 'xác định một vấn đề', 'v + n', '[{"en":"The audit helped identify an issue with the accounts.","vi":"Cuộc kiểm toán giúp xác định một vấn đề với các tài khoản."},{"en":"It is important to identify an issue before it grows.","vi":"Điều quan trọng là xác định một vấn đề trước khi nó lớn lên."},{"en":"Teachers can identify an issue early through regular feedback.","vi":"Giáo viên có thể xác định một vấn đề sớm qua phản hồi thường xuyên."}]', '[]', NULL, '/aɪˈdentəˌfaɪ ən ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 16, 'immediate environment', 'môi trường xung quanh trực tiếp', 'adj + n', '[{"en":"Children learn quickly from their immediate environment.","vi":"Trẻ em học hỏi nhanh từ môi trường xung quanh trực tiếp."},{"en":"The study focused on the cell''s immediate environment.","vi":"Nghiên cứu tập trung vào môi trường trực tiếp quanh tế bào."},{"en":"We adapt our behavior to the immediate environment.","vi":"Chúng ta điều chỉnh hành vi theo môi trường xung quanh trực tiếp."}]', '[]', NULL, '/ɪˈmiːdiət ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 17, 'immediately apparent', 'rõ ràng ngay lập tức', 'adv + adj', '[{"en":"The cause of the error was not immediately apparent.","vi":"Nguyên nhân của lỗi không rõ ràng ngay lập tức."},{"en":"The benefits became immediately apparent after the change.","vi":"Lợi ích trở nên rõ ràng ngay lập tức sau khi thay đổi."},{"en":"It was immediately apparent that the data was flawed.","vi":"Rõ ràng ngay lập tức rằng dữ liệu có sai sót."}]', '[]', NULL, '/ɪˈmiːdiətli əˈpærənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 18, 'immediately following', 'ngay sau đó', 'adv + adj', '[{"en":"Sales dropped in the weeks immediately following the news.","vi":"Doanh số giảm trong những tuần ngay sau khi tin tức xuất hiện."},{"en":"The discussion took place immediately following the lecture.","vi":"Cuộc thảo luận diễn ra ngay sau buổi giảng."},{"en":"In the period immediately following the war, prices rose.","vi":"Trong giai đoạn ngay sau chiến tranh, giá cả tăng lên."}]', '[]', NULL, '/ɪˈmiːdiətli ˈfɑːloʊɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 19, 'immediately obvious', 'hiển nhiên ngay lập tức', 'adv + adj', '[{"en":"The solution was not immediately obvious to the students.","vi":"Giải pháp không hiển nhiên ngay lập tức đối với học sinh."},{"en":"It is immediately obvious that the two graphs differ.","vi":"Hiển nhiên ngay lập tức rằng hai đồ thị này khác nhau."},{"en":"The flaw becomes immediately obvious when tested properly.","vi":"Khiếm khuyết trở nên hiển nhiên ngay khi được kiểm tra đúng cách."}]', '[]', NULL, '/ɪˈmiːdiətli ˈɑːbviəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 20, 'immediately preceding', 'ngay trước đó', 'adv + adj', '[{"en":"The years immediately preceding the crisis saw rapid growth.","vi":"Những năm ngay trước cuộc khủng hoảng chứng kiến tăng trưởng nhanh."},{"en":"Refer to the paragraph immediately preceding this section.","vi":"Hãy xem đoạn văn ngay trước phần này."},{"en":"Events immediately preceding the vote shaped the outcome.","vi":"Những sự kiện ngay trước cuộc bỏ phiếu đã định hình kết quả."}]', '[]', NULL, '/ɪˈmiːdiətli prɪˈsiːdɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 21, 'imported goods', 'hàng hóa nhập khẩu', 'adj + n', '[{"en":"Tariffs raised the price of many imported goods.","vi":"Thuế quan làm tăng giá của nhiều hàng hóa nhập khẩu."},{"en":"Consumers increasingly prefer cheaper imported goods.","vi":"Người tiêu dùng ngày càng ưa chuộng hàng nhập khẩu rẻ hơn."},{"en":"The country relies heavily on imported goods and fuel.","vi":"Quốc gia này phụ thuộc nhiều vào hàng hóa và nhiên liệu nhập khẩu."}]', '[]', NULL, '/ɪmˈpɔːrtɪd ˈɡʊdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 22, 'imported products', 'sản phẩm nhập khẩu', 'adj + n', '[{"en":"Imported products often face strict safety inspections.","vi":"Sản phẩm nhập khẩu thường phải qua kiểm tra an toàn nghiêm ngặt."},{"en":"Local firms struggle to compete with imported products.","vi":"Các công ty trong nước chật vật cạnh tranh với sản phẩm nhập khẩu."},{"en":"Demand for imported products grew steadily last year.","vi":"Nhu cầu về sản phẩm nhập khẩu tăng đều đặn trong năm ngoái."}]', '[]', NULL, '/ɪmˈpɔːrtɪd ˈprɑːdʌkts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 23, 'impose constraints', 'áp đặt những ràng buộc', 'v + n', '[{"en":"Limited funding can impose constraints on the research design.","vi":"Kinh phí hạn chế có thể áp đặt những ràng buộc lên thiết kế nghiên cứu."},{"en":"New regulations impose constraints on how data is shared.","vi":"Các quy định mới áp đặt những ràng buộc về cách chia sẻ dữ liệu."},{"en":"Time pressure imposes constraints on what we can achieve.","vi":"Áp lực thời gian áp đặt những ràng buộc lên điều ta có thể đạt được."}]', '[]', NULL, '/ɪmˈpoʊz kənˈstreɪnts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 24, 'impose limitations', 'áp đặt những hạn chế', 'v + n', '[{"en":"The small sample size imposes limitations on the conclusions.","vi":"Cỡ mẫu nhỏ áp đặt những hạn chế lên các kết luận."},{"en":"Budget cuts impose limitations on the program''s scope.","vi":"Việc cắt giảm ngân sách áp đặt những hạn chế lên phạm vi chương trình."},{"en":"Physical laws impose limitations on what engines can do.","vi":"Các định luật vật lý áp đặt những hạn chế lên khả năng của động cơ."}]', '[]', NULL, '/ɪmˈpoʊz ˌlɪmɪˈteɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 25, 'impose restrictions', 'áp đặt các hạn chế', 'v + n', '[{"en":"The government decided to impose restrictions on water usage.","vi":"Chính phủ quyết định áp đặt các hạn chế về việc dùng nước."},{"en":"Schools may impose restrictions on the use of phones.","vi":"Trường học có thể áp đặt hạn chế về việc dùng điện thoại."},{"en":"Authorities often impose restrictions to protect public health.","vi":"Nhà chức trách thường áp đặt hạn chế để bảo vệ sức khỏe cộng đồng."}]', '[]', NULL, '/ɪmˈpoʊz rɪˈstrɪkʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 26, 'improved performance', 'hiệu suất được cải thiện', 'adj + n', '[{"en":"The new training led to improved performance across the team.","vi":"Việc đào tạo mới giúp hiệu suất của cả đội được cải thiện."},{"en":"Researchers measured improved performance after the software update.","vi":"Các nhà nghiên cứu đo được hiệu suất cải thiện sau khi cập nhật phần mềm."},{"en":"Students showed improved performance once they studied regularly.","vi":"Học sinh có hiệu suất cải thiện khi học đều đặn hơn."}]', '[]', NULL, '/ɪmˈpruːvd pərˈfɔːrməns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 27, 'increase awareness', 'nâng cao nhận thức', 'v + n', '[{"en":"The campaign aims to increase awareness of climate change.","vi":"Chiến dịch nhằm nâng cao nhận thức về biến đổi khí hậu."},{"en":"Schools work hard to increase awareness about online safety.","vi":"Các trường nỗ lực nâng cao nhận thức về an toàn trực tuyến."},{"en":"Posters were used to increase awareness among local residents.","vi":"Áp phích được dùng để nâng cao nhận thức cho cư dân địa phương."}]', '[]', NULL, '/ɪnˈkriːs əˈwernəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 28, 'increase dramatically', 'tăng lên đáng kể', 'v + adv', '[{"en":"House prices increase dramatically when demand outpaces supply.","vi":"Giá nhà tăng đáng kể khi nhu cầu vượt nguồn cung."},{"en":"Sales tend to increase dramatically during the holiday season.","vi":"Doanh số thường tăng đáng kể trong mùa lễ."},{"en":"Pollution levels can increase dramatically in crowded cities.","vi":"Mức ô nhiễm có thể tăng đáng kể ở các thành phố đông đúc."}]', '[]', NULL, '/ɪnˈkriːs drəˈmætɪkli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 29, 'increase likelihood', 'làm tăng khả năng xảy ra', 'v + n', '[{"en":"Regular exercise can increase the likelihood of better health.","vi":"Tập thể dục đều đặn có thể làm tăng khả năng có sức khỏe tốt."},{"en":"Careful planning will increase the likelihood of project success.","vi":"Lập kế hoạch cẩn thận sẽ làm tăng khả năng thành công của dự án."},{"en":"Poor diet may increase the likelihood of serious illness.","vi":"Chế độ ăn kém có thể làm tăng khả năng mắc bệnh nặng."}]', '[]', NULL, '/ɪnˈkriːs ˈlaɪkliˌhʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 30, 'increased awareness', 'nhận thức gia tăng', 'adj + n', '[{"en":"Increased awareness of recycling has reduced household waste.","vi":"Nhận thức gia tăng về tái chế đã giảm rác thải sinh hoạt."},{"en":"The study reports increased awareness of mental health issues.","vi":"Nghiên cứu cho thấy nhận thức gia tăng về vấn đề sức khỏe tâm thần."},{"en":"Increased awareness among voters changed the election outcome.","vi":"Nhận thức gia tăng của cử tri đã thay đổi kết quả bầu cử."}]', '[]', NULL, '/ɪnˈkriːst əˈwernəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 31, 'increased competition', 'sự cạnh tranh gia tăng', 'adj + n', '[{"en":"Increased competition forced companies to lower their prices.","vi":"Sự cạnh tranh gia tăng buộc các công ty hạ giá."},{"en":"Global markets face increased competition from new firms.","vi":"Thị trường toàn cầu đối mặt cạnh tranh gia tăng từ các hãng mới."},{"en":"Increased competition often drives faster innovation.","vi":"Cạnh tranh gia tăng thường thúc đẩy đổi mới nhanh hơn."}]', '[]', NULL, '/ɪnˈkriːst ˌkɑːmpəˈtɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 32, 'increased demand', 'nhu cầu gia tăng', 'adj + n', '[{"en":"Increased demand for housing pushed rents much higher.","vi":"Nhu cầu gia tăng về nhà ở đẩy tiền thuê lên cao."},{"en":"The factory expanded to meet increased demand for goods.","vi":"Nhà máy mở rộng để đáp ứng nhu cầu gia tăng về hàng hóa."},{"en":"Increased demand for energy strains the national grid.","vi":"Nhu cầu gia tăng về năng lượng gây áp lực lên lưới điện quốc gia."}]', '[]', NULL, '/ɪnˈkriːst dɪˈmænd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 33, 'increased importance', 'tầm quan trọng gia tăng', 'adj + n', '[{"en":"The increased importance of data has reshaped modern business.","vi":"Tầm quan trọng gia tăng của dữ liệu đã định hình lại kinh doanh hiện đại."},{"en":"Researchers note the increased importance of soft skills.","vi":"Các nhà nghiên cứu lưu ý tầm quan trọng gia tăng của kỹ năng mềm."},{"en":"Climate policy reflects the increased importance of sustainability.","vi":"Chính sách khí hậu phản ánh tầm quan trọng gia tăng của tính bền vững."}]', '[]', NULL, '/ɪnˈkriːst ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 34, 'increased interest', 'sự quan tâm gia tăng', 'adj + n', '[{"en":"There is increased interest in learning languages online.","vi":"Có sự quan tâm gia tăng đến việc học ngôn ngữ trực tuyến."},{"en":"The museum saw increased interest after the new exhibit opened.","vi":"Bảo tàng có sự quan tâm gia tăng sau khi mở triển lãm mới."},{"en":"Increased interest in healthy food boosted organic sales.","vi":"Sự quan tâm gia tăng đến thực phẩm lành mạnh thúc đẩy doanh số hữu cơ."}]', '[]', NULL, '/ɪnˈkriːst ˈɪntrəst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 35, 'increased level', 'mức độ gia tăng', 'adj + n', '[{"en":"Doctors observed an increased level of stress among students.","vi":"Bác sĩ ghi nhận mức độ căng thẳng gia tăng ở học sinh."},{"en":"An increased level of activity improves overall fitness.","vi":"Mức độ vận động gia tăng cải thiện thể lực tổng thể."},{"en":"The report shows an increased level of public spending.","vi":"Báo cáo cho thấy mức độ chi tiêu công gia tăng."}]', '[]', NULL, '/ɪnˈkriːst ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 36, 'increased number', 'số lượng gia tăng', 'adj + n', '[{"en":"An increased number of students enrolled in online courses.","vi":"Số lượng học sinh đăng ký khóa học trực tuyến gia tăng."},{"en":"The city recorded an increased number of cycling commuters.","vi":"Thành phố ghi nhận số lượng người đi xe đạp gia tăng."},{"en":"An increased number of firms now offer remote work.","vi":"Số lượng công ty cung cấp làm việc từ xa hiện đã gia tăng."}]', '[]', NULL, '/ɪnˈkriːst ˈnʌmbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 37, 'increased pressure', 'áp lực gia tăng', 'adj + n', '[{"en":"Increased pressure at work left many employees exhausted.","vi":"Áp lực gia tăng tại nơi làm việc khiến nhiều nhân viên kiệt sức."},{"en":"Farmers face increased pressure from changing weather patterns.","vi":"Nông dân đối mặt áp lực gia tăng từ thời tiết thay đổi."},{"en":"Increased pressure on resources demands smarter planning.","vi":"Áp lực gia tăng lên tài nguyên đòi hỏi lập kế hoạch thông minh hơn."}]', '[]', NULL, '/ɪnˈkriːst ˈpreʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 38, 'increased production', 'sản lượng gia tăng', 'adj + n', '[{"en":"Increased production helped the company meet rising demand.","vi":"Sản lượng gia tăng giúp công ty đáp ứng nhu cầu tăng cao."},{"en":"New machines allowed increased production at the plant.","vi":"Máy móc mới cho phép sản lượng gia tăng tại nhà máy."},{"en":"Increased production of solar panels lowered their cost.","vi":"Sản lượng gia tăng của tấm pin mặt trời làm giảm giá thành."}]', '[]', NULL, '/ɪnˈkriːst prəˈdʌkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 39, 'increased productivity', 'năng suất gia tăng', 'adj + n', '[{"en":"Flexible hours led to increased productivity among staff.","vi":"Giờ làm linh hoạt dẫn đến năng suất gia tăng của nhân viên."},{"en":"Better tools resulted in increased productivity for the team.","vi":"Công cụ tốt hơn mang lại năng suất gia tăng cho cả đội."},{"en":"Training programs are linked to increased productivity overall.","vi":"Các chương trình đào tạo gắn liền với năng suất gia tăng nói chung."}]', '[]', NULL, '/ɪnˈkriːst ˌproʊdʌkˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 40, 'increased risk', 'nguy cơ gia tăng', 'adj + n', '[{"en":"Smoking is linked to an increased risk of heart disease.","vi":"Hút thuốc gắn liền với nguy cơ gia tăng mắc bệnh tim."},{"en":"Poor diet brings an increased risk of long-term illness.","vi":"Chế độ ăn kém mang lại nguy cơ gia tăng mắc bệnh lâu dài."},{"en":"Climate change creates an increased risk of severe floods.","vi":"Biến đổi khí hậu tạo ra nguy cơ gia tăng về lũ lụt nghiêm trọng."}]', '[]', NULL, '/ɪnˈkriːst rɪsk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 41, 'increasing awareness', 'nhận thức ngày càng tăng', 'adj + n', '[{"en":"There is increasing awareness of the dangers of plastic.","vi":"Có nhận thức ngày càng tăng về mối nguy của nhựa."},{"en":"Increasing awareness of nutrition has changed eating habits.","vi":"Nhận thức ngày càng tăng về dinh dưỡng đã thay đổi thói quen ăn uống."},{"en":"The media plays a role in increasing awareness of disease.","vi":"Truyền thông góp phần làm nhận thức về bệnh tật ngày càng tăng."}]', '[]', NULL, '/ɪnˈkriːsɪŋ əˈwernəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 42, 'increasing complexity', 'sự phức tạp ngày càng tăng', 'adj + n', '[{"en":"The increasing complexity of software makes testing harder.","vi":"Sự phức tạp ngày càng tăng của phần mềm khiến kiểm thử khó hơn."},{"en":"Global trade reflects the increasing complexity of economies.","vi":"Thương mại toàn cầu phản ánh sự phức tạp ngày càng tăng của các nền kinh tế."},{"en":"Students struggle with the increasing complexity of the syllabus.","vi":"Học sinh vật lộn với sự phức tạp ngày càng tăng của chương trình học."}]', '[]', NULL, '/ɪnˈkriːsɪŋ kəmˈpleksəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 43, 'increasing demand', 'nhu cầu ngày càng tăng', 'adj + n', '[{"en":"Increasing demand for electric cars is reshaping the industry.","vi":"Nhu cầu ngày càng tăng về xe điện đang định hình lại ngành."},{"en":"Hospitals face increasing demand for skilled nurses.","vi":"Bệnh viện đối mặt nhu cầu ngày càng tăng về y tá lành nghề."},{"en":"Increasing demand for clean water threatens scarce supplies.","vi":"Nhu cầu ngày càng tăng về nước sạch đe dọa nguồn cung khan hiếm."}]', '[]', NULL, '/ɪnˈkriːsɪŋ dɪˈmænd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 44, 'increasing emphasis', 'sự nhấn mạnh ngày càng tăng', 'adj + n', '[{"en":"There is increasing emphasis on practical skills in schools.","vi":"Có sự nhấn mạnh ngày càng tăng vào kỹ năng thực hành trong trường học."},{"en":"Companies place increasing emphasis on customer satisfaction.","vi":"Các công ty ngày càng nhấn mạnh vào sự hài lòng của khách hàng."},{"en":"The increasing emphasis on data drives many new policies.","vi":"Sự nhấn mạnh ngày càng tăng vào dữ liệu thúc đẩy nhiều chính sách mới."}]', '[]', NULL, '/ɪnˈkriːsɪŋ ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 45, 'increasing importance', 'tầm quan trọng ngày càng tăng', 'adj + n', '[{"en":"The increasing importance of English shapes career choices.","vi":"Tầm quan trọng ngày càng tăng của tiếng Anh định hình lựa chọn nghề nghiệp."},{"en":"Educators stress the increasing importance of digital literacy.","vi":"Nhà giáo dục nhấn mạnh tầm quan trọng ngày càng tăng của hiểu biết số."},{"en":"Reports highlight the increasing importance of renewable energy.","vi":"Các báo cáo nêu bật tầm quan trọng ngày càng tăng của năng lượng tái tạo."}]', '[]', NULL, '/ɪnˈkriːsɪŋ ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 46, 'increasing interest', 'sự quan tâm ngày càng tăng', 'adj + n', '[{"en":"There is increasing interest in studying abroad among teenagers.","vi":"Có sự quan tâm ngày càng tăng đến du học trong giới thanh thiếu niên."},{"en":"Scientists show increasing interest in deep-sea exploration.","vi":"Các nhà khoa học ngày càng quan tâm đến khám phá biển sâu."},{"en":"Increasing interest in vegan food expanded the menu options.","vi":"Sự quan tâm ngày càng tăng đến đồ ăn thuần chay mở rộng thực đơn."}]', '[]', NULL, '/ɪnˈkriːsɪŋ ˈɪntrəst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 47, 'increasing pressure', 'áp lực ngày càng tăng', 'adj + n', '[{"en":"Teachers face increasing pressure to improve exam results.","vi":"Giáo viên đối mặt áp lực ngày càng tăng để cải thiện kết quả thi."},{"en":"Increasing pressure on the budget forced difficult cuts.","vi":"Áp lực ngày càng tăng lên ngân sách buộc phải cắt giảm khó khăn."},{"en":"Athletes work under increasing pressure to break records.","vi":"Vận động viên làm việc dưới áp lực ngày càng tăng để phá kỷ lục."}]', '[]', NULL, '/ɪnˈkriːsɪŋ ˈpreʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 48, 'increasing proportion of', 'tỷ lệ ngày càng tăng của', 'adj + n', '[{"en":"An increasing proportion of workers now telecommute from home.","vi":"Một tỷ lệ ngày càng tăng của người lao động nay làm việc từ xa tại nhà."},{"en":"An increasing proportion of energy comes from renewable sources.","vi":"Một tỷ lệ ngày càng tăng của năng lượng đến từ nguồn tái tạo."},{"en":"An increasing proportion of students choose science subjects.","vi":"Một tỷ lệ ngày càng tăng của học sinh chọn các môn khoa học."}]', '[]', NULL, '/ɪnˈkriːsɪŋ prəˈpɔːrʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 49, 'increasing tendency', 'xu hướng ngày càng tăng', 'adj + n', '[{"en":"There is an increasing tendency to shop entirely online.","vi":"Có một xu hướng ngày càng tăng là mua sắm hoàn toàn trực tuyến."},{"en":"Researchers note an increasing tendency toward remote learning.","vi":"Các nhà nghiên cứu lưu ý xu hướng ngày càng tăng hướng tới học từ xa."},{"en":"An increasing tendency to delay marriage is widely observed.","vi":"Xu hướng ngày càng tăng là trì hoãn kết hôn được ghi nhận rộng rãi."}]', '[]', NULL, '/ɪnˈkriːsɪŋ ˈtendənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 50, 'increasing trend', 'xu thế ngày càng tăng', 'adj + n', '[{"en":"The data reveals an increasing trend in global temperatures.","vi":"Dữ liệu cho thấy một xu thế ngày càng tăng của nhiệt độ toàn cầu."},{"en":"There is an increasing trend toward plant-based diets.","vi":"Có một xu thế ngày càng tăng hướng tới chế độ ăn từ thực vật."},{"en":"Analysts highlight an increasing trend in online payments.","vi":"Các nhà phân tích nêu bật xu thế ngày càng tăng của thanh toán trực tuyến."}]', '[]', NULL, '/ɪnˈkriːsɪŋ trend/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 51, 'increasingly aware', 'ngày càng nhận thức rõ', 'adv + adj', '[{"en":"Consumers are increasingly aware of the products they buy.","vi":"Người tiêu dùng ngày càng nhận thức rõ về sản phẩm họ mua."},{"en":"Citizens have become increasingly aware of their legal rights.","vi":"Người dân ngày càng nhận thức rõ về quyền pháp lý của mình."},{"en":"Companies are increasingly aware of their environmental impact.","vi":"Các công ty ngày càng nhận thức rõ về tác động môi trường của họ."}]', '[]', NULL, '/ɪnˈkriːsɪŋli əˈwer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 52, 'increasingly common', 'ngày càng phổ biến', 'adv + adj', '[{"en":"Remote work has become increasingly common in recent years.","vi":"Làm việc từ xa đã trở nên ngày càng phổ biến trong những năm gần đây."},{"en":"Electric vehicles are increasingly common on city streets.","vi":"Xe điện ngày càng phổ biến trên đường phố thành phố."},{"en":"Online courses are increasingly common at most universities.","vi":"Khóa học trực tuyến ngày càng phổ biến tại hầu hết các trường đại học."}]', '[]', NULL, '/ɪnˈkriːsɪŋli ˈkɑːmən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 53, 'increasingly complex', 'ngày càng phức tạp', 'adv + adj', '[{"en":"Modern supply chains have grown increasingly complex worldwide.","vi":"Chuỗi cung ứng hiện đại đã trở nên ngày càng phức tạp trên toàn cầu."},{"en":"The legal system can seem increasingly complex to ordinary people.","vi":"Hệ thống pháp luật có thể trở nên ngày càng phức tạp với người thường."},{"en":"Software architecture becomes increasingly complex as it grows.","vi":"Kiến trúc phần mềm trở nên ngày càng phức tạp khi mở rộng."}]', '[]', NULL, '/ɪnˈkriːsɪŋli kəmˈpleks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 54, 'increasingly difficult', 'ngày càng khó khăn', 'adv + adj', '[{"en":"It is increasingly difficult to find affordable housing nearby.","vi":"Ngày càng khó khăn để tìm nhà ở giá phải chăng gần đây."},{"en":"Saving money becomes increasingly difficult as prices rise.","vi":"Việc tiết kiệm tiền trở nên ngày càng khó khăn khi giá tăng."},{"en":"Maintaining focus is increasingly difficult with constant notifications.","vi":"Việc giữ tập trung ngày càng khó khăn với thông báo liên tục."}]', '[]', NULL, '/ɪnˈkriːsɪŋli ˈdɪfɪkəlt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 55, 'increasingly important', 'ngày càng quan trọng', 'adv + adj', '[{"en":"Digital skills are increasingly important in the job market.","vi":"Kỹ năng số ngày càng quan trọng trong thị trường lao động."},{"en":"Sustainability has become increasingly important to investors.","vi":"Tính bền vững đã trở nên ngày càng quan trọng với nhà đầu tư."},{"en":"Teamwork is increasingly important in research projects.","vi":"Làm việc nhóm ngày càng quan trọng trong các dự án nghiên cứu."}]', '[]', NULL, '/ɪnˈkriːsɪŋli ɪmˈpɔːrtənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 56, 'increasingly popular', 'ngày càng được ưa chuộng', 'adv + adj', '[{"en":"Cycling has become increasingly popular among young commuters.","vi":"Đi xe đạp ngày càng được ưa chuộng trong giới đi làm trẻ tuổi."},{"en":"Plant-based meals are increasingly popular in restaurants.","vi":"Bữa ăn từ thực vật ngày càng được ưa chuộng tại nhà hàng."},{"en":"Podcasts are increasingly popular as a way to learn.","vi":"Podcast ngày càng được ưa chuộng như một cách để học."}]', '[]', NULL, '/ɪnˈkriːsɪŋli ˈpɑːpjələr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 57, 'increasingly sophisticated', 'ngày càng tinh vi', 'adv + adj', '[{"en":"Cyberattacks are becoming increasingly sophisticated each year.","vi":"Các cuộc tấn công mạng ngày càng tinh vi qua từng năm."},{"en":"Marketing tools have grown increasingly sophisticated recently.","vi":"Công cụ tiếp thị đã trở nên ngày càng tinh vi gần đây."},{"en":"Modern robots are increasingly sophisticated and highly precise.","vi":"Robot hiện đại ngày càng tinh vi và rất chính xác."}]', '[]', NULL, '/ɪnˈkriːsɪŋli səˈfɪstɪˌkeɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 58, 'independent state', 'nhà nước độc lập', 'adj + n', '[{"en":"The colony fought for years to become an independent state.","vi":"Thuộc địa đã đấu tranh nhiều năm để trở thành một nhà nước độc lập."},{"en":"An independent state controls its own foreign policy.","vi":"Một nhà nước độc lập kiểm soát chính sách đối ngoại của mình."},{"en":"The treaty recognized the region as an independent state.","vi":"Hiệp ước công nhận khu vực là một nhà nước độc lập."}]', '[]', NULL, '/ˌɪndɪˈpendənt steɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 59, 'independent variable', 'biến độc lập', 'adj + n', '[{"en":"In the experiment, temperature was the independent variable.","vi":"Trong thí nghiệm, nhiệt độ là biến độc lập."},{"en":"Researchers change the independent variable to test its effect.","vi":"Các nhà nghiên cứu thay đổi biến độc lập để kiểm tra ảnh hưởng của nó."},{"en":"The independent variable here is the amount of sleep.","vi":"Biến độc lập ở đây là lượng giấc ngủ."}]', '[]', NULL, '/ˌɪndɪˈpendənt ˈveriəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 60, 'indigenous people', 'người bản địa', 'adj + n', '[{"en":"Indigenous people have lived on this land for centuries.","vi":"Người bản địa đã sống trên vùng đất này nhiều thế kỷ."},{"en":"The museum honors the traditions of indigenous people.","vi":"Bảo tàng tôn vinh truyền thống của người bản địa."},{"en":"Many indigenous people protect ancient forests carefully.","vi":"Nhiều người bản địa bảo vệ những khu rừng cổ một cách cẩn thận."}]', '[]', NULL, '/ɪnˈdɪdʒənəs ˈpiːpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 61, 'indigenous population', 'dân số bản địa', 'adj + n', '[{"en":"The indigenous population declined sharply after colonization.","vi":"Dân số bản địa giảm mạnh sau quá trình thực dân hóa."},{"en":"Researchers studied the health of the indigenous population.","vi":"Các nhà nghiên cứu nghiên cứu sức khỏe của dân số bản địa."},{"en":"The indigenous population maintains its own distinct language.","vi":"Dân số bản địa duy trì ngôn ngữ riêng biệt của mình."}]', '[]', NULL, '/ɪnˈdɪdʒənəs ˌpɑːpjəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 62, 'individual behavior', 'hành vi cá nhân', 'adj + n', '[{"en":"Psychologists study how culture shapes individual behavior.","vi":"Nhà tâm lý học nghiên cứu cách văn hóa định hình hành vi cá nhân."},{"en":"Individual behavior can change dramatically under group pressure.","vi":"Hành vi cá nhân có thể thay đổi mạnh dưới áp lực nhóm."},{"en":"The survey measured individual behavior toward saving money.","vi":"Khảo sát đo lường hành vi cá nhân đối với việc tiết kiệm tiền."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl bɪˈheɪvjər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 63, 'individual case', 'trường hợp riêng lẻ', 'adj + n', '[{"en":"Each individual case must be reviewed on its own merits.","vi":"Mỗi trường hợp riêng lẻ phải được xem xét theo giá trị của nó."},{"en":"The doctor examined every individual case very carefully.","vi":"Bác sĩ kiểm tra từng trường hợp riêng lẻ rất cẩn thận."},{"en":"Outcomes vary widely from one individual case to another.","vi":"Kết quả thay đổi rất nhiều từ trường hợp riêng lẻ này sang trường hợp khác."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl keɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 64, 'individual characteristics', 'đặc điểm cá nhân', 'adj + n', '[{"en":"Teachers should consider the individual characteristics of students.","vi":"Giáo viên nên xem xét đặc điểm cá nhân của học sinh."},{"en":"The study compared individual characteristics across two groups.","vi":"Nghiên cứu so sánh đặc điểm cá nhân giữa hai nhóm."},{"en":"Individual characteristics influence how people respond to stress.","vi":"Đặc điểm cá nhân ảnh hưởng đến cách người ta phản ứng với căng thẳng."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ˌkerəktəˈrɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 65, 'individual choice', 'lựa chọn cá nhân', 'adj + n', '[{"en":"Voting is an individual choice protected by the constitution.","vi":"Bỏ phiếu là một lựa chọn cá nhân được hiến pháp bảo vệ."},{"en":"The policy respects individual choice in healthcare decisions.","vi":"Chính sách tôn trọng lựa chọn cá nhân trong các quyết định y tế."},{"en":"Diet is ultimately a matter of individual choice.","vi":"Chế độ ăn rốt cuộc là vấn đề của lựa chọn cá nhân."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl tʃɔɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 66, 'individual component', 'thành phần riêng lẻ', 'adj + n', '[{"en":"Engineers tested each individual component before assembly.","vi":"Kỹ sư kiểm tra từng thành phần riêng lẻ trước khi lắp ráp."},{"en":"Every individual component of the engine was replaced.","vi":"Mỗi thành phần riêng lẻ của động cơ đã được thay thế."},{"en":"The report breaks the system into each individual component.","vi":"Báo cáo chia hệ thống thành từng thành phần riêng lẻ."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl kəmˈpoʊnənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 67, 'individual differences', 'sự khác biệt cá nhân', 'adj + n', '[{"en":"The study highlights individual differences in learning speed.","vi":"Nghiên cứu nêu bật sự khác biệt cá nhân về tốc độ học."},{"en":"Individual differences make a one-size-fits-all approach unwise.","vi":"Sự khác biệt cá nhân khiến cách tiếp cận chung cho mọi người là không khôn ngoan."},{"en":"Teachers must respect individual differences among their students.","vi":"Giáo viên phải tôn trọng sự khác biệt cá nhân giữa học sinh."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ˈdɪfərənsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 68, 'individual element', 'yếu tố riêng lẻ', 'adj + n', '[{"en":"Each individual element of the design serves a clear purpose.","vi":"Mỗi yếu tố riêng lẻ của thiết kế phục vụ một mục đích rõ ràng."},{"en":"Analysts examined every individual element of the contract.","vi":"Các nhà phân tích xem xét từng yếu tố riêng lẻ của hợp đồng."},{"en":"Removing one individual element changed the whole result.","vi":"Loại bỏ một yếu tố riêng lẻ đã thay đổi toàn bộ kết quả."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 69, 'individual experience', 'trải nghiệm cá nhân', 'adj + n', '[{"en":"Every learner brings a unique individual experience to class.","vi":"Mỗi người học mang một trải nghiệm cá nhân riêng vào lớp."},{"en":"The book draws on the author''s individual experience abroad.","vi":"Cuốn sách dựa trên trải nghiệm cá nhân của tác giả ở nước ngoài."},{"en":"Individual experience strongly shapes how we view the world.","vi":"Trải nghiệm cá nhân định hình mạnh mẽ cách chúng ta nhìn thế giới."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ɪkˈspɪriəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 70, 'individual interests', 'lợi ích cá nhân', 'adj + n', '[{"en":"Good leaders balance individual interests with the common good.","vi":"Lãnh đạo giỏi cân bằng lợi ích cá nhân với lợi ích chung."},{"en":"Sometimes individual interests conflict with team goals.","vi":"Đôi khi lợi ích cá nhân xung đột với mục tiêu của nhóm."},{"en":"The policy tries to protect individual interests fairly.","vi":"Chính sách cố gắng bảo vệ lợi ích cá nhân một cách công bằng."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ˈɪntrəsts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 71, 'individual item', 'món đồ riêng lẻ', 'adj + n', '[{"en":"The cashier scanned each individual item at the register.","vi":"Nhân viên thu ngân quét từng món đồ riêng lẻ tại quầy."},{"en":"Every individual item in the collection was carefully labeled.","vi":"Mỗi món đồ riêng lẻ trong bộ sưu tập được dán nhãn cẩn thận."},{"en":"The price of each individual item is listed clearly.","vi":"Giá của từng món đồ riêng lẻ được niêm yết rõ ràng."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ˈaɪtəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 72, 'individual needs', 'nhu cầu cá nhân', 'adj + n', '[{"en":"The program is designed around each student''s individual needs.","vi":"Chương trình được thiết kế quanh nhu cầu cá nhân của mỗi học sinh."},{"en":"Good care must respond to the individual needs of patients.","vi":"Chăm sóc tốt phải đáp ứng nhu cầu cá nhân của bệnh nhân."},{"en":"Teachers adapt their lessons to meet individual needs.","vi":"Giáo viên điều chỉnh bài giảng để đáp ứng nhu cầu cá nhân."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl niːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 73, 'individual response', 'phản ứng cá nhân', 'adj + n', '[{"en":"The drug''s individual response varies from person to person.","vi":"Phản ứng cá nhân với thuốc thay đổi tùy từng người."},{"en":"Researchers recorded each individual response to the survey.","vi":"Các nhà nghiên cứu ghi lại từng phản ứng cá nhân với khảo sát."},{"en":"Individual response to therapy can be hard to predict.","vi":"Phản ứng cá nhân với liệu pháp có thể khó dự đoán."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl rɪˈspɑːns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 74, 'individual responsibility', 'trách nhiệm cá nhân', 'adj + n', '[{"en":"Recycling depends partly on individual responsibility at home.","vi":"Việc tái chế phụ thuộc một phần vào trách nhiệm cá nhân ở nhà."},{"en":"The campaign stresses individual responsibility for public health.","vi":"Chiến dịch nhấn mạnh trách nhiệm cá nhân đối với sức khỏe cộng đồng."},{"en":"Safe driving is a matter of individual responsibility.","vi":"Lái xe an toàn là vấn đề của trách nhiệm cá nhân."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl rɪˌspɑːnsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 75, 'individual rights', 'quyền cá nhân', 'adj + n', '[{"en":"The constitution protects the individual rights of citizens.","vi":"Hiến pháp bảo vệ quyền cá nhân của công dân."},{"en":"Courts must balance individual rights against public safety.","vi":"Tòa án phải cân bằng quyền cá nhân với an toàn công cộng."},{"en":"Freedom of speech is a fundamental individual right.","vi":"Tự do ngôn luận là một quyền cá nhân cơ bản."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl raɪts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 76, 'individual variable', 'biến số cá nhân', 'adj + n', '[{"en":"The model adjusts for each individual variable in the dataset.","vi":"Mô hình điều chỉnh cho từng biến số cá nhân trong bộ dữ liệu."},{"en":"Analysts tested how each individual variable affects the result.","vi":"Các nhà phân tích kiểm tra cách từng biến số cá nhân ảnh hưởng kết quả."},{"en":"An individual variable may have little impact on its own.","vi":"Một biến số cá nhân có thể ít tác động khi đứng riêng."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ˈveriəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 77, 'individual variation', 'sự biến thiên cá nhân', 'adj + n', '[{"en":"There is wide individual variation in how people learn.","vi":"Có sự biến thiên cá nhân lớn về cách người ta học."},{"en":"Individual variation in metabolism affects weight loss results.","vi":"Sự biến thiên cá nhân về trao đổi chất ảnh hưởng kết quả giảm cân."},{"en":"The data showed considerable individual variation in scores.","vi":"Dữ liệu cho thấy sự biến thiên cá nhân đáng kể về điểm số."}]', '[]', NULL, '/ˌɪndɪˈvɪdʒuəl ˌveriˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 78, 'industrial capitalism', 'chủ nghĩa tư bản công nghiệp', 'adj + n', '[{"en":"Industrial capitalism transformed cities during the nineteenth century.","vi":"Chủ nghĩa tư bản công nghiệp biến đổi các thành phố trong thế kỷ mười chín."},{"en":"Factories were central to the rise of industrial capitalism.","vi":"Nhà máy là trung tâm của sự trỗi dậy của chủ nghĩa tư bản công nghiệp."},{"en":"Historians debate the social cost of industrial capitalism.","vi":"Các sử gia tranh luận về cái giá xã hội của chủ nghĩa tư bản công nghiệp."}]', '[]', NULL, '/ɪnˈdʌstriəl ˈkæpɪtəlɪzəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 79, 'industrial country', 'quốc gia công nghiệp', 'adj + n', '[{"en":"An industrial country relies heavily on manufacturing for income.","vi":"Một quốc gia công nghiệp phụ thuộc nhiều vào sản xuất để có thu nhập."},{"en":"Pollution remains a serious problem in many industrial countries.","vi":"Ô nhiễm vẫn là vấn đề nghiêm trọng ở nhiều quốc gia công nghiệp."},{"en":"An industrial country usually has a large skilled workforce.","vi":"Một quốc gia công nghiệp thường có lực lượng lao động lành nghề lớn."}]', '[]', NULL, '/ɪnˈdʌstriəl ˈkʌntri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 80, 'industrial development', 'phát triển công nghiệp', 'adj + n', '[{"en":"Industrial development brought new jobs to the rural region.","vi":"Phát triển công nghiệp mang lại việc làm mới cho vùng nông thôn."},{"en":"Rapid industrial development can harm the local environment.","vi":"Phát triển công nghiệp nhanh có thể gây hại cho môi trường địa phương."},{"en":"The government invested heavily in industrial development.","vi":"Chính phủ đầu tư mạnh vào phát triển công nghiệp."}]', '[]', NULL, '/ɪnˈdʌstriəl dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 81, 'industrial production', 'sản xuất công nghiệp', 'adj + n', '[{"en":"Industrial production rose sharply after the new factory opened.","vi":"Sản xuất công nghiệp tăng mạnh sau khi nhà máy mới mở."},{"en":"The recession caused industrial production to fall steeply.","vi":"Suy thoái khiến sản xuất công nghiệp giảm mạnh."},{"en":"Automation has greatly increased industrial production efficiency.","vi":"Tự động hóa đã tăng đáng kể hiệu quả sản xuất công nghiệp."}]', '[]', NULL, '/ɪnˈdʌstriəl prəˈdʌkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 82, 'industrial society', 'xã hội công nghiệp', 'adj + n', '[{"en":"An industrial society depends on machines and steady energy.","vi":"Một xã hội công nghiệp phụ thuộc vào máy móc và năng lượng ổn định."},{"en":"Life in an industrial society changed family structures greatly.","vi":"Cuộc sống trong xã hội công nghiệp thay đổi cấu trúc gia đình rất nhiều."},{"en":"Industrial society created both wealth and new inequalities.","vi":"Xã hội công nghiệp tạo ra cả sự giàu có lẫn bất bình đẳng mới."}]', '[]', NULL, '/ɪnˈdʌstriəl səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 83, 'industrialized country', 'quốc gia công nghiệp hóa', 'adj + n', '[{"en":"An industrialized country often consumes vast amounts of energy.","vi":"Một quốc gia công nghiệp hóa thường tiêu thụ lượng năng lượng khổng lồ."},{"en":"Many industrialized countries face an aging population.","vi":"Nhiều quốc gia công nghiệp hóa đối mặt với dân số già."},{"en":"An industrialized country generally has advanced infrastructure.","vi":"Một quốc gia công nghiệp hóa nhìn chung có hạ tầng tiên tiến."}]', '[]', NULL, '/ɪnˈdʌstriəˌlaɪzd ˈkʌntri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 84, 'industrialized nation', 'quốc gia công nghiệp hóa', 'adj + n', '[{"en":"An industrialized nation produces most goods within its borders.","vi":"Một quốc gia công nghiệp hóa sản xuất phần lớn hàng hóa trong biên giới."},{"en":"Industrialized nations contribute heavily to global emissions.","vi":"Các quốc gia công nghiệp hóa đóng góp lớn vào khí thải toàn cầu."},{"en":"An industrialized nation usually offers strong public services.","vi":"Một quốc gia công nghiệp hóa thường cung cấp dịch vụ công mạnh."}]', '[]', NULL, '/ɪnˈdʌstriəˌlaɪzd ˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 85, 'increasingly linked to', 'ngày càng gắn liền với', 'adv + vpp', '[{"en":"Poor sleep is increasingly linked to long-term health problems.","vi":"Giấc ngủ kém ngày càng gắn liền với các vấn đề sức khỏe lâu dài."},{"en":"Success is increasingly linked to digital skills these days.","vi":"Thành công ngày nay ngày càng gắn liền với kỹ năng số."},{"en":"Rising costs are increasingly linked to global supply issues.","vi":"Chi phí tăng ngày càng gắn liền với vấn đề cung ứng toàn cầu."}]', '[]', NULL, '/ɪnˈkriːsɪŋli lɪŋkt tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 86, 'infinite number', 'vô số', 'adj + n', '[{"en":"There is an infinite number of points on a line.","vi":"Có vô số điểm trên một đường thẳng."},{"en":"An infinite number of combinations is possible with the code.","vi":"Vô số tổ hợp có thể xảy ra với mã này."},{"en":"The universe may contain an infinite number of stars.","vi":"Vũ trụ có thể chứa vô số ngôi sao."}]', '[]', NULL, '/ˈɪnfɪnət ˈnʌmbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 87, 'information flow', 'luồng thông tin', 'n + n', '[{"en":"A clear information flow helps teams make better decisions.","vi":"Luồng thông tin rõ ràng giúp các nhóm ra quyết định tốt hơn."},{"en":"The new system improved information flow between departments.","vi":"Hệ thống mới cải thiện luồng thông tin giữa các phòng ban."},{"en":"Poor information flow often leads to costly mistakes.","vi":"Luồng thông tin kém thường dẫn đến những sai lầm tốn kém."}]', '[]', NULL, '/ˌɪnfərˈmeɪʃən floʊ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 88, 'information gathering', 'việc thu thập thông tin', 'n + n', '[{"en":"Information gathering is the first stage of any research project.","vi":"Việc thu thập thông tin là giai đoạn đầu của mọi dự án nghiên cứu."},{"en":"Careful information gathering reduces the risk of errors.","vi":"Việc thu thập thông tin cẩn thận giảm rủi ro sai sót."},{"en":"Reporters spend much of their time on information gathering.","vi":"Phóng viên dành phần lớn thời gian cho việc thu thập thông tin."}]', '[]', NULL, '/ˌɪnfərˈmeɪʃən ˈɡæðərɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 89, 'information processing', 'việc xử lý thông tin', 'n + n', '[{"en":"The brain is remarkably fast at information processing.","vi":"Bộ não xử lý thông tin nhanh một cách đáng kinh ngạc."},{"en":"Computers excel at the rapid information processing of numbers.","vi":"Máy tính giỏi trong việc xử lý thông tin số liệu nhanh chóng."},{"en":"Stress can slow down our everyday information processing.","vi":"Căng thẳng có thể làm chậm việc xử lý thông tin hằng ngày của ta."}]', '[]', NULL, '/ˌɪnfərˈmeɪʃən ˈprɑːsesɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 90, 'information retrieval', 'việc truy xuất thông tin', 'n + n', '[{"en":"Search engines made information retrieval fast and simple.","vi":"Công cụ tìm kiếm khiến việc truy xuất thông tin nhanh và đơn giản."},{"en":"Good indexing improves information retrieval from large databases.","vi":"Lập chỉ mục tốt cải thiện việc truy xuất thông tin từ cơ sở dữ liệu lớn."},{"en":"The library system streamlined information retrieval for students.","vi":"Hệ thống thư viện tinh giản việc truy xuất thông tin cho sinh viên."}]', '[]', NULL, '/ˌɪnfərˈmeɪʃən rɪˈtriːvəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 91, 'information sharing', 'việc chia sẻ thông tin', 'n + n', '[{"en":"Information sharing between agencies improved the emergency response.","vi":"Việc chia sẻ thông tin giữa các cơ quan cải thiện ứng phó khẩn cấp."},{"en":"Open information sharing builds trust within a team.","vi":"Việc chia sẻ thông tin cởi mở xây dựng niềm tin trong nhóm."},{"en":"Privacy rules can limit information sharing across borders.","vi":"Quy định riêng tư có thể hạn chế việc chia sẻ thông tin xuyên biên giới."}]', '[]', NULL, '/ˌɪnfərˈmeɪʃən ˈʃerɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 92, 'informed consent', 'sự đồng ý có hiểu biết', 'adj + n', '[{"en":"Doctors must obtain informed consent before any operation.","vi":"Bác sĩ phải có được sự đồng ý có hiểu biết trước mọi ca mổ."},{"en":"Researchers require informed consent from every participant.","vi":"Các nhà nghiên cứu yêu cầu sự đồng ý có hiểu biết từ mỗi người tham gia."},{"en":"Informed consent means the patient understands the risks involved.","vi":"Sự đồng ý có hiểu biết nghĩa là bệnh nhân hiểu các rủi ro liên quan."}]', '[]', NULL, '/ɪnˈfɔːrmd kənˈsent/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 93, 'initial period', 'giai đoạn ban đầu', 'adj + n', '[{"en":"During the initial period, sales grew slowly but steadily.","vi":"Trong giai đoạn ban đầu, doanh số tăng chậm nhưng đều."},{"en":"The initial period of training is the most demanding.","vi":"Giai đoạn ban đầu của quá trình huấn luyện là khắt khe nhất."},{"en":"After the initial period, the project gained strong momentum.","vi":"Sau giai đoạn ban đầu, dự án có được đà phát triển mạnh."}]', '[]', NULL, '/ɪˈnɪʃəl ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 94, 'initial phase', 'pha ban đầu', 'adj + n', '[{"en":"The initial phase of the study focused on collecting data.","vi":"Pha ban đầu của nghiên cứu tập trung vào thu thập dữ liệu."},{"en":"Funding was secured during the initial phase of the plan.","vi":"Nguồn vốn được đảm bảo trong pha ban đầu của kế hoạch."},{"en":"The initial phase of construction took almost six months.","vi":"Pha ban đầu của việc xây dựng mất gần sáu tháng."}]', '[]', NULL, '/ɪˈnɪʃəl feɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 95, 'initial position', 'vị trí ban đầu', 'adj + n', '[{"en":"The runner returned to her initial position before the race.","vi":"Vận động viên trở về vị trí ban đầu của mình trước cuộc đua."},{"en":"We measured the object''s movement from its initial position.","vi":"Chúng tôi đo chuyển động của vật từ vị trí ban đầu của nó."},{"en":"The negotiator softened from his initial position over time.","vi":"Người đàm phán dần nới lỏng từ vị trí ban đầu của mình."}]', '[]', NULL, '/ɪˈnɪʃəl pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 96, 'initial research', 'nghiên cứu ban đầu', 'adj + n', '[{"en":"Initial research suggested the treatment was both safe and effective.","vi":"Nghiên cứu ban đầu cho thấy phương pháp điều trị vừa an toàn vừa hiệu quả."},{"en":"The team published its initial research findings last spring.","vi":"Nhóm công bố kết quả nghiên cứu ban đầu vào mùa xuân năm ngoái."},{"en":"Initial research often raises more questions than answers.","vi":"Nghiên cứu ban đầu thường đặt ra nhiều câu hỏi hơn là câu trả lời."}]', '[]', NULL, '/ɪˈnɪʃəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 97, 'initial stage', 'giai đoạn đầu', 'adj + n', '[{"en":"In the initial stage, the disease shows almost no symptoms.","vi":"Ở giai đoạn đầu, căn bệnh hầu như không có triệu chứng."},{"en":"The initial stage of the plan involves gathering feedback.","vi":"Giai đoạn đầu của kế hoạch bao gồm thu thập phản hồi."},{"en":"Mistakes made in the initial stage are costly to fix.","vi":"Sai lầm ở giai đoạn đầu rất tốn kém để sửa chữa."}]', '[]', NULL, '/ɪˈnɪʃəl steɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 98, 'institutional arrangement', 'sự sắp xếp về thể chế', 'adj + n', '[{"en":"A stable institutional arrangement supports long-term economic growth.","vi":"Một sự sắp xếp thể chế ổn định hỗ trợ tăng trưởng kinh tế dài hạn."},{"en":"The reform changed the institutional arrangement of local government.","vi":"Cuộc cải cách thay đổi sự sắp xếp thể chế của chính quyền địa phương."},{"en":"Researchers compared institutional arrangements across several countries.","vi":"Các nhà nghiên cứu so sánh sự sắp xếp thể chế giữa nhiều quốc gia."}]', '[]', NULL, '/ˌɪnstɪˈtuːʃənəl əˈreɪndʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 99, 'institutional context', 'bối cảnh thể chế', 'adj + n', '[{"en":"Policies must be understood within their institutional context.","vi":"Các chính sách phải được hiểu trong bối cảnh thể chế của chúng."},{"en":"The institutional context shapes how reforms are carried out.","vi":"Bối cảnh thể chế định hình cách các cải cách được thực hiện."},{"en":"Behavior differs greatly depending on the institutional context.","vi":"Hành vi khác nhau rất nhiều tùy theo bối cảnh thể chế."}]', '[]', NULL, '/ˌɪnstɪˈtuːʃənəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 100, 'institutional framework', 'khuôn khổ thể chế', 'adj + n', '[{"en":"A strong institutional framework is needed to enforce the new law.","vi":"Cần một khuôn khổ thể chế vững mạnh để thực thi luật mới."},{"en":"The treaty established an institutional framework for cooperation.","vi":"Hiệp ước thiết lập một khuôn khổ thể chế cho hợp tác."},{"en":"Without a clear institutional framework, reforms often fail.","vi":"Thiếu khuôn khổ thể chế rõ ràng, các cải cách thường thất bại."}]', '[]', NULL, '/ˌɪnstɪˈtuːʃənəl ˈfreɪmwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 101, 'institutional structure', 'cấu trúc thể chế', 'adj + n', '[{"en":"The institutional structure of the university is quite complex.","vi":"Cấu trúc thể chế của trường đại học khá phức tạp."},{"en":"Reforms aim to simplify the existing institutional structure.","vi":"Các cải cách nhằm đơn giản hóa cấu trúc thể chế hiện có."},{"en":"The institutional structure determines how decisions are made.","vi":"Cấu trúc thể chế quyết định cách các quyết định được đưa ra."}]', '[]', NULL, '/ˌɪnstɪˈtuːʃənəl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 102, 'institutional support', 'sự hỗ trợ từ thể chế', 'adj + n', '[{"en":"The project succeeded thanks to strong institutional support.","vi":"Dự án thành công nhờ sự hỗ trợ thể chế mạnh mẽ."},{"en":"Students benefit from institutional support such as scholarships.","vi":"Sinh viên hưởng lợi từ sự hỗ trợ thể chế như học bổng."},{"en":"Without institutional support, the initiative quickly collapsed.","vi":"Thiếu sự hỗ trợ thể chế, sáng kiến nhanh chóng sụp đổ."}]', '[]', NULL, '/ˌɪnstɪˈtuːʃənəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 103, 'integral part', 'bộ phận không thể thiếu', 'adj + n', '[{"en":"Music is an integral part of the school''s daily routine.","vi":"Âm nhạc là một bộ phận không thể thiếu trong sinh hoạt hằng ngày của trường."},{"en":"Feedback is an integral part of the learning process.","vi":"Phản hồi là một bộ phận không thể thiếu của quá trình học."},{"en":"Trust is an integral part of any successful partnership.","vi":"Niềm tin là một bộ phận không thể thiếu của mọi quan hệ đối tác thành công."}]', '[]', NULL, '/ˈɪntɪɡrəl pɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 104, 'integrated approach', 'cách tiếp cận tích hợp', 'adj + n', '[{"en":"An integrated approach combines several methods into one plan.","vi":"Một cách tiếp cận tích hợp kết hợp nhiều phương pháp vào một kế hoạch."},{"en":"The clinic uses an integrated approach to patient care.","vi":"Phòng khám dùng cách tiếp cận tích hợp trong chăm sóc bệnh nhân."},{"en":"An integrated approach to teaching links theory with practice.","vi":"Cách tiếp cận tích hợp trong giảng dạy kết nối lý thuyết với thực hành."}]', '[]', NULL, '/ˈɪntɪˌɡreɪtɪd əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 105, 'integrated system', 'hệ thống tích hợp', 'adj + n', '[{"en":"The company built an integrated system to manage all orders.","vi":"Công ty xây dựng một hệ thống tích hợp để quản lý mọi đơn hàng."},{"en":"An integrated system connects billing, shipping, and support together.","vi":"Một hệ thống tích hợp kết nối thanh toán, vận chuyển và hỗ trợ với nhau."},{"en":"The hospital introduced an integrated system for patient records.","vi":"Bệnh viện giới thiệu một hệ thống tích hợp cho hồ sơ bệnh nhân."}]', '[]', NULL, '/ˈɪntɪˌɡreɪtɪd ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 106, 'intellectual property', 'sở hữu trí tuệ', 'adj + n', '[{"en":"Patents protect a company''s valuable intellectual property.","vi":"Bằng sáng chế bảo vệ sở hữu trí tuệ quý giá của công ty."},{"en":"Copying software without permission violates intellectual property rights.","vi":"Sao chép phần mềm không phép vi phạm quyền sở hữu trí tuệ."},{"en":"Universities increasingly value the intellectual property they create.","vi":"Các trường đại học ngày càng coi trọng sở hữu trí tuệ mà họ tạo ra."}]', '[]', NULL, '/ˌɪntəˈlektʃuəl ˈprɑːpərti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 107, 'intellectual work', 'công việc trí óc', 'adj + n', '[{"en":"Writing a thesis demands sustained intellectual work over many months.","vi":"Viết luận án đòi hỏi công việc trí óc bền bỉ trong nhiều tháng."},{"en":"Universities value intellectual work that pushes the boundaries of knowledge.","vi":"Các trường đại học coi trọng công việc trí óc mở rộng ranh giới tri thức."},{"en":"Good sleep helps the brain handle demanding intellectual work each day.","vi":"Ngủ đủ giúp não xử lý công việc trí óc nặng nhọc mỗi ngày."}]', '[]', NULL, '/ˌɪntəˈlektʃuəl ˈwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 108, 'intensive study', 'việc học tập chuyên sâu', 'adj + n', '[{"en":"The topic deserves intensive study before any firm conclusions are drawn.","vi":"Chủ đề này xứng đáng được nghiên cứu chuyên sâu trước khi kết luận."},{"en":"Months of intensive study prepared her for the final examination.","vi":"Nhiều tháng học tập chuyên sâu đã chuẩn bị cho cô kỳ thi cuối."},{"en":"Intensive study of the data revealed several unexpected patterns.","vi":"Việc nghiên cứu chuyên sâu dữ liệu đã hé lộ vài mẫu hình bất ngờ."}]', '[]', NULL, '/ɪnˈtensɪv ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 109, 'interested party', 'bên liên quan, bên có quyền lợi', 'adj + n', '[{"en":"Every interested party was invited to comment on the proposal.","vi":"Mọi bên liên quan đều được mời góp ý cho đề xuất."},{"en":"The court must consider the views of each interested party.","vi":"Tòa án phải xem xét quan điểm của từng bên liên quan."},{"en":"As an interested party, the company joined the public consultation.","vi":"Là một bên có quyền lợi, công ty đã tham gia buổi tham vấn công khai."}]', '[]', NULL, '/ˈɪntrəstɪd ˈpɑːrti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 110, 'internal affairs', 'công việc nội bộ', 'adj + n', '[{"en":"Many states reject foreign interference in their internal affairs.","vi":"Nhiều quốc gia phản đối sự can thiệp nước ngoài vào công việc nội bộ."},{"en":"The minister handles the country''s internal affairs and security policy.","vi":"Vị bộ trưởng phụ trách công việc nội bộ và chính sách an ninh."},{"en":"Critics said the report meddled in the firm''s internal affairs.","vi":"Giới phê bình nói báo cáo can thiệp vào công việc nội bộ của hãng."}]', '[]', NULL, '/ɪnˈtɜːrnəl əˈferz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 111, 'internal conflict', 'xung đột nội bộ', 'adj + n', '[{"en":"Years of internal conflict weakened the organization from within.","vi":"Nhiều năm xung đột nội bộ đã làm suy yếu tổ chức từ bên trong."},{"en":"The novel explores the hero''s internal conflict over loyalty.","vi":"Cuốn tiểu thuyết khám phá xung đột nội tâm của người hùng về lòng trung thành."},{"en":"Internal conflict among managers delayed the important decision.","vi":"Xung đột nội bộ giữa các quản lý đã trì hoãn quyết định quan trọng."}]', '[]', NULL, '/ɪnˈtɜːrnəl ˈkɑːnflɪkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 112, 'internal control', 'kiểm soát nội bộ', 'adj + n', '[{"en":"Strong internal control helps prevent fraud within a company.","vi":"Kiểm soát nội bộ chặt chẽ giúp ngăn chặn gian lận trong công ty."},{"en":"Auditors examine whether internal control systems work effectively.","vi":"Kiểm toán viên kiểm tra xem hệ thống kiểm soát nội bộ có hiệu quả không."},{"en":"Weak internal control allowed the errors to go unnoticed for months.","vi":"Kiểm soát nội bộ yếu khiến các lỗi không bị phát hiện trong nhiều tháng."}]', '[]', NULL, '/ɪnˈtɜːrnəl kənˈtroʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 113, 'internal market', 'thị trường nội địa', 'adj + n', '[{"en":"The reforms aimed to create a single internal market for goods.","vi":"Các cải cách nhằm tạo ra một thị trường nội địa thống nhất cho hàng hóa."},{"en":"Tariffs were removed to strengthen the region''s internal market.","vi":"Thuế quan được bãi bỏ để củng cố thị trường nội địa của khu vực."},{"en":"A growing internal market gives local firms more room to expand.","vi":"Thị trường nội địa đang lớn mạnh cho doanh nghiệp địa phương thêm dư địa mở rộng."}]', '[]', NULL, '/ɪnˈtɜːrnəl ˈmɑːrkɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 114, 'internal organ', 'nội tạng, cơ quan nội tạng', 'adj + n', '[{"en":"The scan revealed damage to several internal organs.","vi":"Ảnh chụp cho thấy tổn thương ở vài cơ quan nội tạng."},{"en":"Surgeons must work carefully near delicate internal organs.","vi":"Bác sĩ phẫu thuật phải thao tác cẩn thận gần các nội tạng mong manh."},{"en":"The liver is an internal organ that filters toxins from blood.","vi":"Gan là một cơ quan nội tạng lọc độc tố khỏi máu."}]', '[]', NULL, '/ɪnˈtɜːrnəl ˈɔːrɡən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 115, 'internal structure', 'cấu trúc bên trong', 'adj + n', '[{"en":"Microscopes let scientists study the internal structure of cells.","vi":"Kính hiển vi cho phép nhà khoa học nghiên cứu cấu trúc bên trong tế bào."},{"en":"The essay''s internal structure follows a clear logical order.","vi":"Cấu trúc bên trong của bài luận tuân theo một trật tự logic rõ ràng."},{"en":"Engineers analyzed the internal structure of the damaged bridge.","vi":"Các kỹ sư đã phân tích cấu trúc bên trong của cây cầu hư hỏng."}]', '[]', NULL, '/ɪnˈtɜːrnəl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 116, 'international agreement', 'thỏa thuận quốc tế', 'adj + n', '[{"en":"A new international agreement set limits on carbon emissions.","vi":"Một thỏa thuận quốc tế mới đặt ra giới hạn cho phát thải carbon."},{"en":"Several nations signed the international agreement on trade.","vi":"Nhiều quốc gia đã ký thỏa thuận quốc tế về thương mại."},{"en":"The international agreement took years of careful negotiation.","vi":"Thỏa thuận quốc tế đó mất nhiều năm đàm phán thận trọng."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl əˈɡriːmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 117, 'international body', 'tổ chức quốc tế', 'adj + n', '[{"en":"An international body was created to oversee global health.","vi":"Một tổ chức quốc tế được lập ra để giám sát sức khỏe toàn cầu."},{"en":"Disputes are often referred to a neutral international body.","vi":"Tranh chấp thường được chuyển đến một tổ chức quốc tế trung lập."},{"en":"The international body issued guidelines for member states.","vi":"Tổ chức quốc tế đã ban hành hướng dẫn cho các quốc gia thành viên."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl ˈbɑːdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 118, 'international community', 'cộng đồng quốc tế', 'adj + n', '[{"en":"The international community condemned the violence in strong terms.","vi":"Cộng đồng quốc tế đã lên án mạnh mẽ bạo lực."},{"en":"Climate change requires action from the whole international community.","vi":"Biến đổi khí hậu đòi hỏi hành động từ toàn thể cộng đồng quốc tế."},{"en":"Aid flowed in once the international community recognized the crisis.","vi":"Viện trợ đổ về khi cộng đồng quốc tế thừa nhận cuộc khủng hoảng."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 119, 'international conference', 'hội nghị quốc tế', 'adj + n', '[{"en":"She presented her findings at an international conference in Paris.","vi":"Cô trình bày kết quả tại một hội nghị quốc tế ở Paris."},{"en":"The international conference brought together experts from many fields.","vi":"Hội nghị quốc tế quy tụ các chuyên gia từ nhiều lĩnh vực."},{"en":"Leaders met at an international conference to discuss trade policy.","vi":"Các lãnh đạo gặp nhau tại hội nghị quốc tế để bàn về chính sách thương mại."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl ˈkɑːnfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 120, 'international context', 'bối cảnh quốc tế', 'adj + n', '[{"en":"The policy must be understood within a wider international context.","vi":"Chính sách này phải được hiểu trong một bối cảnh quốc tế rộng hơn."},{"en":"Her study places local events in an international context.","vi":"Nghiên cứu của cô đặt các sự kiện địa phương vào bối cảnh quốc tế."},{"en":"In an international context, these standards vary considerably.","vi":"Trong bối cảnh quốc tế, các tiêu chuẩn này khác nhau đáng kể."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 121, 'international journal', 'tạp chí quốc tế', 'adj + n', '[{"en":"Her paper appeared in a leading international journal last year.","vi":"Bài báo của cô xuất hiện trên một tạp chí quốc tế hàng đầu năm ngoái."},{"en":"Publishing in an international journal boosts a researcher''s reputation.","vi":"Đăng bài trên tạp chí quốc tế nâng cao danh tiếng của nhà nghiên cứu."},{"en":"The international journal reviews each submission very carefully.","vi":"Tạp chí quốc tế đánh giá rất kỹ từng bài gửi đến."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl ˈdʒɜːrnəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 122, 'international organization', 'tổ chức quốc tế', 'adj + n', '[{"en":"The international organization coordinates relief efforts after disasters.","vi":"Tổ chức quốc tế điều phối các nỗ lực cứu trợ sau thảm họa."},{"en":"Many countries fund the international organization through annual dues.","vi":"Nhiều nước tài trợ cho tổ chức quốc tế qua phí thường niên."},{"en":"She works for an international organization focused on human rights.","vi":"Cô làm việc cho một tổ chức quốc tế tập trung vào nhân quyền."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl ˌɔːrɡənəˈzeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 123, 'international treaty', 'hiệp ước quốc tế', 'adj + n', '[{"en":"The international treaty bans the testing of nuclear weapons.","vi":"Hiệp ước quốc tế cấm thử nghiệm vũ khí hạt nhân."},{"en":"Both governments agreed to honor the international treaty fully.","vi":"Cả hai chính phủ đồng ý tuân thủ đầy đủ hiệp ước quốc tế."},{"en":"Ratifying the international treaty required approval from parliament.","vi":"Việc phê chuẩn hiệp ước quốc tế cần sự đồng ý của quốc hội."}]', '[]', NULL, '/ˌɪntərˈnæʃənəl ˈtriːti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 124, 'internet access', 'khả năng truy cập internet', 'n + n', '[{"en":"Rural schools often lack reliable internet access for students.","vi":"Các trường ở nông thôn thường thiếu internet ổn định cho học sinh."},{"en":"Internet access has become essential for everyday academic work.","vi":"Truy cập internet đã trở nên thiết yếu cho việc học hằng ngày."},{"en":"The library provides free internet access to all members.","vi":"Thư viện cung cấp truy cập internet miễn phí cho mọi thành viên."}]', '[]', NULL, '/ˈɪntərnet ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 125, 'interpersonal relationships', 'các mối quan hệ giữa người với người', 'adj + n', '[{"en":"Healthy interpersonal relationships support emotional well-being at work.","vi":"Các mối quan hệ lành mạnh giữa người với người hỗ trợ sức khỏe tinh thần ở nơi làm việc."},{"en":"The course examines how culture shapes interpersonal relationships.","vi":"Khóa học xem xét cách văn hóa định hình các mối quan hệ giữa người với người."},{"en":"Strong interpersonal relationships help teams resolve conflict quickly.","vi":"Các mối quan hệ tốt giữa người với người giúp đội nhóm giải quyết xung đột nhanh."}]', '[]', NULL, '/ˌɪntərˈpɜːrsənəl rɪˈleɪʃənʃɪps/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 126, 'interpersonal skills', 'kỹ năng giao tiếp ứng xử', 'adj + n', '[{"en":"Good interpersonal skills are vital for working in a team.","vi":"Kỹ năng giao tiếp ứng xử tốt rất quan trọng khi làm việc nhóm."},{"en":"Employers increasingly value interpersonal skills over technical knowledge.","vi":"Nhà tuyển dụng ngày càng coi trọng kỹ năng ứng xử hơn kiến thức kỹ thuật."},{"en":"The workshop helps students develop their interpersonal skills.","vi":"Buổi hội thảo giúp sinh viên phát triển kỹ năng giao tiếp ứng xử."}]', '[]', NULL, '/ˌɪntərˈpɜːrsənəl skɪlz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 127, 'interpret data', 'diễn giải dữ liệu', 'v + n', '[{"en":"Researchers must interpret data carefully before drawing conclusions.","vi":"Nhà nghiên cứu phải diễn giải dữ liệu cẩn thận trước khi kết luận."},{"en":"Students learn to interpret data using statistical software.","vi":"Sinh viên học cách diễn giải dữ liệu bằng phần mềm thống kê."},{"en":"It is easy to interpret data wrongly without proper context.","vi":"Rất dễ diễn giải sai dữ liệu nếu thiếu bối cảnh phù hợp."}]', '[]', NULL, '/ɪnˈtɜːrprət ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 128, 'intimate relationship', 'mối quan hệ thân mật', 'adj + n', '[{"en":"The study explores how trust develops in an intimate relationship.","vi":"Nghiên cứu khám phá cách lòng tin phát triển trong một mối quan hệ thân mật."},{"en":"An intimate relationship requires honest and open communication.","vi":"Một mối quan hệ thân mật cần sự giao tiếp trung thực và cởi mở."},{"en":"Stress can place strain on even a strong intimate relationship.","vi":"Căng thẳng có thể gây áp lực ngay cả lên một mối quan hệ thân mật vững chắc."}]', '[]', NULL, '/ˈɪntəmət rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 129, 'intimately connected to', 'gắn bó chặt chẽ với', 'adv + vpp', '[{"en":"Language is intimately connected to the culture that produces it.","vi":"Ngôn ngữ gắn bó chặt chẽ với nền văn hóa đã sản sinh ra nó."},{"en":"Poverty is intimately connected to poor health outcomes worldwide.","vi":"Nghèo đói gắn bó chặt chẽ với các kết quả sức khỏe kém trên toàn cầu."},{"en":"The two theories are intimately connected to one another.","vi":"Hai lý thuyết này gắn bó chặt chẽ với nhau."}]', '[]', NULL, '/ˈɪntəmətli kəˈnektɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 130, 'intrinsic value', 'giá trị nội tại', 'adj + n', '[{"en":"Philosophers debate whether nature has intrinsic value of its own.","vi":"Các triết gia tranh luận liệu thiên nhiên có giá trị nội tại hay không."},{"en":"Education has an intrinsic value beyond future earning power.","vi":"Giáo dục có một giá trị nội tại vượt ra ngoài khả năng kiếm tiền tương lai."},{"en":"The artwork''s intrinsic value does not depend on its price.","vi":"Giá trị nội tại của tác phẩm nghệ thuật không phụ thuộc vào giá tiền."}]', '[]', NULL, '/ɪnˈtrɪnsɪk ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 131, 'introduce legislation', 'đưa ra dự luật', 'v + n', '[{"en":"The government plans to introduce legislation on data privacy.","vi":"Chính phủ dự định đưa ra dự luật về quyền riêng tư dữ liệu."},{"en":"Lawmakers introduce legislation hoping to curb pollution.","vi":"Các nhà lập pháp đưa ra dự luật với hy vọng hạn chế ô nhiễm."},{"en":"It took years to introduce legislation protecting workers'' rights.","vi":"Phải mất nhiều năm để đưa ra dự luật bảo vệ quyền của người lao động."}]', '[]', NULL, '/ˌɪntrəˈduːs ˌledʒɪsˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 132, 'introductory chapter', 'chương mở đầu', 'adj + n', '[{"en":"The introductory chapter outlines the main argument of the book.","vi":"Chương mở đầu phác thảo luận điểm chính của cuốn sách."},{"en":"Read the introductory chapter carefully before the first lecture.","vi":"Hãy đọc kỹ chương mở đầu trước buổi giảng đầu tiên."},{"en":"Her introductory chapter sets out the research questions clearly.","vi":"Chương mở đầu của cô trình bày rõ các câu hỏi nghiên cứu."}]', '[]', NULL, '/ˌɪntrəˈdʌktəri ˈtʃæptər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 133, 'introductory section', 'phần mở đầu', 'adj + n', '[{"en":"The introductory section explains why the topic matters today.","vi":"Phần mở đầu giải thích vì sao chủ đề này quan trọng hiện nay."},{"en":"Keep the introductory section brief and focused on context.","vi":"Hãy giữ phần mở đầu ngắn gọn và tập trung vào bối cảnh."},{"en":"Reviewers often judge a paper from its introductory section.","vi":"Người phản biện thường đánh giá bài báo qua phần mở đầu."}]', '[]', NULL, '/ˌɪntrəˈdʌktəri ˈsekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 134, 'introductory text', 'giáo trình nhập môn', 'adj + n', '[{"en":"This introductory text covers the basics of economics clearly.","vi":"Giáo trình nhập môn này trình bày rõ những điều cơ bản của kinh tế học."},{"en":"Beginners should start with an accessible introductory text.","vi":"Người mới nên bắt đầu với một giáo trình nhập môn dễ hiểu."},{"en":"The introductory text includes exercises at the end of each chapter.","vi":"Giáo trình nhập môn có bài tập ở cuối mỗi chương."}]', '[]', NULL, '/ˌɪntrəˈdʌktəri ˈtekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 135, 'keenly aware', 'ý thức rõ rệt, nhận thức sâu sắc', 'adv + adj', '[{"en":"The author is keenly aware of the limits of her data.","vi":"Tác giả ý thức rõ rệt về những giới hạn trong dữ liệu của mình."},{"en":"Managers must be keenly aware of changing market conditions.","vi":"Các nhà quản lý phải nhận thức sâu sắc về điều kiện thị trường thay đổi."},{"en":"We were keenly aware that time was running short.","vi":"Chúng tôi ý thức rõ rệt rằng thời gian sắp hết."}]', '[]', NULL, '/ˈkiːnli əˈwer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 136, 'key area', 'lĩnh vực then chốt', 'adj + n', '[{"en":"The report identifies three key areas for future research.","vi":"Báo cáo xác định ba lĩnh vực then chốt cho nghiên cứu tương lai."},{"en":"Healthcare is a key area in which reform is urgently needed.","vi":"Y tế là một lĩnh vực then chốt cần cải cách gấp."},{"en":"The course covers several key areas of modern linguistics.","vi":"Khóa học bao quát vài lĩnh vực then chốt của ngôn ngữ học hiện đại."}]', '[]', NULL, '/ˈkiː ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 137, 'key aspect', 'khía cạnh then chốt', 'adj + n', '[{"en":"Motivation is a key aspect of successful language learning.","vi":"Động lực là một khía cạnh then chốt của việc học ngôn ngữ thành công."},{"en":"The essay overlooks one key aspect of the original theory.","vi":"Bài luận bỏ qua một khía cạnh then chốt của lý thuyết gốc."},{"en":"Cost remains a key aspect of any practical solution.","vi":"Chi phí vẫn là một khía cạnh then chốt của bất kỳ giải pháp thực tế nào."}]', '[]', NULL, '/ˈkiː ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 138, 'key characteristic', 'đặc điểm then chốt', 'adj + n', '[{"en":"Flexibility is a key characteristic of a good research design.","vi":"Tính linh hoạt là một đặc điểm then chốt của thiết kế nghiên cứu tốt."},{"en":"The author lists the key characteristics of each social group.","vi":"Tác giả liệt kê các đặc điểm then chốt của từng nhóm xã hội."},{"en":"Transparency is a key characteristic of trustworthy institutions.","vi":"Minh bạch là một đặc điểm then chốt của các thể chế đáng tin."}]', '[]', NULL, '/ˈkiː ˌkærəktəˈrɪstɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 139, 'key component', 'thành phần then chốt', 'adj + n', '[{"en":"Feedback is a key component of the whole learning process.","vi":"Phản hồi là một thành phần then chốt của toàn bộ quá trình học."},{"en":"Trust is a key component of any lasting partnership.","vi":"Lòng tin là một thành phần then chốt của mọi quan hệ đối tác bền vững."},{"en":"Memory is a key component in the model of cognition.","vi":"Trí nhớ là một thành phần then chốt trong mô hình nhận thức."}]', '[]', NULL, '/ˈkiː kəmˈpoʊnənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 140, 'key concept', 'khái niệm then chốt', 'adj + n', '[{"en":"The lecture introduced several key concepts in economics.","vi":"Bài giảng giới thiệu vài khái niệm then chốt trong kinh tế học."},{"en":"Students should master this key concept before moving on.","vi":"Sinh viên nên nắm vững khái niệm then chốt này trước khi học tiếp."},{"en":"Identity is a key concept running through the entire course.","vi":"Bản sắc là một khái niệm then chốt xuyên suốt cả khóa học."}]', '[]', NULL, '/ˈkiː ˈkɑːnsept/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 141, 'key element', 'yếu tố then chốt', 'adj + n', '[{"en":"Clear goals are a key element of effective planning.","vi":"Mục tiêu rõ ràng là một yếu tố then chốt của việc lập kế hoạch hiệu quả."},{"en":"The author treats narrative as a key element of memory.","vi":"Tác giả xem tự sự là một yếu tố then chốt của trí nhớ."},{"en":"Cooperation became a key element in the project''s success.","vi":"Sự hợp tác trở thành một yếu tố then chốt cho thành công của dự án."}]', '[]', NULL, '/ˈkiː ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 142, 'key factor', 'nhân tố then chốt', 'adj + n', '[{"en":"Cost was a key factor in the committee''s final decision.","vi":"Chi phí là một nhân tố then chốt trong quyết định cuối của hội đồng."},{"en":"Climate is a key factor shaping where crops can grow.","vi":"Khí hậu là một nhân tố then chốt quyết định nơi cây trồng có thể phát triển."},{"en":"Motivation is often the key factor behind student success.","vi":"Động lực thường là nhân tố then chốt đằng sau thành công của sinh viên."}]', '[]', NULL, '/ˈkiː ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 143, 'key feature', 'đặc trưng then chốt', 'adj + n', '[{"en":"Symmetry is a key feature of the building''s design.","vi":"Tính đối xứng là một đặc trưng then chốt trong thiết kế tòa nhà."},{"en":"The report highlights the key features of the new system.","vi":"Báo cáo nêu bật các đặc trưng then chốt của hệ thống mới."},{"en":"Repetition is a key feature of the poem''s structure.","vi":"Sự lặp lại là một đặc trưng then chốt trong cấu trúc bài thơ."}]', '[]', NULL, '/ˈkiː ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 144, 'key findings', 'những phát hiện then chốt', 'adj + n', '[{"en":"The abstract summarizes the study''s key findings in a paragraph.","vi":"Phần tóm tắt nêu những phát hiện then chốt của nghiên cứu trong một đoạn."},{"en":"She presented the key findings to the research committee.","vi":"Cô trình bày những phát hiện then chốt cho hội đồng nghiên cứu."},{"en":"The key findings challenge several long-held assumptions.","vi":"Những phát hiện then chốt thách thức vài giả định lâu nay."}]', '[]', NULL, '/ˈkiː ˈfaɪndɪŋz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 145, 'key issue', 'vấn đề then chốt', 'adj + n', '[{"en":"Funding remains the key issue facing the new program.","vi":"Kinh phí vẫn là vấn đề then chốt mà chương trình mới đối mặt."},{"en":"The debate centered on one key issue: data privacy.","vi":"Cuộc tranh luận xoay quanh một vấn đề then chốt: quyền riêng tư dữ liệu."},{"en":"Fairness is a key issue in any discussion of taxation.","vi":"Công bằng là một vấn đề then chốt trong mọi cuộc bàn về thuế."}]', '[]', NULL, '/ˈkiː ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 146, 'key objective', 'mục tiêu then chốt', 'adj + n', '[{"en":"Reducing waste is a key objective of the new policy.","vi":"Giảm lãng phí là một mục tiêu then chốt của chính sách mới."},{"en":"The plan lists three key objectives for the coming year.","vi":"Kế hoạch liệt kê ba mục tiêu then chốt cho năm tới."},{"en":"Improving safety remained the project''s key objective throughout.","vi":"Cải thiện an toàn vẫn là mục tiêu then chốt của dự án từ đầu đến cuối."}]', '[]', NULL, '/ˈkiː əbˈdʒektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 147, 'key player', 'nhân vật chủ chốt', 'adj + n', '[{"en":"The company is a key player in the renewable energy market.","vi":"Công ty là một nhân vật chủ chốt trên thị trường năng lượng tái tạo."},{"en":"She became a key player in the negotiations early on.","vi":"Cô trở thành nhân vật chủ chốt trong các cuộc đàm phán từ sớm."},{"en":"Several key players left the project before it was finished.","vi":"Vài nhân vật chủ chốt đã rời dự án trước khi nó hoàn thành."}]', '[]', NULL, '/ˈkiː ˈpleɪər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 148, 'key policy', 'chính sách then chốt', 'adj + n', '[{"en":"Education reform was the government''s key policy that year.","vi":"Cải cách giáo dục là chính sách then chốt của chính phủ năm đó."},{"en":"The party announced several key policies before the election.","vi":"Đảng công bố vài chính sách then chốt trước cuộc bầu cử."},{"en":"Critics questioned whether the key policy would actually work.","vi":"Giới phê bình nghi ngờ liệu chính sách then chốt có thực sự hiệu quả."}]', '[]', NULL, '/ˈkiː ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 149, 'key principle', 'nguyên tắc then chốt', 'adj + n', '[{"en":"Fairness is a key principle underlying the whole legal system.","vi":"Công bằng là một nguyên tắc then chốt làm nền cho cả hệ thống pháp luật."},{"en":"The chapter explains the key principles of sustainable design.","vi":"Chương này giải thích các nguyên tắc then chốt của thiết kế bền vững."},{"en":"Respect for evidence is a key principle of good science.","vi":"Tôn trọng bằng chứng là một nguyên tắc then chốt của khoa học chân chính."}]', '[]', NULL, '/ˈkiː ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-8-01', 150, 'key role', 'vai trò then chốt', 'adj + n', '[{"en":"Technology plays a key role in modern medical research.","vi":"Công nghệ đóng vai trò then chốt trong nghiên cứu y học hiện đại."},{"en":"Teachers play a key role in shaping young minds.","vi":"Giáo viên đóng vai trò then chốt trong việc hình thành những trí óc trẻ."},{"en":"She played a key role in organizing the conference.","vi":"Cô đóng vai trò then chốt trong việc tổ chức hội nghị."}]', '[]', NULL, '/ˈkiː ˈroʊl/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-9-01', 'colloc-9', 'Cụm học thuật · Nhóm 9', 'Academic Collocation List (Pearson/PTE) — nhóm 9 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 1, 'key source', 'nguồn tư liệu then chốt', 'adj + n', '[{"en":"These letters are a key source for understanding the period.","vi":"Những bức thư này là nguồn tư liệu then chốt để hiểu thời kỳ đó."},{"en":"The census remains a key source of population statistics.","vi":"Cuộc tổng điều tra vẫn là nguồn then chốt cho số liệu dân số."},{"en":"Interviews became a key source of evidence in her study.","vi":"Phỏng vấn trở thành nguồn bằng chứng then chốt trong nghiên cứu của cô."}]', '[]', NULL, '/ˈkiː ˈsɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 2, 'key text', 'văn bản then chốt', 'adj + n', '[{"en":"This essay is a key text in the history of philosophy.","vi":"Tiểu luận này là một văn bản then chốt trong lịch sử triết học."},{"en":"The reading list includes the key texts of the movement.","vi":"Danh mục đọc gồm các văn bản then chốt của trào lưu đó."},{"en":"Scholars still return to this key text again and again.","vi":"Các học giả vẫn liên tục quay lại văn bản then chốt này."}]', '[]', NULL, '/ˈkiː ˈtekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 3, 'key theme', 'chủ đề then chốt', 'adj + n', '[{"en":"Loss is a key theme running through the entire novel.","vi":"Mất mát là một chủ đề then chốt xuyên suốt cả cuốn tiểu thuyết."},{"en":"The conference focused on three key themes in education.","vi":"Hội nghị tập trung vào ba chủ đề then chốt trong giáo dục."},{"en":"Identity emerges as a key theme in her later poems.","vi":"Bản sắc nổi lên như một chủ đề then chốt trong các bài thơ sau này của bà."}]', '[]', NULL, '/ˈkiː ˈθiːm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 4, 'key topic', 'chủ đề then chốt', 'adj + n', '[{"en":"Climate change is a key topic in environmental science courses.","vi":"Biến đổi khí hậu là một chủ đề then chốt trong các môn khoa học môi trường."},{"en":"The seminar will cover several key topics in detail.","vi":"Buổi hội thảo sẽ đề cập chi tiết vài chủ đề then chốt."},{"en":"Inequality has become a key topic in public debate.","vi":"Bất bình đẳng đã trở thành một chủ đề then chốt trong tranh luận công khai."}]', '[]', NULL, '/ˈkiː ˈtɑːpɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 5, 'large majority', 'đa số áp đảo', 'adj + n', '[{"en":"A large majority of students supported the proposed change.","vi":"Một đa số áp đảo sinh viên ủng hộ thay đổi được đề xuất."},{"en":"The bill passed with a large majority in parliament.","vi":"Dự luật được thông qua với đa số áp đảo trong quốc hội."},{"en":"In the survey, a large majority preferred online classes.","vi":"Trong khảo sát, một đa số áp đảo thích các lớp học trực tuyến."}]', '[]', NULL, '/ˈlɑːrdʒ məˈdʒɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 6, 'large percentage', 'tỷ lệ phần trăm lớn', 'adj + n', '[{"en":"A large percentage of the budget goes toward research.","vi":"Một tỷ lệ phần trăm lớn của ngân sách dành cho nghiên cứu."},{"en":"A large percentage of respondents reported feeling stressed.","vi":"Một tỷ lệ phần trăm lớn người trả lời cho biết họ thấy căng thẳng."},{"en":"The disease affects a large percentage of the elderly.","vi":"Căn bệnh ảnh hưởng đến một tỷ lệ phần trăm lớn người cao tuổi."}]', '[]', NULL, '/ˈlɑːrdʒ pərˈsentɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 7, 'large portion', 'phần lớn', 'adj + n', '[{"en":"A large portion of the data was collected during summer.","vi":"Phần lớn dữ liệu đã được thu thập trong mùa hè."},{"en":"She devoted a large portion of the essay to methods.","vi":"Cô dành phần lớn bài luận để nói về phương pháp."},{"en":"A large portion of the population lives near the coast.","vi":"Phần lớn dân số sinh sống gần bờ biển."}]', '[]', NULL, '/ˈlɑːrdʒ ˈpɔːrʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 8, 'large proportion of', 'một phần lớn của', 'adj + n', '[{"en":"A large proportion of income is spent on housing costs.","vi":"Một phần lớn thu nhập được chi cho chi phí nhà ở."},{"en":"A large proportion of the sample came from rural areas.","vi":"Một phần lớn của mẫu khảo sát đến từ vùng nông thôn."},{"en":"A large proportion of energy is still lost as heat.","vi":"Một phần lớn năng lượng vẫn bị thất thoát dưới dạng nhiệt."}]', '[]', NULL, '/ˈlɑːrdʒ prəˈpɔːrʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 9, 'large quantities of', 'một lượng lớn', 'adj + n', '[{"en":"The factory releases large quantities of waste into the river.","vi":"Nhà máy thải một lượng lớn chất thải ra sông."},{"en":"Researchers processed large quantities of survey data by computer.","vi":"Các nhà nghiên cứu xử lý một lượng lớn dữ liệu khảo sát bằng máy tính."},{"en":"Large quantities of food are wasted every single day.","vi":"Một lượng lớn thực phẩm bị lãng phí mỗi ngày."}]', '[]', NULL, '/ˈlɑːrdʒ ˈkwɑːntətiz əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 10, 'large range of', 'phạm vi rộng các', 'adj + n', '[{"en":"The library offers a large range of academic resources.","vi":"Thư viện cung cấp một phạm vi rộng các tài nguyên học thuật."},{"en":"The study covered a large range of age groups.","vi":"Nghiên cứu bao quát một phạm vi rộng các nhóm tuổi."},{"en":"The course explores a large range of historical sources.","vi":"Khóa học khám phá một phạm vi rộng các nguồn sử liệu."}]', '[]', NULL, '/ˈlɑːrdʒ ˈreɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 11, 'largely based on', 'chủ yếu dựa trên', 'adv + vpp', '[{"en":"Her argument is largely based on earlier field research.","vi":"Lập luận của cô chủ yếu dựa trên nghiên cứu thực địa trước đó."},{"en":"The model is largely based on assumptions about behavior.","vi":"Mô hình này chủ yếu dựa trên các giả định về hành vi."},{"en":"The film is largely based on a true historical event.","vi":"Bộ phim chủ yếu dựa trên một sự kiện lịch sử có thật."}]', '[]', NULL, '/ˈlɑːrdʒli ˈbeɪst ɑːn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 12, 'largely confined to', 'phần lớn giới hạn trong', 'adv + vpp', '[{"en":"The disease is largely confined to tropical regions.","vi":"Căn bệnh phần lớn giới hạn trong các vùng nhiệt đới."},{"en":"Early debate was largely confined to a few specialists.","vi":"Cuộc tranh luận ban đầu phần lớn giới hạn trong vài chuyên gia."},{"en":"Such practices were largely confined to rural communities.","vi":"Những tập tục như vậy phần lớn giới hạn trong các cộng đồng nông thôn."}]', '[]', NULL, '/ˈlɑːrdʒli kənˈfaɪnd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 13, 'largely determined by', 'phần lớn được quyết định bởi', 'adv + vpp', '[{"en":"Success is largely determined by effort and preparation.","vi":"Thành công phần lớn được quyết định bởi nỗ lực và sự chuẩn bị."},{"en":"Crop yields are largely determined by rainfall each season.","vi":"Năng suất cây trồng phần lớn được quyết định bởi lượng mưa mỗi mùa."},{"en":"Wages are largely determined by supply and demand.","vi":"Tiền lương phần lớn được quyết định bởi cung và cầu."}]', '[]', NULL, '/ˈlɑːrdʒli dɪˈtɜːrmɪnd baɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 14, 'largely ignored', 'phần lớn bị phớt lờ', 'adv + vpp', '[{"en":"Her early warnings were largely ignored by the authorities.","vi":"Những cảnh báo sớm của cô phần lớn bị giới chức phớt lờ."},{"en":"The issue was largely ignored until the crisis began.","vi":"Vấn đề này phần lớn bị phớt lờ cho đến khi khủng hoảng bắt đầu."},{"en":"These findings were largely ignored by later researchers.","vi":"Những phát hiện này phần lớn bị các nhà nghiên cứu sau phớt lờ."}]', '[]', NULL, '/ˈlɑːrdʒli ɪɡˈnɔːrd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 15, 'largely responsible for', 'phần lớn chịu trách nhiệm cho', 'adv + adj', '[{"en":"Human activity is largely responsible for rising temperatures.","vi":"Hoạt động của con người phần lớn chịu trách nhiệm cho nhiệt độ tăng."},{"en":"Poor planning was largely responsible for the project''s delay.","vi":"Việc lập kế hoạch kém phần lớn chịu trách nhiệm cho sự chậm trễ của dự án."},{"en":"She was largely responsible for the program''s early success.","vi":"Cô phần lớn chịu trách nhiệm cho thành công ban đầu của chương trình."}]', '[]', NULL, '/ˈlɑːrdʒli rɪˈspɑːnsəbəl fər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 16, 'later work', 'công trình về sau', 'adj + n', '[{"en":"His later work shows a clear shift in style.","vi":"Công trình về sau của ông cho thấy một sự thay đổi rõ về phong cách."},{"en":"Her later work builds directly on these early experiments.","vi":"Công trình về sau của cô xây dựng trực tiếp trên những thí nghiệm ban đầu này."},{"en":"Critics often prefer the artist''s later work to her earliest.","vi":"Giới phê bình thường thích công trình về sau của nghệ sĩ hơn các tác phẩm đầu tay."}]', '[]', NULL, '/ˈleɪtər ˈwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 17, 'later writings', 'các trước tác về sau', 'adj + n', '[{"en":"His later writings reveal a more cautious philosophical view.","vi":"Các trước tác về sau của ông bộc lộ một quan điểm triết học thận trọng hơn."},{"en":"Scholars find new themes in her later writings.","vi":"Các học giả tìm thấy những chủ đề mới trong các trước tác về sau của bà."},{"en":"The later writings address questions the early ones avoided.","vi":"Các trước tác về sau giải quyết những câu hỏi mà tác phẩm đầu tránh né."}]', '[]', NULL, '/ˈleɪtər ˈraɪtɪŋz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 18, 'lead to the conclusion', 'dẫn đến kết luận', 'v + n', '[{"en":"These results lead to the conclusion that the method works.","vi":"Những kết quả này dẫn đến kết luận rằng phương pháp có hiệu quả."},{"en":"Such evidence may lead to the conclusion that reform is needed.","vi":"Bằng chứng như vậy có thể dẫn đến kết luận rằng cần cải cách."},{"en":"The data lead to the conclusion that costs are rising.","vi":"Dữ liệu dẫn đến kết luận rằng chi phí đang tăng."}]', '[]', NULL, '/ˈliːd tə ðə kənˈkluːʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 19, 'leading role', 'vai trò dẫn dắt', 'adj + n', '[{"en":"The university played a leading role in the research effort.","vi":"Trường đại học đóng vai trò dẫn dắt trong nỗ lực nghiên cứu."},{"en":"She took a leading role in shaping the new policy.","vi":"Cô đảm nhận vai trò dẫn dắt trong việc định hình chính sách mới."},{"en":"The country has a leading role in regional trade talks.","vi":"Quốc gia này có vai trò dẫn dắt trong các cuộc đàm phán thương mại khu vực."}]', '[]', NULL, '/ˈliːdɪŋ ˈroʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 20, 'learning activity', 'hoạt động học tập', 'adj + n', '[{"en":"Each learning activity is designed to reinforce a key skill.","vi":"Mỗi hoạt động học tập được thiết kế để củng cố một kỹ năng then chốt."},{"en":"Group discussion is a popular learning activity in this class.","vi":"Thảo luận nhóm là một hoạt động học tập phổ biến trong lớp này."},{"en":"Teachers vary learning activities to keep students engaged.","vi":"Giáo viên thay đổi các hoạt động học tập để giữ học sinh hứng thú."}]', '[]', NULL, '/ˈlɜːrnɪŋ ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 21, 'learning difficulties', 'khó khăn trong học tập', 'n + n', '[{"en":"The school offers extra support for children with learning difficulties.","vi":"Trường cung cấp hỗ trợ thêm cho trẻ có khó khăn trong học tập."},{"en":"Early diagnosis of learning difficulties improves later outcomes.","vi":"Chẩn đoán sớm khó khăn trong học tập giúp cải thiện kết quả về sau."},{"en":"Teachers are trained to recognize common learning difficulties.","vi":"Giáo viên được đào tạo để nhận ra các khó khăn học tập thường gặp."}]', '[]', NULL, '/ˈlɜːrnɪŋ ˈdɪfɪkəltiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 22, 'learning environment', 'môi trường học tập', 'n + n', '[{"en":"A safe learning environment helps students take more risks.","vi":"Một môi trường học tập an toàn giúp học sinh dám mạo hiểm hơn."},{"en":"Technology has transformed the modern learning environment.","vi":"Công nghệ đã thay đổi môi trường học tập hiện đại."},{"en":"Teachers work hard to create a positive learning environment.","vi":"Giáo viên nỗ lực tạo ra một môi trường học tập tích cực."}]', '[]', NULL, '/ˈlɜːrnɪŋ ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 23, 'learning objective', 'mục tiêu học tập', 'n + n', '[{"en":"Each lesson begins with a clearly stated learning objective.","vi":"Mỗi bài học bắt đầu với một mục tiêu học tập được nêu rõ."},{"en":"The teacher aligned the activities with the learning objectives.","vi":"Giáo viên đã gắn các hoạt động với mục tiêu học tập."},{"en":"Students should know the learning objectives before they start.","vi":"Học sinh nên biết các mục tiêu học tập trước khi bắt đầu."}]', '[]', NULL, '/ˈlɜːrnɪŋ əbˈdʒektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 24, 'learning outcome', 'kết quả học tập đầu ra', 'n + n', '[{"en":"The course lists its learning outcomes in the syllabus.","vi":"Khóa học liệt kê các kết quả học tập đầu ra trong đề cương."},{"en":"Assessment should match the stated learning outcomes closely.","vi":"Việc đánh giá nên bám sát các kết quả học tập đầu ra đã nêu."},{"en":"Clear learning outcomes help students measure their progress.","vi":"Kết quả học tập đầu ra rõ ràng giúp học sinh đo lường tiến bộ."}]', '[]', NULL, '/ˈlɜːrnɪŋ ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 25, 'learning process', 'quá trình học tập', 'n + n', '[{"en":"Mistakes are a natural part of the learning process.","vi":"Sai lầm là một phần tự nhiên của quá trình học tập."},{"en":"Feedback plays a central role in the learning process.","vi":"Phản hồi đóng vai trò trung tâm trong quá trình học tập."},{"en":"The study examines how emotion shapes the learning process.","vi":"Nghiên cứu xem xét cách cảm xúc định hình quá trình học tập."}]', '[]', NULL, '/ˈlɜːrnɪŋ ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 26, 'learning resources', 'tài nguyên học tập', 'n + n', '[{"en":"The platform offers free learning resources to every student.","vi":"Nền tảng cung cấp tài nguyên học tập miễn phí cho mọi học sinh."},{"en":"Good learning resources can make difficult topics easier.","vi":"Tài nguyên học tập tốt có thể giúp các chủ đề khó trở nên dễ hơn."},{"en":"Teachers create learning resources tailored to their classes.","vi":"Giáo viên tạo ra tài nguyên học tập phù hợp với lớp của mình."}]', '[]', NULL, '/ˈlɜːrnɪŋ ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 27, 'learning strategy', 'chiến lược học tập', 'n + n', '[{"en":"Spacing out review is an effective learning strategy.","vi":"Giãn cách việc ôn tập là một chiến lược học tập hiệu quả."},{"en":"Students benefit from trying several learning strategies.","vi":"Học sinh hưởng lợi khi thử nhiều chiến lược học tập khác nhau."},{"en":"The teacher explained a simple learning strategy for vocabulary.","vi":"Giáo viên giải thích một chiến lược học tập đơn giản cho từ vựng."}]', '[]', NULL, '/ˈlɜːrnɪŋ ˈstrætədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 28, 'legal action', 'hành động pháp lý', 'adj + n', '[{"en":"The company threatened legal action against its former partner.","vi":"Công ty đe dọa hành động pháp lý chống lại đối tác cũ."},{"en":"Victims may take legal action to recover their losses.","vi":"Nạn nhân có thể tiến hành hành động pháp lý để đòi lại tổn thất."},{"en":"Legal action was avoided when both sides reached a settlement.","vi":"Hành động pháp lý được tránh khi hai bên đạt được thỏa thuận."}]', '[]', NULL, '/ˈliːɡəl ˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 29, 'legal basis', 'cơ sở pháp lý', 'adj + n', '[{"en":"The decision lacked any clear legal basis at the time.","vi":"Quyết định khi đó thiếu một cơ sở pháp lý rõ ràng."},{"en":"The treaty provides the legal basis for the new rules.","vi":"Hiệp ước cung cấp cơ sở pháp lý cho các quy định mới."},{"en":"Lawyers questioned the legal basis of the government''s order.","vi":"Các luật sư đặt nghi vấn về cơ sở pháp lý của lệnh chính phủ."}]', '[]', NULL, '/ˈliːɡəl ˈbeɪsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 30, 'legal framework', 'khung pháp lý', 'adj + n', '[{"en":"A clear legal framework is needed to regulate the industry.","vi":"Cần một khung pháp lý rõ ràng để điều chỉnh ngành công nghiệp này."},{"en":"The new legal framework protects consumers more effectively.","vi":"Khung pháp lý mới bảo vệ người tiêu dùng hiệu quả hơn."},{"en":"Companies must operate within the existing legal framework.","vi":"Các công ty phải hoạt động trong khung pháp lý hiện hành."}]', '[]', NULL, '/ˈliːɡəl ˈfreɪmwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 31, 'legal issue', 'vấn đề pháp lý', 'adj + n', '[{"en":"The contract raised several complex legal issues for the team.","vi":"Hợp đồng đặt ra vài vấn đề pháp lý phức tạp cho nhóm."},{"en":"Privacy has become a major legal issue in technology.","vi":"Quyền riêng tư đã trở thành một vấn đề pháp lý lớn trong công nghệ."},{"en":"The lawyer advised her on a tricky legal issue.","vi":"Luật sư tư vấn cho cô về một vấn đề pháp lý hóc búa."}]', '[]', NULL, '/ˈliːɡəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 32, 'legal obligation', 'nghĩa vụ pháp lý', 'adj + n', '[{"en":"Employers have a legal obligation to ensure workplace safety.","vi":"Người sử dụng lao động có nghĩa vụ pháp lý bảo đảm an toàn nơi làm việc."},{"en":"The company met its legal obligations under the contract.","vi":"Công ty đã thực hiện các nghĩa vụ pháp lý theo hợp đồng."},{"en":"Paying taxes is a legal obligation for every citizen.","vi":"Nộp thuế là một nghĩa vụ pháp lý của mọi công dân."}]', '[]', NULL, '/ˈliːɡəl ˌɑːblɪˈɡeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 33, 'legal position', 'tình trạng pháp lý, lập trường pháp lý', 'adj + n', '[{"en":"The lawyer explained the company''s legal position in detail.","vi":"Luật sư giải thích chi tiết tình trạng pháp lý của công ty."},{"en":"Their legal position weakened once new evidence appeared.","vi":"Lập trường pháp lý của họ yếu đi khi bằng chứng mới xuất hiện."},{"en":"We should clarify our legal position before signing anything.","vi":"Chúng ta nên làm rõ tình trạng pháp lý trước khi ký bất cứ điều gì."}]', '[]', NULL, '/ˈliːɡəl pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 34, 'legal proceedings', 'thủ tục tố tụng', 'adj + n', '[{"en":"Legal proceedings began after the two firms failed to agree.","vi":"Thủ tục tố tụng bắt đầu sau khi hai công ty không thể thỏa thuận."},{"en":"The legal proceedings could last for several years.","vi":"Thủ tục tố tụng có thể kéo dài nhiều năm."},{"en":"She was advised not to comment during the legal proceedings.","vi":"Cô được khuyên không bình luận trong quá trình tố tụng."}]', '[]', NULL, '/ˈliːɡəl prəˈsiːdɪŋz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 35, 'legal protection', 'sự bảo vệ pháp lý', 'adj + n', '[{"en":"The law gives strong legal protection to tenants.","vi":"Luật trao sự bảo vệ pháp lý mạnh mẽ cho người thuê nhà."},{"en":"Workers demanded better legal protection against unfair dismissal.","vi":"Người lao động đòi hỏi sự bảo vệ pháp lý tốt hơn trước sa thải bất công."},{"en":"Copyright offers legal protection for original creative work.","vi":"Bản quyền cung cấp sự bảo vệ pháp lý cho sáng tác gốc."}]', '[]', NULL, '/ˈliːɡəl prəˈtekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 36, 'legal requirement', 'yêu cầu pháp lý', 'adj + n', '[{"en":"Wearing a seatbelt is a legal requirement in most countries.","vi":"Thắt dây an toàn là một yêu cầu pháp lý ở hầu hết các nước."},{"en":"The firm must meet every legal requirement before opening.","vi":"Công ty phải đáp ứng mọi yêu cầu pháp lý trước khi mở cửa."},{"en":"Reporting income is a legal requirement for all businesses.","vi":"Khai báo thu nhập là một yêu cầu pháp lý đối với mọi doanh nghiệp."}]', '[]', NULL, '/ˈliːɡəl rɪˈkwaɪrmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 37, 'legal right', 'quyền hợp pháp', 'adj + n', '[{"en":"Every citizen has the legal right to a fair trial.","vi":"Mọi công dân đều có quyền hợp pháp được xét xử công bằng."},{"en":"Workers have a legal right to safe working conditions.","vi":"Người lao động có quyền hợp pháp được làm việc trong điều kiện an toàn."},{"en":"The reform extended legal rights to more groups.","vi":"Cuộc cải cách mở rộng quyền hợp pháp cho nhiều nhóm hơn."}]', '[]', NULL, '/ˈliːɡəl ˈraɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 38, 'legal rule', 'quy tắc pháp lý', 'adj + n', '[{"en":"A clear legal rule helps judges decide similar cases.","vi":"Một quy tắc pháp lý rõ ràng giúp thẩm phán xử các vụ tương tự."},{"en":"The new legal rule applies to all imported goods.","vi":"Quy tắc pháp lý mới áp dụng cho mọi hàng hóa nhập khẩu."},{"en":"Courts sometimes reinterpret an old legal rule over time.","vi":"Tòa án đôi khi diễn giải lại một quy tắc pháp lý cũ theo thời gian."}]', '[]', NULL, '/ˈliːɡəl ˈruːl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 39, 'legal status', 'tư cách pháp lý', 'adj + n', '[{"en":"The treaty clarifies the legal status of refugees in the country.","vi":"Hiệp ước làm rõ tư cách pháp lý của người tị nạn trong nước."},{"en":"Marriage can change a person''s legal status in many ways.","vi":"Hôn nhân có thể thay đổi tư cách pháp lý của một người theo nhiều cách."},{"en":"Lawyers debated the legal status of the disputed land.","vi":"Các luật sư tranh luận về tư cách pháp lý của khu đất tranh chấp."}]', '[]', NULL, '/ˈliːɡəl ˈstætəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 40, 'legal system', 'hệ thống pháp luật', 'adj + n', '[{"en":"The country''s legal system protects the rights of every citizen.","vi":"Hệ thống pháp luật của quốc gia bảo vệ quyền của mọi công dân."},{"en":"Reforming the legal system requires careful planning and broad support.","vi":"Cải cách hệ thống pháp luật đòi hỏi kế hoạch kỹ lưỡng và sự ủng hộ rộng rãi."},{"en":"Students compared the legal system of two different nations.","vi":"Sinh viên so sánh hệ thống pháp luật của hai quốc gia khác nhau."}]', '[]', NULL, '/ˈliːɡəl ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 41, 'legislative measures', 'các biện pháp lập pháp', 'adj + n', '[{"en":"The government introduced legislative measures to reduce air pollution.","vi":"Chính phủ đưa ra các biện pháp lập pháp để giảm ô nhiễm không khí."},{"en":"New legislative measures aim to protect workers from unfair dismissal.","vi":"Các biện pháp lập pháp mới nhằm bảo vệ người lao động khỏi việc sa thải bất công."},{"en":"Effective legislative measures often follow extensive public consultation.","vi":"Các biện pháp lập pháp hiệu quả thường theo sau quá trình tham vấn công chúng rộng rãi."}]', '[]', NULL, '/ˈledʒɪsleɪtɪv ˈmeʒərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 42, 'legislative power', 'quyền lập pháp', 'adj + n', '[{"en":"The constitution gives legislative power to the elected parliament.","vi":"Hiến pháp trao quyền lập pháp cho nghị viện được bầu."},{"en":"Critics argued that the reform expanded the president''s legislative power.","vi":"Các nhà phê bình cho rằng cải cách đã mở rộng quyền lập pháp của tổng thống."},{"en":"Legislative power should remain separate from the judiciary.","vi":"Quyền lập pháp nên tách biệt khỏi quyền tư pháp."}]', '[]', NULL, '/ˈledʒɪsleɪtɪv ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 43, 'liberal democracy', 'nền dân chủ tự do', 'adj + n', '[{"en":"A liberal democracy depends on free elections and individual rights.","vi":"Một nền dân chủ tự do phụ thuộc vào bầu cử tự do và quyền cá nhân."},{"en":"The essay examined challenges facing modern liberal democracy.","vi":"Bài luận xem xét những thách thức mà nền dân chủ tự do hiện đại đối mặt."},{"en":"In a liberal democracy, the press operates without state control.","vi":"Trong nền dân chủ tự do, báo chí hoạt động mà không bị nhà nước kiểm soát."}]', '[]', NULL, '/ˈlɪbərəl dɪˈmɑːkrəsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 44, 'lifelong learning', 'học tập suốt đời', 'adj + n', '[{"en":"Lifelong learning helps people adapt to a changing job market.","vi":"Học tập suốt đời giúp con người thích nghi với thị trường việc làm đang thay đổi."},{"en":"The university promotes lifelong learning through its evening courses.","vi":"Trường đại học thúc đẩy học tập suốt đời qua các khóa học buổi tối."},{"en":"Many employers now value a commitment to lifelong learning.","vi":"Nhiều nhà tuyển dụng giờ đây coi trọng cam kết học tập suốt đời."}]', '[]', NULL, '/ˈlaɪflɔːŋ ˈlɜːrnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 45, 'likely impact', 'tác động có khả năng xảy ra', 'adj + n', '[{"en":"Researchers assessed the likely impact of the new policy.","vi":"Các nhà nghiên cứu đánh giá tác động có khả năng xảy ra của chính sách mới."},{"en":"The report describes the likely impact of climate change on farming.","vi":"Báo cáo mô tả tác động có khả năng xảy ra của biến đổi khí hậu lên nông nghiệp."},{"en":"Economists disagreed about the likely impact of the tax cut.","vi":"Các nhà kinh tế bất đồng về tác động có khả năng xảy ra của việc giảm thuế."}]', '[]', NULL, '/ˈlaɪkli ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 46, 'likely outcome', 'kết quả có khả năng xảy ra', 'adj + n', '[{"en":"Analysts predicted the most likely outcome of the election.","vi":"Các nhà phân tích dự đoán kết quả có khả năng xảy ra nhất của cuộc bầu cử."},{"en":"The model calculates the likely outcome of each treatment.","vi":"Mô hình tính toán kết quả có khả năng xảy ra của mỗi phương pháp điều trị."},{"en":"A delayed flight was the likely outcome of the storm.","vi":"Chuyến bay bị hoãn là kết quả có khả năng xảy ra của cơn bão."}]', '[]', NULL, '/ˈlaɪkli ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 47, 'limited access', 'khả năng tiếp cận hạn chế', 'adj + n', '[{"en":"Rural areas often have limited access to specialist healthcare.","vi":"Các vùng nông thôn thường có khả năng tiếp cận dịch vụ y tế chuyên khoa hạn chế."},{"en":"Students with limited access to computers fall behind quickly.","vi":"Học sinh có khả năng tiếp cận máy tính hạn chế sẽ tụt lại nhanh chóng."},{"en":"The reserve grants visitors limited access during nesting season.","vi":"Khu bảo tồn cho khách tham quan khả năng tiếp cận hạn chế trong mùa làm tổ."}]', '[]', NULL, '/ˈlɪmɪtɪd ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 48, 'limited capacity', 'năng lực hạn chế', 'adj + n', '[{"en":"The hospital has limited capacity to treat emergency patients.","vi":"Bệnh viện có năng lực hạn chế để điều trị bệnh nhân cấp cứu."},{"en":"Short-term memory has a limited capacity for holding information.","vi":"Trí nhớ ngắn hạn có năng lực hạn chế trong việc lưu giữ thông tin."},{"en":"Small firms have limited capacity to absorb sudden losses.","vi":"Các công ty nhỏ có năng lực hạn chế để hấp thụ thua lỗ bất ngờ."}]', '[]', NULL, '/ˈlɪmɪtɪd kəˈpæsəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 49, 'limited information', 'thông tin hạn chế', 'adj + n', '[{"en":"Doctors made the decision with only limited information available.","vi":"Các bác sĩ ra quyết định khi chỉ có thông tin hạn chế."},{"en":"The early study provided limited information about the disease.","vi":"Nghiên cứu ban đầu cung cấp thông tin hạn chế về căn bệnh."},{"en":"Investors often act despite limited information about new markets.","vi":"Các nhà đầu tư thường hành động dù chỉ có thông tin hạn chế về thị trường mới."}]', '[]', NULL, '/ˈlɪmɪtɪd ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 50, 'limited opportunity', 'cơ hội hạn chế', 'adj + n', '[{"en":"Young people in the village had limited opportunity for advancement.","vi":"Người trẻ trong làng có cơ hội thăng tiến hạn chế."},{"en":"The internship offers limited opportunity to gain practical experience.","vi":"Kỳ thực tập cung cấp cơ hội hạn chế để tích lũy kinh nghiệm thực tế."},{"en":"She faced limited opportunity to present her own research.","vi":"Cô gặp cơ hội hạn chế để trình bày nghiên cứu của riêng mình."}]', '[]', NULL, '/ˈlɪmɪtɪd ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 51, 'limited range of', 'phạm vi hạn chế của', 'adj + n', '[{"en":"The shop stocked only a limited range of imported goods.","vi":"Cửa hàng chỉ trữ một phạm vi hạn chế của hàng nhập khẩu."},{"en":"The survey covered a limited range of social behaviours.","vi":"Cuộc khảo sát bao quát một phạm vi hạn chế của các hành vi xã hội."},{"en":"Early phones supported a limited range of functions.","vi":"Điện thoại đời đầu hỗ trợ một phạm vi hạn chế của các chức năng."}]', '[]', NULL, '/ˈlɪmɪtɪd ˈreɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 52, 'limited resources', 'nguồn lực hạn chế', 'adj + n', '[{"en":"Charities must achieve their goals with limited resources.","vi":"Các tổ chức từ thiện phải đạt được mục tiêu với nguồn lực hạn chế."},{"en":"The school managed excellent results despite limited resources.","vi":"Trường đạt kết quả xuất sắc dù có nguồn lực hạn chế."},{"en":"Developing nations often compete for limited resources.","vi":"Các quốc gia đang phát triển thường cạnh tranh giành nguồn lực hạn chế."}]', '[]', NULL, '/ˈlɪmɪtɪd ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 53, 'linear relationship', 'mối quan hệ tuyến tính', 'adj + n', '[{"en":"The graph shows a clear linear relationship between the two variables.","vi":"Đồ thị cho thấy mối quan hệ tuyến tính rõ ràng giữa hai biến số."},{"en":"Researchers found no linear relationship between diet and mood.","vi":"Các nhà nghiên cứu không tìm thấy mối quan hệ tuyến tính giữa chế độ ăn và tâm trạng."},{"en":"A linear relationship makes the data easy to predict.","vi":"Mối quan hệ tuyến tính khiến dữ liệu dễ dự đoán."}]', '[]', NULL, '/ˈlɪniər rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 54, 'literal interpretation', 'cách diễn giải theo nghĩa đen', 'adj + n', '[{"en":"A literal interpretation of the poem misses its deeper meaning.","vi":"Cách diễn giải theo nghĩa đen của bài thơ bỏ lỡ ý nghĩa sâu xa của nó."},{"en":"Judges sometimes prefer a literal interpretation of the law.","vi":"Đôi khi các thẩm phán ưa thích cách diễn giải luật theo nghĩa đen."},{"en":"His literal interpretation of the instructions caused confusion.","vi":"Cách diễn giải theo nghĩa đen của anh về hướng dẫn đã gây nhầm lẫn."}]', '[]', NULL, '/ˈlɪtərəl ɪnˌtɜːrprɪˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 55, 'literal meaning', 'nghĩa đen', 'adj + n', '[{"en":"The literal meaning of the phrase differs from its common usage.","vi":"Nghĩa đen của cụm từ khác với cách dùng thông thường của nó."},{"en":"Idioms cannot be understood from their literal meaning alone.","vi":"Không thể hiểu thành ngữ chỉ qua nghĩa đen của chúng."},{"en":"Translators must look beyond the literal meaning of words.","vi":"Người dịch phải nhìn xa hơn nghĩa đen của từ ngữ."}]', '[]', NULL, '/ˈlɪtərəl ˈmiːnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 56, 'literal sense', 'nghĩa đen', 'adj + n', '[{"en":"In the literal sense, the word simply means to fall.","vi":"Theo nghĩa đen, từ này chỉ đơn giản có nghĩa là rơi."},{"en":"She did not mean the comment in a literal sense.","vi":"Cô không có ý nói nhận xét đó theo nghĩa đen."},{"en":"Taken in its literal sense, the rule seems absurd.","vi":"Hiểu theo nghĩa đen, quy tắc này có vẻ vô lý."}]', '[]', NULL, '/ˈlɪtərəl ˈsens/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 57, 'literary text', 'văn bản văn học', 'adj + n', '[{"en":"Students analysed the literary text for its hidden symbolism.","vi":"Sinh viên phân tích văn bản văn học để tìm tính biểu tượng ẩn giấu."},{"en":"Each literary text reflects the era in which it was written.","vi":"Mỗi văn bản văn học phản ánh thời đại mà nó được viết ra."},{"en":"The professor compared two literary texts from the same period.","vi":"Giáo sư so sánh hai văn bản văn học từ cùng một thời kỳ."}]', '[]', NULL, '/ˈlɪtəreri ˈtekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 58, 'literary tradition', 'truyền thống văn học', 'adj + n', '[{"en":"The novel draws heavily on a rich literary tradition.","vi":"Cuốn tiểu thuyết dựa nhiều vào một truyền thống văn học phong phú."},{"en":"Oral storytelling forms part of the region''s literary tradition.","vi":"Kể chuyện truyền miệng là một phần của truyền thống văn học của vùng."},{"en":"Modern writers often challenge an established literary tradition.","vi":"Các nhà văn hiện đại thường thách thức một truyền thống văn học đã được thiết lập."}]', '[]', NULL, '/ˈlɪtəreri trəˈdɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 59, 'little evidence', 'ít bằng chứng', 'adj + n', '[{"en":"There is little evidence that the treatment actually works.","vi":"Có ít bằng chứng cho thấy phương pháp điều trị thực sự hiệu quả."},{"en":"The study found little evidence of long-term harm.","vi":"Nghiên cứu tìm thấy ít bằng chứng về tác hại lâu dài."},{"en":"Little evidence supports the claim that prices will fall.","vi":"Ít bằng chứng ủng hộ tuyên bố rằng giá sẽ giảm."}]', '[]', NULL, '/ˈlɪtəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 60, 'little impact', 'ít tác động', 'adj + n', '[{"en":"The new rules had little impact on student behaviour.","vi":"Các quy tắc mới có ít tác động đến hành vi của học sinh."},{"en":"Advertising made little impact on the company''s sales.","vi":"Quảng cáo có ít tác động đến doanh số của công ty."},{"en":"Small donations have little impact on a large deficit.","vi":"Những khoản quyên góp nhỏ có ít tác động đến một khoản thâm hụt lớn."}]', '[]', NULL, '/ˈlɪtəl ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 61, 'little information', 'ít thông tin', 'adj + n', '[{"en":"The website offers little information about the program''s costs.","vi":"Trang web cung cấp ít thông tin về chi phí của chương trình."},{"en":"We had little information to guide our final decision.","vi":"Chúng tôi có ít thông tin để định hướng quyết định cuối cùng."},{"en":"Little information existed about the species before this study.","vi":"Có ít thông tin về loài này trước nghiên cứu này."}]', '[]', NULL, '/ˈlɪtəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 62, 'little research', 'ít nghiên cứu', 'adj + n', '[{"en":"Little research has examined the effects of night-shift work.","vi":"Ít nghiên cứu đã xem xét tác động của công việc ca đêm."},{"en":"Surprisingly little research exists on this common illness.","vi":"Đáng ngạc nhiên là có ít nghiên cứu về căn bệnh phổ biến này."},{"en":"There is little research linking the two phenomena directly.","vi":"Có ít nghiên cứu liên kết trực tiếp hai hiện tượng này."}]', '[]', NULL, '/ˈlɪtəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 63, 'little significance', 'ít ý nghĩa', 'adj + n', '[{"en":"The difference between the groups had little significance statistically.","vi":"Sự khác biệt giữa các nhóm có ít ý nghĩa về mặt thống kê."},{"en":"Critics argued the discovery held little significance for medicine.","vi":"Các nhà phê bình cho rằng phát hiện này có ít ý nghĩa với y học."},{"en":"These minor errors are of little significance to the result.","vi":"Những lỗi nhỏ này có ít ý nghĩa đối với kết quả."}]', '[]', NULL, '/ˈlɪtəl sɪɡˈnɪfɪkəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 64, 'living conditions', 'điều kiện sống', 'adj + n', '[{"en":"Poor living conditions can lead to serious health problems.","vi":"Điều kiện sống tồi tệ có thể dẫn đến các vấn đề sức khỏe nghiêm trọng."},{"en":"The charity works to improve living conditions in slums.","vi":"Tổ chức từ thiện nỗ lực cải thiện điều kiện sống trong các khu ổ chuột."},{"en":"Better living conditions have raised average life expectancy.","vi":"Điều kiện sống tốt hơn đã nâng cao tuổi thọ trung bình."}]', '[]', NULL, '/ˈlɪvɪŋ kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 65, 'living organism', 'sinh vật sống', 'adj + n', '[{"en":"Every living organism requires energy to survive and grow.","vi":"Mọi sinh vật sống đều cần năng lượng để tồn tại và phát triển."},{"en":"Bacteria are the smallest living organism visible under a microscope.","vi":"Vi khuẩn là sinh vật sống nhỏ nhất có thể thấy dưới kính hiển vi."},{"en":"Pollution threatens nearly every living organism in the river.","vi":"Ô nhiễm đe dọa gần như mọi sinh vật sống trong dòng sông."}]', '[]', NULL, '/ˈlɪvɪŋ ˈɔːrɡənɪzəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 66, 'living standard', 'mức sống', 'adj + n', '[{"en":"Rising wages have improved the living standard of many families.","vi":"Lương tăng đã cải thiện mức sống của nhiều gia đình."},{"en":"Economists use income to measure a country''s living standard.","vi":"Các nhà kinh tế dùng thu nhập để đo lường mức sống của một quốc gia."},{"en":"A higher living standard often follows steady economic growth.","vi":"Mức sống cao hơn thường đi kèm với tăng trưởng kinh tế ổn định."}]', '[]', NULL, '/ˈlɪvɪŋ ˈstændərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 67, 'local area', 'khu vực địa phương', 'adj + n', '[{"en":"The survey gathered opinions from residents in the local area.","vi":"Cuộc khảo sát thu thập ý kiến từ cư dân trong khu vực địa phương."},{"en":"New shops have brought more jobs to the local area.","vi":"Các cửa hàng mới đã mang lại nhiều việc làm hơn cho khu vực địa phương."},{"en":"Volunteers cleaned several parks across the local area.","vi":"Các tình nguyện viên dọn dẹp vài công viên trong khu vực địa phương."}]', '[]', NULL, '/ˈloʊkəl ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 68, 'local authority', 'chính quyền địa phương', 'adj + n', '[{"en":"The local authority is responsible for collecting household waste.","vi":"Chính quyền địa phương chịu trách nhiệm thu gom rác thải sinh hoạt."},{"en":"Residents petitioned the local authority for safer roads.","vi":"Cư dân kiến nghị chính quyền địa phương về những con đường an toàn hơn."},{"en":"Funding from the local authority supports the public library.","vi":"Kinh phí từ chính quyền địa phương hỗ trợ thư viện công cộng."}]', '[]', NULL, '/ˈloʊkəl əˈθɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 69, 'local circumstances', 'hoàn cảnh địa phương', 'adj + n', '[{"en":"Policies must be adapted to suit local circumstances.","vi":"Các chính sách phải được điều chỉnh để phù hợp với hoàn cảnh địa phương."},{"en":"What works in one city may fail under different local circumstances.","vi":"Điều hiệu quả ở một thành phố có thể thất bại trong hoàn cảnh địa phương khác."},{"en":"The plan ignored important local circumstances and quickly failed.","vi":"Kế hoạch bỏ qua những hoàn cảnh địa phương quan trọng và nhanh chóng thất bại."}]', '[]', NULL, '/ˈloʊkəl ˈsɜːrkəmstænsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 70, 'local community', 'cộng đồng địa phương', 'adj + n', '[{"en":"The factory provides many jobs for the local community.","vi":"Nhà máy cung cấp nhiều việc làm cho cộng đồng địa phương."},{"en":"Schools play a central role in the local community.","vi":"Trường học đóng vai trò trung tâm trong cộng đồng địa phương."},{"en":"The festival brings the whole local community together.","vi":"Lễ hội gắn kết cả cộng đồng địa phương lại với nhau."}]', '[]', NULL, '/ˈloʊkəl kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 71, 'local culture', 'văn hóa địa phương', 'adj + n', '[{"en":"Tourists are encouraged to respect the local culture.","vi":"Du khách được khuyến khích tôn trọng văn hóa địa phương."},{"en":"The museum preserves objects that reflect the local culture.","vi":"Bảo tàng lưu giữ các hiện vật phản ánh văn hóa địa phương."},{"en":"Globalisation sometimes threatens unique forms of local culture.","vi":"Toàn cầu hóa đôi khi đe dọa những hình thức độc đáo của văn hóa địa phương."}]', '[]', NULL, '/ˈloʊkəl ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 72, 'local economy', 'nền kinh tế địa phương', 'adj + n', '[{"en":"Tourism contributes significantly to the local economy each summer.","vi":"Du lịch đóng góp đáng kể cho nền kinh tế địa phương mỗi mùa hè."},{"en":"Closing the mine would damage the entire local economy.","vi":"Việc đóng cửa mỏ sẽ làm tổn hại cả nền kinh tế địa phương."},{"en":"Small businesses are the backbone of the local economy.","vi":"Các doanh nghiệp nhỏ là xương sống của nền kinh tế địa phương."}]', '[]', NULL, '/ˈloʊkəl ɪˈkɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 73, 'local government', 'chính quyền địa phương', 'adj + n', '[{"en":"Local government manages schools, roads, and public parks.","vi":"Chính quyền địa phương quản lý trường học, đường sá và công viên công cộng."},{"en":"Citizens elect representatives to their local government every four years.","vi":"Người dân bầu đại biểu vào chính quyền địa phương bốn năm một lần."},{"en":"Budget cuts have reduced services provided by local government.","vi":"Việc cắt giảm ngân sách đã thu hẹp dịch vụ do chính quyền địa phương cung cấp."}]', '[]', NULL, '/ˈloʊkəl ˈɡʌvərnmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 74, 'logical approach', 'cách tiếp cận hợp lý', 'adj + n', '[{"en":"A logical approach to the problem saves a lot of time.","vi":"Một cách tiếp cận hợp lý cho vấn đề tiết kiệm rất nhiều thời gian."},{"en":"The teacher praised her logical approach to the essay.","vi":"Giáo viên khen ngợi cách tiếp cận hợp lý của cô với bài luận."},{"en":"Engineers favour a logical approach over guesswork.","vi":"Các kỹ sư ưa thích cách tiếp cận hợp lý hơn là phỏng đoán."}]', '[]', NULL, '/ˈlɑːdʒɪkəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 75, 'logical argument', 'lập luận hợp lý', 'adj + n', '[{"en":"She built a logical argument supported by clear evidence.","vi":"Cô xây dựng một lập luận hợp lý được hỗ trợ bởi bằng chứng rõ ràng."},{"en":"A logical argument should avoid contradictions and gaps.","vi":"Một lập luận hợp lý nên tránh mâu thuẫn và những lỗ hổng."},{"en":"The debate was won through a calm, logical argument.","vi":"Cuộc tranh luận được thắng nhờ một lập luận bình tĩnh và hợp lý."}]', '[]', NULL, '/ˈlɑːdʒɪkəl ˈɑːrɡjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 76, 'logical conclusion', 'kết luận hợp lý', 'adj + n', '[{"en":"The evidence leads to one clear, logical conclusion.","vi":"Bằng chứng dẫn đến một kết luận hợp lý rõ ràng."},{"en":"Taking the idea to its logical conclusion reveals a flaw.","vi":"Đưa ý tưởng đến kết luận hợp lý của nó cho thấy một sai sót."},{"en":"Readers can draw their own logical conclusion from the data.","vi":"Người đọc có thể tự rút ra kết luận hợp lý từ dữ liệu."}]', '[]', NULL, '/ˈlɑːdʒɪkəl kənˈkluːʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 77, 'long duration', 'thời gian dài', 'adj + n', '[{"en":"The experiment ran over a long duration to ensure accuracy.","vi":"Thí nghiệm chạy trong một thời gian dài để đảm bảo độ chính xác."},{"en":"Treatments of long duration often raise the cost of care.","vi":"Các liệu trình kéo dài thời gian dài thường làm tăng chi phí chăm sóc."},{"en":"The storm''s long duration caused widespread flooding.","vi":"Thời gian dài của cơn bão đã gây ra lũ lụt trên diện rộng."}]', '[]', NULL, '/ˈlɔːŋ duˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 78, 'long established', 'đã được thiết lập từ lâu', 'adv + adj', '[{"en":"The company follows a long established tradition of quality.","vi":"Công ty tuân theo một truyền thống chất lượng đã được thiết lập từ lâu."},{"en":"These long established methods are still taught today.","vi":"Những phương pháp đã được thiết lập từ lâu này vẫn được dạy ngày nay."},{"en":"She challenged a long established belief in the field.","vi":"Cô thách thức một niềm tin đã được thiết lập từ lâu trong lĩnh vực này."}]', '[]', NULL, '/ˈlɔːŋ ɪˈstæblɪʃt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 79, 'longitudinal study', 'nghiên cứu theo chiều dọc', 'adj + n', '[{"en":"A longitudinal study followed the same children for ten years.","vi":"Một nghiên cứu theo chiều dọc theo dõi cùng những đứa trẻ trong mười năm."},{"en":"The longitudinal study revealed gradual changes in health.","vi":"Nghiên cứu theo chiều dọc cho thấy những thay đổi dần dần về sức khỏe."},{"en":"Funding a longitudinal study requires long-term commitment.","vi":"Tài trợ cho một nghiên cứu theo chiều dọc đòi hỏi cam kết lâu dài."}]', '[]', NULL, '/ˌlɔːndʒɪˈtuːdɪnəl ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 80, 'low income', 'thu nhập thấp', 'adj + n', '[{"en":"Families on a low income struggle to afford housing.","vi":"Các gia đình có thu nhập thấp gặp khó khăn trong việc trang trải nhà ở."},{"en":"The program offers grants to low income students.","vi":"Chương trình cấp học bổng cho sinh viên có thu nhập thấp."},{"en":"Low income often limits access to healthy food.","vi":"Thu nhập thấp thường hạn chế khả năng tiếp cận thực phẩm lành mạnh."}]', '[]', NULL, '/ˈloʊ ˈɪnkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 81, 'low intensity', 'cường độ thấp', 'adj + n', '[{"en":"Low intensity exercise is recommended for older patients.","vi":"Bài tập cường độ thấp được khuyến nghị cho bệnh nhân lớn tuổi."},{"en":"The conflict remained at low intensity for several years.","vi":"Cuộc xung đột duy trì ở cường độ thấp trong vài năm."},{"en":"Plants near the wall received only low intensity light.","vi":"Cây cối gần tường chỉ nhận được ánh sáng cường độ thấp."}]', '[]', NULL, '/ˈloʊ ɪnˈtensəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 82, 'low level', 'mức độ thấp', 'adj + n', '[{"en":"Tests detected a low level of pollution in the water.","vi":"Các xét nghiệm phát hiện mức độ ô nhiễm thấp trong nước."},{"en":"Workers reported a low level of job satisfaction.","vi":"Người lao động báo cáo mức độ hài lòng với công việc thấp."},{"en":"A low level of rainfall harmed the year''s harvest.","vi":"Mức độ lượng mưa thấp đã làm hỏng vụ thu hoạch năm đó."}]', '[]', NULL, '/ˈloʊ ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 83, 'low percentage', 'tỷ lệ phần trăm thấp', 'adj + n', '[{"en":"Only a low percentage of applicants passed the final exam.","vi":"Chỉ một tỷ lệ phần trăm thấp ứng viên vượt qua kỳ thi cuối."},{"en":"A low percentage of voters turned out for the election.","vi":"Một tỷ lệ phần trăm thấp cử tri đi bỏ phiếu trong cuộc bầu cử."},{"en":"The drug helped only a low percentage of patients.","vi":"Loại thuốc chỉ giúp được một tỷ lệ phần trăm thấp bệnh nhân."}]', '[]', NULL, '/ˈloʊ pərˈsentɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 84, 'low priority', 'mức ưu tiên thấp', 'adj + n', '[{"en":"Road repairs were given low priority in this year''s budget.","vi":"Việc sửa đường được dành mức ưu tiên thấp trong ngân sách năm nay."},{"en":"The task seemed important but was actually low priority.","vi":"Nhiệm vụ có vẻ quan trọng nhưng thực ra là mức ưu tiên thấp."},{"en":"Staff training became a low priority during the crisis.","vi":"Đào tạo nhân viên trở thành mức ưu tiên thấp trong khủng hoảng."}]', '[]', NULL, '/ˈloʊ praɪˈɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 85, 'low probability', 'xác suất thấp', 'adj + n', '[{"en":"There is a low probability of rain this afternoon.","vi":"Có xác suất thấp xảy ra mưa vào chiều nay."},{"en":"The model assigns a low probability to that outcome.","vi":"Mô hình gán xác suất thấp cho kết quả đó."},{"en":"Despite the low probability, the team prepared for failure.","vi":"Dù xác suất thấp, đội vẫn chuẩn bị cho thất bại."}]', '[]', NULL, '/ˈloʊ ˌprɑːbəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 86, 'low profile', 'sự kín đáo, ít phô trương', 'adj + n', '[{"en":"The politician kept a low profile during the scandal.","vi":"Chính trị gia giữ thái độ kín đáo trong suốt vụ bê bối."},{"en":"After the controversy, the company maintained a low profile.","vi":"Sau cuộc tranh cãi, công ty duy trì sự kín đáo."},{"en":"She prefers a low profile and avoids public attention.","vi":"Cô thích sự kín đáo và tránh sự chú ý của công chúng."}]', '[]', NULL, '/ˈloʊ ˈproʊfaɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 87, 'low quality', 'chất lượng thấp', 'adj + n', '[{"en":"Customers complained about the low quality of the materials.","vi":"Khách hàng phàn nàn về chất lượng thấp của vật liệu."},{"en":"Low quality data can ruin an otherwise good study.","vi":"Dữ liệu chất lượng thấp có thể phá hỏng một nghiên cứu vốn tốt."},{"en":"Cheap goods are often of disappointingly low quality.","vi":"Hàng giá rẻ thường có chất lượng thấp đáng thất vọng."}]', '[]', NULL, '/ˈloʊ ˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 88, 'low status', 'địa vị thấp', 'adj + n', '[{"en":"Manual jobs were once seen as having low status.","vi":"Công việc chân tay từng bị xem là có địa vị thấp."},{"en":"The reform aimed to help workers of low status.","vi":"Cuộc cải cách nhằm giúp đỡ những người lao động có địa vị thấp."},{"en":"Low status within the group limited her influence.","vi":"Địa vị thấp trong nhóm đã hạn chế ảnh hưởng của cô."}]', '[]', NULL, '/ˈloʊ ˈstætəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 89, 'low turnover', 'tỷ lệ thay đổi nhân sự thấp', 'adj + n', '[{"en":"The firm enjoys low turnover thanks to fair wages.","vi":"Công ty có tỷ lệ thay đổi nhân sự thấp nhờ mức lương công bằng."},{"en":"Low turnover suggests employees are happy in their roles.","vi":"Tỷ lệ thay đổi nhân sự thấp cho thấy nhân viên hài lòng với vai trò của mình."},{"en":"Good management is linked to low turnover among staff.","vi":"Quản lý tốt gắn liền với tỷ lệ thay đổi nhân sự thấp."}]', '[]', NULL, '/ˈloʊ ˈtɜːrnoʊvər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 90, 'low unemployment', 'tỷ lệ thất nghiệp thấp', 'adj + n', '[{"en":"Low unemployment usually signals a healthy economy.","vi":"Tỷ lệ thất nghiệp thấp thường báo hiệu một nền kinh tế lành mạnh."},{"en":"The region enjoyed low unemployment for several years.","vi":"Khu vực này có tỷ lệ thất nghiệp thấp trong nhiều năm."},{"en":"Low unemployment can push wages gradually higher.","vi":"Tỷ lệ thất nghiệp thấp có thể đẩy lương tăng dần lên."}]', '[]', NULL, '/ˈloʊ ˌʌnɪmˈplɔɪmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 91, 'low/er frequency', 'tần suất thấp/thấp hơn', 'adj + n', '[{"en":"The disease occurs at a lower frequency in rural areas.","vi":"Căn bệnh xảy ra với tần suất thấp hơn ở vùng nông thôn."},{"en":"Lower frequency sounds travel farther than high ones.","vi":"Âm thanh tần suất thấp hơn truyền đi xa hơn âm thanh cao."},{"en":"Researchers noted a lower frequency of errors after training.","vi":"Các nhà nghiên cứu ghi nhận tần suất lỗi thấp hơn sau khi đào tạo."}]', '[]', NULL, '/ˈloʊər ˈfriːkwənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 92, 'lower class', 'tầng lớp hạ lưu', 'adj + n', '[{"en":"The novel portrays the hardships of the lower class.","vi":"Cuốn tiểu thuyết khắc họa những khó khăn của tầng lớp hạ lưu."},{"en":"Education was once denied to the lower class.","vi":"Giáo dục từng bị từ chối với tầng lớp hạ lưu."},{"en":"Historians studied how the lower class lived during that era.","vi":"Các nhà sử học nghiên cứu cách tầng lớp hạ lưu sống trong thời đại đó."}]', '[]', NULL, '/ˈloʊər ˈklæs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 93, 'main area', 'lĩnh vực chính', 'adj + n', '[{"en":"The report focuses on three main areas of concern.","vi":"Báo cáo tập trung vào ba lĩnh vực chính đáng quan tâm."},{"en":"Her main area of research is renewable energy.","vi":"Lĩnh vực nghiên cứu chính của cô là năng lượng tái tạo."},{"en":"The main area of disagreement concerned the budget.","vi":"Lĩnh vực bất đồng chính liên quan đến ngân sách."}]', '[]', NULL, '/ˈmeɪn ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 94, 'main argument', 'luận điểm chính', 'adj + n', '[{"en":"The main argument of the essay appears in the introduction.","vi":"Luận điểm chính của bài luận xuất hiện ở phần mở đầu."},{"en":"Her main argument rests on solid historical evidence.","vi":"Luận điểm chính của cô dựa trên bằng chứng lịch sử vững chắc."},{"en":"Critics quickly attacked the writer''s main argument.","vi":"Các nhà phê bình nhanh chóng công kích luận điểm chính của tác giả."}]', '[]', NULL, '/ˈmeɪn ˈɑːrɡjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 95, 'main category', 'loại chính', 'adj + n', '[{"en":"The data fall into three main categories for analysis.","vi":"Dữ liệu được chia thành ba loại chính để phân tích."},{"en":"Each main category contains several smaller subgroups.","vi":"Mỗi loại chính chứa một số nhóm nhỏ hơn."},{"en":"Books here are sorted by their main category first.","vi":"Sách ở đây được sắp xếp theo loại chính trước tiên."}]', '[]', NULL, '/ˈmeɪn ˈkætəɡɔːri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 96, 'main characteristics', 'những đặc điểm chính', 'adj + n', '[{"en":"The chapter lists the main characteristics of each species.","vi":"Chương này liệt kê những đặc điểm chính của mỗi loài."},{"en":"Students must describe the main characteristics of the period.","vi":"Sinh viên phải mô tả những đặc điểm chính của thời kỳ này."},{"en":"These main characteristics distinguish one group from another.","vi":"Những đặc điểm chính này phân biệt nhóm này với nhóm khác."}]', '[]', NULL, '/ˈmeɪn ˌkærəktəˈrɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 97, 'main component', 'thành phần chính', 'adj + n', '[{"en":"Water is the main component of the human body.","vi":"Nước là thành phần chính của cơ thể con người."},{"en":"The engine is the main component of the entire system.","vi":"Động cơ là thành phần chính của toàn bộ hệ thống."},{"en":"Reading is the main component of the language course.","vi":"Đọc là thành phần chính của khóa học ngôn ngữ."}]', '[]', NULL, '/ˈmeɪn kəmˈpoʊnənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 98, 'main element', 'yếu tố chính', 'adj + n', '[{"en":"Trust is the main element of any successful partnership.","vi":"Sự tin tưởng là yếu tố chính của mọi quan hệ đối tác thành công."},{"en":"The plot is the main element that drives the story.","vi":"Cốt truyện là yếu tố chính thúc đẩy câu chuyện."},{"en":"Practice remains the main element of mastering a skill.","vi":"Luyện tập vẫn là yếu tố chính để thành thạo một kỹ năng."}]', '[]', NULL, '/ˈmeɪn ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 99, 'main factor', 'yếu tố chính', 'adj + n', '[{"en":"Cost was the main factor behind their final decision.","vi":"Chi phí là yếu tố chính đằng sau quyết định cuối cùng của họ."},{"en":"Climate is the main factor affecting crop yields here.","vi":"Khí hậu là yếu tố chính ảnh hưởng đến năng suất cây trồng ở đây."},{"en":"Motivation is the main factor in long-term learning.","vi":"Động lực là yếu tố chính trong việc học lâu dài."}]', '[]', NULL, '/ˈmeɪn ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 100, 'main feature', 'đặc điểm chính', 'adj + n', '[{"en":"The main feature of the app is its simple design.","vi":"Đặc điểm chính của ứng dụng là thiết kế đơn giản của nó."},{"en":"A large garden is the house''s main feature.","vi":"Một khu vườn rộng là đặc điểm chính của ngôi nhà."},{"en":"The main feature of the region is its volcanic soil.","vi":"Đặc điểm chính của vùng này là đất núi lửa của nó."}]', '[]', NULL, '/ˈmeɪn ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 101, 'main findings', 'những phát hiện chính', 'adj + n', '[{"en":"The summary presents the main findings of the study.","vi":"Phần tóm tắt trình bày những phát hiện chính của nghiên cứu."},{"en":"Her main findings challenged earlier assumptions in the field.","vi":"Những phát hiện chính của cô thách thức các giả định trước đó trong lĩnh vực này."},{"en":"The main findings were published in a leading journal.","vi":"Những phát hiện chính được công bố trên một tạp chí hàng đầu."}]', '[]', NULL, '/ˈmeɪn ˈfaɪndɪŋz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 102, 'main focus', 'trọng tâm chính', 'adj + n', '[{"en":"The main focus of the lecture was climate policy.","vi":"Trọng tâm chính của bài giảng là chính sách khí hậu."},{"en":"Customer safety is the company''s main focus this year.","vi":"An toàn của khách hàng là trọng tâm chính của công ty năm nay."},{"en":"Her main focus shifted from theory to practice.","vi":"Trọng tâm chính của cô chuyển từ lý thuyết sang thực hành."}]', '[]', NULL, '/ˈmeɪn ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 103, 'main function', 'chức năng chính', 'adj + n', '[{"en":"The heart''s main function is to pump blood around the body.","vi":"Chức năng chính của tim là bơm máu khắp cơ thể."},{"en":"The committee''s main function is to review new proposals.","vi":"Chức năng chính của ủy ban là xem xét các đề xuất mới."},{"en":"A dictionary''s main function is to define words clearly.","vi":"Chức năng chính của từ điển là định nghĩa từ ngữ rõ ràng."}]', '[]', NULL, '/ˈmeɪn ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 104, 'main issue', 'vấn đề chính', 'adj + n', '[{"en":"The main issue discussed was rising housing costs.","vi":"Vấn đề chính được thảo luận là chi phí nhà ở tăng cao."},{"en":"We must address the main issue before moving forward.","vi":"Chúng ta phải giải quyết vấn đề chính trước khi tiến tới."},{"en":"The main issue for many students is a lack of time.","vi":"Vấn đề chính của nhiều sinh viên là thiếu thời gian."}]', '[]', NULL, '/ˈmeɪn ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 105, 'main principle', 'nguyên tắc chính', 'adj + n', '[{"en":"Fairness is the main principle behind the new rules.","vi":"Công bằng là nguyên tắc chính đằng sau các quy tắc mới."},{"en":"The main principle of the theory is surprisingly simple.","vi":"Nguyên tắc chính của lý thuyết này đơn giản đến bất ngờ."},{"en":"Equality remains the main principle of the organisation.","vi":"Bình đẳng vẫn là nguyên tắc chính của tổ chức."}]', '[]', NULL, '/ˈmeɪn ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 106, 'main source', 'nguồn chính', 'adj + n', '[{"en":"Tourism is the main source of income for the island.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo."},{"en":"The river is the main source of water for the city.","vi":"Con sông là nguồn nước chính cho thành phố."},{"en":"Books were once the main source of reliable knowledge.","vi":"Sách từng là nguồn kiến thức đáng tin cậy chính."}]', '[]', NULL, '/ˈmeɪn ˈsɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 107, 'main task', 'nhiệm vụ chính', 'adj + n', '[{"en":"The main task of the editor is to check accuracy.","vi":"Nhiệm vụ chính của biên tập viên là kiểm tra độ chính xác."},{"en":"Their main task was to gather data from the field.","vi":"Nhiệm vụ chính của họ là thu thập dữ liệu từ thực địa."},{"en":"Completing the main task took the team several weeks.","vi":"Hoàn thành nhiệm vụ chính khiến cả đội mất vài tuần."}]', '[]', NULL, '/ˈmeɪn ˈtæsk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 108, 'main theme', 'chủ đề chính', 'adj + n', '[{"en":"Loss is the main theme running through the entire novel.","vi":"Mất mát là chủ đề chính xuyên suốt cả cuốn tiểu thuyết."},{"en":"The conference''s main theme was sustainable development.","vi":"Chủ đề chính của hội nghị là phát triển bền vững."},{"en":"Identity emerges as the main theme of her poetry.","vi":"Bản sắc nổi lên như chủ đề chính trong thơ của cô."}]', '[]', NULL, '/ˈmeɪn ˈθiːm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 109, 'mainly concerned with', 'chủ yếu liên quan đến', 'adv + vpp', '[{"en":"The study is mainly concerned with the effects of sleep.","vi":"Nghiên cứu chủ yếu liên quan đến tác động của giấc ngủ."},{"en":"This chapter is mainly concerned with economic theory.","vi":"Chương này chủ yếu liên quan đến lý thuyết kinh tế."},{"en":"Her work is mainly concerned with social inequality.","vi":"Công việc của cô chủ yếu liên quan đến bất bình đẳng xã hội."}]', '[]', NULL, '/ˈmeɪnli kənˈsɜːrnd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 110, 'maintain contact', 'duy trì liên lạc', 'v + n', '[{"en":"Researchers maintain contact with participants throughout the project.","vi":"Các nhà nghiên cứu duy trì liên lạc với người tham gia suốt dự án."},{"en":"It is hard to maintain contact with old school friends.","vi":"Thật khó để duy trì liên lạc với bạn học cũ."},{"en":"The two offices maintain contact through weekly video calls.","vi":"Hai văn phòng duy trì liên lạc qua các cuộc gọi video hàng tuần."}]', '[]', NULL, '/meɪnˈteɪn ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 111, 'major advantage', 'lợi thế lớn', 'adj + n', '[{"en":"A major advantage of the method is its low cost.","vi":"Một lợi thế lớn của phương pháp này là chi phí thấp."},{"en":"Speaking two languages is a major advantage when travelling.","vi":"Nói được hai ngôn ngữ là một lợi thế lớn khi đi du lịch."},{"en":"Their early start gave them a major advantage.","vi":"Việc khởi đầu sớm mang lại cho họ một lợi thế lớn."}]', '[]', NULL, '/ˈmeɪdʒər ədˈvæntɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 112, 'major area', 'lĩnh vực lớn', 'adj + n', '[{"en":"Healthcare is a major area of government spending.","vi":"Y tế là một lĩnh vực lớn trong chi tiêu của chính phủ."},{"en":"Robotics has become a major area of modern research.","vi":"Robot học đã trở thành một lĩnh vực lớn của nghiên cứu hiện đại."},{"en":"The reform targeted a major area of public concern.","vi":"Cuộc cải cách nhắm vào một lĩnh vực lớn mà công chúng quan tâm."}]', '[]', NULL, '/ˈmeɪdʒər ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 113, 'major cause', 'nguyên nhân chính', 'adj + n', '[{"en":"Smoking is a major cause of lung disease worldwide.","vi":"Hút thuốc là nguyên nhân chính gây bệnh phổi trên toàn thế giới."},{"en":"Deforestation is a major cause of habitat loss.","vi":"Phá rừng là nguyên nhân chính gây mất môi trường sống."},{"en":"Stress is a major cause of poor sleep in adults.","vi":"Căng thẳng là nguyên nhân chính gây mất ngủ ở người lớn."}]', '[]', NULL, '/ˈmeɪdʒər ˈkɔːz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 114, 'major challenge', 'thách thức lớn', 'adj + n', '[{"en":"Climate change is a major challenge for future generations.","vi":"Biến đổi khí hậu là một thách thức lớn cho các thế hệ tương lai."},{"en":"Funding remained the major challenge facing the project.","vi":"Tài chính vẫn là thách thức lớn mà dự án phải đối mặt."},{"en":"Learning a new language poses a major challenge.","vi":"Học một ngôn ngữ mới đặt ra một thách thức lớn."}]', '[]', NULL, '/ˈmeɪdʒər ˈtʃælɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 115, 'major change', 'thay đổi lớn', 'adj + n', '[{"en":"The reform brought a major change to the tax system.","vi":"Cuộc cải cách mang lại một thay đổi lớn cho hệ thống thuế."},{"en":"Technology has caused a major change in how we work.","vi":"Công nghệ đã gây ra một thay đổi lớn trong cách chúng ta làm việc."},{"en":"Adapting to a major change takes time and patience.","vi":"Thích nghi với một thay đổi lớn cần thời gian và kiên nhẫn."}]', '[]', NULL, '/ˈmeɪdʒər ˈtʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 116, 'major component', 'thành phần chính', 'adj + n', '[{"en":"Carbon is a major component of all living things.","vi":"Cacbon là một thành phần chính của mọi sinh vật sống."},{"en":"Tuition is a major component of the total study cost.","vi":"Học phí là một thành phần chính của tổng chi phí học tập."},{"en":"Trust is a major component of effective teamwork.","vi":"Sự tin tưởng là một thành phần chính của làm việc nhóm hiệu quả."}]', '[]', NULL, '/ˈmeɪdʒər kəmˈpoʊnənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 117, 'major concern', 'mối lo ngại lớn', 'adj + n', '[{"en":"Air pollution is a major concern in large cities.","vi":"Ô nhiễm không khí là một mối lo ngại lớn ở các thành phố lớn."},{"en":"Safety was the parents'' major concern about the trip.","vi":"An toàn là mối lo ngại lớn của phụ huynh về chuyến đi."},{"en":"Rising costs are a major concern for small businesses.","vi":"Chi phí tăng là một mối lo ngại lớn đối với doanh nghiệp nhỏ."}]', '[]', NULL, '/ˈmeɪdʒər kənˈsɜːrn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 118, 'major contribution', 'đóng góp lớn', 'adj + n', '[{"en":"Her research made a major contribution to modern medicine.","vi":"Nghiên cứu của cô đã có đóng góp lớn cho y học hiện đại."},{"en":"Volunteers made a major contribution to the festival''s success.","vi":"Các tình nguyện viên đã đóng góp lớn vào thành công của lễ hội."},{"en":"The scientist''s major contribution was recognised with an award.","vi":"Đóng góp lớn của nhà khoa học được công nhận bằng một giải thưởng."}]', '[]', NULL, '/ˈmeɪdʒər ˌkɑːntrɪˈbjuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 119, 'major decision', 'quyết định quan trọng', 'adj + n', '[{"en":"Choosing a career is a major decision for young people.","vi":"Chọn nghề nghiệp là một quyết định quan trọng đối với người trẻ."},{"en":"The board postponed the major decision until next month.","vi":"Hội đồng đã hoãn quyết định quan trọng đến tháng sau."},{"en":"They consulted experts before making such a major decision.","vi":"Họ tham khảo ý kiến chuyên gia trước khi đưa ra quyết định quan trọng như vậy."}]', '[]', NULL, '/ˈmeɪdʒər dɪˈsɪʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 120, 'major difference', 'sự khác biệt lớn', 'adj + n', '[{"en":"There is a major difference between the two theories.","vi":"Có một sự khác biệt lớn giữa hai lý thuyết."},{"en":"Climate is the major difference between the two regions.","vi":"Khí hậu là sự khác biệt lớn giữa hai vùng."},{"en":"Experience makes a major difference in this kind of work.","vi":"Kinh nghiệm tạo nên sự khác biệt lớn trong loại công việc này."}]', '[]', NULL, '/ˈmeɪdʒər ˈdɪfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 121, 'major factor', 'yếu tố chính', 'adj + n', '[{"en":"Cost was a major factor in choosing this supplier.","vi":"Chi phí là một yếu tố chính trong việc chọn nhà cung cấp này."},{"en":"Sleep is a major factor affecting students'' overall performance.","vi":"Giấc ngủ là một yếu tố chính ảnh hưởng đến thành tích chung của sinh viên."},{"en":"The study identified pollution as a major factor in disease.","vi":"Nghiên cứu xác định ô nhiễm là một yếu tố chính gây bệnh."}]', '[]', NULL, '/ˈmeɪdʒər ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 122, 'major feature', 'đặc điểm chính', 'adj + n', '[{"en":"Flexibility is a major feature of this online course.","vi":"Tính linh hoạt là một đặc điểm chính của khóa học trực tuyến này."},{"en":"The report highlights several major features of the new system.","vi":"Báo cáo nêu bật một số đặc điểm chính của hệ thống mới."},{"en":"A major feature of the design is its low energy use.","vi":"Một đặc điểm chính của thiết kế là mức tiêu thụ năng lượng thấp."}]', '[]', NULL, '/ˈmeɪdʒər ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 123, 'major focus', 'trọng tâm chính', 'adj + n', '[{"en":"Customer satisfaction is a major focus of the company.","vi":"Sự hài lòng của khách hàng là trọng tâm chính của công ty."},{"en":"Reducing waste became a major focus of the research.","vi":"Giảm thiểu rác thải trở thành trọng tâm chính của nghiên cứu."},{"en":"A major focus of the lecture was climate adaptation.","vi":"Một trọng tâm chính của bài giảng là thích ứng với khí hậu."}]', '[]', NULL, '/ˈmeɪdʒər ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 124, 'major impact', 'tác động lớn', 'adj + n', '[{"en":"The new policy had a major impact on small businesses.","vi":"Chính sách mới đã có tác động lớn đến các doanh nghiệp nhỏ."},{"en":"Technology has a major impact on how we communicate.","vi":"Công nghệ có tác động lớn đến cách chúng ta giao tiếp."},{"en":"Early education can make a major impact on later success.","vi":"Giáo dục sớm có thể tạo ra tác động lớn đến thành công về sau."}]', '[]', NULL, '/ˈmeɪdʒər ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 125, 'major implications', 'hệ quả lớn', 'adj + n', '[{"en":"The findings have major implications for public health policy.","vi":"Các phát hiện có hệ quả lớn đối với chính sách y tế công cộng."},{"en":"This decision carries major implications for future trade deals.","vi":"Quyết định này mang theo những hệ quả lớn cho các thỏa thuận thương mại tương lai."},{"en":"Rising sea levels have major implications for coastal cities.","vi":"Mực nước biển dâng có hệ quả lớn đối với các thành phố ven biển."}]', '[]', NULL, '/ˈmeɪdʒər ˌɪmplɪˈkeɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 126, 'major influence', 'ảnh hưởng lớn', 'adj + n', '[{"en":"Her mentor had a major influence on her career choices.","vi":"Người cố vấn của cô đã có ảnh hưởng lớn đến các lựa chọn nghề nghiệp."},{"en":"Culture exerts a major influence on consumer behavior.","vi":"Văn hóa tạo ra ảnh hưởng lớn đến hành vi của người tiêu dùng."},{"en":"Greek philosophy was a major influence on Western thought.","vi":"Triết học Hy Lạp là một ảnh hưởng lớn đối với tư tưởng phương Tây."}]', '[]', NULL, '/ˈmeɪdʒər ˈɪnfluəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 127, 'major issue', 'vấn đề lớn', 'adj + n', '[{"en":"Traffic congestion remains a major issue in the city.","vi":"Ùn tắc giao thông vẫn là một vấn đề lớn ở thành phố."},{"en":"Data privacy is a major issue for many users today.","vi":"Quyền riêng tư dữ liệu là một vấn đề lớn với nhiều người dùng ngày nay."},{"en":"The meeting addressed a major issue facing the department.","vi":"Cuộc họp đã giải quyết một vấn đề lớn mà phòng ban đang đối mặt."}]', '[]', NULL, '/ˈmeɪdʒər ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 128, 'major part', 'phần lớn', 'adj + n', '[{"en":"Reading plays a major part in language learning.","vi":"Việc đọc đóng một phần lớn trong việc học ngôn ngữ."},{"en":"Agriculture forms a major part of the local economy.","vi":"Nông nghiệp tạo nên một phần lớn của nền kinh tế địa phương."},{"en":"A major part of the budget goes to research and development.","vi":"Một phần lớn ngân sách dành cho nghiên cứu và phát triển."}]', '[]', NULL, '/ˈmeɪdʒər ˈpɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 129, 'major problem', 'vấn đề nghiêm trọng', 'adj + n', '[{"en":"Air pollution is a major problem in large cities.","vi":"Ô nhiễm không khí là một vấn đề nghiêm trọng ở các thành phố lớn."},{"en":"The team faced a major problem with the software.","vi":"Nhóm đã gặp một vấn đề nghiêm trọng với phần mềm."},{"en":"Unemployment became a major problem after the crisis.","vi":"Thất nghiệp trở thành một vấn đề nghiêm trọng sau khủng hoảng."}]', '[]', NULL, '/ˈmeɪdʒər ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 130, 'major reason', 'lý do chính', 'adj + n', '[{"en":"Cost is a major reason students choose online courses.","vi":"Chi phí là một lý do chính khiến sinh viên chọn học trực tuyến."},{"en":"A major reason for the delay was poor planning.","vi":"Một lý do chính cho sự chậm trễ là việc lập kế hoạch kém."},{"en":"Convenience is a major reason people shop online.","vi":"Sự tiện lợi là một lý do chính khiến người ta mua sắm trực tuyến."}]', '[]', NULL, '/ˈmeɪdʒər ˈriːzən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 131, 'major role', 'vai trò lớn', 'adj + n', '[{"en":"Teachers play a major role in shaping young minds.","vi":"Giáo viên đóng một vai trò lớn trong việc định hình tư duy trẻ."},{"en":"Diet plays a major role in maintaining good health.","vi":"Chế độ ăn đóng một vai trò lớn trong việc duy trì sức khỏe tốt."},{"en":"The internet has a major role in modern education.","vi":"Internet có một vai trò lớn trong giáo dục hiện đại."}]', '[]', NULL, '/ˈmeɪdʒər ˈroʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 132, 'major shift', 'sự thay đổi lớn', 'adj + n', '[{"en":"There has been a major shift toward remote working.","vi":"Đã có một sự thay đổi lớn hướng tới làm việc từ xa."},{"en":"The data shows a major shift in consumer preferences.","vi":"Dữ liệu cho thấy một sự thay đổi lớn trong sở thích người tiêu dùng."},{"en":"A major shift in policy followed the election results.","vi":"Một sự thay đổi lớn về chính sách diễn ra sau kết quả bầu cử."}]', '[]', NULL, '/ˈmeɪdʒər ˈʃɪft/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 133, 'major source', 'nguồn chính', 'adj + n', '[{"en":"Tourism is a major source of income for the region.","vi":"Du lịch là một nguồn thu nhập chính cho khu vực này."},{"en":"Coal remains a major source of energy in many countries.","vi":"Than đá vẫn là một nguồn năng lượng chính ở nhiều nước."},{"en":"Stress is a major source of health problems among workers.","vi":"Căng thẳng là một nguồn chính gây vấn đề sức khỏe cho người lao động."}]', '[]', NULL, '/ˈmeɪdʒər ˈsɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 134, 'major theme', 'chủ đề chính', 'adj + n', '[{"en":"Identity is a major theme in the author''s novels.","vi":"Bản sắc là một chủ đề chính trong các tiểu thuyết của tác giả."},{"en":"Sustainability was a major theme at the conference.","vi":"Tính bền vững là một chủ đề chính tại hội nghị."},{"en":"A major theme of the essay is social inequality.","vi":"Một chủ đề chính của bài luận là bất bình đẳng xã hội."}]', '[]', NULL, '/ˈmeɪdʒər ˈθiːm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 135, 'make adjustments', 'thực hiện điều chỉnh', 'v + n', '[{"en":"We may need to make adjustments to the project plan.","vi":"Chúng ta có thể cần thực hiện điều chỉnh cho kế hoạch dự án."},{"en":"The teacher made adjustments to suit different learning styles.","vi":"Giáo viên đã thực hiện điều chỉnh để phù hợp các phong cách học khác nhau."},{"en":"Companies often make adjustments based on customer feedback.","vi":"Các công ty thường thực hiện điều chỉnh dựa trên phản hồi của khách hàng."}]', '[]', NULL, '/ˈmeɪk əˈdʒʌstmənts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 136, 'make arrangements', 'sắp xếp, thu xếp', 'v + n', '[{"en":"The office will make arrangements for your accommodation.","vi":"Văn phòng sẽ thu xếp chỗ ở cho bạn."},{"en":"We need to make arrangements for the guest speaker.","vi":"Chúng ta cần sắp xếp cho diễn giả khách mời."},{"en":"She made arrangements to travel before the deadline.","vi":"Cô ấy đã thu xếp để đi lại trước hạn chót."}]', '[]', NULL, '/ˈmeɪk əˈreɪndʒmənts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 137, 'make available', 'cung cấp, làm cho sẵn có', 'v + adj', '[{"en":"The library makes available many e-books to students.","vi":"Thư viện cung cấp nhiều sách điện tử cho sinh viên."},{"en":"The company made the report available to all employees.","vi":"Công ty đã làm cho báo cáo sẵn có với mọi nhân viên."},{"en":"We should make these resources available online for free.","vi":"Chúng ta nên cung cấp các tài nguyên này trực tuyến miễn phí."}]', '[]', NULL, '/ˈmeɪk əˈveɪləbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 138, 'make aware', 'làm cho nhận thức được', 'v + adj', '[{"en":"The campaign aims to make people aware of the risks.","vi":"Chiến dịch nhằm làm cho mọi người nhận thức được các rủi ro."},{"en":"Teachers should make students aware of plagiarism rules.","vi":"Giáo viên nên làm cho sinh viên nhận thức được các quy định đạo văn."},{"en":"The article made readers aware of the growing problem.","vi":"Bài báo đã làm cho độc giả nhận thức được vấn đề đang gia tăng."}]', '[]', NULL, '/ˈmeɪk əˈwer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 139, 'make contact', 'liên hệ, tiếp xúc', 'v + n', '[{"en":"Try to make contact with the supplier before Friday.","vi":"Hãy cố gắng liên hệ với nhà cung cấp trước thứ Sáu."},{"en":"Researchers made contact with several local communities.","vi":"Các nhà nghiên cứu đã tiếp xúc với một số cộng đồng địa phương."},{"en":"It can be hard to make contact with busy officials.","vi":"Có thể khó liên hệ với các quan chức bận rộn."}]', '[]', NULL, '/ˈmeɪk ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 140, 'make a contribution', 'đóng góp', 'v + n', '[{"en":"Every student can make a contribution to the discussion.","vi":"Mỗi sinh viên đều có thể đóng góp vào cuộc thảo luận."},{"en":"The scientist made a major contribution to the field.","vi":"Nhà khoa học đã có một đóng góp lớn cho lĩnh vực này."},{"en":"Volunteers make a valuable contribution to the community.","vi":"Các tình nguyện viên đóng góp quý giá cho cộng đồng."}]', '[]', NULL, '/ˈmeɪk ə ˌkɑːntrɪˈbjuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 141, 'make explicit', 'làm cho rõ ràng', 'v + adj', '[{"en":"The author should make the argument explicit in the introduction.","vi":"Tác giả nên làm cho lập luận rõ ràng trong phần mở đầu."},{"en":"Good instructions make every step explicit for the reader.","vi":"Hướng dẫn tốt làm cho mọi bước trở nên rõ ràng với người đọc."},{"en":"The policy makes explicit who is responsible for safety.","vi":"Chính sách làm rõ ràng ai chịu trách nhiệm về an toàn."}]', '[]', NULL, '/ˈmeɪk ɪkˈsplɪsɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 142, 'make policy', 'hoạch định chính sách', 'v + n', '[{"en":"Governments make policy based on careful research.","vi":"Chính phủ hoạch định chính sách dựa trên nghiên cứu kỹ lưỡng."},{"en":"Those who make policy must consider public opinion.","vi":"Những người hoạch định chính sách phải cân nhắc ý kiến công chúng."},{"en":"Experts help officials make policy on climate change.","vi":"Các chuyên gia giúp quan chức hoạch định chính sách về biến đổi khí hậu."}]', '[]', NULL, '/ˈmeɪk ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 143, 'make provision', 'có sự chuẩn bị, dự liệu', 'v + n', '[{"en":"The school should make provision for disabled students.","vi":"Nhà trường nên có sự chuẩn bị cho sinh viên khuyết tật."},{"en":"The plan makes provision for future population growth.","vi":"Kế hoạch dự liệu cho sự gia tăng dân số trong tương lai."},{"en":"Governments must make provision for emergency situations.","vi":"Chính phủ phải có sự chuẩn bị cho các tình huống khẩn cấp."}]', '[]', NULL, '/ˈmeɪk prəˈvɪʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 144, 'make visible', 'làm cho thấy được', 'v + adj', '[{"en":"The chart makes the trend visible at a glance.","vi":"Biểu đồ làm cho xu hướng thấy được chỉ trong nháy mắt."},{"en":"The study makes visible the hidden costs of pollution.","vi":"Nghiên cứu làm cho thấy được những chi phí ẩn của ô nhiễm."},{"en":"Good design makes important data visible to users.","vi":"Thiết kế tốt làm cho dữ liệu quan trọng thấy được với người dùng."}]', '[]', NULL, '/ˈmeɪk ˈvɪzəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 145, 'make a comment', 'đưa ra nhận xét', 'v + n', '[{"en":"The professor made a comment on my essay structure.","vi":"Giáo sư đã đưa ra nhận xét về cấu trúc bài luận của tôi."},{"en":"Feel free to make a comment during the presentation.","vi":"Bạn cứ thoải mái đưa ra nhận xét trong bài thuyết trình."},{"en":"She made a brief comment before leaving the meeting.","vi":"Cô ấy đã đưa ra một nhận xét ngắn trước khi rời cuộc họp."}]', '[]', NULL, '/ˈmeɪk ə ˈkɑːment/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 146, 'make a distinction', 'phân biệt', 'v + n', '[{"en":"It is important to make a distinction between cause and effect.","vi":"Điều quan trọng là phân biệt giữa nguyên nhân và hệ quả."},{"en":"The author makes a clear distinction between the two terms.","vi":"Tác giả phân biệt rõ ràng giữa hai thuật ngữ."},{"en":"We should make a distinction between fact and opinion.","vi":"Chúng ta nên phân biệt giữa sự thật và ý kiến."}]', '[]', NULL, '/ˈmeɪk ə dɪˈstɪŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 147, 'make a judgement', 'đưa ra phán đoán, đánh giá', 'v + n', '[{"en":"Try not to make a judgement before hearing all sides.","vi":"Cố đừng đưa ra phán đoán trước khi nghe hết các bên."},{"en":"The committee must make a judgement based on evidence.","vi":"Hội đồng phải đưa ra đánh giá dựa trên bằng chứng."},{"en":"Readers can make their own judgement about the findings.","vi":"Độc giả có thể tự đưa ra phán đoán về các phát hiện."}]', '[]', NULL, '/ˈmeɪk ə ˈdʒʌdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 148, 'make a living', 'kiếm sống', 'v + n', '[{"en":"Many artists struggle to make a living from their work.","vi":"Nhiều nghệ sĩ vất vả để kiếm sống bằng nghề của mình."},{"en":"Farmers in the region make a living from rice.","vi":"Nông dân trong vùng kiếm sống bằng nghề trồng lúa."},{"en":"It is hard to make a living as a freelance writer.","vi":"Thật khó để kiếm sống bằng nghề viết tự do."}]', '[]', NULL, '/ˈmeɪk ə ˈlɪvɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 149, 'make a prediction', 'đưa ra dự đoán', 'v + n', '[{"en":"Scientists make a prediction based on current data.","vi":"Các nhà khoa học đưa ra dự đoán dựa trên dữ liệu hiện tại."},{"en":"It is risky to make a prediction about the economy.","vi":"Thật mạo hiểm khi đưa ra dự đoán về nền kinh tế."},{"en":"The model lets us make a prediction about future trends.","vi":"Mô hình cho phép chúng ta đưa ra dự đoán về xu hướng tương lai."}]', '[]', NULL, '/ˈmeɪk ə prɪˈdɪkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-9-01', 150, 'make a recommendation', 'đưa ra khuyến nghị', 'v + n', '[{"en":"The report makes a recommendation to improve safety standards.","vi":"Báo cáo đưa ra khuyến nghị nhằm cải thiện tiêu chuẩn an toàn."},{"en":"The doctor made a recommendation about my diet.","vi":"Bác sĩ đã đưa ra khuyến nghị về chế độ ăn của tôi."},{"en":"Experts make a recommendation after reviewing the evidence.","vi":"Các chuyên gia đưa ra khuyến nghị sau khi xem xét bằng chứng."}]', '[]', NULL, '/ˈmeɪk ə ˌrekəmenˈdeɪʃən/', NULL, NULL, NULL);
